function userKey(){const sess=getSession();return 'studioOS_v3_'+(sess?sess.id:'guest');}
function _localStateKeys(){
  const sess=getSession();
  const uid=(sess&&sess.id)||(typeof _supaUserId!=='undefined'&&_supaUserId)||(window.ORDO_CONFIG&&ORDO_CONFIG.DEFAULT_USER_ID)||'local_user';
  const keys=[userKey(),'studioOS_v3_'+uid,'_ordo_cache_'+uid,'ordo_local_snapshot_v1','studioOS_v3_local_user'];
  return keys.filter((k,i)=>k&&keys.indexOf(k)===i);
}
function _normalizeLocalState(d){
  if(typeof d==='string'){try{d=JSON.parse(d);}catch(e){d=null;}}
  if(d&&d.data&&!d.tasks)d=typeof d.data==='string'?JSON.parse(d.data):d.data;
  if(!d||typeof d!=='object')return null;
  d.settings=d.settings||{name:'',phone:'',email:'',address:'',terms:'',logo:'',logoDark:'',logoLight:''};
  if(d.settings.logoDark === undefined) d.settings.logoDark='';
  if(d.settings.logoLight === undefined) d.settings.logoLight='';
  ['tasks','clients','transactions','invoices','goals','schedule','teams','subscriptions','projects','project_tasks','task_collections','services','standalone_packages','portfolio_projects','svc_orders','specializations','client_portals','loans','budgets','statements','timeEntries','contracts','stores','reviews','meetings','courses','wallets','wallet_transfers','temp_todo_lists','archivedTasks'].forEach(k=>{if(!Array.isArray(d[k]))d[k]=[];});
  return d;
}
function _localStateScore(d){
  if(!d)return 0;
  return (d.tasks||[]).length*4+(d.clients||[]).length*3+(d.invoices||[]).length*3+(d.transactions||[]).length*2+(d.projects||[]).length*2+(d.project_tasks||[]).length*2+(d.services||[]).length+(d.contracts||[]).length+(d.reviews||[]).length+(d.settings&&Object.keys(d.settings).length?1:0);
}
function _readBestLocalState(){
  let best=null,bestScore=-1,bestTime=0;
  try{
    const xhr=new XMLHttpRequest();
    xhr.open('GET','/api/local-state?t='+Date.now(),false);
    xhr.send(null);
    if(xhr.status>=200&&xhr.status<300){
      const serverState=_normalizeLocalState(xhr.responseText);
      if(serverState){best=serverState;bestScore=_localStateScore(serverState);bestTime=Date.parse(serverState._savedAt||serverState.updated_at||'')||0;}
    }
  }catch(e){}
  _localStateKeys().forEach(key=>{
    try{
      const d=_normalizeLocalState(localStorage.getItem(key));
      if(!d)return;
      const sc=_localStateScore(d);
      const tm=Date.parse(d._savedAt||d.updated_at||'')||0;
      if(sc>bestScore||(sc===bestScore&&tm>bestTime)){best=d;bestScore=sc;bestTime=tm;}
    }catch(e){}
  });
  return best;
}
function lsLoad(){
  const local=_readBestLocalState();
  if(local) S=local;
  migrateSFields();
  return S;
}
function lsSave(){
  try{
    S=_normalizeLocalState(S)||S;
    S._savedAt=new Date().toISOString();
    const json=JSON.stringify(S);
    _localStateKeys().forEach(key=>{try{localStorage.setItem(key,json);}catch(e){}});
    try{
      const xhr=new XMLHttpRequest();
      xhr.open('POST','/api/local-state',false);
      xhr.setRequestHeader('Content-Type','application/json');
      xhr.send(json);
    }catch(e){}
    if(window.OrdoLocalPersistence&&typeof OrdoLocalPersistence.backupNow==='function'){
      try{OrdoLocalPersistence.backupNow('lsSave');}catch(e){}
    }
  }catch(e){console.warn('lsSave failed:',e);}
  return S;
}
function cloudLoad(){
  return Promise.resolve(_readBestLocalState());
}
function cloudSave(data){
  if(data) S=data;
  lsSave();
  return Promise.resolve(S);
}
function cloudSaveNow(data){
  return cloudSave(data);
}
function _doCloudSave(data){
  return cloudSave(data);
}
function _queueCloudSave(){
  clearTimeout(window._ordoLocalCloudSaveTimer);
  window._ordoLocalCloudSaveTimer=setTimeout(function(){cloudSave(S);},300);
}
function tryParseDate(dateStr){
  if(!dateStr) return '';
  // Try ISO format first
  if(/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return dateStr;
  // Try to extract from Arabic locale date (e.g. "ظ،/ظ،/ظ¢ظ ٢٤")
  try {
    const d = new Date(dateStr);
    if(!isNaN(d)) return d.toISOString().split('T')[0];
  } catch(e){}
  return '';
}
