window.__ordoModalStack = window.__ordoModalStack || [];
window.__ordoModalZ = window.__ordoModalZ || 10000;
function _ordoIsModalVisible(m){
  if(!m) return false;
  var s = (m.getAttribute('style') || '').replace(/\s+/g, '').toLowerCase();
  return m.classList.contains('open') || s.indexOf('display:flex') !== -1 || s.indexOf('display:block') !== -1;
}
function _ordoPromoteModalLayer(m){
  if(!m || !m.classList || !m.classList.contains('modal-overlay')) return;
  if(m.parentNode !== document.body){
    document.body.appendChild(m);
  }
  if(_ordoIsModalVisible(m)){
    m.style.position = 'fixed';
    m.style.inset = '0';
    if(!m.dataset.ordoLayer || Number(m.dataset.ordoLayer) < 10000){
      m.dataset.ordoLayer = String(++window.__ordoModalZ);
      m.style.setProperty('z-index', m.dataset.ordoLayer, 'important');
    }
  }
}
function _ordoSyncModalLayers(root){
  var base = root && root.querySelectorAll ? root : document;
  if(root && root.classList && root.classList.contains('modal-overlay')) _ordoPromoteModalLayer(root);
  base.querySelectorAll('.modal-overlay').forEach(_ordoPromoteModalLayer);
}
_ordoSyncModalLayers(document);
if(!window.__ordoModalObserver && window.MutationObserver){
  window.__ordoModalObserver = new MutationObserver(function(mutations){
    mutations.forEach(function(mt){
      if(mt.type === 'childList'){
        mt.addedNodes.forEach(function(n){
          if(n && n.nodeType === 1) _ordoSyncModalLayers(n);
        });
      } else if(mt.type === 'attributes' && mt.target && mt.target.classList && mt.target.classList.contains('modal-overlay')){
        _ordoPromoteModalLayer(mt.target);
      }
    });
  });
  window.__ordoModalObserver.observe(document.documentElement, {childList:true, subtree:true, attributes:true, attributeFilter:['class','style']});
}
function _ordoTopOpenModal(exceptId){
  var open = Array.from(document.querySelectorAll('.modal-overlay.open')).filter(function(m){ return m.id && m.id !== exceptId; });
  return open.length ? open[open.length - 1] : null;
}
function _ordoResetModal(m){
  if(!m) return;
  m.classList.remove('expanded');
  m.style.zIndex = '';
  delete m.dataset.ordoLayer;
  var _eb = m.querySelector('.expand-btn');
  if(_eb){ _eb.innerHTML='<i class="fa-solid fa-expand"></i>'; _eb.title='توسيع'; }
}
function openM(id){
  var m = document.getElementById(id);
  if(!m) return;
  _ordoPromoteModalLayer(m);
  var current = _ordoTopOpenModal(id);
  if(current){
    current.classList.remove('open');
    current.dataset.pausedModal = '1';
    window.__ordoModalStack.push(current.id);
  }
  m.classList.add('open');
  m.dataset.pausedModal = '';
  m.dataset.ordoLayer = String(++window.__ordoModalZ);
  m.style.setProperty('z-index', m.dataset.ordoLayer, 'important');
  _ordoPromoteModalLayer(m);
}
function closeM(id){
  var _m = document.getElementById(id);
  if(!_m) return;
  if(id==='modal-income' && window._pendingStmtCollection) window._pendingStmtCollection=null;
  _m.classList.remove('open');
  _ordoResetModal(_m);
  var prevId = window.__ordoModalStack.pop();
  while(prevId){
    var prev = document.getElementById(prevId);
    if(prev && prev.dataset.pausedModal === '1'){
      prev.dataset.pausedModal = '';
      prev.classList.add('open');
      prev.style.zIndex = String(++window.__ordoModalZ);
      break;
    }
    prevId = window.__ordoModalStack.pop();
  }
  if(typeof window.__ordoAfterModalClose === 'function') setTimeout(window.__ordoAfterModalClose, 40);
}
document.querySelectorAll('.modal-overlay').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeM(m.id);}));
function confirmDel(msg,cb){
  const msgEl = document.getElementById('confirm-msg');
  const btnEl = document.getElementById('confirm-btn');
  if(!msgEl||!btnEl){ if(window.confirm(msg)) cb(); return; }
  msgEl.textContent=msg;
  // Replace button to remove old event listeners
  const newBtn = btnEl.cloneNode(true);
  btnEl.parentNode.replaceChild(newBtn, btnEl);
  newBtn.onclick = function(){ cb(); closeM('modal-confirm'); };
  openM('modal-confirm');
}

