function cleanWaTemplate(txt){
  return String(txt || '')
    .replace(/<i\b[^>]*><\/i>/gi, '')
    .replace(/<[^>]+>/g, '')
    .replace(/آ«/g, '«')
    .replace(/آ»/g, '»')
    .replace(/ط³ظ†/g, 'سن')
    .replace(/ط±/g, 'ر')
    .replace(/ظ†/g, 'ن')
    .replace(/ظ„/g, 'ل')
    .replace(/ًں‘‹/g, '')
    .replace(/ًں™ڈ/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .trim();
}

