/* â”€â”€ WhatsApp Modal â”€â”€ */
// waCtx: بيانات السياق الحالي (فاتورة أو مهمة)
let waCtx = {};

function openWaModal(tplType, invIdOrNull, taskIdOrNull){
  const s = S.settings||{};
  waCtx = { tplType, invId: invIdOrNull, taskId: taskIdOrNull };

  // جمع البيانات
  let clientName='', clientPhone='', invNum='', invTotal='', invDue='', projectUrl='', taskName='';

  if(invIdOrNull){
    const inv = S.invoices.find(x=>x.id===invIdOrNull);
    if(inv){
      clientName = inv.client;
      invNum     = inv.num||'';
      invTotal   = _invoiceDisplayTotal(inv).toLocaleString()+' '+_getCurrency();
      invDue     = inv.due||'';
      projectUrl = inv.projectUrl||'';
      taskName   = inv.items?.[0]?.desc||'';
      const cl   = S.clients.find(c=>c.name===inv.client);
      clientPhone = cl?.phone||'';
    }
  } else if(taskIdOrNull){
    const t = S.tasks.find(x=>x.id===taskIdOrNull);
    if(t){
      clientName  = t.client||'';
      taskName    = t.title||'';
      projectUrl  = t.brief?'':''
      const cl    = S.clients.find(c=>c.name===t.client);
      clientPhone = cl?.phone||'';
    }
  }

  waCtx.vars = {
    '{{اسم_العميل}}':           clientName,
    '{{اسم_المشروع}}':           taskName,
    '{{قيمة_الفاتورة}}':         invTotal,
    '{{رقم_الفاتورة}}':          invNum,
    '{{تاريخ_الاستحقاق}}':       invDue,
    '{{رابط_المشروع}}':          projectUrl,
    '{{اسم_العمل}}':         s.name||'العمل',
    '{{رقم_هاتف_العمل}}':    s.phone||'',
  };

  // عرض المستلم
  document.getElementById('wa-recip-name').textContent     = clientName||'?';
  document.getElementById('wa-recip-phone-disp').innerHTML = clientPhone ? '<i class="fa-solid fa-phone"></i> '+clientPhone : 'لا يوجد رقم ? أدخله يدوياً';
  // تنظيف الرقم (أرقام فقط)
  document.getElementById('wa-phone-input').value = clientPhone.replace(/[^\d]/g,'');

  // تحديد القالب المناسب
  loadWaTpl(tplType);

  // تمييز الزر النشط
  ['invoice','task','done','remind'].forEach(k=>{
    const btn = document.getElementById('wa-tpl-btn-'+k);
    if(btn) btn.className = 'btn btn-sm btn-'+(k===tplType?'primary':'ghost');
  });

  openM('modal-whatsapp');
}

function loadWaTpl(key){
  const wt = S.settings?.waTemplates||{};
  const defaults = getWaTemplateDefaults();
  const raw = cleanWaTemplate(wt[key] || defaults[key] || '');
  const filled = fillWaVars(raw, waCtx.vars||{});

  const ta = document.getElementById('wa-msg-text');
  if(ta){ ta.value = filled; }

  // تمييز الأزرار
  ['invoice','task','done','remind'].forEach(k=>{
    const btn = document.getElementById('wa-tpl-btn-'+k);
    if(btn) btn.className = 'btn btn-sm '+(k===key?'btn-primary':'btn-ghost');
  });

  updateWaPreview();
}

function fillWaVars(template, vars){
  let out = template;
  Object.entries(vars).forEach(([k,v])=>{ out = out.split(k).join(v||'?'); });
  return out;
}

function updateWaPreview(){
  const txt = document.getElementById('wa-msg-text')?.value||'';
  const prev = document.getElementById('wa-preview-text');
  if(prev) prev.textContent = txt || '...';
}

function doSendWhatsApp(){
  const phone = document.getElementById('wa-phone-input')?.value.trim().replace(/[^\d]/g,'');
  if(!phone){ alert('<i class="fa-solid fa-triangle-exclamation"></i> أدخل رقم واتساب المستلم'); return; }
  const msg   = document.getElementById('wa-msg-text')?.value||'';
  const url   = `https://wa.me/${phone}?text=${encodeURIComponent(msg)}`;
  window.open(url,'_blank');
  closeM('modal-whatsapp');
  showMiniNotif('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم فتح واتساب');
}
window.openReceivableWhatsAppModal = function(clientName, phone, msg){
  var cleanPhone = String(phone || '').replace(/[^\d]/g,'');
  var nameEl = document.getElementById('wa-recip-name');
  var phoneDisp = document.getElementById('wa-recip-phone-disp');
  var phoneInput = document.getElementById('wa-phone-input');
  var msgEl = document.getElementById('wa-msg-text');
  if(nameEl) nameEl.textContent = clientName || '—';
  if(phoneDisp) phoneDisp.innerHTML = cleanPhone ? '<i class="fa-solid fa-phone"></i> '+cleanPhone : 'لا يوجد رقم - أدخله يدوياً';
  if(phoneInput) phoneInput.value = cleanPhone;
  if(msgEl) msgEl.value = msg || '';
  if(typeof updateWaPreview === 'function') updateWaPreview();
  openM('modal-whatsapp');
};
function v(id){const e=document.getElementById(id);return e?e.value:'';}
function _logoForContext(context){
  const s=S.settings||{};
  if(context==='dark-bg') return s.logoLight || s.logo || s.logoDark || '';
  return s.logoDark || s.logo || s.logoLight || '';
}
function _printTheme(){
  const raw=(localStorage.getItem('studioAccentColor') || S.settings?.accentColor || S.settings?.toneColor || '#7c6ff7');
  const hex=/^#[0-9a-f]{6}$/i.test(raw) ? raw : '#7c6ff7';
  const rgb=hex.match(/\w\w/g).map(x=>parseInt(x,16));
  const mix=(to,p)=>'#'+rgb.map((v,i)=>Math.round(v+(to[i]-v)*p).toString(16).padStart(2,'0')).join('');
  return {
    accent:hex,
    accentDark:mix([20,20,30],.72),
    soft:mix([255,255,255],.88),
    softer:mix([255,255,255],.94),
    line:mix([255,255,255],.78),
    ink:'#171721',
    muted:'#74748a',
    ok:'#2f9d74',
    warn:'#b88700'
  };
}
function _renderLogoPreviews(){
  const s=S.settings||{};
  const darkLogo=s.logoDark||s.logo||'';
  const lightLogo=s.logoLight||'';
  const darkPrev=document.getElementById('logo-dark-preview');
  const lightPrev=document.getElementById('logo-light-preview');
  if(darkPrev) darkPrev.innerHTML=darkLogo
    ? "<img src=\""+darkLogo+"\" style=\"max-height:80px;max-width:200px;object-fit:contain;border-radius:6px\" onerror=\"this.style.display='none'\">"
    : '<span style="color:var(--text3);font-size:13px">لا يوجد لوجو</span>';
  if(lightPrev) lightPrev.innerHTML=lightLogo
    ? "<img src=\""+lightLogo+"\" style=\"max-height:80px;max-width:200px;object-fit:contain;border-radius:6px\" onerror=\"this.style.display='none'\">"
    : '<span style="color:rgba(255,255,255,.55);font-size:13px">لا يوجد لوجو</span>';
}
function uploadLogo(input, variant){
  const f=input.files[0];if(!f)return;
  if(f.size>2*1024*1024){toast('<i class="fa-solid fa-triangle-exclamation"></i> الصورة أكبر من 2 ميجا');input.value='';return;}
  toast('<i class="fa-solid fa-spinner fa-spin"></i> جاري رفع اللوجو...');
  const reader = new FileReader();
  reader.onload = function(e) {
    const url = e.target.result;
    if(!S.settings) S.settings={};
    if(variant==='light') S.settings.logoLight = url;
    else if(variant==='dark') S.settings.logoDark = url;
    else S.settings.logo = url;
    if(!S.settings.logo) S.settings.logo = url;
    lsSave(); cloudSaveNow(S);
    _renderLogoPreviews();
    toast('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم رفع اللوجو');
  };
  reader.onerror = function(){ toast('<i class="fa-solid fa-triangle-exclamation"></i> فشل قراءة الصورة'); };
  reader.readAsDataURL(f);
}

