function toggleDarkLight() {
  const current = localStorage.getItem('studioDisplayMode') || 'dark';
  const next = current === 'dark' ? 'light' : 'dark';
  setDisplayMode(next);
  const btn = document.getElementById('dark-toggle-btn');
  if(btn) { var ic=btn.querySelector('i'); if(ic) ic.className=next==='dark'?'fa-solid fa-moon':'fa-solid fa-sun'; }
}

function setDisplayMode(mode) {
  document.body.classList.toggle('light-mode', mode === 'light');
  document.documentElement.classList.toggle('light-mode', mode === 'light');
  localStorage.setItem('studioDisplayMode', mode);

  // â”€â”€ Fix: Update inline CSS variables + background that anti-flash script sets â”€â”€
  if(mode === 'light') {
    document.documentElement.style.setProperty('--bg',      '#f0f2f8');
    document.documentElement.style.setProperty('--surface', '#ffffff');
    document.documentElement.style.setProperty('--surface2','#f5f6fb');
    document.documentElement.style.setProperty('--surface3','#eceef5');
    document.documentElement.style.setProperty('--border',  '#d8dae8');
    document.documentElement.style.setProperty('--text',    '#1a1a2e');
    document.documentElement.style.setProperty('--text2',   '#5a5a7a');
    document.documentElement.style.setProperty('--text3',   '#9090b0');
    document.documentElement.style.background = '#f0f2f8';
    document.body.style.background = '#f0f2f8';
    document.body.style.color = '#1a1a2e';
  } else {
    document.documentElement.style.setProperty('--bg',      '#0a0a0f');
    document.documentElement.style.setProperty('--surface', '#111118');
    document.documentElement.style.setProperty('--surface2','#16161f');
    document.documentElement.style.setProperty('--surface3','#1c1c28');
    document.documentElement.style.setProperty('--border',  '#2a2a3a');
    document.documentElement.style.setProperty('--text',    '#e8e8f0');
    document.documentElement.style.setProperty('--text2',   '#9090a8');
    document.documentElement.style.setProperty('--text3',   '#5a5a70');
    document.documentElement.style.background = '#0a0a0f';
    document.body.style.background = '#0a0a0f';
    document.body.style.color = '#e8e8f0';
  }

  const btnDark  = document.getElementById('btn-dark-mode');
  const btnLight = document.getElementById('btn-light-mode');
  if(btnDark && btnLight) {
    btnDark.className  = mode === 'dark'  ? 'btn btn-primary' : 'btn btn-ghost';
    btnLight.className = mode === 'light' ? 'btn btn-primary' : 'btn btn-ghost';
  }
  const toggleBtn = document.getElementById('dark-toggle-btn');
  if(toggleBtn){ var tic=toggleBtn.querySelector('i'); if(tic) tic.className=mode==='dark'?'fa-solid fa-moon':'fa-solid fa-sun'; var bi=document.querySelector('#bnm-dark-icon i'); if(bi) bi.className=mode==='dark'?'fa-solid fa-moon':'fa-solid fa-sun'; }
  // Sync to cloud
  if(typeof S !== 'undefined' && S){
    if(!S.settings) S.settings={};
    S.settings.displayMode = mode;
    if(typeof lsSave==='function') lsSave();
    clearTimeout(window._modeCloudTimer);
    if(typeof cloudSaveNow==='function') cloudSaveNow(S);
  }
  // Force recreate styled elements so they pick up new variables
  var _staleEls = ['_toast','_autosave-dot','sync-indicator','mini-notif'];
  _staleEls.forEach(function(id){ var e=document.getElementById(id); if(e) e.remove(); });
  applyStudioAppearance();
}

function setThemeColor(color) {
  document.documentElement.style.setProperty('--accent', color);
  var rgb = _hexToRgbObj(color);
  if(rgb) document.documentElement.style.setProperty('--accent-rgb', rgb.r+','+rgb.g+','+rgb.b);
  localStorage.setItem('studioAccentColor', color);
  // update swatches
  document.querySelectorAll('.theme-swatch').forEach(s => {
    s.classList.toggle('active', s.dataset.color === color);
  });
  const picker = document.getElementById('custom-accent-picker');
  if(picker) picker.value = color;
  // Sync to cloud via S.settings
  if(typeof S !== 'undefined' && S){
    if(!S.settings) S.settings={};
    S.settings.accentColor = color;
    if(typeof lsSave === 'function') lsSave();
    if(typeof cloudSave === 'function') clearTimeout(window._themeCloudTimer);
    if(typeof cloudSaveNow==='function') cloudSaveNow(S);
  }
  if(typeof applyStudioAppearance === 'function') applyStudioAppearance();
}

function _hexToRgbObj(hex){
  hex = String(hex || '').replace('#','').trim();
  if(hex.length === 3) hex = hex.split('').map(function(c){ return c+c; }).join('');
  if(hex.length !== 6) return null;
  var n = parseInt(hex, 16);
  if(Number.isNaN(n)) return null;
  return {r:(n>>16)&255,g:(n>>8)&255,b:n&255};
}
function _mixHex(hex, pct){
  var rgb = _hexToRgbObj(hex); if(!rgb) return hex;
  var target = pct >= 0 ? 255 : 0;
  var p = Math.abs(pct);
  function c(v){ return Math.round(v + (target - v) * p); }
  return '#'+[c(rgb.r),c(rgb.g),c(rgb.b)].map(function(v){ return v.toString(16).padStart(2,'0'); }).join('');
}
function _isLightHex(hex){
  var rgb = _hexToRgbObj(hex); if(!rgb) return false;
  var lum = (0.299 * rgb.r + 0.587 * rgb.g + 0.114 * rgb.b) / 255;
  return lum > .58;
}
function applyStudioInlineFontScale(scale){
  scale = Math.max(.86, Math.min(1.12, Number(scale) || 1));
  document.querySelectorAll('[style*="font-size"]').forEach(function(el){
    var raw = el.dataset.studioBaseFontSize || '';
    if(!raw){
      raw = (el.style && el.style.fontSize) || '';
      if(!/^\d+(\.\d+)?px$/.test(raw.trim())) return;
      el.dataset.studioBaseFontSize = raw.trim();
    }
    var base = parseFloat(raw);
    if(!base) return;
    el.style.fontSize = (Math.round(base * scale * 100) / 100) + 'px';
  });
}
function installStudioFontScaleObserver(){
  if(window.__studioFontScaleObserver || !window.MutationObserver) return;
  var timer = null;
  window.__studioFontScaleObserver = new MutationObserver(function(){
    clearTimeout(timer);
    timer = setTimeout(function(){
      var s = (typeof S !== 'undefined' && S && S.settings) || {};
      var scale = Number(localStorage.getItem('studioFontScale') || s.fontScale || 1);
      applyStudioInlineFontScale(scale);
    }, 80);
  });
  window.__studioFontScaleObserver.observe(document.body || document.documentElement, {childList:true, subtree:true});
}
function applyStudioAppearance(){
  var s = (typeof S !== 'undefined' && S && S.settings) || {};
  var mode = localStorage.getItem('studioDisplayMode') || s.displayMode || 'dark';
  var fontScale = Number(localStorage.getItem('studioFontScale') || s.fontScale || 1);
  var accent = localStorage.getItem('studioAccentColor') || s.accentColor || '#7c6ff7';
  var hover = localStorage.getItem('studioHoverOverlay') || s.hoverOverlayColor || '';
  var tone = localStorage.getItem('studioToneColor') || s.toneColor || '';
  fontScale = Math.max(.86, Math.min(1.12, fontScale || 1));
  document.documentElement.style.setProperty('--app-font-scale', String(fontScale || 1));
  document.documentElement.style.setProperty('--app-font-scale-inverse', String(1 / (fontScale || 1)));
  applyStudioInlineFontScale(fontScale);
  installStudioFontScaleObserver();
  if(document.body){
    document.body.style.removeProperty('zoom');
    document.body.classList.toggle('studio-toned', !!tone);
  }
  if(accent){
    document.documentElement.style.setProperty('--accent', accent);
    var rgb = _hexToRgbObj(accent);
    if(rgb) document.documentElement.style.setProperty('--accent-rgb', rgb.r+','+rgb.g+','+rgb.b);
  }
  if(hover){
    var hrgb = _hexToRgbObj(hover);
    document.documentElement.style.setProperty('--hover-overlay', hrgb ? 'rgba('+hrgb.r+','+hrgb.g+','+hrgb.b+',.13)' : hover);
  } else {
    document.documentElement.style.setProperty('--hover-overlay', 'rgba(var(--accent-rgb,124,111,247),.10)');
  }
  if(tone){
    var toneIsLight = _isLightHex(tone);
    document.documentElement.style.setProperty('--bg', tone);
    document.documentElement.style.setProperty('--surface', toneIsLight ? _mixHex(tone, .82) : _mixHex(tone, .10));
    document.documentElement.style.setProperty('--surface2', toneIsLight ? _mixHex(tone, .70) : _mixHex(tone, .17));
    document.documentElement.style.setProperty('--surface3', toneIsLight ? _mixHex(tone, .58) : _mixHex(tone, .25));
    document.documentElement.style.setProperty('--border', toneIsLight ? _mixHex(tone, -.18) : _mixHex(tone, .34));
    document.body.style.background = tone;
    document.documentElement.style.background = tone;
  } else if(document.body){
    document.body.classList.remove('studio-toned');
    document.body.style.background = '';
    document.documentElement.style.background = '';
  }
  ['studio-font-scale','studio-tone-color','studio-hover-color'].forEach(function(id){
    var el = document.getElementById(id);
    if(!el) return;
    if(id === 'studio-font-scale') el.value = String(fontScale || 1);
    if(id === 'studio-tone-color') el.value = tone || (mode === 'light' ? '#f0f2f8' : '#0a0a0f');
    if(id === 'studio-hover-color') el.value = hover || accent;
  });
  var fsTxt = document.getElementById('studio-font-scale-value');
  if(fsTxt) fsTxt.textContent = Math.round((fontScale || 1) * 100) + '%';
}
function setStudioFontScale(v){
  v = Math.max(.86, Math.min(1.12, Number(v) || 1));
  localStorage.setItem('studioFontScale', String(v));
  if(typeof S !== 'undefined' && S){
    if(!S.settings) S.settings = {};
    S.settings.fontScale = v;
    if(typeof lsSave === 'function') lsSave();
    if(typeof cloudSaveNow === 'function') cloudSaveNow(S);
  }
  applyStudioAppearance();
}
function setStudioToneColor(color){
  localStorage.setItem('studioToneColor', color || '');
  if(typeof S !== 'undefined' && S){
    if(!S.settings) S.settings = {};
    S.settings.toneColor = color || '';
    if(typeof lsSave === 'function') lsSave();
    if(typeof cloudSaveNow === 'function') cloudSaveNow(S);
  }
  applyStudioAppearance();
}
function setStudioHoverOverlay(color){
  localStorage.setItem('studioHoverOverlay', color || '');
  if(typeof S !== 'undefined' && S){
    if(!S.settings) S.settings = {};
    S.settings.hoverOverlayColor = color || '';
    if(typeof lsSave === 'function') lsSave();
    if(typeof cloudSaveNow === 'function') cloudSaveNow(S);
  }
  applyStudioAppearance();
}
function saveStudioAppearanceSettings(){
  var font = document.getElementById('studio-font-scale')?.value || localStorage.getItem('studioFontScale') || 1;
  var tone = document.getElementById('studio-tone-color')?.value || '';
  var hover = document.getElementById('studio-hover-color')?.value || '';
  setStudioFontScale(font);
  setStudioToneColor(tone);
  setStudioHoverOverlay(hover);
  if(typeof toast === 'function') toast('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم حفظ وتطبيق المظهر');
}
function resetStudioAppearanceSettings(){
  setStudioFontScale(1);
  setStudioToneColor('');
  setStudioHoverOverlay('');
  applyStudioAppearance();
  if(typeof toast === 'function') toast('تمت إعادة المظهر للوضع الافتراضي');
}
window.setStudioFontScale = setStudioFontScale;
window.setStudioToneColor = setStudioToneColor;
window.setStudioHoverOverlay = setStudioHoverOverlay;
window.saveStudioAppearanceSettings = saveStudioAppearanceSettings;
window.resetStudioAppearanceSettings = resetStudioAppearanceSettings;

function installSettingsRedesign(){
  var page = document.getElementById('page-settings');
  if(!page) return;
  page.classList.add('settings-v2');
  var tabs = document.getElementById('settings-tabs-row');
  if(tabs && !tabs.dataset.reordered){
    ['general','appearance','tasks','finance','currencies','team-specs','whatsapp','features','danger'].forEach(function(id){
      var btn = document.getElementById('stab-'+id);
      if(btn) tabs.appendChild(btn);
    });
    tabs.dataset.reordered = '1';
  }
  var quick = document.getElementById('settings-v2-quick');
  if(quick) quick.remove();
  var appearance = document.getElementById('stabp-appearance');
  if(appearance && !document.getElementById('settings-v2-appearance-extra')){
    var extra = document.createElement('div');
    extra.id = 'settings-v2-appearance-extra';
    extra.className = 'settings-v2-appearance-grid';
    extra.innerHTML =
      '<div class="settings-v2-control settings-v2-control-wide"><h4><i class="fa-solid fa-text-height"></i> حجم خط الموقع بالكامل</h4><p>يصغر أو يكبر واجهة الموقع فورًا، ويُحفظ مع إعدادات الاستوديو.</p><div class="settings-v2-control-row"><input id="studio-font-scale" type="range" min="0.86" max="1.12" step="0.02" oninput="setStudioFontScale(this.value)"><b id="studio-font-scale-value">100%</b><button class="btn btn-ghost btn-sm" onclick="setStudioFontScale(1)">إعادة ضبط</button></div></div>'+
      '<div class="settings-v2-control"><h4><i class="fa-solid fa-fill-drip"></i> درجة الخلفية العامة</h4><p>تحدد روح الصفحة في الليلي أو النهاري بدون خلطها مع العملات أو المالية.</p><div class="settings-v2-control-row"><input id="studio-tone-color" type="color" oninput="setStudioToneColor(this.value)" onchange="setStudioToneColor(this.value)"><button class="btn btn-ghost btn-sm" onclick="setStudioToneColor(&quot;&quot;)">افتراضي</button></div><div class="settings-v2-preview"><span></span><span style="background:var(--surface2)"></span></div></div>'+
      '<div class="settings-v2-control"><h4><i class="fa-solid fa-computer-mouse"></i> لون المرور على العناصر</h4><p>لون overlay عند مرور المؤشر على الأزرار والصفوف.</p><div class="settings-v2-control-row"><input id="studio-hover-color" type="color" oninput="setStudioHoverOverlay(this.value)" onchange="setStudioHoverOverlay(this.value)"><button class="btn btn-ghost btn-sm" onclick="setStudioHoverOverlay(&quot;&quot;)">حسب الهوية</button></div><div class="settings-v2-preview"><span style="background:var(--hover-overlay)"></span><span style="background:rgba(var(--accent-rgb,124,111,247),.18)"></span></div></div>'+
      '<div class="settings-v2-control settings-v2-control-wide" style="display:flex;align-items:center;justify-content:flex-end;gap:10px"><button class="btn btn-ghost" onclick="resetStudioAppearanceSettings()"><i class="fa-solid fa-rotate-left"></i> إعادة افتراضي</button><button class="btn btn-primary" onclick="saveStudioAppearanceSettings()"><i class="fa-solid fa-floppy-disk"></i> حفظ وتطبيق المظهر</button></div>';
    appearance.appendChild(extra);
  }
  applyStudioAppearance();
}
if(document.readyState === 'loading'){
  document.addEventListener('DOMContentLoaded', function(){
    setTimeout(function(){ applyStudioAppearance(); installSettingsRedesign(); }, 120);
  });
} else {
  setTimeout(function(){ applyStudioAppearance(); installSettingsRedesign(); }, 120);
}

