/* â”€â”€ Salary reminders on dashboard â”€â”€ */
function renderSalaryReminders(){
  const wrap = document.getElementById('dash-salary-reminders');
  if(!wrap) return;
  const now = new Date();
  const curY = now.getFullYear(), curM = now.getMonth()+1, curD = now.getDate();

  // قراءة بيانات الراتب من العملاء (مش من المهام)
  const salariedClients = S.clients.filter(c=>
    (c.workType==='fulltime'||c.workType==='parttime') && c.salary>0 && c.salaryDay
  );
  if(!salariedClients.length){ wrap.style.display='none'; return; }

  const cards = salariedClients.map(c=>{
    const salDay = +c.salaryDay;
    const lastPaid = c.salaryLastPaid;
    const paidThisMonth = lastPaid && lastPaid === `${curY}-${String(curM).padStart(2,'0')}`;
    if(paidThisMonth) return '';

    const isOverdue = curD >= salDay;
    const daysLeft  = salDay - curD;
    const wtLabel   = c.workType==='fulltime'?'<i class="fa-solid fa-building"></i> دوام كامل':'<i class="fa-solid fa-alarm-clock"></i> بارت تايم';
    const salCur = _salaryCurrencyMeta(c.salaryCurrency || c.currency_code || c.currency || 'EGP');
    const hiddenId = 'salary-amount-' + c.id;

    return `<div class="salary-card ${isOverdue?'overdue':'pending'}">
      <div style="font-size:22px">${isOverdue?'<i class="fa-solid fa-triangle-exclamation" style="color:#ff6b6b"></i>':'<i class="fa-solid fa-coins" style="color:var(--accent3)"></i>'}</div>
      <div style="flex:1">
        <div style="font-weight:700;font-size:14px">${c.name}</div>
        <div style="font-size:12px;color:var(--text2);margin-top:2px">
          ${wtLabel} آ· <span>راتب</span>
          <button class="btn btn-ghost btn-sm" style="font-size:10px;padding:2px 8px;margin-inline:4px" onclick="toggleSalaryAmount('${hiddenId}', ${Number(c.salary||0)}, '${salCur.symbol}')"><i class="fa-solid fa-eye"></i> عرض المبلغ</button>
          <b id="${hiddenId}" style="color:var(--accent3);display:none">${Number(c.salary||0).toLocaleString()} ${salCur.symbol}</b>
          ${isOverdue
            ? `<span style="color:#ff6b6b;font-weight:700;margin-right:8px"><i class="fa-solid fa-circle-exclamation"></i> موعد الراتب يوم ${salDay}${curD>salDay?' ? تجاوز الموعد!':' ? اليوم!'}</span>`
            : `<span style="color:var(--accent2);margin-right:8px"><i class="fa-solid fa-clock"></i> ينزل بعد ${daysLeft} يوم (يوم ${salDay})</span>`
          }
        </div>
        ${c.salaryLastPaidDate
          ? `<div style="font-size:10px;color:var(--text3);margin-top:3px"><i class="fa-solid fa-calendar-check" style="color:var(--accent3)"></i> آخر قبض: ${c.salaryLastPaidDate}${c.salaryHistory?` آ· ${c.salaryHistory.length} مرة إجمالي`:''}</div>`
          : `<div style="font-size:10px;color:var(--accent4);margin-top:3px"><i class="fa-solid fa-circle-info"></i> لم يتم القبض بعد</div>`
        }
      </div>
      <div style="display:flex;flex-direction:column;gap:6px;align-items:flex-end">
        <button class="btn btn-success btn-sm" onclick="markClientSalaryPaid(${c.id})"><i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم القبض</button>
        <button class="btn btn-ghost btn-sm" style="font-size:10px" onclick="snoozeClientSalary(${c.id})"><i class="fa-solid fa-clock"></i> +يوم تأجيل</button>
      </div>
    </div>`;
  }).filter(Boolean).join('');

  if(!cards){ wrap.style.display='none'; return; }
  wrap.style.display='block';
  wrap.innerHTML=`<div style="font-size:13px;font-weight:700;color:var(--text);margin-bottom:8px"><i class="fa-solid fa-briefcase"></i> تذكيرات الرواتب</div>${cards}`;
}

function markClientSalaryPaid(clientId){
  const c = S.clients.find(x=>x.id===clientId);
  if(!c) return;
  openSalaryPaymentModal(clientId);
}

function snoozeClientSalary(clientId){
  const c = S.clients.find(x=>x.id===clientId);
  if(!c) return;
  c.salaryDay = Math.min(+c.salaryDay+1, 28);
  lsSave(); renderSalaryReminders();
  showMiniNotif(`<i class="fa-solid fa-alarm-clock"></i> تم تأجيل موعد الراتب ليوم ${c.salaryDay}`);
}

function _salaryCurrencyMeta(value){
  if(window.OrdoData && typeof window.OrdoData.getCurrencyMeta === 'function'){
    return window.OrdoData.getCurrencyMeta(value || 'EGP');
  }
  const defs = [
    {code:'EGP',symbol:'ج.م',label:'جنيه مصري'},
    {code:'USD',symbol:'$',label:'دولار أمريكي'},
    {code:'SAR',symbol:'ر.س',label:'ريال سعودي'},
    {code:'AED',symbol:'د.إ',label:'درهم إماراتي'},
    {code:'EUR',symbol:'€',label:'يورو'},
    {code:'KWD',symbol:'د.ك',label:'دينار كويتي'},
    {code:'QAR',symbol:'ر.ق',label:'ريال قطري'}
  ];
  const val = String(value || 'EGP');
  return defs.find(c=>c.code===val || c.symbol===val || c.label===val) || defs[0];
}

function _salaryEnabledCurrencies(){
  const saved = S.settings && Array.isArray(S.settings.enabled_currencies) ? S.settings.enabled_currencies : null;
  const list = saved && saved.length ? saved.filter(c=>c && c.enabled !== false) : ['EGP','USD','SAR','AED','EUR'].map(code=>_salaryCurrencyMeta(code));
  return list.map(c=>_salaryCurrencyMeta(c.code || c.currency_code || c.symbol || c.label));
}

function _salaryCurrencyOptions(selected){
  const cur = _salaryCurrencyMeta(selected || S.settings?.base_currency_code || S.settings?.currency || 'EGP').code;
  return _salaryEnabledCurrencies().map(c=>`<option value="${c.code}" ${c.code===cur?'selected':''}>${c.label} (${c.symbol})</option>`).join('');
}

function _salaryDestinationOptions(selected){
  const accounts = (S.finance_accounts||[]).filter(a=>a && a.active !== false);
  const wallets = (S.wallets||[]).filter(w=>w);
  let html = '<option value="">بدون حساب محدد</option>';
  if(accounts.length){
    html += '<optgroup label="حسابات وبنوك">';
    html += accounts.map(a=>`<option value="account:${a.id}" data-currency="${a.currency_code||'EGP'}" ${selected==='account:'+a.id?'selected':''}>${escapeHtml(a.name||'حساب')} - ${_salaryCurrencyMeta(a.currency_code||'EGP').symbol}</option>`).join('');
    html += '</optgroup>';
  }
  if(wallets.length){
    html += '<optgroup label="محافظ العملات">';
    html += wallets.map(w=>{
      const code = w.currency_code || w.currency || w.id || 'EGP';
      const cur = _salaryCurrencyMeta(code);
      return `<option value="wallet:${w.id||cur.code}" data-currency="${cur.code}" ${selected==='wallet:'+(w.id||cur.code)?'selected':''}>محفظة ${cur.label} - ${cur.symbol}</option>`;
    }).join('');
    html += '</optgroup>';
  }
  return html;
}

function toggleSalaryAmount(id, amount, symbol){
  const el = document.getElementById(id);
  if(!el) return;
  const hidden = el.style.display === 'none';
  el.textContent = Number(amount||0).toLocaleString() + ' ' + (symbol || '');
  el.style.display = hidden ? 'inline' : 'none';
}

function _ensureSalaryPaymentModal(){
  if(document.getElementById('modal-salary-payment')) return;
  const modal = document.createElement('div');
  modal.className = 'modal-overlay';
  modal.id = 'modal-salary-payment';
  modal.innerHTML = `
    <div class="modal" style="max-width:560px">
      <div class="modal-header">
        <div class="modal-title"><i class="fa-solid fa-money-check-dollar"></i> تسجيل قبض راتب</div>
        <button class="close-btn" onclick="closeM('modal-salary-payment')"><i class="fa-solid fa-xmark"></i></button>
      </div>
      <input type="hidden" id="salary-pay-client-id">
      <div id="salary-pay-name" style="font-size:13px;font-weight:800;color:var(--text);margin-bottom:10px"></div>
      <div class="form-row">
        <div class="form-group"><label class="form-label">المبلغ المقبوض</label><input class="form-input" type="number" id="salary-pay-amount" placeholder="0"></div>
        <div class="form-group"><label class="form-label">العملة</label><select class="form-select" id="salary-pay-currency"></select></div>
      </div>
      <div class="form-row">
        <div class="form-group"><label class="form-label">تاريخ القبض</label><input class="form-input" type="date" id="salary-pay-date"></div>
        <div class="form-group"><label class="form-label">تسجيل في الدخل؟</label><select class="form-select" id="salary-pay-register" onchange="toggleSalaryIncomeFields()"><option value="yes">نعم، سجل حركة دخل</option><option value="no">لا، علّم الراتب كمقبوض فقط</option></select></div>
      </div>
      <div id="salary-income-fields">
        <div class="form-group"><label class="form-label">الدخل رايح على حساب / محفظة</label><select class="form-select" id="salary-pay-destination" onchange="syncSalaryCurrencyFromDestination()"></select></div>
        <div class="form-group"><label class="form-label">ملاحظة الحركة</label><input class="form-input" id="salary-pay-note" placeholder="راتب الشهر"></div>
      </div>
      <div style="display:flex;gap:10px;justify-content:flex-end;margin-top:12px">
        <button class="btn btn-ghost" onclick="closeM('modal-salary-payment')">إلغاء</button>
        <button class="btn btn-success" onclick="saveSalaryPayment()"><i class="fa-solid fa-floppy-disk"></i> حفظ القبض</button>
      </div>
    </div>`;
  document.body.appendChild(modal);
}

function openSalaryPaymentModal(clientId){
  const c = (S.clients||[]).find(x=>String(x.id)===String(clientId));
  if(!c) return;
  _ensureSalaryPaymentModal();
  const cur = _salaryCurrencyMeta(c.salaryCurrency || c.currency_code || c.currency || S.settings?.base_currency_code || 'EGP');
  document.getElementById('salary-pay-client-id').value = c.id;
  document.getElementById('salary-pay-name').innerHTML = `<i class="fa-solid fa-user-tie"></i> ${escapeHtml(c.name||'')} <span style="color:var(--text3);font-weight:600">- ${c.workType==='fulltime'?'دوام كامل':'بارت تايم'}</span>`;
  document.getElementById('salary-pay-amount').value = Number(c.salary||0);
  document.getElementById('salary-pay-currency').innerHTML = _salaryCurrencyOptions(cur.code);
  document.getElementById('salary-pay-date').value = new Date().toISOString().split('T')[0];
  document.getElementById('salary-pay-register').value = 'yes';
  document.getElementById('salary-pay-destination').innerHTML = _salaryDestinationOptions('');
  document.getElementById('salary-pay-note').value = `راتب ${c.name}`;
  toggleSalaryIncomeFields();
  openM('modal-salary-payment');
}

function toggleSalaryIncomeFields(){
  const yes = document.getElementById('salary-pay-register')?.value !== 'no';
  const fields = document.getElementById('salary-income-fields');
  if(fields) fields.style.display = yes ? 'block' : 'none';
}

function syncSalaryCurrencyFromDestination(){
  const dest = document.getElementById('salary-pay-destination');
  const cur = document.getElementById('salary-pay-currency');
  const opt = dest && dest.selectedOptions ? dest.selectedOptions[0] : null;
  const code = opt && opt.dataset ? opt.dataset.currency : '';
  if(cur && code) cur.value = _salaryCurrencyMeta(code).code;
}

function saveSalaryPayment(){
  const id = document.getElementById('salary-pay-client-id')?.value;
  const c = (S.clients||[]).find(x=>String(x.id)===String(id));
  if(!c) return;
  const amount = +(document.getElementById('salary-pay-amount')?.value || 0);
  if(!amount) return alert('أدخل مبلغ الراتب');
  const payDate = document.getElementById('salary-pay-date')?.value || new Date().toISOString().split('T')[0];
  const month = payDate.slice(0,7);
  const cur = _salaryCurrencyMeta(document.getElementById('salary-pay-currency')?.value || c.salaryCurrency || 'EGP');
  const shouldRegister = document.getElementById('salary-pay-register')?.value !== 'no';
  let txId = null;
  if(shouldRegister){
    const dest = document.getElementById('salary-pay-destination')?.value || '';
    const tx = {
      id: Date.now(),
      type: 'income',
      amount,
      source: c.name,
      client: c.name,
      desc: document.getElementById('salary-pay-note')?.value || `راتب ${c.name}`,
      date: new Date(payDate+'T00:00:00').toLocaleDateString('ar-EG'),
      isoDate: payDate,
      category: 'salary',
      paymentType: 'salary',
      payMethod: 'salary',
      isSalary: true,
      salaryClientId: c.id,
      currency_code: cur.code,
      currency_symbol: cur.symbol,
      currency: cur.code,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      _dirty: true
    };
    if(dest.startsWith('account:')) tx.account_id = dest.slice(8);
    if(dest.startsWith('wallet:')) tx.wallet_id = dest.slice(7);
    S.transactions = Array.isArray(S.transactions) ? S.transactions : [];
    S.transactions.push(tx);
    txId = tx.id;
  }
  c.salaryLastPaid = month;
  c.salaryLastPaidDate = payDate;
  c.salaryCurrency = cur.code;
  if(!Array.isArray(c.salaryHistory)) c.salaryHistory = [];
  c.salaryHistory.push({
    month,
    amount,
    currency_code: cur.code,
    currency_symbol: cur.symbol,
    paidAt: new Date(payDate+'T12:00:00').toISOString(),
    transactionId: txId,
    registeredIncome: shouldRegister
  });
  lsSave();
  if(typeof cloudSaveNow === 'function') cloudSaveNow(S); else if(typeof cloudSave === 'function') cloudSave(S);
  closeM('modal-salary-payment');
  renderAll();
  showMiniNotif(`<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم حفظ قبض الراتب ${shouldRegister?'وتسجيله كدخل':'بدون حركة دخل'}`);
}

/* â”€â”€ Task Filters â”€â”€ */
let taskFilterState = {status:'',priority:'',jobtype:'',client:'',month:'',year:'',search:''};

function populateTaskFilterDropdowns(){
  // clients
  const cfsel = document.getElementById('tf-client');
  if(cfsel){
    const cur = cfsel.value;
    cfsel.innerHTML = '<option value="">كل العملاء</option>';
    [...new Set(S.tasks.map(t=>t.client).filter(Boolean))].forEach(c=>{
      const o=document.createElement('option');o.value=c;o.textContent=c;cfsel.appendChild(o);
    });
    cfsel.value = cur;
  }
  // years
  const yrsel = document.getElementById('tf-year');
  if(yrsel){
    const cur = yrsel.value;
    yrsel.innerHTML = '<option value="">كل السنوات</option>';
    const years = [...new Set(S.tasks.flatMap(t=>[t.orderDate,t.deadline]).filter(Boolean).map(d=>d.slice(0,4)))].sort();
    years.forEach(y=>{const o=document.createElement('option');o.value=y;o.textContent=y;yrsel.appendChild(o);});
    yrsel.value = cur;
  }
}

function applyTaskFilters(){
  taskFilterState.status   = document.getElementById('tf-status')?.value||'';
  taskFilterState.priority = document.getElementById('tf-priority')?.value||'';
  taskFilterState.jobtype  = document.getElementById('tf-jobtype')?.value||'';
  taskFilterState.client   = document.getElementById('tf-client')?.value||'';
  taskFilterState.month    = document.getElementById('tf-month')?.value||'';
  taskFilterState.year     = document.getElementById('tf-year')?.value||'';
  taskFilterState.search   = (document.getElementById('tf-search')?.value||'').trim().toLowerCase();
  renderTasks();
}

function resetTaskFilters(){
  ['tf-status','tf-priority','tf-jobtype','tf-client','tf-month','tf-year'].forEach(id=>{
    const el=document.getElementById(id);if(el)el.value='';
  });
  const s=document.getElementById('tf-search');if(s)s.value='';
  taskFilterState={status:'',priority:'',jobtype:'',client:'',month:'',year:'',search:''};
  renderTasks();
}

function filterTasks(tasks){
  const f=taskFilterState;
  return tasks.filter(t=>{
    if(f.status   && (f.status==='done'?!t.done:f.status==='paused'?(t.status!=='paused'):(t.status!==f.status||t.done||t.status==='paused'))) return false;
    if(f.priority && t.priority!==f.priority) return false;
    if(f.jobtype  && (t.jobType||'freelance')!==f.jobtype) return false;
    if(f.client   && t.client!==f.client) return false;
    if(f.month||f.year){
      const d = t.orderDate||t.deadline||'';
      if(!d) return false;
      const [yr,mo] = d.split('-');
      if(f.month && mo !== f.month.padStart(2,'0')) return false;
      if(f.year  && yr !== f.year) return false;
    }
    if(f.search){
      const hay = (t.title+' '+(t.client||'')+' '+(t.notes||'')).toLowerCase();
      if(!hay.includes(f.search)) return false;
    }
    return true;
  });
}

/* â”€â”€ Client Filters â”€â”€ */
function setCFType(val, btn){
  document.querySelectorAll('.cf-type-btn').forEach(b=>b.classList.remove('active'));
  if(btn) btn.classList.add('active');
  const el=document.getElementById('cf-type'); if(el) el.value=val;
  renderClients();
}
function setCFChannel(val, btn){
  document.querySelectorAll('.cf-ch-btn').forEach(b=>b.classList.remove('active'));
  if(btn) btn.classList.add('active');
  const el=document.getElementById('cf-channel'); if(el) el.value=val;
  renderClients();
}
function applyClientFilters(){
  renderClients();
}
function resetClientFilters(){
  ['cf-type','cf-channel'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  document.querySelectorAll('.cf-type-btn').forEach((b,i)=>b.classList.toggle('active',i===0));
  document.querySelectorAll('.cf-ch-btn').forEach((b,i)=>b.classList.toggle('active',i===0));
  const s=document.getElementById('cf-search');if(s)s.value='';
  renderClients();
}

/* فلتر مهام داخل ملف العميل */
function filterClientProfileTasks(clientName){
  const statusF = document.getElementById('cp-tf-status')?.value||'';
  const monthF  = document.getElementById('cp-tf-month')?.value||'';
  const tbody = document.getElementById('cp-tasks-tbody');
  if(!tbody) return;
  tbody.querySelectorAll('tr').forEach(tr=>{
    const order  = tr.dataset.order||'';
    const status = tr.dataset.status||'';
    let show = true;
    if(statusF && status !== statusF) show = false;
    if(monthF  && !order.includes('-'+monthF+'-') && order.slice(5,7) !== monthF) show = false;
    tr.style.display = show ? '' : 'none';
  });
}

/* â”€â”€ Quill editor instance â”€â”€ */
let taskQuill = null;
