/* Final recurring project behavior v7 */
(function(){
  function esc(v){ return String(v==null?'':v).replace(/[&<>"']/g,function(c){return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c];}); }
  function num(v){ var n=parseFloat(v); return isNaN(n)?0:n; }
  function money(v, cur){ return num(v).toLocaleString('ar-EG')+' '+(cur||'ج.م'); }
  function projectById(id){ return (S.projects||[]).find(function(p){ return String(p.id)===String(id); }); }
  function saveState(){ try{ lsSave(); }catch(e){} try{ if(typeof cloudSave==='function') cloudSave(S); }catch(e){} }
  function tasksForProject(id){ return (S.project_tasks||[]).filter(function(t){ return String(t.project_id)===String(id); }); }
  function ledgerRows(p){ return Array.isArray(p&&p.projectLedger) ? p.projectLedger : []; }
  function childProjects(parentId){ return (S.projects||[]).filter(function(p){ return String(p.parentProjectId||'')===String(parentId); }).sort(function(a,b){ return String(a.createdAt||a.start||'').localeCompare(String(b.createdAt||b.start||'')); }); }
  function parentPeriods(parent){
    var kids=childProjects(parent.id), byProject={};
    kids.forEach(function(k){ byProject[String(k.id)]=true; });
    var legacy=(parent.subProjects||[]).filter(function(sp){ return !sp.projectId || !byProject[String(sp.projectId)]; });
    return kids.map(function(k){ return {id:k.parentPeriodId||k.id,projectId:k.id,name:k.parentPeriodName||k.name,budget:k.budget,start:k.start,deadline:k.deadline,desc:k.desc,child:k}; }).concat(legacy);
  }
  function periodSummary(sp){
    var p=sp.child || (sp.projectId ? projectById(sp.projectId) : null);
    var tasks=p ? tasksForProject(p.id) : [];
    var ledger=p ? ledgerRows(p) : [];
    var collected=ledger.filter(function(r){ return r.kind==='client_payment'; }).reduce(function(s,r){ return s+num(r.amount); },0);
    var teamPaid=ledger.filter(function(r){ return r.kind==='team_payout'; }).reduce(function(s,r){ return s+num(r.amount); },0);
    var expenses=ledger.filter(function(r){ return r.kind==='project_expense'; }).reduce(function(s,r){ return s+num(r.amount); },0);
    var spent=teamPaid+expenses;
    var taskCost=tasks.reduce(function(s,t){ return s+num(t.value||t.workerAmount); },0);
    var done=tasks.filter(function(t){ return t.status==='done'||t.done; }).length;
    return {project:p,tasks:tasks,ledger:ledger,collected:collected,teamPaid:teamPaid,expenses:expenses,spent:spent,taskCost:taskCost,profit:collected-spent,done:done,pct:tasks.length?Math.round(done/tasks.length*100):0};
  }
  function parentFinance(parent){
    return parentPeriods(parent).reduce(function(acc,sp){
      var s=periodSummary(sp);
      acc.periods.push(sp); acc.budget+=num(sp.budget); acc.tasks+=s.tasks.length; acc.done+=s.done; acc.collected+=s.collected; acc.spent+=s.spent; acc.profit+=s.profit; acc.taskCost+=s.taskCost;
      acc.ledger=acc.ledger.concat(s.ledger.map(function(r){ return Object.assign({periodName:sp.name,periodProjectId:sp.projectId||''},r); }));
      return acc;
    },{periods:[],budget:0,tasks:0,done:0,collected:0,spent:0,profit:0,taskCost:0,ledger:[]});
  }
  function selectedProjectType(){ return (document.querySelector('input[name="proj-type"]:checked')||{}).value||'tasks'; }
  function syncParentFinanceFields(){
    var isParent=selectedProjectType()==='parent';
    var finance=document.getElementById('project-finance-section') || document.querySelector('#modal-project .project-modal-v4-section:nth-of-type(4)');
    if(finance){ finance.id='project-finance-section'; finance.style.display=isParent?'none':''; }
    var budget=document.getElementById('proj-budget'), dep=document.getElementById('proj-deposit-amount'), pay=document.getElementById('proj-payment-status');
    if(isParent){ if(budget) budget.value=0; if(dep) dep.value=0; if(pay) pay.value='none'; }
  }
  var prevType=window.onProjTypeChange;
  window.onProjTypeChange=function(){ if(prevType) prevType.apply(this,arguments); syncParentFinanceFields(); };
  try{ onProjTypeChange=window.onProjTypeChange; }catch(e){}

  var prevOpen=window.openProjectModal;
  window.openProjectModal=function(id){
    if(prevOpen) prevOpen.apply(this,arguments);
    var finance=document.querySelector('#modal-project .project-modal-v4-section:nth-of-type(4)');
    if(finance) finance.id='project-finance-section';
    var hint=document.querySelector('#modal-project .project-modal-v4-head p');
    if(hint) hint.textContent='المشروع المتجدد لا يحمل ميزانية مباشرة؛ كل شهر أو مرحلة لها ميزانيتها وحركاتها.';
    setTimeout(syncParentFinanceFields,0);
  };
  try{ openProjectModal=window.openProjectModal; }catch(e){}

  var prevSave=window.saveProject;
  window.saveProject=function(){
    if(selectedProjectType()==='parent'){
      var budget=document.getElementById('proj-budget'), dep=document.getElementById('proj-deposit-amount'), pay=document.getElementById('proj-payment-status');
      if(budget) budget.value=0; if(dep) dep.value=0; if(pay) pay.value='none';
    }
    if(prevSave) return prevSave.apply(this,arguments);
  };
  try{ saveProject=window.saveProject; }catch(e){}

  window.deleteProjectPeriod=function(parentId, periodId){
    var parent=projectById(parentId); if(!parent) return;
    var sp=parentPeriods(parent).find(function(x){ return String(x.id)===String(periodId) || String(x.projectId||'')===String(periodId); });
    if(!sp) return;
    confirmDel('حذف الشهر / المرحلة: '+(sp.name||'مرحلة')+'؟ سيتم حذف مشروع الشهر ومهامه وحركاته المالية.',function(){
      if(sp.projectId){
        S.project_tasks=(S.project_tasks||[]).filter(function(t){ return String(t.project_id)!==String(sp.projectId); });
        S.projects=(S.projects||[]).filter(function(p){ return String(p.id)!==String(sp.projectId); });
      }
      parent.subProjects=(parent.subProjects||[]).filter(function(x){ return String(x.id)!==String(sp.id) && String(x.projectId||'')!==String(sp.projectId||''); });
      saveState();
      if(typeof renderProjects==='function') renderProjects();
      if(typeof renderProjectDetail==='function') renderProjectDetail();
      if(typeof toast==='function') toast('<i class="fa-solid fa-trash"></i> تم حذف الشهر / المرحلة');
    });
  };

  window.openParentStatement=function(parentId, periodId){
    var parent=projectById(parentId); if(!parent) return;
    var periods=parentPeriods(parent).filter(function(sp){ return !periodId || String(sp.id)===String(periodId) || String(sp.projectId||'')===String(periodId); });
    var cur=parent.budgetCurrency||'ج.م';
    var totals=periods.reduce(function(acc,sp){ var s=periodSummary(sp); acc.budget+=num(sp.budget); acc.collected+=s.collected; acc.spent+=s.spent; acc.profit+=s.profit; acc.rows=acc.rows.concat(s.ledger.map(function(r){return Object.assign({periodName:sp.name},r);})); return acc; },{budget:0,collected:0,spent:0,profit:0,rows:[]});
    var rows=totals.rows.sort(function(a,b){return String(b.date||'').localeCompare(String(a.date||''));}).map(function(r){ var inc=r.kind==='client_payment'; return '<tr><td>'+esc(r.periodName||'-')+'</td><td>'+esc(r.date||'')+'</td><td>'+esc(r.kind||'')+'</td><td>'+esc(r.desc||'')+'</td><td class="'+(inc?'income':'expense')+'">'+(inc?'+':'-')+money(r.amount,r.currency||cur)+'</td></tr>'; }).join('');
    var ov=document.createElement('div'); ov.className='modal-overlay'; ov.style.display='flex';
    ov.innerHTML='<div class="modal project-statement-v6"><div class="project-period-v5-head"><div><h2><i class="fa-solid fa-file-invoice-dollar"></i> كشف حساب '+(periodId?'الشهر':'كل الشهور')+'</h2><p>'+esc(parent.name)+'</p></div><button class="close-btn" onclick="this.closest(&quot;.modal-overlay&quot;).remove()"><i class="fa-solid fa-xmark"></i></button></div><div class="project-statement-v6-body"><div class="project-statement-v6-kpis"><span><b>'+money(totals.budget,cur)+'</b><small>الميزانيات</small></span><span><b>'+money(totals.collected,cur)+'</b><small>محصل</small></span><span><b>'+money(totals.spent,cur)+'</b><small>مصروف</small></span><span><b>'+money(totals.profit,cur)+'</b><small>صافي ربح</small></span></div><div class="project-statement-v6-table"><table><thead><tr><th>الشهر</th><th>التاريخ</th><th>النوع</th><th>الوصف</th><th>المبلغ</th></tr></thead><tbody>'+(rows||'<tr><td colspan="5">لا توجد حركات مالية بعد</td></tr>')+'</tbody></table></div></div><div class="project-period-v5-footer"><button class="btn btn-ghost" onclick="window.print()"><i class="fa-solid fa-print"></i> طباعة</button><button class="btn btn-primary" onclick="this.closest(&quot;.modal-overlay&quot;).remove()">تم</button></div></div>';
    document.body.appendChild(ov);
  };

  function financeReport(parent,f){
    var cur=parent.budgetCurrency||'ج.م';
    var rows=f.periods.map(function(sp){ var s=periodSummary(sp); return '<tr><td>'+esc(sp.name||'مرحلة')+'</td><td>'+money(sp.budget,cur)+'</td><td>'+money(s.collected,cur)+'</td><td>'+money(s.spent,cur)+'</td><td class="'+(s.profit>=0?'income':'expense')+'">'+money(s.profit,cur)+'</td><td><button class="btn btn-ghost btn-sm" onclick="openParentStatement(&quot;'+esc(parent.id)+'&quot;,&quot;'+esc(sp.id||sp.projectId)+'&quot;)"><i class="fa-solid fa-file-lines"></i></button></td></tr>'; }).join('');
    return '<section class="project-recurring-v6-panel"><div class="project-recurring-v6-panel-head"><div><h2><i class="fa-solid fa-chart-line"></i> تقرير مالية الشهور</h2><p>ملخص الميزانية، التحصيل، المصروف، والربح لكل شهر.</p></div><button class="btn btn-primary btn-sm" onclick="openParentStatement(&quot;'+esc(parent.id)+'&quot;)"><i class="fa-solid fa-file-invoice-dollar"></i> كشف كل الشهور</button></div><div class="project-recurring-v6-table"><table><thead><tr><th>الشهر</th><th>الميزانية</th><th>محصل</th><th>مصروف</th><th>صافي الربح</th><th>كشف</th></tr></thead><tbody>'+(rows||'<tr><td colspan="6">لا توجد شهور بعد</td></tr>')+'</tbody></table></div></section>';
  }
  function movementReport(parent,f){
    var cur=parent.budgetCurrency||'ج.م';
    var rows=f.ledger.sort(function(a,b){return String(b.date||'').localeCompare(String(a.date||''));}).slice(0,12).map(function(r){ var inc=r.kind==='client_payment'; return '<div class="project-recurring-v6-move '+(inc?'income':'expense')+'"><span><i class="fa-solid '+(inc?'fa-arrow-down':'fa-arrow-up')+'"></i></span><div><b>'+esc(r.desc||r.kind)+'</b><small>'+esc(r.periodName||'')+' · '+esc(r.date||'')+'</small></div><strong>'+(inc?'+':'-')+money(r.amount,r.currency||cur)+'</strong></div>'; }).join('');
    return '<section class="project-recurring-v6-panel"><div class="project-recurring-v6-panel-head"><div><h2><i class="fa-solid fa-clock-rotate-left"></i> تقرير حركة كل الشهور</h2><p>آخر التحصيلات والمصروفات من كل الشهور.</p></div></div>'+(rows?'<div class="project-recurring-v6-moves">'+rows+'</div>':'<div class="project-recurring-v5-empty small"><b>لا توجد حركات بعد</b></div>')+'</section>';
  }
  function periodCard(parent,sp){
    var s=periodSummary(sp), cur=parent.budgetCurrency||'ج.م';
    return '<article class="project-period-v5-card" onclick="openProjectPeriod(&quot;'+esc(parent.id)+'&quot;,&quot;'+esc(sp.id||sp.projectId)+'&quot;)"><div class="project-period-v5-card-head"><span><i class="fa-solid fa-calendar-days"></i></span><div class="project-period-v6-actions"><button title="تعديل" onclick="event.stopPropagation();openProjectPeriodModal(&quot;'+esc(parent.id)+'&quot;,&quot;'+esc(sp.id||sp.projectId)+'&quot;)"><i class="fa-solid fa-pen"></i></button><button class="danger" title="حذف" onclick="event.stopPropagation();deleteProjectPeriod(&quot;'+esc(parent.id)+'&quot;,&quot;'+esc(sp.id||sp.projectId)+'&quot;)"><i class="fa-solid fa-trash"></i></button></div></div><h3>'+esc(sp.name||'مرحلة')+'</h3><p>'+esc(sp.start||'بدون بداية')+' - '+esc(sp.deadline||'بدون موعد نهائي')+'</p><div class="project-period-v5-stats"><span><b>'+money(sp.budget,cur)+'</b><small>ميزانية</small></span><span><b>'+money(s.spent,cur)+'</b><small>مصروف</small></span><span><b>'+money(s.profit,cur)+'</b><small>ربح</small></span></div><div class="project-period-v5-stats"><span><b>'+s.tasks.length+'</b><small>مهام</small></span><span><b>'+s.pct+'%</b><small>تقدم</small></span><span><b>'+money(s.collected,cur)+'</b><small>محصل</small></span></div><div class="project-period-v5-progress"><i style="width:'+s.pct+'%;background:'+(s.project&&s.project.color||parent.color||'#7c6ff7')+'"></i></div></article>';
  }
  var prevRender=window.renderProjectDetail;
  window.renderProjectDetail=function(){
    var id=window._currentProjId || (typeof _currentProjId!=='undefined' ? _currentProjId : '');
    var parent=projectById(id);
    if(!(parent && parent.projectKind==='parent' && !parent.parentProjectId)){ if(prevRender) return prevRender.apply(this,arguments); return; }
    var clr=parent.color||'#7c6ff7', f=parentFinance(parent), cur=parent.budgetCurrency||'ج.م';
    var inner=document.getElementById('proj-detail-inner'); if(!inner) return;
    inner.innerHTML='<div class="project-recurring-v5" style="--project-color:'+clr+'"><header class="project-recurring-v5-head"><button class="project-v2-back" onclick="showPage(&quot;projects&quot;)"><i class="fa-solid fa-arrow-right"></i></button><div class="project-recurring-v5-title"><span style="background:'+clr+'"></span><div><h1>'+esc(parent.name)+'</h1><p>مشروع رئيسي متجدد</p></div></div><div class="project-recurring-v5-actions"><button class="btn btn-primary btn-sm" onclick="openProjectPeriodModal(&quot;'+esc(parent.id)+'&quot;)"><i class="fa-solid fa-plus"></i> شهر / مرحلة</button><button class="btn btn-ghost btn-sm" onclick="openProjectModal(&quot;'+esc(parent.id)+'&quot;)"><i class="fa-solid fa-pen"></i></button></div></header><section class="project-recurring-v5-hero"><div><b>إدارة شهرية داخل مشروع واحد</b><span>ميزانية المشروع الرئيسي لا تسجل هنا. كل شهر أو مرحلة له ميزانيته وحركاته، وهذه الصفحة تجمع التقارير فقط.</span></div><button class="btn btn-primary" onclick="openProjectPeriodModal(&quot;'+esc(parent.id)+'&quot;)"><i class="fa-solid fa-calendar-plus"></i> إنشاء شهر / مرحلة</button></section><section class="project-recurring-v5-kpis project-recurring-v6-kpis"><span><b>'+f.periods.length+'</b><small>شهور / مراحل</small></span><span><b>'+money(f.budget,cur)+'</b><small>إجمالي ميزانيات الشهور</small></span><span><b>'+money(f.spent,cur)+'</b><small>إجمالي المصروف</small></span><span><b>'+money(f.profit,cur)+'</b><small>إجمالي صافي الربح</small></span><span><b>'+money(f.collected,cur)+'</b><small>إجمالي المحصل</small></span><span><b>'+f.tasks+'</b><small>إجمالي المهام</small></span><span><b>'+f.done+'</b><small>مهام مكتملة</small></span><span><b>'+money(f.taskCost,cur)+'</b><small>تكلفة المهام</small></span></section>'+financeReport(parent,f)+movementReport(parent,f)+'<section class="project-recurring-v5-list"><div class="project-recurring-v5-list-head"><div><h2>الشهور والمراحل</h2><p>اضغط على أي شهر لفتح تفاصيل المشروع الخاصة به.</p></div><button class="btn btn-ghost btn-sm" onclick="openProjectPeriodModal(&quot;'+esc(parent.id)+'&quot;)"><i class="fa-solid fa-plus"></i></button></div>'+(f.periods.length?'<div class="project-period-v5-grid">'+f.periods.map(function(sp){return periodCard(parent,sp);}).join('')+'</div>':'<div class="project-recurring-v5-empty"><i class="fa-solid fa-calendar-plus"></i><b>لا توجد شهور أو مراحل بعد</b><span>ابدأ بإنشاء الشهر الأول. كل شهر سيظهر كمشروع مستقل بتفاصيله المالية والمهام.</span><button class="btn btn-primary" onclick="openProjectPeriodModal(&quot;'+esc(parent.id)+'&quot;)"><i class="fa-solid fa-plus"></i> إنشاء شهر / مرحلة</button></div>')+'</section></div>';
  };
  try{ renderProjectDetail=window.renderProjectDetail; }catch(e){}
})();

/* Projects/team finance fixes: deposits, assignees, scoped kanban, and team detail page */
(function(){
  function esc(v){ return typeof escapeHtml === 'function' ? escapeHtml(v == null ? '' : String(v)) : String(v == null ? '' : v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); }
  function strip(v){ return String(v || '').replace(/<[^>]*>/g,'').replace(/\s+/g,' ').trim(); }
  function num(v){ return +v || 0; }
  function today(){ return new Date().toISOString().slice(0,10); }
  function money(v, cur){ return num(v).toLocaleString('ar-EG')+' '+(cur || 'ج.م'); }
  function projectById(id){ return (S.projects || []).find(function(p){ return String(p.id) === String(id); }); }
  function projectTasks(id){ return (S.project_tasks || []).filter(function(t){ return String(t.project_id) === String(id); }); }
  function ledger(p){ if(!p.projectLedger) p.projectLedger = []; return p.projectLedger; }
  function saveState(){ try { lsSave(); } catch(e) {} try { if(typeof cloudSave === 'function') cloudSave(S); } catch(e) {} }
  function currentIdentity(){
    var s = S.settings || {};
    return {
      id: (typeof _supaUserId !== 'undefined' && _supaUserId) ? String(_supaUserId) : '',
      names: [s.name, s.username, s.studio, s.email, s.phone, 'me', 'أنا', 'أنا (أنت)'].map(strip).filter(Boolean).map(function(x){return x.toLowerCase();}),
      emails: [s.email].map(strip).filter(Boolean).map(function(x){return x.toLowerCase();})
    };
  }
  function normalizeMember(m, team){
    m = Object.assign({}, m || {});
    return {
      id: String(m.id || m.linkedUserId || m.email || m.name || ('m_'+Math.random())).trim(),
      name: strip(m.name || m.email || 'عضو'),
      email: strip(m.email || '').toLowerCase(),
      phone: strip(m.phone || ''),
      role: strip(m.role || m.specialty || 'عضو'),
      linkedUserId: String(m.linkedUserId || m.user_id || '').trim(),
      rate: num(m.rate),
      teamId: team ? String(team.id) : '',
      teamName: team ? strip(team.name) : ''
    };
  }
  function teamGroups(){
    var groups = [];
    (S.teams || []).forEach(function(t){
      if(t && Array.isArray(t.members)){
        groups.push({
          id: String(t.id),
          name: strip(t.name || 'فريق'),
          desc: strip(t.desc || ''),
          ownerName: strip(t.ownerName || (S.settings && S.settings.name) || 'المسؤول'),
          specialty: strip(t.specialty || t.desc || ''),
          members: t.members.map(function(m){ return normalizeMember(m, t); }).filter(function(m){ return m.name; })
        });
      } else if(t && (t.name || t.email)){
        var legacy = {id:'legacy_team', name:'الفريق العام', desc:'', ownerName:strip((S.settings||{}).name || 'المسؤول'), members:[]};
        legacy.members.push(normalizeMember(t, legacy));
        groups.push(legacy);
      }
    });
    var byId = {};
    groups.forEach(function(g){
      if(!byId[g.id]) byId[g.id] = g;
      else byId[g.id].members = byId[g.id].members.concat(g.members || []);
    });
    return Object.keys(byId).map(function(k){
      var seen = {};
      byId[k].members = (byId[k].members || []).filter(function(m){
        var key = String(m.id || m.email || m.name);
        if(seen[key]) return false;
        seen[key] = true;
        return true;
      });
      return byId[k];
    });
  }
  function allMembers(){
    var arr = [];
    teamGroups().forEach(function(g){ arr = arr.concat(g.members || []); });
    var seen = {};
    var me = normalizeMember({id:'me', name:(S.settings && S.settings.name) || 'أنا (أنت)', email:(S.settings||{}).email || '', role:'مالك'}, null);
    arr.unshift(me);
    return arr.filter(function(m){
      var key = String(m.id || m.email || m.name);
      if(seen[key]) return false;
      seen[key] = true;
      return true;
    });
  }
  function selectedProjectMembers(){
    return Array.from(document.querySelectorAll('#proj-members-select .selected')).map(function(el){
      return {
        id: el.dataset.mid || '',
        name: el.dataset.mname || '',
        email: el.dataset.email || '',
        role: el.dataset.role || '',
        linkedUserId: el.dataset.userid || '',
        teamId: el.dataset.teamid || '',
        teamName: el.dataset.teamname || ''
      };
    });
  }
  function isMineProjectTask(t){
    if(!t) return false;
    if(!t.assignee_id && !t.assignee_name && !t.assignee_email && !t.assignee_user_id) return true;
    var me = currentIdentity();
    var ids = [t.assignee_id, t.assignee_user_id, t.linkedUserId, t.assigneeLinkedUserId].map(function(x){ return String(x || '').trim(); }).filter(Boolean);
    if(me.id && ids.indexOf(me.id) >= 0) return true;
    if(String(t.assignee_id || '') === 'me') return true;
    var email = strip(t.assignee_email || t.email || '').toLowerCase();
    if(email && me.emails.indexOf(email) >= 0) return true;
    var name = strip(t.assignee_name || '').toLowerCase();
    return !!(name && me.names.indexOf(name) >= 0);
  }
  function financeSummary(proj, tasks){
    var rows = ledger(proj);
    var cur = proj.budgetCurrency || 'ج.م';
    var budget = num(proj.budget) || tasks.reduce(function(s,t){ return s + num(t.value); },0);
    var taskCost = tasks.reduce(function(s,t){ return s + num(t.value); },0);
    var collected = rows.filter(function(r){ return r.kind === 'client_payment'; }).reduce(function(s,r){ return s + num(r.amount); },0);
    if(!collected){
      collected = tasks.filter(function(t){ return t.paymentCollected || t.paymentStatus === 'collected'; }).reduce(function(s,t){ return s + num(t.value); },0)
        + tasks.filter(function(t){ return t.paymentStatus === 'deposit' || num(t.deposit) > 0; }).reduce(function(s,t){ return s + num(t.deposit); },0);
    }
    var paidTeam = rows.filter(function(r){ return r.kind === 'team_payout'; }).reduce(function(s,r){ return s + num(r.amount); },0);
    var expenses = rows.filter(function(r){ return r.kind === 'project_expense'; }).reduce(function(s,r){ return s + num(r.amount); },0);
    var posted = rows.filter(function(r){ return r.kind === 'main_post'; }).reduce(function(s,r){ return s + num(r.amount); },0);
    var remainingClient = Math.max(0, budget - collected);
    var remainingBudget = budget - taskCost - paidTeam - expenses;
    return {cur:cur,budget:budget,taskCost:taskCost,collected:collected,paidTeam:paidTeam,expenses:expenses,posted:posted,remainingClient:remainingClient,remainingBudget:remainingBudget,balance:collected-paidTeam-expenses-posted};
  }
  function financeStrip(proj, tasks){
    var f = financeSummary(proj, tasks);
    return '<section class="project-v3-strip">'+
      '<div><b>'+tasks.length+'</b><span>مهام المشروع</span></div>'+
      '<div><b>'+money(f.taskCost,f.cur)+'</b><span>تكلفة المهام</span></div>'+
      '<div><b>'+money(f.budget,f.cur)+'</b><span>ميزانية المشروع</span></div>'+
      '<div class="ok"><b>'+money(f.collected,f.cur)+'</b><span>محصل</span></div>'+
      '<div class="warn"><b>'+money(f.remainingBudget,f.cur)+'</b><span>متبقي من الميزانية</span></div>'+
    '</section>';
  }
  function ensureProjectInitialPayment(proj, amount, status, oldAmount){
    if(!proj || !amount || status === 'none') return;
    var rows = ledger(proj);
    var row = rows.find(function(r){ return r.kind === 'client_payment' && r.source === 'project_initial_payment'; });
    var desc = status === 'full' ? 'تحصيل كامل عند إنشاء المشروع' : 'عربون مشروع';
    if(row){
      row.amount = amount;
      row.desc = desc;
      row.currency = proj.budgetCurrency || row.currency || 'ج.م';
      row.date = row.date || today();
    } else if(amount !== oldAmount){
      rows.push({id:'pl_'+Date.now()+Math.random(),kind:'client_payment',source:'project_initial_payment',amount:amount,currency:proj.budgetCurrency||'ج.م',date:today(),desc:desc,posted:false,createdAt:new Date().toISOString()});
    }
  }

  window.toggleProjectDepositField = function(){
    var st = (document.getElementById('proj-payment-status') || {}).value || 'none';
    var wrap = document.getElementById('proj-deposit-wrap');
    var label = wrap && wrap.querySelector('.form-label');
    if(wrap) wrap.style.display = st === 'none' ? 'none' : '';
    if(label) label.textContent = st === 'full' ? 'المبلغ المحصل' : 'قيمة العربون';
  };

  window._getTeamGroups = teamGroups;
  try { _getTeamGroups = window._getTeamGroups; } catch(e) {}

  window._renderProjMembersSelect = function(selected){
    var container = document.getElementById('proj-members-select'); if(!container) return;
    selected = (selected || []).map(function(m){ return normalizeMember(m, null); });
    var selectedKeys = {};
    selected.forEach(function(m){ selectedKeys[String(m.id)] = true; selectedKeys[String(m.email)] = true; selectedKeys[String(m.name)] = true; });
    var members = allMembers();
    container.innerHTML = members.length ? members.map(function(m){
      var isSel = !!(selectedKeys[String(m.id)] || selectedKeys[String(m.email)] || selectedKeys[String(m.name)]);
      return '<button type="button" class="proj-member-toggle '+(isSel?'selected':'')+'" data-mid="'+esc(m.id)+'" data-mname="'+esc(m.name)+'" data-email="'+esc(m.email)+'" data-role="'+esc(m.role)+'" data-userid="'+esc(m.linkedUserId)+'" data-teamid="'+esc(m.teamId)+'" data-teamname="'+esc(m.teamName)+'" onclick="toggleProjMember(this)">'+
        '<span>'+esc((m.name || '?').slice(0,1))+'</span><b>'+esc(m.name)+'</b><small>'+esc(m.role || m.teamName || 'عضو')+'</small>'+
      '</button>';
    }).join('') : '<div class="team-v2-no-members">لا يوجد أعضاء. أضف أعضاء من قسم الفريق أولاً.</div>';
  };
  try { _renderProjMembersSelect = window._renderProjMembersSelect; } catch(e) {}

  window.onProjTeamChange = function(teamGroupId){
    if(!teamGroupId){ window._renderProjMembersSelect([]); return; }
    var group = teamGroups().find(function(g){ return String(g.id) === String(teamGroupId); });
    window._renderProjMembersSelect(group ? group.members : []);
  };
  try { onProjTeamChange = window.onProjTeamChange; } catch(e) {}

  var oldOpenProjectModal = window.openProjectModal || (typeof openProjectModal === 'function' ? openProjectModal : null);
  window.openProjectModal = function(id){
    if(oldOpenProjectModal) oldOpenProjectModal(id);
    var proj = id ? projectById(id) : null;
    var modal = document.querySelector('#modal-project .modal');
    if(modal) modal.classList.add('project-v3-modal');
    var pay = document.getElementById('proj-payment-status');
    var dep = document.getElementById('proj-deposit-amount');
    if(pay){
      pay.value = proj ? (proj.paymentStatus || (num(proj.depositAmount) ? 'deposit' : 'none')) : 'none';
    }
    if(dep) dep.value = proj ? (proj.depositAmount || '') : '';
    window.toggleProjectDepositField();
    var tsel = document.getElementById('proj-team-select');
    if(tsel){
      var groups = teamGroups();
      tsel.innerHTML = '<option value="">- اختر فريق اختياري -</option>'+groups.map(function(g){ return '<option value="'+esc(g.id)+'" '+(proj && String(proj.team_group_id)===String(g.id)?'selected':'')+'>'+esc(g.name)+' - '+(g.members||[]).length+' أعضاء</option>'; }).join('');
    }
    window._renderProjMembersSelect(proj ? (proj.members || []) : []);
  };
  try { openProjectModal = window.openProjectModal; } catch(e) {}

  window.saveProject = function(){
    var id = (document.getElementById('proj-eid') || {}).value || '';
    var old = id ? projectById(id) : null;
    var name = strip((document.getElementById('proj-name') || {}).value || '');
    if(!name){ toast('<i class="fa-solid fa-triangle-exclamation"></i> اسم المشروع مطلوب'); return; }
    if(!S.projects) S.projects = [];
    var paymentStatus = (document.getElementById('proj-payment-status') || {}).value || 'none';
    var depositAmount = paymentStatus === 'none' ? 0 : num((document.getElementById('proj-deposit-amount') || {}).value);
    var tsel = document.getElementById('proj-team-select');
    var data = Object.assign({}, old || {}, {
      id: old ? old.id : Date.now(),
      name: name,
      desc: strip((document.getElementById('proj-desc') || {}).value || ''),
      client_id: (document.getElementById('proj-client') || {}).value || '',
      status: (document.getElementById('proj-status') || {}).value || 'active',
      start: (document.getElementById('proj-start') || {}).value || '',
      deadline: (document.getElementById('proj-deadline') || {}).value || '',
      color: (document.getElementById('proj-color') || {}).value || '#7c6ff7',
      projectType: (document.getElementById('proj-type-team') && document.getElementById('proj-type-team').checked) ? 'team' : 'tasks',
      members: selectedProjectMembers(),
      team_group_id: tsel ? (tsel.value || '') : '',
      budget: num((document.getElementById('proj-budget') || {}).value),
      budgetCurrency: (document.getElementById('proj-budget-currency') || {}).value || 'ج.م',
      pricingType: (document.getElementById('proj-pricing-type') || {}).value || 'fixed',
      paymentStatus: paymentStatus,
      depositAmount: depositAmount,
      updatedAt: new Date().toISOString(),
      createdAt: old && old.createdAt || new Date().toISOString()
    });
    data.projectLedger = old && Array.isArray(old.projectLedger) ? old.projectLedger : [];
    ensureProjectInitialPayment(data, depositAmount, paymentStatus, old ? num(old.depositAmount) : 0);
    var idx = S.projects.findIndex(function(p){ return String(p.id) === String(data.id); });
    if(idx >= 0) S.projects[idx] = data;
    else S.projects.push(data);
    saveState();
    closeM('modal-project');
    if(typeof renderProjects === 'function') renderProjects();
    if(typeof renderProjectDetail === 'function' && String(window._currentProjId || _currentProjId || '') === String(data.id)) renderProjectDetail();
    toast('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم حفظ المشروع: '+name);
  };
  try { saveProject = window.saveProject; } catch(e) {}

  function memberOptions(members, selectedId){
    return '<option value="">- اختر المسؤول -</option>'+members.map(function(m){
      var sel = String(selectedId || '') === String(m.id) ? 'selected' : '';
      return '<option value="'+esc(m.id)+'" data-name="'+esc(m.name)+'" data-email="'+esc(m.email)+'" data-userid="'+esc(m.linkedUserId)+'" '+sel+'>'+esc(m.name)+' - '+esc(m.role || m.teamName || 'عضو')+'</option>';
    }).join('');
  }
  function membersForTask(proj, teamId){
    if(teamId){
      var g = teamGroups().find(function(x){ return String(x.id) === String(teamId); });
      return g ? g.members : [];
    }
    if(proj && (proj.members || []).length) return (proj.members || []).map(function(m){ return normalizeMember(m, null); });
    return allMembers();
  }
  window.onPtaskTeamChange = function(teamGroupId){
    var proj = projectById((document.getElementById('ptask-proj-id') || {}).value || '');
    var asel = document.getElementById('ptask-assignee'); if(!asel) return;
    var cur = asel.value;
    var members = membersForTask(proj, teamGroupId);
    asel.innerHTML = memberOptions(members, cur);
    if(!asel.value && members.some(function(m){ return String(m.id) === String(cur); })) asel.value = cur;
    var hint = document.getElementById('ptask-no-members-hint');
    if(hint) hint.style.display = members.length ? 'none' : 'block';
    var src = document.getElementById('ptask-assignee-src');
    if(src) src.textContent = teamGroupId ? '(من الفريق المحدد)' : (proj && (proj.members||[]).length ? '(من فريق المشروع)' : '(كل الأعضاء)');
  };
  try { onPtaskTeamChange = window.onPtaskTeamChange; } catch(e) {}

  window.openProjTaskModal = function(projId, taskId, defaultStatus){
    var proj = projectById(projId);
    var t = taskId ? (S.project_tasks || []).find(function(x){ return String(x.id) === String(taskId); }) : null;
    _ptaskSteps = t ? (t.steps || []).slice() : [];
    var set = function(id,v){ var el=document.getElementById(id); if(el) el.value = v == null ? '' : v; };
    var modal = document.querySelector('#modal-proj-task .modal'); if(modal) modal.classList.add('project-v3-task-modal');
    set('ptask-eid', taskId || '');
    set('ptask-proj-id', projId || '');
    var title = document.getElementById('proj-task-modal-title');
    if(title) title.innerHTML = t ? '<i class="fa-solid fa-pen"></i> تعديل مهمة مشروع' : '<i class="fa-solid fa-list-check"></i> مهمة جديدة داخل المشروع';
    set('ptask-title', t ? t.title : '');
    set('ptask-desc', t ? t.desc || '' : '');
    set('ptask-priority', t ? t.priority || 'normal' : 'normal');
    set('ptask-status', t ? t.status || 'todo' : (defaultStatus || 'todo'));
    set('ptask-deadline', t ? t.deadline || '' : '');
    set('ptask-orderdate', t ? t.orderDate || '' : today());
    set('ptask-value', t ? t.value || '' : '');
    set('ptask-currency', t ? t.currency || (proj && proj.budgetCurrency) || 'ج.م' : (proj && proj.budgetCurrency) || 'ج.م');
    var pay = t ? (t.paymentCollected ? 'collected' : (t.paymentStatus || (num(t.deposit) ? 'deposit' : 'pending'))) : 'pending';
    set('ptask-payment-status', pay);
    set('ptask-deposit', t ? t.deposit || '' : '');
    if(typeof togglePtaskDepositField === 'function') togglePtaskDepositField();
    var teamSel = document.getElementById('ptask-team-filter');
    if(teamSel){
      var groups = teamGroups();
      teamSel.innerHTML = '<option value="">- فريق المشروع / كل الأعضاء -</option>'+groups.map(function(g){ return '<option value="'+esc(g.id)+'">'+esc(g.name)+' - '+(g.members||[]).length+' أعضاء</option>'; }).join('');
      teamSel.value = proj && proj.team_group_id || '';
    }
    var asel = document.getElementById('ptask-assignee');
    if(asel){
      var members = membersForTask(proj, teamSel ? teamSel.value : '');
      var selected = t ? (t.assignee_id || '') : '';
      asel.innerHTML = memberOptions(members, selected);
    }
    var hint = document.getElementById('ptask-no-members-hint');
    if(hint) hint.style.display = asel && asel.options.length > 1 ? 'none' : 'block';
    var src = document.getElementById('ptask-assignee-src');
    if(src) src.textContent = proj && (proj.members||[]).length ? '(من فريق المشروع)' : '(كل الأعضاء)';
    if(typeof renderPtaskSteps === 'function') renderPtaskSteps();
    if(typeof _renderPtaskAssigneeInfo === 'function') _renderPtaskAssigneeInfo(t);
    openM('modal-proj-task');
    setTimeout(function(){ var x=document.getElementById('ptask-title'); if(x) x.focus(); },80);
  };
  try { openProjTaskModal = window.openProjTaskModal; } catch(e) {}

  window.saveProjTask = function(){
    var eid = (document.getElementById('ptask-eid') || {}).value || '';
    var projId = (document.getElementById('ptask-proj-id') || {}).value || '';
    var title = strip((document.getElementById('ptask-title') || {}).value || '');
    if(!title){ toast('<i class="fa-solid fa-triangle-exclamation"></i> عنوان المهمة مطلوب'); return; }
    var asel = document.getElementById('ptask-assignee');
    var opt = asel && asel.options[asel.selectedIndex];
    var payStatus = (document.getElementById('ptask-payment-status') || {}).value || 'pending';
    var depositVal = payStatus === 'deposit' ? num((document.getElementById('ptask-deposit') || {}).value) : 0;
    if(!S.project_tasks) S.project_tasks = [];
    var old = eid ? S.project_tasks.find(function(t){ return String(t.id) === String(eid); }) : null;
    var d = Object.assign({}, old || {}, {
      id: old ? old.id : Date.now(),
      title: title,
      desc: strip((document.getElementById('ptask-desc') || {}).value || ''),
      project_id: projId,
      priority: (document.getElementById('ptask-priority') || {}).value || 'normal',
      status: (document.getElementById('ptask-status') || {}).value || 'todo',
      orderDate: (document.getElementById('ptask-orderdate') || {}).value || '',
      deadline: (document.getElementById('ptask-deadline') || {}).value || '',
      value: num((document.getElementById('ptask-value') || {}).value),
      currency: (document.getElementById('ptask-currency') || {}).value || 'ج.م',
      paymentStatus: payStatus,
      paymentCollected: payStatus === 'collected',
      deposit: depositVal,
      assignee_id: asel ? asel.value || '' : '',
      assignee_name: opt ? (opt.dataset.name || '') : '',
      assignee_email: opt ? (opt.dataset.email || '') : '',
      assignee_user_id: opt ? (opt.dataset.userid || '') : '',
      steps: (_ptaskSteps || []).slice(),
      updatedAt: new Date().toISOString(),
      createdAt: old && old.createdAt || new Date().toISOString()
    });
    var idx = S.project_tasks.findIndex(function(t){ return String(t.id) === String(d.id); });
    if(idx >= 0) S.project_tasks[idx] = d;
    else S.project_tasks.push(d);
    var proj = projectById(projId);
    if(proj && (payStatus === 'deposit' || payStatus === 'collected') && (depositVal || d.value)){
      var amount = payStatus === 'collected' ? d.value : depositVal;
      var rows = ledger(proj);
      var row = rows.find(function(r){ return String(r.linkedProjTaskId) === String(d.id) && r.kind === 'client_payment'; });
      var desc = (payStatus === 'collected' ? 'تحصيل مهمة: ' : 'عربون مهمة: ') + d.title;
      if(row){ row.amount = amount; row.desc = desc; row.currency = d.currency; }
      else rows.push({id:'pl_'+Date.now()+Math.random(),kind:'client_payment',linkedProjTaskId:d.id,amount:amount,currency:d.currency,date:today(),desc:desc,posted:false,createdAt:new Date().toISOString()});
    }
    saveState();
    closeM('modal-proj-task');
    if(typeof renderProjectDetail === 'function') renderProjectDetail();
    if(typeof renderTasks === 'function') renderTasks();
    toast('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم حفظ مهمة المشروع');
  };
  try { saveProjTask = window.saveProjTask; } catch(e) {}

  var oldRenderProjTabContent = window.renderProjTabContent || (typeof renderProjTabContent === 'function' ? renderProjTabContent : null);
  window.renderProjTabContent = function(tab, proj, tasks, client, clr){
    tasks = tasks || projectTasks(proj.id);
    var base = oldRenderProjTabContent ? oldRenderProjTabContent(tab, proj, tasks, client, clr) : '';
    if(tab === 'finance'){
      var f = financeSummary(proj, tasks);
      return financeStrip(proj,tasks)+
        '<div class="project-v3-finance-note"><i class="fa-solid fa-circle-info"></i><span>المحصل هنا يشمل عربون المشروع وحركات التحصيل المسجلة داخل محفظة المشروع. لا يتم ترحيله للمالية الرئيسية إلا يدويًا.</span></div>'+
        base.replace('ميزانية المشروع', 'ميزانية المشروع');
    }
    return financeStrip(proj,tasks)+base;
  };
  try { renderProjTabContent = window.renderProjTabContent; } catch(e) {}

  function withScopedProjectKanban(fn){
    return function(){
      var mode = localStorage.getItem('studioTaskView') || 'kanban';
      if(mode !== 'kanban') return fn.apply(this, arguments);
      var original = S.project_tasks || [];
      S.project_tasks = original.filter(isMineProjectTask);
      try { return fn.apply(this, arguments); }
      finally { S.project_tasks = original; }
    };
  }
  if(typeof window._renderProjectTasksList === 'function') window._renderProjectTasksList = withScopedProjectKanban(window._renderProjectTasksList);
  try { if(typeof _renderProjectTasksList === 'function') _renderProjectTasksList = window._renderProjectTasksList; } catch(e) {}
  if(typeof window._renderAllTasksList === 'function') window._renderAllTasksList = withScopedProjectKanban(window._renderAllTasksList);
  try { if(typeof _renderAllTasksList === 'function') _renderAllTasksList = window._renderAllTasksList; } catch(e) {}

  function teamTasks(team){
    var names = {};
    (team.members || []).forEach(function(m){ names[strip(m.name)] = true; });
    var regular = (S.tasks || []).filter(function(t){ return names[strip(t.workerMember || '')]; });
    var project = (S.project_tasks || []).filter(function(t){ return names[strip(t.assignee_name || '')]; });
    return {regular:regular, project:project, all:regular.concat(project)};
  }
  function teamFinance(team){
    var names = {};
    (team.members || []).forEach(function(m){ names[strip(m.name)] = true; });
    var paid = 0, assigned = 0, collected = 0;
    (S.projects || []).forEach(function(p){
      (p.projectLedger || []).forEach(function(r){
        if(r.kind === 'team_payout' && names[strip(r.assignee_name || '')]) paid += num(r.amount);
        if(r.kind === 'client_payment') collected += num(r.amount);
      });
    });
    (S.project_tasks || []).forEach(function(t){ if(names[strip(t.assignee_name || '')]) assigned += num(t.value); });
    (S.tasks || []).forEach(function(t){ if(names[strip(t.workerMember || '')]) assigned += num(t.workerAmount || t.value); });
    return {paid:paid,assigned:assigned,collected:collected};
  }
  function teamSpecialty(team){
    if(team.specialty || team.desc) return strip(team.specialty || team.desc);
    var counts = {};
    (team.members || []).forEach(function(m){ var r=strip(m.role||'عام'); counts[r]=(counts[r]||0)+1; });
    return Object.keys(counts).sort(function(a,b){ return counts[b]-counts[a]; })[0] || 'عام';
  }
  window.renderTeams = function(){
    var grid = document.getElementById('teams-grid'); if(!grid) return;
    var teams = teamGroups();
    grid.className = 'team-v3-grid';
    var sub = document.querySelector('#page-team .page-subtitle');
    if(sub) sub.textContent = teams.length+' فرق · '+teams.reduce(function(s,t){return s+(t.members||[]).length;},0)+' أعضاء';
    if(!teams.length){
      grid.innerHTML = '<div class="team-v2-empty"><i class="fa-solid fa-people-group"></i><b>لا توجد فرق بعد</b><button class="btn btn-primary" onclick="_openNewTeamChooser()"><i class="fa-solid fa-plus"></i> فريق جديد</button></div>';
      return;
    }
    grid.innerHTML = teams.map(function(team){
      return '<article class="team-v3-card" onclick="openTeamDetail(&quot;'+esc(team.id)+'&quot;)">'+
        '<div class="team-v3-card-head"><span><i class="fa-solid fa-people-group"></i></span><button onclick="event.stopPropagation();openTeamModal(&quot;'+esc(team.id)+'&quot;)" title="تعديل"><i class="fa-solid fa-pen"></i></button></div>'+
        '<h3>'+esc(team.name)+'</h3>'+
        '<div class="team-v3-mini-meta"><b>'+esc(teamSpecialty(team))+'</b><span>'+esc(team.ownerName || 'المسؤول')+'</span></div>'+
        '<div class="team-v3-mini-stats"><span>'+((team.members||[]).length)+' أعضاء</span><span>اضغط للتفاصيل</span></div>'+
      '</article>';
    }).join('');
    if(typeof renderMyMemberTeams === 'function') renderMyMemberTeams();
  };
  try { renderTeams = window.renderTeams; } catch(e) {}

  window.openTeamDetail = function(teamId){
    var team = teamGroups().find(function(t){ return String(t.id) === String(teamId); });
    if(!team) return;
    var gridView = document.getElementById('teams-grid-view'); if(gridView) gridView.style.display = 'none';
    var memberProfile = document.getElementById('member-profile-view'); if(memberProfile) memberProfile.style.display = 'none';
    var view = document.getElementById('team-detail-view');
    if(!view){
      view = document.createElement('div');
      view.id = 'team-detail-view';
      var page = document.getElementById('page-team');
      if(page) page.appendChild(view);
    }
    var tt = teamTasks(team), fin = teamFinance(team);
    var active = tt.all.filter(function(t){ return !(t.done || t.status === 'done'); });
    var done = tt.all.filter(function(t){ return t.done || t.status === 'done'; });
    var thisMonth = new Date().toISOString().slice(0,7);
    var activity = tt.all.slice().sort(function(a,b){ return String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||'')); }).slice(0,8);
    view.style.display = 'block';
    view.innerHTML = '<div class="team-v3-detail">'+
      '<header><button class="project-v2-back" onclick="closeTeamDetail()"><i class="fa-solid fa-arrow-right"></i></button><div><h2>'+esc(team.name)+'</h2><p>'+esc(teamSpecialty(team))+' · المسؤول: '+esc(team.ownerName || 'المسؤول')+'</p></div><button class="btn btn-primary btn-sm" onclick="openTeamModal(&quot;'+esc(team.id)+'&quot;)"><i class="fa-solid fa-pen"></i> تعديل</button></header>'+
      '<section class="team-v3-stats">'+
        '<span><b>'+team.members.length+'</b><small>أعضاء</small></span><span><b>'+active.length+'</b><small>مهام نشطة</small></span><span><b>'+done.length+'</b><small>مكتملة</small></span><span><b>'+money(fin.assigned,'ج.م')+'</b><small>قيمة الشغل</small></span><span><b>'+money(fin.paid,'ج.م')+'</b><small>مدفوع للفريق</small></span>'+
      '</section>'+
      '<section class="team-v3-columns"><div class="team-v3-panel"><h3><i class="fa-solid fa-users"></i> الأعضاء</h3>'+team.members.map(function(m){ return '<button onclick="openTeamMemberProfile(&quot;'+esc(team.id)+'&quot;,&quot;'+esc(m.id || m.name)+'&quot;)"><span>'+esc((m.name||'?').slice(0,1))+'</span><b>'+esc(m.name)+'</b><small>'+esc(m.role || 'عضو')+'</small></button>'; }).join('')+'</div>'+
      '<div class="team-v3-panel"><h3><i class="fa-solid fa-list-check"></i> شغل الفريق</h3>'+(active.length?active.slice(0,8).map(function(t){ return '<div class="team-v3-work"><b>'+esc(t.title)+'</b><small>'+esc(t.project_id ? 'مهمة مشروع' : 'مهمة عامة')+(t.deadline?' · '+esc(t.deadline):'')+'</small></div>'; }).join(''):'<div class="tasks-v2-empty">لا مهام نشطة</div>')+'</div></section>'+
      '<section class="team-v3-columns"><div class="team-v3-panel"><h3><i class="fa-solid fa-wallet"></i> مالية الشهر</h3><div class="team-v3-money"><span><b>'+money(fin.assigned,'ج.م')+'</b><small>قيمة مسندة</small></span><span><b>'+money(fin.paid,'ج.م')+'</b><small>مدفوع</small></span><span><b>'+money(fin.assigned-fin.paid,'ج.م')+'</b><small>متبقي للفريق</small></span></div></div>'+
      '<div class="team-v3-panel"><h3><i class="fa-solid fa-clock-rotate-left"></i> سجل النشاط</h3>'+(activity.length?activity.map(function(t){ return '<div class="team-v3-activity"><b>'+esc(t.title)+'</b><small>'+esc(t.updatedAt || t.createdAt || 'بدون تاريخ')+'</small></div>'; }).join(''):'<div class="tasks-v2-empty">لا نشاط بعد</div>')+'</div></section>'+
    '</div>';
  };
  window.closeTeamDetail = function(){
    var view = document.getElementById('team-detail-view'); if(view) view.style.display = 'none';
    var gridView = document.getElementById('teams-grid-view'); if(gridView) gridView.style.display = 'block';
  };

  setTimeout(function(){
    if(typeof renderTeams === 'function') renderTeams();
    if(typeof renderProjects === 'function') renderProjects();
  },250);
})();

/* Team v2: editable members, cleaner cards, and member profile */
(function(){
  function esc(v){ return typeof escapeHtml === 'function' ? escapeHtml(v == null ? '' : String(v)) : String(v == null ? '' : v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); }
  function stripHtml(v){ return String(v || '').replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim(); }
  function cleanRole(v){
    var r = stripHtml(v);
    r = r.replace(/^(undefined|null)\s*/i,'').trim();
    return r || 'أخرى';
  }
  function cleanMember(m){
    m = Object.assign({}, m || {});
    m.name = stripHtml(m.name || '');
    m.role = cleanRole(m.role || 'أخرى');
    m.phone = stripHtml(m.phone || '');
    m.email = stripHtml(m.email || '').toLowerCase();
    m.extraSpecs = Array.isArray(m.extraSpecs) ? m.extraSpecs.map(stripHtml).filter(Boolean) : (typeof m.extraSpecs === 'string' ? m.extraSpecs.split(',').map(stripHtml).filter(Boolean) : []);
    m.rate = +m.rate || 0;
    if(!m.id) m.id = 'm_'+Date.now()+'_'+Math.random().toString(16).slice(2);
    return m;
  }
  function teamById(id){ return (S.teams || []).find(function(t){ return String(t.id) === String(id); }); }
  function memberKey(m){ return String(m.id || m.email || m.name || ''); }
  function findMember(teamId, memberIdOrName){
    var teams = teamId ? [teamById(teamId)].filter(Boolean) : (S.teams || []);
    for(var ti=0; ti<teams.length; ti++){
      var team = teams[ti];
      var members = team.members || [];
      for(var mi=0; mi<members.length; mi++){
        var m = cleanMember(members[mi]);
        if(String(m.id) === String(memberIdOrName) || String(m.email) === String(memberIdOrName) || String(m.name) === String(memberIdOrName)){
          return {team:team, member:m, index:mi};
        }
      }
    }
    return null;
  }
  function roleIcon(role){
    var r = cleanRole(role);
    if(r.indexOf('تصميم') >= 0) return 'fa-palette';
    if(r.indexOf('مونتاج') >= 0 || r.indexOf('فيديو') >= 0) return 'fa-clapperboard';
    if(r.indexOf('تطوير') >= 0 || r.indexOf('برمجة') >= 0) return 'fa-laptop-code';
    if(r.indexOf('تسويق') >= 0) return 'fa-bullhorn';
    if(r.indexOf('كتابة') >= 0 || r.indexOf('محتوى') >= 0) return 'fa-pen-nib';
    if(r.indexOf('مود') >= 0) return 'fa-comments';
    return 'fa-user';
  }
  function memberTasks(name){
    return (S.tasks || []).filter(function(t){ return String(t.workerMember || '') === String(name); });
  }
  function saveTeamState(){
    try { lsSave(); } catch(e) {}
    try { if(typeof cloudSave === 'function') cloudSave(S); } catch(e) {}
  }

  var oldOpenTeamModal = typeof openTeamModal === 'function' ? openTeamModal : null;
  window.openTeamModal = function(id){
    teamMembersForm = [];
    var title = document.getElementById('team-modal-ttl');
    if(title) title.innerHTML = id ? '<i class="fa-solid fa-users"></i> تعديل الفريق' : '<i class="fa-solid fa-users"></i> فريق جديد';
    var eid = document.getElementById('team-eid'); if(eid) eid.value = id || '';
    var team = id ? teamById(id) : null;
    var name = document.getElementById('team-name');
    var desc = document.getElementById('team-desc');
    if(name) name.value = team ? stripHtml(team.name) : '';
    if(desc) desc.value = team ? stripHtml(team.desc || '') : '';
    teamMembersForm = team ? (team.members || []).map(cleanMember) : [];
    window._teamV2EditMemberIndex = null;
    resetTeamMemberForm();
    renderTeamMembersForm();
    openM('modal-team');
    setTimeout(function(){ var n=document.getElementById('team-name'); if(n) n.focus(); },80);
  };
  try { openTeamModal = window.openTeamModal; } catch(e) {}

  window.renderTeamMembersForm = function(){
    var el = document.getElementById('team-members-list'); if(!el) return;
    teamMembersForm = (teamMembersForm || []).map(cleanMember);
    if(!teamMembersForm.length){
      el.innerHTML = '<div class="team-v2-member-empty"><i class="fa-solid fa-user-plus"></i><b>لا يوجد أعضاء بعد</b><span>أضف أعضاء الفريق من النموذج أسفل القائمة.</span></div>';
      return;
    }
    el.innerHTML = '<div class="team-v2-member-list">'+teamMembersForm.map(function(m,i){
      var tasks = memberTasks(m.name);
      return '<article class="team-v2-member-row">'+
        '<button type="button" class="team-v2-member-main" onclick="openTeamMemberProfile(null,&quot;'+esc(memberKey(m))+'&quot;)">'+
          '<span class="team-v2-avatar"><i class="fa-solid '+roleIcon(m.role)+'"></i></span>'+
          '<span><b>'+esc(m.name || 'عضو بدون اسم')+'</b><small>'+esc(m.role)+(m.email?' · '+esc(m.email):'')+(m.phone?' · '+esc(m.phone):'')+'</small></span>'+
        '</button>'+
        '<div class="team-v2-member-badges">'+
          (m.linked ? '<span class="ok"><i class="fa-solid fa-check"></i> حساب مرتبط</span>' : '')+
          (m.rate ? '<span>'+m.rate+'%</span>' : '')+
          (tasks.length ? '<span>'+tasks.length+' مهمة</span>' : '')+
        '</div>'+
        '<div class="team-v2-row-actions">'+
          '<button type="button" onclick="editTeamMemberInForm('+i+')" title="تعديل"><i class="fa-solid fa-pen"></i></button>'+
          '<button type="button" onclick="openTeamMemberProfile(null,&quot;'+esc(memberKey(m))+'&quot;)" title="البروفايل"><i class="fa-regular fa-eye"></i></button>'+
          '<button type="button" class="danger" onclick="removeTeamMember('+i+')" title="حذف"><i class="fa-solid fa-xmark"></i></button>'+
        '</div>'+
      '</article>';
    }).join('')+'</div>';
  };
  try { renderTeamMembersForm = window.renderTeamMembersForm; } catch(e) {}

  function resetTeamMemberForm(){
    ['member-name','member-phone','member-email','member-rate','member-extra-specs'].forEach(function(id){ var el=document.getElementById(id); if(el) el.value=''; });
    var role = document.getElementById('member-role'); if(role) role.value = 'تصميم';
    window._teamV2EditMemberIndex = null;
    var btn = document.querySelector('[onclick="addMemberToForm()"]');
    if(btn) btn.innerHTML = '<i class="fa-solid fa-plus"></i> إضافة عضو';
  }
  window.editTeamMemberInForm = function(index){
    var m = cleanMember(teamMembersForm[index]); if(!m.name) return;
    window._teamV2EditMemberIndex = index;
    var set = function(id,v){ var el=document.getElementById(id); if(el) el.value=v || ''; };
    set('member-name', m.name);
    set('member-phone', m.phone);
    set('member-email', m.email);
    set('member-rate', m.rate || '');
    set('member-extra-specs', (m.extraSpecs || []).join(', '));
    var role = document.getElementById('member-role'); if(role) role.value = m.role;
    var btn = document.querySelector('[onclick="addMemberToForm()"]');
    if(btn) btn.innerHTML = '<i class="fa-solid fa-floppy-disk"></i> حفظ تعديل العضو';
    var name = document.getElementById('member-name'); if(name) name.focus();
  };
  window.addMemberToForm = async function(){
    var name = stripHtml(document.getElementById('member-name') && document.getElementById('member-name').value);
    var email = stripHtml((document.getElementById('member-email') && document.getElementById('member-email').value) || '').toLowerCase();
    if(!name) return alert('أدخل اسم العضو');
    var existing = window._teamV2EditMemberIndex != null ? cleanMember(teamMembersForm[window._teamV2EditMemberIndex]) : {};
    var member = cleanMember({
      id: existing.id,
      name: name,
      role: document.getElementById('member-role') ? document.getElementById('member-role').value : 'أخرى',
      phone: document.getElementById('member-phone') ? document.getElementById('member-phone').value : '',
      email: email,
      extraSpecs: (document.getElementById('member-extra-specs') ? document.getElementById('member-extra-specs').value : '').split(',').map(stripHtml).filter(Boolean),
      rate: +(document.getElementById('member-rate') && document.getElementById('member-rate').value) || 0,
      linked: existing.linked || false,
      linkedUserId: existing.linkedUserId || null,
      addedAt: existing.addedAt || new Date().toISOString()
    });
    if(window._teamV2EditMemberIndex != null){
      teamMembersForm[window._teamV2EditMemberIndex] = member;
      showMiniNotif('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم تعديل بيانات العضو');
    } else {
      teamMembersForm.push(member);
      showMiniNotif('<i class="fa-solid fa-user-plus" style="color:var(--accent3)"></i> تم إضافة العضو');
    }
    resetTeamMemberForm();
    renderTeamMembersForm();
  };
  try { addMemberToForm = window.addMemberToForm; } catch(e) {}

  window.removeTeamMember = function(i){
    teamMembersForm.splice(i,1);
    renderTeamMembersForm();
  };
  try { removeTeamMember = window.removeTeamMember; } catch(e) {}

  window.saveTeam = async function(){
    var name = stripHtml(document.getElementById('team-name') && document.getElementById('team-name').value);
    if(!name) return alert('أدخل اسم الفريق');
    var eid = document.getElementById('team-eid') ? document.getElementById('team-eid').value : '';
    var oldTeam = eid ? teamById(eid) : null;
    var d = {
      id: oldTeam ? oldTeam.id : Date.now(),
      name: name,
      desc: stripHtml(document.getElementById('team-desc') && document.getElementById('team-desc').value),
      members: (teamMembersForm || []).map(cleanMember),
      createdAt: oldTeam && oldTeam.createdAt || new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };
    if(eid){
      var idx = (S.teams || []).findIndex(function(t){ return String(t.id) === String(eid); });
      if(idx > -1) S.teams[idx] = d;
      else S.teams.push(d);
    } else {
      if(!S.teams) S.teams = [];
      S.teams.push(d);
    }
    saveTeamState();
    closeM('modal-team');
    renderTeams();
    if(typeof fillWorkerMembersDD === 'function') fillWorkerMembersDD();
    showMiniNotif('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم حفظ الفريق: '+name);
  };
  try { saveTeam = window.saveTeam; } catch(e) {}

  window.renderTeams = function(){
    var grid = document.getElementById('teams-grid'); if(!grid) return;
    S.teams = (S.teams || []).map(function(t){
      t.members = (t.members || []).map(cleanMember);
      return t;
    });
    var totalMembers = S.teams.reduce(function(s,t){ return s + (t.members || []).length; },0);
    var activeTasks = (S.tasks || []).filter(function(t){ return t.workerMember && !t.done; }).length;
    var header = document.querySelector('#page-team .page-subtitle');
    if(header) header.textContent = S.teams.length+' فرق · '+totalMembers+' أعضاء · '+activeTasks+' مهام نشطة للفريق';
    if(typeof renderMyMemberTeams === 'function') renderMyMemberTeams();
    if(!S.teams.length){
      grid.className = 'team-v2-grid';
      grid.innerHTML = '<div class="team-v2-empty"><i class="fa-solid fa-people-group"></i><b>لا توجد فرق بعد</b><span>ابدأ بفريق عمل، ثم أضف الأعضاء وافتح بروفايل كل عضو من الكارت.</span><button class="btn btn-primary" onclick="_openNewTeamChooser()"><i class="fa-solid fa-plus"></i> فريق جديد</button></div>';
      return;
    }
    grid.className = 'team-v2-grid';
    grid.innerHTML = S.teams.map(function(team){
      var members = (team.members || []).map(cleanMember);
      var tasks = (S.tasks || []).filter(function(t){ return members.some(function(m){ return m.name === t.workerMember; }); });
      var done = tasks.filter(function(t){ return t.done; }).length;
      return '<article class="team-v2-card">'+
        '<div class="team-v2-card-head">'+
          '<div><h3><i class="fa-solid fa-people-group"></i> '+esc(team.name)+'</h3><p>'+esc(team.desc || 'فريق عمل')+'</p></div>'+
          '<div class="team-v2-card-actions">'+
            '<button onclick="openTeamModal('+team.id+')" title="تعديل الفريق"><i class="fa-solid fa-pen"></i></button>'+
            '<button class="danger" onclick="delTeam('+team.id+')" title="حذف الفريق"><i class="fa-solid fa-trash"></i></button>'+
          '</div>'+
        '</div>'+
        '<div class="team-v2-stats"><span><b>'+members.length+'</b><small>أعضاء</small></span><span><b>'+tasks.length+'</b><small>مهام</small></span><span><b>'+done+'</b><small>مكتملة</small></span></div>'+
        '<div class="team-v2-members">'+(members.length ? members.map(function(m){
          var mtasks = memberTasks(m.name).filter(function(t){ return !t.done; }).length;
          return '<button type="button" onclick="openTeamMemberProfile(&quot;'+esc(team.id)+'&quot;,&quot;'+esc(memberKey(m))+'&quot;)">'+
            '<span><i class="fa-solid '+roleIcon(m.role)+'"></i></span><b>'+esc(m.name)+'</b><small>'+esc(m.role)+(mtasks?' · '+mtasks+' مهام':'')+'</small>'+
          '</button>';
        }).join('') : '<div class="team-v2-no-members">لا أعضاء داخل هذا الفريق</div>')+'</div>'+
      '</article>';
    }).join('');
  };
  try { renderTeams = window.renderTeams; } catch(e) {}

  window.openTeamMemberProfile = function(teamId, memberIdOrName){
    var found = findMember(teamId, memberIdOrName);
    if(!found) return;
    var team = found.team, m = found.member;
    document.getElementById('teams-grid-view').style.display = 'none';
    var view = document.getElementById('member-profile-view');
    view.style.display = 'block';
    view.classList.add('team-v2-profile');
    var tasks = memberTasks(m.name);
    var active = tasks.filter(function(t){ return !t.done; });
    var done = tasks.filter(function(t){ return t.done; });
    var totalOwed = tasks.reduce(function(s,t){ return s + (+t.workerAmount || 0); },0);
    var paid = tasks.reduce(function(s,t){ return s + (t.workerDepositPaid ? (+t.workerDepositAmount || 0) : 0); },0);
    window._mpCurrentMember = m.name;
    window._mpAllTasks = tasks;
    window._mpTotalOwed = totalOwed;
    window._mpTotalDeposits = paid;
    window._mpPendingPay = totalOwed - paid;
    var title = document.getElementById('member-profile-title');
    if(title){
      title.innerHTML = '<div class="team-v2-profile-title"><span><i class="fa-solid '+roleIcon(m.role)+'"></i></span><div><b>'+esc(m.name)+'</b><small>'+esc(team.name)+' · '+esc(m.role)+'</small></div></div>';
    }
    var top = view.querySelector(':scope > div:first-child');
    if(top){
      top.classList.add('team-v2-profile-top');
      var actions = top.querySelector('div[style*="margin-right:auto"]');
      if(actions && !actions.querySelector('[data-team-v2-edit]')){
        actions.insertAdjacentHTML('afterbegin','<button class="btn btn-primary btn-sm" data-team-v2-edit onclick="openTeamMemberEditModal(&quot;'+esc(team.id)+'&quot;,&quot;'+esc(memberKey(m))+'&quot;)"><i class="fa-solid fa-pen"></i> تعديل البيانات</button>');
      }
    }
    var set=function(id,v){ var e=document.getElementById(id); if(e) e.textContent=v; };
    set('mp-tasks-count', active.length);
    set('mp-done-count', done.length);
    set('mp-total-paid', paid.toLocaleString()+' '+_getCurrency());
    set('mp-pending-pay', (totalOwed-paid).toLocaleString()+' '+_getCurrency());
    renderMemberInfoPanel(view, team, m);
    renderMemberTaskPanels(active, done, tasks, totalOwed, paid);
  };
  try { openMemberProfile = window.openTeamMemberProfile; } catch(e) {}

  function renderMemberInfoPanel(view, team, m){
    var existing = document.getElementById('team-v2-member-info-panel');
    if(existing) existing.remove();
    var html = '<section class="team-v2-info-panel" id="team-v2-member-info-panel">'+
      '<div><b><i class="fa-solid fa-id-card"></i> البيانات المسجلة</b><button class="btn btn-ghost btn-sm" onclick="openTeamMemberEditModal(&quot;'+esc(team.id)+'&quot;,&quot;'+esc(memberKey(m))+'&quot;)"><i class="fa-solid fa-pen"></i> تعديل</button></div>'+
      '<div class="team-v2-info-grid">'+
        infoCell('الاسم', m.name, 'fa-user')+
        infoCell('الفريق', team.name, 'fa-people-group')+
        infoCell('التخصص', m.role, roleIcon(m.role))+
        infoCell('الهاتف', m.phone || 'غير مسجل', 'fa-phone')+
        infoCell('البريد', m.email || 'غير مسجل', 'fa-envelope')+
        infoCell('نسبة الربح', m.rate ? m.rate+'%' : 'غير محددة', 'fa-percent')+
        infoCell('تخصصات إضافية', (m.extraSpecs || []).join('، ') || 'لا توجد', 'fa-tags')+
      '</div></section>';
    var stats = document.getElementById('member-stats-row');
    if(stats) stats.insertAdjacentHTML('afterend', html);
  }
  function infoCell(label, value, icon){
    return '<span><i class="fa-solid '+icon+'"></i><small>'+esc(label)+'</small><b>'+esc(value)+'</b></span>';
  }
  function renderMemberTaskPanels(active, done, tasks, totalOwed, paid){
    var activeEl = document.getElementById('mp-tasks-list');
    if(activeEl) activeEl.innerHTML = active.length ? active.map(memberTaskCard).join('') : '<div class="tasks-v2-empty">لا مهام نشطة</div>';
    var payEl = document.getElementById('mp-payments-list');
    if(payEl) payEl.innerHTML = tasks.length ? tasks.map(function(t){
      var owed = +t.workerAmount || 0, p = t.workerDepositPaid ? (+t.workerDepositAmount || 0) : 0;
      return '<div class="team-v2-pay-row"><div><b>'+esc(t.title)+'</b><small>'+(t.done?'مكتمل':'نشط')+'</small></div><strong>'+owed.toLocaleString()+' ج</strong><span>'+p.toLocaleString()+' مدفوع</span></div>';
    }).join('') : '<div class="tasks-v2-empty">لا مدفوعات مسجلة</div>';
    var doneEl = document.getElementById('mp-done-list');
    if(doneEl) doneEl.innerHTML = done.length ? done.map(memberTaskCard).join('') : '<div class="tasks-v2-empty">لا مهام مكتملة</div>';
  }
  function memberTaskCard(t){
    return '<button class="team-v2-task-card" onclick="openTaskDetail('+t.id+')"><b>'+esc(t.title)+'</b><small>'+esc(t.client || 'بدون عميل')+(t.deadline?' · '+esc(t.deadline):'')+'</small><span>'+((+t.workerAmount||0).toLocaleString())+' ج</span></button>';
  }

  window.openTeamMemberEditModal = function(teamId, memberIdOrName){
    var found = findMember(teamId, memberIdOrName); if(!found) return;
    var m = found.member;
    var ov = document.getElementById('modal-team-member-edit');
    if(!ov){ ov = document.createElement('div'); ov.id='modal-team-member-edit'; ov.className='modal-overlay'; document.body.appendChild(ov); }
    ov.innerHTML = '<div class="modal team-v2-member-modal">'+
      '<div class="modal-header"><div class="modal-title"><i class="fa-solid fa-user-pen"></i> تعديل بيانات العضو</div><button class="close-btn" onclick="closeM(&quot;modal-team-member-edit&quot;)"><i class="fa-solid fa-xmark"></i></button></div>'+
      '<input type="hidden" id="tm-edit-team" value="'+esc(found.team.id)+'"><input type="hidden" id="tm-edit-member" value="'+esc(memberKey(m))+'">'+
      '<div class="form-row"><div class="form-group"><label class="form-label">الاسم *</label><input class="form-input" id="tm-edit-name" value="'+esc(m.name)+'"></div><div class="form-group"><label class="form-label">التخصص</label><select class="form-select" id="tm-edit-role">'+roleOptions(m.role)+'</select></div></div>'+
      '<div class="form-row"><div class="form-group"><label class="form-label">رقم الهاتف</label><input class="form-input" id="tm-edit-phone" value="'+esc(m.phone)+'"></div><div class="form-group"><label class="form-label">البريد الإلكتروني</label><input class="form-input" id="tm-edit-email" value="'+esc(m.email)+'"></div></div>'+
      '<div class="form-row"><div class="form-group"><label class="form-label">تخصصات إضافية</label><input class="form-input" id="tm-edit-extra" value="'+esc((m.extraSpecs||[]).join(', '))+'"></div><div class="form-group"><label class="form-label">نسبة الربح الافتراضية (%)</label><input class="form-input" type="number" id="tm-edit-rate" value="'+esc(m.rate || '')+'"></div></div>'+
      '<div class="team-v2-modal-actions"><button class="btn btn-ghost" onclick="closeM(&quot;modal-team-member-edit&quot;)">إلغاء</button><button class="btn btn-primary" onclick="saveTeamMemberEdit()"><i class="fa-solid fa-floppy-disk"></i> حفظ التعديل</button></div>'+
    '</div>';
    openM('modal-team-member-edit');
  };
  function roleOptions(current){
    var opts = ['تصميم','مونتاج فيديو','تطوير','تسويق','كتابة محتوى','كونتنت كريتور','مودريتور','مستقل','أخرى'];
    current = cleanRole(current);
    if(opts.indexOf(current) === -1) opts.push(current);
    return opts.map(function(o){ return '<option value="'+esc(o)+'" '+(o===current?'selected':'')+'>'+esc(o)+'</option>'; }).join('');
  }
  window.saveTeamMemberEdit = function(){
    var teamId = document.getElementById('tm-edit-team') && document.getElementById('tm-edit-team').value;
    var memberId = document.getElementById('tm-edit-member') && document.getElementById('tm-edit-member').value;
    var found = findMember(teamId, memberId); if(!found) return;
    var oldName = found.member.name;
    var updated = cleanMember({
      id: found.member.id,
      name: document.getElementById('tm-edit-name') && document.getElementById('tm-edit-name').value,
      role: document.getElementById('tm-edit-role') && document.getElementById('tm-edit-role').value,
      phone: document.getElementById('tm-edit-phone') && document.getElementById('tm-edit-phone').value,
      email: document.getElementById('tm-edit-email') && document.getElementById('tm-edit-email').value,
      extraSpecs: (document.getElementById('tm-edit-extra') && document.getElementById('tm-edit-extra').value || '').split(',').map(stripHtml).filter(Boolean),
      rate: +(document.getElementById('tm-edit-rate') && document.getElementById('tm-edit-rate').value) || 0,
      linked: found.member.linked,
      linkedUserId: found.member.linkedUserId,
      addedAt: found.member.addedAt
    });
    if(!updated.name) return alert('أدخل اسم العضو');
    found.team.members[found.index] = updated;
    if(oldName !== updated.name){
      (S.tasks || []).forEach(function(t){ if(t.workerMember === oldName) t.workerMember = updated.name; });
      (S.project_tasks || []).forEach(function(t){ if(t.assignee_name === oldName) t.assignee_name = updated.name; });
    }
    saveTeamState();
    closeM('modal-team-member-edit');
    renderTeams();
    openTeamMemberProfile(found.team.id, updated.id);
    if(typeof fillWorkerMembersDD === 'function') fillWorkerMembersDD();
    showMiniNotif('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم تحديث بيانات العضو');
  };

  var oldCloseMemberProfile = typeof closeMemberProfile === 'function' ? closeMemberProfile : null;
  window.closeMemberProfile = function(){
    var grid = document.getElementById('teams-grid-view'); if(grid) grid.style.display='block';
    var view = document.getElementById('member-profile-view'); if(view) view.style.display='none';
    var info = document.getElementById('team-v2-member-info-panel'); if(info) info.remove();
  };
  try { closeMemberProfile = window.closeMemberProfile; } catch(e) {}
})();

// ============================================================
// TASKS REDESIGN V2
// ============================================================
(function(){
  var STORE_MODE = 'ordo_tasks_layout_v2';
  var STORE_FILTERS = 'ordo_tasks_v2_filters';
  var STORE_FILTER_OPEN = 'ordo_tasks_v2_filter_open';
  var STORE_VIEW = 'ordo_tasks_v2_view';
  var dragId = null;
  var justDragged = false;

  function tasksV2Mode(){
    return localStorage.getItem(STORE_MODE) || 'new';
  }
  function setTasksV2Mode(mode){
    localStorage.setItem(STORE_MODE, mode === 'classic' ? 'classic' : 'new');
    renderTasks();
  }
  window.setTasksV2Mode = setTasksV2Mode;
  function tasksV2View(){
    return localStorage.getItem(STORE_VIEW) || 'kanban';
  }
  window.__tasksV2SetView = function(view){
    localStorage.setItem(STORE_VIEW, view === 'list' ? 'list' : 'kanban');
    renderTasks();
  };

  function esc(v){
    if(typeof escapeHtml === 'function') return escapeHtml(v || '');
    return String(v || '').replace(/[&<>"']/g, function(c){
      return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
    });
  }
  function todayIso(){
    var d = new Date();
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
    return d.toISOString().slice(0,10);
  }
  function addDaysIso(days){
    var d = new Date();
    d.setDate(d.getDate() + days);
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
    return d.toISOString().slice(0,10);
  }
  function niceDate(d){
    if(!d) return '';
    var out = typeof _friendlyDate === 'function' ? _friendlyDate(d) : d;
    return String(out || '')
      .replace(/<[^>]*>/g,'')
      .replace(/&lt;[^&]*?&gt;/g,'')
      .replace(/;?\s*font-family\s*:[^;<>]+;?/gi,'')
      .replace(/;?\s*font-size\s*:[^;<>]+;?/gi,'')
      .replace(/;?\s*font-weight\s*:[^;<>]+;?/gi,'')
      .replace(/style\s*=\s*['\"][^'\"]*['\"]/gi,'')
      .trim();
  }
  function money(v){
    v = Number(v || 0);
    return v ? v.toLocaleString('ar-EG') + ' ج' : '';
  }
  function taskMoney(t){
    if(t && t.value && window.OrdoCurrencyPatch && typeof window.OrdoCurrencyPatch.formatMoney === 'function'){
      return window.OrdoCurrencyPatch.formatMoney(t.value, t);
    }
    return money(t && t.value);
  }
  function getStatusLabel(id){
    if(typeof _getStatusLabel === 'function') return _getStatusLabel(id);
    var map = {new:'جديد',progress:'قيد التنفيذ',review:'مراجعة',paused:'موقوف',done:'مكتمل'};
    var cs = (S.customStatuses || []).find(function(s){ return s.id === id; });
    return cs ? cs.label : (map[id] || id || 'جديد');
  }
  function getStatusColor(id){
    if(typeof _getStatusColor === 'function') return _getStatusColor(id);
    var map = {new:'#8f93b7',progress:'#f7c948',review:'#7c6ff7',paused:'#64b5f6',done:'#4fd1a5'};
    var cs = (S.customStatuses || []).find(function(s){ return s.id === id; });
    return cs ? (cs.color || '#7c6ff7') : (map[id] || '#7c6ff7');
  }
  function taskColor(t){
    return (t && t.color) || getStatusColor(taskStatus(t || {}));
  }
  function createdLabel(t){
    var raw = t.createdAt || t.created_at || t.orderCreatedAt || t.orderDate || '';
    if(!raw) return 'غير محدد';
    var d = new Date(raw);
    if(!isNaN(d.getTime())) return d.toLocaleString('ar-EG', {dateStyle:'medium', timeStyle:'short'});
    return niceDate(raw);
  }
  function findClientByName(name){
    return (S.clients || []).find(function(c){ return String(c.name || '').trim() === String(name || '').trim(); }) || null;
  }
  function findTeamMemberByName(name){
    var target = String(name || '').trim();
    if(!target) return null;
    var found = null;
    (S.teams || []).forEach(function(team){
      if(found) return;
      (team.members || []).forEach(function(m){
        if(found) return;
        if(String(m.name || '').trim() === target || String(m.email || '').trim() === target || String(m.id || '').trim() === target) found = m;
      });
    });
    return found;
  }
  function visibleStatuses(){
    var hidden = S.hiddenStatuses || [];
    var base = [
      {id:'new', label:getStatusLabel('new'), color:getStatusColor('new'), icon:'fa-clipboard-list'},
      {id:'progress', label:getStatusLabel('progress'), color:getStatusColor('progress'), icon:'fa-bolt'},
      {id:'review', label:getStatusLabel('review'), color:getStatusColor('review'), icon:'fa-magnifying-glass'},
      {id:'paused', label:getStatusLabel('paused'), color:getStatusColor('paused'), icon:'fa-pause'},
      {id:'done', label:getStatusLabel('done'), color:getStatusColor('done'), icon:'fa-square-check'}
    ];
    (S.customStatuses || []).forEach(function(cs){
      if(cs && cs.id && !base.find(function(b){ return b.id === cs.id; })){
        base.splice(Math.max(base.length - 1, 0), 0, {
          id:cs.id,
          label:cs.label || cs.id,
          color:cs.color || '#7c6ff7',
          icon:'fa-circle'
        });
      }
    });
    return base.filter(function(s){ return !hidden.includes(s.id); });
  }
  function readFilters(){
    var saved = {};
    try { saved = JSON.parse(localStorage.getItem(STORE_FILTERS) || '{}') || {}; } catch(e) {}
    return {
      search: saved.search || '',
      status: saved.status || '',
      priority: saved.priority || '',
      client: saved.client || '',
      date: saved.date || ''
    };
  }
  function saveFilter(key, value){
    var f = readFilters();
    f[key] = value || '';
    localStorage.setItem(STORE_FILTERS, JSON.stringify(f));
    renderTasks();
  }
  window.__tasksV2SetFilter = saveFilter;
  window.__tasksV2ToggleFilters = function(){
    var open = localStorage.getItem(STORE_FILTER_OPEN) === '1';
    localStorage.setItem(STORE_FILTER_OPEN, open ? '0' : '1');
    renderTasks();
  };

  function taskStatus(t){
    if(t && t._isProjectTask){
      if(t.status === 'todo') return 'new';
      if(t.status === 'hold') return 'paused';
      if(t.status === 'revision') return 'review';
    }
    if(t.done || t.status === 'done') return 'done';
    return t.status || 'new';
  }
  function taskProgress(t){
    var steps = t.steps || [];
    if(t.done || t.status === 'done') return 100;
    if(!steps.length) return 0;
    return Math.round(steps.filter(function(s){ return !!s.done; }).length / steps.length * 100);
  }
  function tasksForV2(){
    var f = readFilters();
    var q = (f.search || '').trim().toLowerCase();
    return tasksV2Source().filter(function(t){
      var st = taskStatus(t);
      if(f.status && st !== f.status) return false;
      if(f.priority && (t.priority || 'med') !== f.priority) return false;
      if(f.client && (t.client || '') !== f.client) return false;
      if(f.date){
        var d = t.deadline || t.orderDate || '';
        if(f.date === 'late' && (!(t.deadline) || t.deadline >= todayIso() || st === 'done')) return false;
        if(f.date === 'today' && t.deadline !== todayIso()) return false;
        if(f.date === 'tomorrow' && t.deadline !== addDaysIso(1)) return false;
        if(f.date === 'week'){
          var max = addDaysIso(7);
          if(!t.deadline || t.deadline < todayIso() || t.deadline > max) return false;
        }
      }
      if(q){
        var hay = taskSearchText(t);
        if(hay.indexOf(q) === -1) return false;
      }
      return true;
    });
  }
  function tasksV2Source(){
    var projectsById = {};
    (S.projects || []).forEach(function(p){ projectsById[String(p.id)] = p; });
    var regular = (S.tasks || []).map(function(t){ return Object.assign({_v2Key:'t_'+t.id}, t); });
    var projectTasks = (S.project_tasks || []).map(function(t){
      var p = projectsById[String(t.project_id)] || {};
      return Object.assign({_isProjectTask:true,_v2Key:'p_'+t.id,projectName:p.name || t.projectName || 'مشروع',projectColor:p.color || t.color || '#7c6ff7',client:p.client_name || t.client || ''}, t);
    });
    return regular.concat(projectTasks);
  }
  function taskSearchText(t){
    return [
      t && t.title,
      t && t.client,
      t && t.projectName,
      t && t.desc,
      t && t.notes,
      t && t.source,
      t && t.assignee_name,
      t && t.workerMember,
      t && getStatusLabel(taskStatus(t || {})),
      t && priorityLabel(t.priority)
    ].join(' ').toLowerCase();
  }
  function taskSearchSuggestions(q){
    q = String(q || '').trim().toLowerCase();
    if(!q) return [];
    return tasksV2Source().filter(function(t){
      return taskSearchText(t).indexOf(q) >= 0;
    }).slice(0,8);
  }
  window.__tasksV2PickSuggestion = function(key){
    var t = tasksV2Source().find(function(x){ return String(x._v2Key) === String(key); });
    if(!t) return;
    saveFilter('search', t.title || '');
  };
  function clientOptions(current){
    var names = Array.from(new Set(tasksV2Source().map(function(t){ return t.client; }).filter(Boolean))).sort();
    return '<option value="">كل العملاء</option>' + names.map(function(n){
      return '<option value="'+esc(n)+'" '+(n === current ? 'selected' : '')+'>'+esc(n)+'</option>';
    }).join('');
  }
  function statusOptions(current){
    return '<option value="">كل الحالات</option>' + visibleStatuses().map(function(s){
      return '<option value="'+s.id+'" '+(s.id === current ? 'selected' : '')+'>'+esc(s.label)+'</option>';
    }).join('');
  }
  function priorityLabel(p){
    return ({high:'عاجل',med:'متوسط',low:'عادي'}[p || 'med'] || 'متوسط');
  }
  function priorityColor(p){
    return ({high:'#f76f7c',med:'#f7c948',low:'#4fd1a5'}[p || 'med'] || '#f7c948');
  }
  function paymentLabel(t){
    if(t.pay === 'full') return '<span class="tasks-v2-chip" style="background:rgba(79,209,165,.14);color:var(--accent3)"><i class="fa-solid fa-check"></i> مدفوع</span>';
    if(t.pay === 'deposit') return '<span class="tasks-v2-chip" style="background:rgba(247,201,72,.14);color:var(--accent2)">عربون</span>';
    return t.value ? '<span class="tasks-v2-chip" style="background:rgba(247,111,124,.12);color:var(--accent4)">غير مدفوع</span>' : '';
  }
  function payText(t){
    if(t.pay === 'full') return 'مدفوع';
    if(t.pay === 'deposit') return 'عربون';
    return t.value ? 'غير مدفوع' : 'بدون قيمة';
  }
  function cardHtml(t){
    var st = taskStatus(t);
    var color = taskColor(t);
    var pct = taskProgress(t);
    var late = t.deadline && t.deadline < todayIso() && st !== 'done';
    var steps = t.steps || [];
    var pay = payText(t);
    var payClass = t.pay === 'full' ? 'is-paid' : (t.value ? 'is-unpaid' : 'is-none');
    var dateText = t.deadline ? niceDate(t.deadline) : 'بدون موعد';
    var valueText = t.value ? taskMoney(t) : '';
    var taskKey = t._v2Key || ('t_'+t.id);
    var openCall = t._isProjectTask ? 'openProjectDetail(&quot;'+esc(t.project_id || '')+'&quot;)' : 'openTaskDetail('+t.id+')';
    var editCall = t._isProjectTask ? 'openProjTaskModal(&quot;'+esc(t.project_id || '')+'&quot;,&quot;'+esc(t.id)+'&quot;)' : 'openTaskModal('+t.id+')';
    return '<div class="tasks-v2-card task-clickable" draggable="true" data-task-id="'+t.id+'" '+
      'data-task-key="'+taskKey+'" ondragstart="__tasksV2DragStart(event,&quot;'+taskKey+'&quot;)" ondragend="__tasksV2DragEnd(event)" '+
      'onclick="__tasksV2OpenTask(event,&quot;'+taskKey+'&quot;)" style="border-right-color:'+(t._isProjectTask ? t.projectColor : color)+'">'+
      '<div class="tasks-v2-card-top">'+
        '<span class="tasks-v2-card-color" style="background:'+(t._isProjectTask ? t.projectColor : color)+'"></span>'+
        '<div class="tasks-v2-card-title">'+esc(t.title || 'مهمة بدون اسم')+'</div>'+
      '</div>'+
      '<div class="tasks-v2-card-sub">'+(t._isProjectTask ? '<i class="fa-solid fa-diagram-project"></i> مهمة مرتبطة بمشروع: '+esc(t.projectName) : esc(t.client || 'مهمة شخصية'))+'</div>'+
      '<div class="tasks-v2-card-line">'+
        '<span class="'+(late?'is-late':'')+'"><i class="fa-regular fa-calendar"></i> '+esc(dateText)+'</span>'+
        (valueText ? '<span class="is-value">'+valueText+'</span>' : '')+
      '</div>'+
      '<div class="tasks-v2-card-line is-muted">'+
        '<span style="color:'+priorityColor(t.priority)+'"><i class="fa-solid fa-circle"></i> '+priorityLabel(t.priority)+'</span>'+
        '<span class="'+payClass+'">'+pay+'</span>'+
      '</div>'+
      (steps.length ? '<div class="tasks-v2-card-foot"><div class="tasks-v2-mini-progress"><span style="width:'+pct+'%;background:'+color+'"></span></div><span>'+steps.filter(function(s){ return s.done; }).length+'/'+steps.length+'</span></div>' : '')+
      '<div class="tasks-v2-card-actions" onclick="event.stopPropagation()">'+
        (t._isProjectTask ? '<button class="tasks-v2-icon-btn" onclick="_completeProjTask(&quot;'+esc(t.id)+'&quot;)" title="إكمال"><i class="fa-solid fa-check"></i></button>' : '<button class="tasks-v2-icon-btn" onclick="archiveTaskNow('+t.id+')" title="أرشفة"><i class="fa-solid fa-box-archive"></i></button>'+(st !== 'done' ? '<button class="tasks-v2-icon-btn" onclick="completeTask('+t.id+')" title="إكمال"><i class="fa-solid fa-check"></i></button>' : ''))+
        '<button class="tasks-v2-icon-btn" onclick="'+editCall+'" title="تعديل"><i class="fa-solid fa-pen"></i></button>'+
        '<button class="tasks-v2-icon-btn" onclick="'+openCall+'" title="تفاصيل"><i class="fa-regular fa-eye"></i></button>'+
        '<button class="tasks-v2-icon-btn" onclick="__ordoDeleteAnyTask(&quot;'+(t._isProjectTask?'project_task':'task')+'&quot;,&quot;'+esc(t.id)+'&quot;)" title="حذف"><i class="fa-solid fa-trash"></i></button>'+
      '</div>'+
    '</div>';
  }
  function agendaHtml(title, items, icon, tone){
    return '<div class="tasks-v2-panel">'+
      '<div class="tasks-v2-panel-head"><span><i class="fa-solid '+icon+'" style="color:'+tone+'"></i> '+title+'</span><span class="tasks-v2-count">'+items.length+'</span></div>'+
      '<div class="tasks-v2-agenda">'+
        (items.length ? items.slice(0,8).map(function(t){
          return '<div class="tasks-v2-agenda-item" onclick="'+(t._isProjectTask?'openProjectDetail(&quot;'+esc(t.project_id||'')+'&quot;)':'openTaskDetail('+t.id+')')+'">'+
            '<span class="tasks-v2-dot" style="background:'+getStatusColor(taskStatus(t))+'"></span>'+
            '<div style="min-width:0;flex:1"><b>'+esc(t.title)+'</b><small>'+(t._isProjectTask?'مشروع: '+esc(t.projectName):esc(t.client || 'بدون عميل'))+(t.deadline ? ' · '+niceDate(t.deadline) : '')+'</small></div>'+
          '</div>';
        }).join('') : '<div class="tasks-v2-empty">لا توجد مهام هنا</div>')+
      '</div></div>';
  }
  function listHtml(items){
    if(!items.length) return '<div class="tasks-v2-list-empty">لا توجد مهام حسب الفلتر الحالي</div>';
    function makeRows(list){
      return list.slice().sort(function(a,b){
      return String(a.deadline || '9999-12-31').localeCompare(String(b.deadline || '9999-12-31'));
    }).map(function(t){
      var st = taskStatus(t);
      var color = taskColor(t);
      var late = t.deadline && t.deadline < todayIso() && st !== 'done';
      var openCall = t._isProjectTask ? 'openProjectDetail(&quot;'+esc(t.project_id || '')+'&quot;)' : 'openTaskDetail('+t.id+')';
      var editCall = t._isProjectTask ? 'openProjTaskModal(&quot;'+esc(t.project_id || '')+'&quot;,&quot;'+esc(t.id)+'&quot;)' : 'openTaskModal('+t.id+')';
      return '<div class="tasks-v2-list-row task-clickable" onclick="'+openCall+'" data-task-id="'+t.id+'">'+
        '<div class="tasks-v2-list-main">'+
          '<span class="tasks-v2-dot" style="background:'+color+'"></span>'+
          '<div><b>'+esc(t.title || 'مهمة بدون اسم')+'</b><div>'+(t._isProjectTask ? 'مهمة مرتبطة بمشروع: '+esc(t.projectName) : esc(t.client || 'بدون عميل'))+'</div></div>'+
        '</div>'+
        '<button class="tasks-v2-list-cell is-clickable" onclick="event.stopPropagation();'+editCall+'" title="تعديل">'+(t._isProjectTask?esc(t.projectName):esc(t.client || 'بدون عميل'))+'</button>'+
        '<button class="tasks-v2-list-cell is-clickable" onclick="event.stopPropagation();'+editCall+'" title="تعديل الأولوية"><span style="color:'+priorityColor(t.priority)+'"><i class="fa-solid fa-circle"></i> '+priorityLabel(t.priority)+'</span></button>'+
        '<button class="tasks-v2-list-cell is-clickable '+(late?'is-late':'')+'" onclick="event.stopPropagation();'+editCall+'" title="تعديل الموعد">'+(t.deadline ? niceDate(t.deadline) : 'بدون موعد')+'</button>'+
        '<button class="tasks-v2-list-cell is-clickable" onclick="event.stopPropagation();'+editCall+'" title="تعديل الدفع">'+payText(t)+'</button>'+
        '<button class="tasks-v2-list-cell is-clickable" onclick="event.stopPropagation();'+editCall+'" title="تعديل الحالة"><span style="color:'+color+'">'+getStatusLabel(st)+'</span></button>'+
        '<div class="tasks-v2-list-actions" onclick="event.stopPropagation()">'+
          (t._isProjectTask ? '' : '<button class="tasks-v2-icon-btn" onclick="archiveTaskNow('+t.id+')" title="أرشفة"><i class="fa-solid fa-box-archive"></i></button>')+
          '<button class="tasks-v2-icon-btn" onclick="'+openCall+'" title="تفاصيل"><i class="fa-regular fa-eye"></i></button>'+
          '<button class="tasks-v2-icon-btn" onclick="'+editCall+'" title="تعديل"><i class="fa-solid fa-pen"></i></button>'+
          (st !== 'done' ? '<button class="tasks-v2-icon-btn" onclick="'+(t._isProjectTask?'_completeProjTask(&quot;'+esc(t.id)+'&quot;)':'completeTask('+t.id+')')+'" title="إكمال"><i class="fa-solid fa-check"></i></button>' : '')+
          '<button class="tasks-v2-icon-btn" onclick="__ordoDeleteAnyTask(&quot;'+(t._isProjectTask?'project_task':'task')+'&quot;,&quot;'+esc(t.id)+'&quot;)" title="حذف"><i class="fa-solid fa-trash"></i></button>'+
        '</div>'+
      '</div>';
      }).join('');
    }
    var openItems = items.filter(function(t){ return taskStatus(t) !== 'done'; });
    var doneItems = items.filter(function(t){ return taskStatus(t) === 'done'; });
    var openRows = makeRows(openItems);
    var doneRows = makeRows(doneItems);
    return '<div class="tasks-v2-list-wrap">'+
      '<div class="tasks-v2-list-head"><span>المهمة</span><span>العميل</span><span>الأولوية</span><span>التسليم</span><span>الدفع</span><span>الحالة</span><span>إجراءات</span></div>'+
      (openRows || '<div class="tasks-v2-list-empty">لا توجد مهام مفتوحة حسب الفلتر الحالي</div>')+
      (doneRows ? '<div class="tasks-v2-completed-block"><button type="button" class="tasks-v2-completed-head" onclick="this.closest(&quot;.tasks-v2-completed-block&quot;).classList.toggle(&quot;is-collapsed&quot;)"><span><i class="fa-solid fa-square-check"></i> المهام المكتملة</span><b>'+doneItems.length+'</b><i class="fa-solid fa-chevron-down"></i></button><div class="tasks-v2-completed-body">'+doneRows+'</div></div>' : '')+
    '</div>';
  }
  function modernTaskStatusOptions(t){
    var hidden = S.hiddenStatuses || [];
    var defaults = [
      {id:'new', label:'جديد'},
      {id:'progress', label:'قيد التنفيذ'},
      {id:'review', label:'مراجعة'},
      {id:'paused', label:'موقوف'}
    ];
    var opts = defaults.filter(function(x){ return !hidden.includes(x.id) && x.id !== taskStatus(t); })
      .map(function(x){ return '<option value="'+x.id+'">'+x.label+'</option>'; }).join('');
    opts += (S.customStatuses || []).filter(function(x){ return x.id !== taskStatus(t); })
      .map(function(x){ return '<option value="'+x.id+'">'+esc((x.icon ? x.icon+' ' : '') + x.label)+'</option>'; }).join('');
    opts += '<option value="done">مكتمل</option>';
    return opts;
  }
  function taskStatusButtonsHtml(t){
    var current = taskStatus(t);
    return visibleStatuses().map(function(s){
      var active = s.id === current;
      return '<button type="button" class="tasks-v2-status-option '+(active?'is-active':'')+'" style="--status-color:'+s.color+'" '+(active?'disabled':'onclick="changeTaskStatus('+t.id+',&quot;'+s.id+'&quot;);renderModernTaskDetail('+t.id+')"')+'><span></span>'+esc(s.label)+'</button>';
    }).join('');
  }
  function commentsHtml(t){
    var comments = (t.comments || []).filter(function(c){ return c.stepIdx === null || c.stepIdx === undefined; });
    if(!comments.length) return '<div class="tasks-v2-detail-empty">لا ملاحظات بعد</div>';
    return comments.map(function(c, idx){
      return '<div class="tasks-v2-detail-comment"><div><b><i class="fa-solid fa-note-sticky"></i> '+esc(c.author || 'ملاحظة')+'</b><span>'+esc((c.at || '').slice(0,16).replace('T',' '))+'</span><button type="button" title="حذف الملاحظة" onclick="__tasksV2DeleteComment('+t.id+','+idx+')"><i class="fa-solid fa-trash"></i></button></div><p>'+esc(c.text || '')+'</p></div>';
    }).join('');
  }
  function taskNotes(t){
    return (t.comments || []).filter(function(c){ return c.stepIdx === null || c.stepIdx === undefined; });
  }
  function taskDetailMessage(t, recipient){
    var defaults = typeof getWaTemplateDefaults === 'function' ? getWaTemplateDefaults() : {};
    var isMember = String(recipient || '') === String(t.workerMember || t.assignee_name || '');
    var key = isMember ? 'memberTask' : 'taskQuick';
    var raw = (S.settings && S.settings.waTemplates && S.settings.waTemplates[key]) || defaults[key] || '';
    var vars = {
      '{{اسم_العميل}}': t.client || 'العميل',
      '{{اسم_المشروع}}': t.title || 'مهمة',
      '{{اسم_المنفذ}}': t.workerMember || t.assignee_name || recipient || 'المنفذ',
      '{{حالة_المهمة}}': getStatusLabel(taskStatus(t)),
      '{{أولوية_المهمة}}': priorityLabel(t.priority),
      '{{تاريخ_التسليم}}': t.deadline ? niceDate(t.deadline) : 'غير محدد',
      '{{قيمة_المهمة}}': t.value ? money(t.value) : 'غير محددة',
      '{{تفاصيل_المهمة}}': t.brief ? String(t.brief).replace(/<[^>]+>/g,'').trim() : '',
      '{{رابط_المشروع}}': t.projectLink || t.driveLink || '',
      '{{اسم_العمل}}': (S.settings && S.settings.name) || 'Ordo',
      '{{رقم_هاتف_العمل}}': (S.settings && S.settings.phone) || ''
    };
    return fillWaVars(cleanWaTemplate(raw), vars);
  }
  function renderModernTaskDetail(id){
    var t = findTaskAny(id);
    if(!t){
      var pt = (S.project_tasks || []).find(function(x){ return String(x.id) === String(id).replace(/^p_/, ''); });
      if(pt) return openProjTaskDetail(pt.id, pt.project_id);
    }
    if(!t) return;
    var editBtn = document.getElementById('td-edit-btn');
    if(editBtn) editBtn.onclick = function(){ closeM('modal-task-detail'); openTaskModal(id); };
    var body = document.getElementById('td-body');
    if(!body) return;
    var st = taskStatus(t);
    var color = taskColor(t);
    var pct = taskProgress(t);
    var relInv = (S.invoices || []).filter(function(inv){ return (inv.items || []).some(function(it){ return String(it._taskId) === String(id); }); });
    var link = esc(t.projectLink || t.driveLink || '');
    var client = findClientByName(t.client);
    var memberName = t.workerMember || t.assignee_name || '';
    var member = findTeamMemberByName(memberName);
    var notes = taskNotes(t);
    var hasLateDeadline = t.deadline && t.deadline < todayIso() && st !== 'done';
    body.innerHTML = '<div class="tasks-v2-detail tasks-v2-detail-compact tasks-v2-detail-flow" style="--task-detail-color:'+color+'">'+
      '<div class="tasks-v2-detail-shell">'+
      '<div class="tasks-v2-compact-head tasks-v2-flow-head">'+
        '<div class="tasks-v2-compact-title">'+
          '<div class="tasks-v2-compact-tags">'+
            '<span class="tasks-v2-status-pill" style="border-color:'+color+';color:'+color+'"><i class="fa-solid fa-circle"></i> '+esc(getStatusLabel(st))+'</span>'+
            (t.client?'<span><i class="fa-solid fa-user"></i> '+esc(t.client)+'</span>':'')+
            (memberName?'<span><i class="fa-solid fa-user-gear"></i> '+esc(memberName)+'</span>':'')+
            '<span>'+priorityLabel(t.priority)+'</span>'+
            (t.taskType?'<span>'+esc(t.taskType)+'</span>':'')+
          '</div>'+
          '<h2>'+esc(t.title || 'مهمة بدون اسم')+'</h2>'+
        '</div>'+
        '<div class="tasks-v2-compact-tools">'+
          '<button type="button" class="tasks-v2-detail-icon" onclick="__tasksV2OpenNotes('+t.id+')" title="الملاحظات"><i class="fa-solid fa-note-sticky"></i>'+(notes.length?'<b>'+notes.length+'</b>':'')+'</button>'+
          '<label class="tasks-v2-color-dot" title="لون المهمة"><input type="color" value="'+esc(color)+'" oninput="__tasksV2SetTaskColor('+t.id+',this.value)"><span style="background:'+color+'"></span></label>'+
          '<button type="button" class="tasks-v2-detail-icon" onclick="closeM(&quot;modal-task-detail&quot;);openTaskModal('+t.id+')" title="تعديل"><i class="fa-solid fa-pen"></i></button>'+
        '</div>'+
      '</div>'+
      '<div class="tasks-v2-detail-progress tasks-v2-detail-progress-compact"><span style="width:'+pct+'%;background:'+color+'"></span></div>'+
      '<div class="tasks-v2-info-strip">'+
        '<button onclick="openTaskModal('+t.id+')" title="تعديل قيمة المهمة"><small><i class="fa-solid fa-coins"></i> القيمة</small><b style="color:var(--accent3)">'+(t.value?money(t.value):'لا توجد')+'</b></button>'+
        '<button onclick="openTaskModal('+t.id+')" title="تعديل حالة الدفع"><small><i class="fa-solid fa-wallet"></i> الدفع</small><b>'+payText(t)+'</b></button>'+
        '<button onclick="openTaskModal('+t.id+')" title="وقت إنشاء المهمة"><small><i class="fa-regular fa-clock"></i> الإنشاء</small><b>'+createdLabel(t)+'</b></button>'+
        '<button onclick="openTaskModal('+t.id+')" title="تعديل تاريخ التسليم"><small><i class="fa-solid fa-calendar-check"></i> التسليم</small><b class="'+(hasLateDeadline?'is-late':'')+'">'+(t.deadline?niceDate(t.deadline):'غير محدد')+'</b></button>'+
      '</div>'+
      '<section class="tasks-v2-status-row-flow"><div><b>حالة المهمة</b><span>غيّر الحالة بضغطة واحدة</span></div><div>'+taskStatusButtonsHtml(t)+'</div></section>'+
      '<div class="tasks-v2-flow-grid">'+
        '<section class="tasks-v2-detail-section tasks-v2-flow-panel tasks-v2-flow-main"><h3><i class="fa-solid fa-file-lines"></i> التفاصيل</h3><div class="td-brief">'+(t.brief || t.desc || '<span style="color:var(--text3)">لا توجد تفاصيل مكتوبة لهذه المهمة</span>')+'</div></section>'+
        '<section class="tasks-v2-detail-section tasks-v2-flow-panel">'+
          '<h3><i class="fa-solid fa-address-card"></i> الأطراف</h3>'+
          '<div class="tasks-v2-flow-people">'+(client?'<span><i class="fa-solid fa-user"></i><b>العميل</b><em>'+esc(client.name || t.client)+'</em><small>'+(client.phone?esc(client.phone):'لا يوجد رقم')+'</small></span>':(t.client?'<span><i class="fa-solid fa-user"></i><b>العميل</b><em>'+esc(t.client)+'</em><small>غير محفوظ</small></span>':''))+(memberName?'<span><i class="fa-solid fa-user-gear"></i><b>المنفذ</b><em>'+esc(memberName)+'</em><small>'+(member&&member.phone?esc(member.phone):'لا يوجد رقم')+'</small></span>':'')+'</div>'+
          '<div class="tasks-v2-compact-send"><button class="btn btn-ghost btn-sm" onclick="__tasksV2SendTaskWhatsApp('+t.id+',&quot;client&quot;)"><i class="fa-brands fa-whatsapp"></i> إرسال للعميل</button>'+(memberName?'<button class="btn btn-ghost btn-sm" onclick="__tasksV2SendTaskWhatsApp('+t.id+',&quot;member&quot;)"><i class="fa-brands fa-whatsapp"></i> إرسال للمنفذ</button>':'')+'</div>'+
        '</section>'+
      '</div>'+
      '<div class="tasks-v2-flow-bottom">'+
        ((t.steps || []).length ? '<details class="tasks-v2-inline-details"><summary><i class="fa-solid fa-list-check"></i> خطوات المهمة <b>'+(t.steps || []).length+'</b></summary>'+renderStepsInDetail(t)+'</details>' : '')+
        (t.notes ? '<details class="tasks-v2-inline-details"><summary><i class="fa-solid fa-lock"></i> ملاحظات داخلية</summary><p class="tasks-v2-detail-note">'+esc(t.notes).replace(/\\n/g,'<br>')+'</p></details>' : '')+
        '<section class="tasks-v2-detail-section tasks-v2-flow-link"><h3><i class="fa-solid fa-link"></i> رابط التسليم</h3><div class="tasks-v2-detail-link"><input id="td-proj-link-input" type="url" value="'+link+'" placeholder="https://drive.google.com/... أو أي رابط للتسليم"><button class="btn btn-ghost btn-sm" onclick="_saveTaskDeliveryLink('+t.id+')"><i class="fa-solid fa-floppy-disk"></i> حفظ</button>'+(link?'<a class="btn btn-ghost btn-sm" target="_blank" href="'+link+'"><i class="fa-solid fa-arrow-up-right-from-square"></i></a>':'')+'</div></section>'+
        (notes.length ? '<button type="button" class="tasks-v2-note-summary" onclick="__tasksV2OpenNotes('+t.id+')"><i class="fa-solid fa-comments"></i><span>'+notes.length+' ملاحظات مضافة</span><i class="fa-solid fa-chevron-left"></i></button>' : '<button type="button" class="tasks-v2-note-summary is-empty" onclick="__tasksV2OpenNotes('+t.id+')"><i class="fa-solid fa-note-sticky"></i><span>إضافة ملاحظة</span><i class="fa-solid fa-plus"></i></button>')+
        (relInv.length ? '<details class="tasks-v2-inline-details"><summary><i class="fa-solid fa-file-invoice"></i> فواتير مرتبطة <b>'+relInv.length+'</b></summary>'+relInv.map(function(inv){ return '<div class="tasks-v2-detail-invoice"><b>'+esc(inv.num)+'</b><span>'+esc(inv.date || '')+'</span><strong>'+money(_invoiceDisplayTotal(inv))+'</strong></div>'; }).join('')+'</details>' : '')+
      '</div>'+
      '</div>'+
      '<div class="tasks-v2-detail-actions tasks-v2-compact-actions tasks-v2-flow-actions">'+
        (st !== 'done' ? '<button class="btn btn-success" onclick="closeM(&quot;modal-task-detail&quot;);completeTask('+t.id+')"><i class="fa-solid fa-check"></i> إكمال</button>' : '<button class="btn btn-ghost" onclick="closeM(&quot;modal-task-detail&quot;);completeTask('+t.id+')">إلغاء الإكمال</button>')+
        '<button class="btn btn-ghost" onclick="closeM(&quot;modal-task-detail&quot;);__tasksV2InvoiceFromTask('+t.id+')"><i class="fa-solid fa-file-invoice"></i> فاتورة</button>'+
        '<button class="btn btn-danger btn-sm" onclick="closeM(&quot;modal-task-detail&quot;);delTask('+t.id+')"><i class="fa-solid fa-trash"></i> حذف</button>'+
      '</div>'+
    '</div>';
    openM('modal-task-detail');
  }
  function renderTaskNotesModal(id){
    var t = (S.tasks || []).find(function(x){ return Number(x.id) === Number(id) || String(x.id) === String(id); });
    if(!t) return;
    var ov = document.getElementById('modal-task-notes');
    if(!ov){
      ov = document.createElement('div');
      ov.id = 'modal-task-notes';
      ov.className = 'modal-overlay';
      document.body.appendChild(ov);
    }
    var notes = taskNotes(t);
    ov.innerHTML = '<div class="modal tasks-v2-notes-modal">'+
      '<div class="modal-header"><h3><i class="fa-solid fa-comments"></i> ملاحظات المهمة <span>'+notes.length+'</span></h3><button class="close-btn" onclick="closeM(&quot;modal-task-notes&quot;)"><i class="fa-solid fa-xmark"></i></button></div>'+
      '<div class="tasks-v2-notes-body">'+
        '<div class="tasks-v2-notes-title"><b>'+esc(t.title || 'مهمة بدون اسم')+'</b><small>'+esc(t.client || '')+'</small></div>'+
        '<div class="tasks-v2-notes-list">'+(notes.length ? commentsHtml(t) : '<div class="tasks-v2-detail-empty">لا توجد ملاحظات بعد</div>')+'</div>'+
        '<div class="tasks-v2-notes-form"><textarea id="task-notes-input" rows="3" placeholder="اكتب ملاحظة قصيرة..."></textarea><button class="btn btn-success" onclick="__tasksV2AddNote('+t.id+')"><i class="fa-solid fa-paper-plane"></i> إضافة</button></div>'+
      '</div>'+
    '</div>';
    openM('modal-task-notes');
  }
  window.__tasksV2InvoiceFromTask = function(id){
    var t = (S.tasks || []).find(function(x){ return Number(x.id) === Number(id) || String(x.id) === String(id); });
    if(t && typeof openInvoiceFromTask === 'function') openInvoiceFromTask(t);
  };
  window.__tasksV2SubmitComment = function(id){
    var input = document.getElementById('td-comment-input');
    if(typeof window._submitLocalComment === 'function') window._submitLocalComment(String(id), input, null);
  };
  window.__tasksV2OpenNotes = function(id){
    renderTaskNotesModal(id);
  };
  window.__tasksV2AddNote = function(id){
    var input = document.getElementById('task-notes-input');
    var text = input ? input.value.trim() : '';
    if(!text) return;
    addTaskComment(id, text, null);
    if(input) input.value = '';
    renderModernTaskDetail(id);
    renderTaskNotesModal(id);
    if(typeof showMiniNotif === 'function') showMiniNotif('تمت إضافة الملاحظة');
  };
  window.__tasksV2DeleteComment = function(id, commentIdx){
    var t = (S.tasks || []).find(function(x){ return String(x.id) === String(id); });
    if(!t || !Array.isArray(t.comments)) return;
    var visible = t.comments.map(function(c, i){ return {c:c, i:i}; }).filter(function(x){ return x.c.stepIdx === null || x.c.stepIdx === undefined; });
    var real = visible[commentIdx] && visible[commentIdx].i;
    if(real === undefined) return;
    t.comments.splice(real, 1);
    lsSave();
    if(typeof cloudSave === 'function') cloudSave(S);
    renderModernTaskDetail(id);
    if(document.getElementById('modal-task-notes') && document.getElementById('modal-task-notes').classList.contains('open')){
      renderTaskNotesModal(id);
    }
  };
  window.__tasksV2SetTaskColor = function(id, color){
    var t = findTaskAny(id);
    if(!t) return;
    t.color = color || '';
    lsSave();
    if(typeof cloudSave === 'function') cloudSave(S);
    var hero = document.querySelector('#modal-task-detail .tasks-v2-detail-hero');
    if(hero) hero.style.borderRightColor = color;
  };
  window.__tasksV2SendTaskWhatsApp = function(id, target){
    var t = (S.tasks || []).find(function(x){ return String(x.id) === String(id); });
    if(!t) return;
    var memberName = t.workerMember || t.assignee_name || '';
    var member = target === 'member' ? findTeamMemberByName(memberName) : null;
    var client = target !== 'member' ? findClientByName(t.client) : null;
    var recipName = target === 'member' ? (memberName || 'المنفذ') : (t.client || 'العميل');
    var phone = target === 'member' ? (member && (member.phone || member.whatsapp) || '') : (client && (client.phone || client.whatsapp) || '');
    var msg = taskDetailMessage(t, recipName);
    if(typeof window.openReceivableWhatsAppModal === 'function') return window.openReceivableWhatsAppModal(recipName, phone, msg);
    openWaModal('task', null, t.id);
  };
  if(typeof openTaskDetail === 'function'){
    openTaskDetail = function(id){ renderModernTaskDetail(id); };
  }
  function ensureShell(page){
    var shell = document.getElementById('tasks-v2-shell');
    if(!shell){
      shell = document.createElement('div');
      shell.id = 'tasks-v2-shell';
      shell.className = 'tasks-v2-shell';
      page.insertBefore(shell, page.firstChild);
    }
    return shell;
  }
  function setClassicVisibility(page, isClassic){
    Array.from(page.children).forEach(function(child){
      if(child.id === 'tasks-v2-shell' || child.id === 'tasks-v2-classic-note') return;
      if(!isClassic){
        if(child.dataset.tasksV2PrevDisplay === undefined){
          child.dataset.tasksV2PrevDisplay = child.style.display || '';
        }
        child.style.display = 'none';
      } else if(child.dataset.tasksV2PrevDisplay !== undefined){
        child.style.display = child.dataset.tasksV2PrevDisplay;
        delete child.dataset.tasksV2PrevDisplay;
      }
    });
    var note = document.getElementById('tasks-v2-classic-note');
    if(isClassic){
      if(!note){
        note = document.createElement('div');
        note.id = 'tasks-v2-classic-note';
        note.className = 'tasks-v2-classic-note';
        note.innerHTML = '<div><b>الشكل الحالي مفعل</b><div style="font-size:12px;color:var(--text3);margin-top:2px">تقدر ترجع للتصميم الجديد في أي وقت.</div></div><button class="btn btn-primary" onclick="setTasksV2Mode(\'new\')"><i class="fa-solid fa-layer-group"></i> تفعيل التصميم الجديد</button>';
        page.insertBefore(note, page.firstChild);
      }
      note.style.display = 'flex';
    } else if(note){
      note.style.display = 'none';
    }
  }
  function renderTasksV2(){
    var page = document.getElementById('page-tasks');
    if(!page) return;
    var classic = tasksV2Mode() === 'classic';
    setClassicVisibility(page, classic);
    var shell = ensureShell(page);
    shell.style.display = classic ? 'none' : 'flex';
    if(classic) return;

    var f = readFilters();
    var all = tasksV2Source();
    var filtered = tasksForV2();
    var open = all.filter(function(t){ return taskStatus(t) !== 'done'; });
    var done = all.filter(function(t){ return taskStatus(t) === 'done'; });
    var today = todayIso();
    var tomorrow = addDaysIso(1);
    var late = open.filter(function(t){ return t.deadline && t.deadline < today; });
    var dueToday = open.filter(function(t){ return t.deadline === today; });
    var dueTomorrow = open.filter(function(t){ return t.deadline === tomorrow; });
    var pct = all.length ? Math.round(done.length / all.length * 100) : 0;
    var filtersOpen = localStorage.getItem(STORE_FILTER_OPEN) === '1';
    var activeFilters = ['search','status','priority','client','date'].filter(function(k){ return !!f[k]; }).length;
    var view = tasksV2View();
    var suggestions = taskSearchSuggestions(f.search);

    var boardStatuses = visibleStatuses();
    var board = boardStatuses.map(function(st){
      var items = filtered.filter(function(t){ return taskStatus(t) === st.id; });
      return '<section class="tasks-v2-col" data-status="'+st.id+'" ondragover="__tasksV2DragOver(event)" ondragleave="__tasksV2DragLeave(event)" ondrop="__tasksV2Drop(event)">'+
        '<div class="tasks-v2-col-head"><div class="tasks-v2-col-title"><span class="tasks-v2-dot" style="background:'+st.color+'"></span><span>'+esc(st.label)+'</span></div><span class="tasks-v2-count">'+items.length+'</span></div>'+
        '<div class="tasks-v2-col-body">'+(items.length ? items.map(cardHtml).join('') : '<div class="tasks-v2-empty">اسحب مهمة هنا</div>')+'</div>'+
      '</section>';
    }).join('');

    shell.innerHTML =
      '<div class="tasks-v2-hero">'+
        '<div><div class="tasks-v2-title">المهام والتاسكات</div><div class="tasks-v2-subtitle">كانبان بعرض الصفحة، واسحب المهمة بين الحالات لتحديثها.</div></div>'+
        '<div class="tasks-v2-actions">'+
          '<button class="btn btn-primary tasks-v2-new-btn" onclick="openTaskModal()"><i class="fa-solid fa-plus"></i> مهمة جديدة</button>'+
          '<button class="tasks-v2-action-icon" onclick="openTasksArchivePage()" title="أرشيف المهام"><i class="fa-solid fa-box-archive"></i>'+((S.archivedTasks||[]).length?'<span>'+(S.archivedTasks||[]).length+'</span>':'')+'</button>'+
          '<button class="tasks-v2-action-icon '+(activeFilters?'is-active':'')+'" data-tasks-v2-action="filters" title="فلترة"><i class="fa-solid fa-filter"></i>'+(activeFilters?'<span>'+activeFilters+'</span>':'')+'</button>'+
          '<button class="tasks-v2-action-icon" data-tasks-v2-action="classic" title="الشكل الحالي"><i class="fa-solid fa-rotate-left"></i></button>'+
          '<button class="tasks-v2-action-icon" data-tasks-v2-action="statuses" title="إدارة الحالات"><i class="fa-solid fa-sliders"></i></button>'+
        '</div>'+
      '</div>'+
      '<div class="tasks-v2-quick-stats">'+
        '<button class="tasks-v2-quick-card is-danger" onclick="__tasksV2SetFilter(&quot;date&quot;,&quot;late&quot;)"><b>'+late.length+'</b><span>مهام متأخرة</span><small>عرض التفاصيل</small></button>'+
        '<button class="tasks-v2-quick-card" onclick="__tasksV2SetFilter(&quot;status&quot;,&quot;&quot;)"><b>'+open.length+'</b><span>غير مكتملة</span><small>كل النشط والموقوف والجديد</small></button>'+
        '<div class="tasks-v2-quick-card is-progress"><b>'+pct+'%</b><span>نسبة الإنجاز</span><small>'+done.length+' مكتملة من '+all.length+'</small></div>'+
        '<button class="tasks-v2-quick-card is-warn" onclick="__tasksV2SetFilter(&quot;date&quot;,&quot;tomorrow&quot;)"><b>'+dueTomorrow.length+'</b><span>تسليم بكرة</span><small>تنبيه قبل الميعاد</small></button>'+
      '</div>'+
      '<div class="tasks-v2-search-block">'+
        '<div class="tasks-v2-search-box">'+
          '<i class="fa-solid fa-magnifying-glass"></i>'+
          '<input value="'+esc(f.search)+'" placeholder="ابحث عن تاسك في المهام أو مهام المشاريع..." oninput="__tasksV2SetFilter(\'search\',this.value)">'+
          (f.search?'<button type="button" onclick="__tasksV2SetFilter(&quot;search&quot;,&quot;&quot;)" title="مسح البحث"><i class="fa-solid fa-xmark"></i></button>':'')+
        '</div>'+
        (f.search?'<div class="tasks-v2-search-meta">'+filtered.length+' نتيجة مطابقة لكلمة البحث</div>':'')+
        (suggestions.length?'<div class="tasks-v2-suggestions">'+suggestions.map(function(t){return '<button type="button" onclick="__tasksV2PickSuggestion(&quot;'+esc(t._v2Key)+'&quot;)"><span style="background:'+(t._isProjectTask?t.projectColor:taskColor(t))+'"></span><b>'+esc(t.title||'مهمة بدون اسم')+'</b><small>'+(t._isProjectTask?'مشروع: '+esc(t.projectName):esc(t.client||'بدون عميل'))+'</small></button>';}).join('')+'</div>':'')+
      '</div>'+
      '<div class="tasks-v2-toolbar '+(filtersOpen?'is-open':'')+'">'+
        '<input class="tasks-v2-input" value="'+esc(f.search)+'" placeholder="بحث باسم المهمة أو العميل..." oninput="__tasksV2SetFilter(\'search\',this.value)">'+
        '<select class="tasks-v2-select" onchange="__tasksV2SetFilter(\'status\',this.value)">'+statusOptions(f.status)+'</select>'+
        '<select class="tasks-v2-select" onchange="__tasksV2SetFilter(\'priority\',this.value)"><option value="">كل الأولويات</option><option value="high" '+(f.priority==='high'?'selected':'')+'>عاجل</option><option value="med" '+(f.priority==='med'?'selected':'')+'>متوسط</option><option value="low" '+(f.priority==='low'?'selected':'')+'>عادي</option></select>'+
        '<select class="tasks-v2-select" onchange="__tasksV2SetFilter(\'client\',this.value)">'+clientOptions(f.client)+'</select>'+
        '<select class="tasks-v2-select" onchange="__tasksV2SetFilter(\'date\',this.value)"><option value="">كل المواعيد</option><option value="late" '+(f.date==='late'?'selected':'')+'>متأخر</option><option value="today" '+(f.date==='today'?'selected':'')+'>اليوم</option><option value="tomorrow" '+(f.date==='tomorrow'?'selected':'')+'>بكرة</option><option value="week" '+(f.date==='week'?'selected':'')+'>خلال أسبوع</option></select>'+
        '<button class="btn btn-ghost" onclick="localStorage.removeItem(\''+STORE_FILTERS+'\');renderTasks()"><i class="fa-solid fa-xmark"></i> مسح</button>'+
      '</div>'+
      '<div class="tasks-v2-layout '+(view==='list'?'is-list':'is-kanban')+'">'+
        '<div class="tasks-v2-board-wrap">'+
          '<div class="tasks-v2-board-head"><div><b>'+(view==='list'?'قائمة المهام':'كانبان المهام')+'</b><div style="font-size:12px;color:var(--text3);margin-top:2px">'+filtered.length+' مهمة حسب الفلتر الحالي</div></div><div class="tasks-v2-board-tools"><button class="tasks-v2-action-icon '+(view==='kanban'?'is-active':'')+'" data-tasks-v2-action="view-kanban" title="عرض كانبان"><i class="fa-solid fa-table-columns"></i></button><button class="tasks-v2-action-icon '+(view==='list'?'is-active':'')+'" data-tasks-v2-action="view-list" title="عرض القائمة"><i class="fa-solid fa-list"></i></button><span>'+pct+'%</span><div class="tasks-v2-progress"><span style="width:'+pct+'%"></span></div></div></div>'+
          (view==='list' ? listHtml(filtered) : '<div class="tasks-v2-board">'+board+'</div>')+
        '</div>'+
      '</div>';
    setTimeout(function(){ if(typeof runDailyArchive === 'function') runDailyArchive(); }, 300);
  }

  window.__tasksV2OpenTask = function(ev, id){
    if(justDragged){ ev && ev.stopPropagation(); return; }
    var key = String(id || '');
    if(key.indexOf('p_') === 0){
      var pt = (S.project_tasks || []).find(function(t){ return String(t.id) === key.slice(2); });
      if(pt) return openProjectDetail(pt.project_id);
    }
    openTaskDetail(key.replace(/^t_/, ''));
  };
  document.addEventListener('click', function(ev){
    var btn = ev.target.closest && ev.target.closest('[data-tasks-v2-action]');
    if(!btn) return;
    ev.preventDefault();
    ev.stopPropagation();
    var action = btn.getAttribute('data-tasks-v2-action');
    if(action === 'filters') return window.__tasksV2ToggleFilters();
    if(action === 'classic') return setTasksV2Mode('classic');
    if(action === 'view-kanban') return window.__tasksV2SetView('kanban');
    if(action === 'view-list') return window.__tasksV2SetView('list');
    if(action === 'statuses' && typeof openStatusManagerModal === 'function') return openStatusManagerModal();
  });
  window.__tasksV2DragStart = function(ev, id){
    dragId = id;
    justDragged = false;
    ev.dataTransfer.effectAllowed = 'move';
    ev.dataTransfer.setData('text/plain', String(id));
    setTimeout(function(){
      var el = document.querySelector('#tasks-v2-shell [data-task-id="'+id+'"]');
      if(el) el.classList.add('dragging');
    }, 0);
  };
  window.__tasksV2DragEnd = function(){
    document.querySelectorAll('#tasks-v2-shell .dragging').forEach(function(el){ el.classList.remove('dragging'); });
    if(dragId){
      justDragged = true;
      setTimeout(function(){ justDragged = false; }, 260);
    }
    dragId = null;
  };
  window.__tasksV2DragOver = function(ev){
    ev.preventDefault();
    ev.dataTransfer.dropEffect = 'move';
    ev.currentTarget.classList.add('drag-over');
  };
  window.__tasksV2DragLeave = function(ev){
    ev.currentTarget.classList.remove('drag-over');
  };
  window.__tasksV2Drop = function(ev){
    ev.preventDefault();
    var col = ev.currentTarget;
    col.classList.remove('drag-over');
    var rawId = String(dragId || ev.dataTransfer.getData('text/plain') || '');
    var status = col.dataset.status;
    var isProjectTask = rawId.indexOf('p_') === 0;
    var id = rawId.replace(/^p_/, '').replace(/^t_/, '');
    var task = (isProjectTask ? (S.project_tasks || []) : (S.tasks || [])).find(function(t){ return String(t.id) === String(id); });
    if(!task || !status) return;
    if(isProjectTask){
      task.status = status === 'new' ? 'todo' : (status === 'paused' ? 'hold' : status);
      task.done = status === 'done';
      if(status === 'done'){
        task.doneAt = task.doneAt || todayIso();
        task.completedAt = task.completedAt || new Date().toISOString();
      } else {
        task.doneAt = null;
        task.completedAt = null;
      }
      lsSave();
      if(typeof cloudSave === 'function') cloudSave(S);
      if(typeof showMiniNotif === 'function') showMiniNotif('<i class="fa-solid fa-diagram-project" style="color:var(--accent)"></i> تم نقل مهمة المشروع');
      renderAll();
      return;
    }
    task.status = status === 'done' ? 'done' : status;
    if(status === 'done'){
      _markTaskCompleted(task);
    } else {
      task.done = false;
      task.doneAt = null;
      task.completedAt = null;
      task.archiveReminder24ShownAt = null;
      task.archiveReminder48ShownAt = null;
      task.archiveReminderShownAt = null;
      task.archiveReminderAgainAt = null;
    }
    lsSave();
    if(typeof cloudSave === 'function') cloudSave(S);
    if(typeof showMiniNotif === 'function') showMiniNotif('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم نقل المهمة إلى '+getStatusLabel(status));
    renderAll();
  };

  if(typeof renderTasks === 'function'){
    var oldRenderTasksV2 = renderTasks;
    renderTasks = function(){
      var out = oldRenderTasksV2.apply(this, arguments);
      setTimeout(renderTasksV2, 0);
      return out;
    };
  }
  window.addEventListener('DOMContentLoaded', function(){ setTimeout(renderTasksV2, 180); });
})();

// â”€â”€â”€ Admin-sent Updates Renderer â”€â”€â”€
function _renderAdminUpdates(container){
  // Admin updates stored in S._platform_updates (array injected by admin into studio_data)
  var updates = (typeof S !== 'undefined' && S._platform_updates) ? S._platform_updates : [];
  // Also check localStorage for cached platform updates
  try {
    var cached = JSON.parse(localStorage.getItem('_platform_updates_cache')||'[]');
    // Merge, deduplicate by id
    cached.forEach(function(u){ if(!updates.find(function(x){ return x.id===u.id; })) updates.push(u); });
  } catch(e){}
  if(!updates.length){ container.innerHTML = ''; return; }
  // Sort by date desc
  updates = updates.slice().sort(function(a,b){ return new Date(b.date||0) - new Date(a.date||0); });
  var lastReadAdminUpdate = localStorage.getItem('_last_read_admin_update')||'';
  var newOnes = [];
  updates.forEach(function(u,i){ if(u.id !== lastReadAdminUpdate && !newOnes.includes(u.id)) newOnes.push(u.id); if(i===0) {} });
  container.innerHTML =
    '<div style="background:linear-gradient(135deg,rgba(124,111,247,.1),rgba(79,209,165,.05));border:1.5px solid var(--accent);border-radius:12px;padding:14px 16px;margin-bottom:16px">'+
    '<div style="display:flex;align-items:center;gap:8px;margin-bottom:12px">'+
      '<div style="font-size:14px;font-weight:800;color:var(--accent)"><i class="fa-solid fa-bullhorn"></i> تحديثات الإدارة</div>'+
      (newOnes.length?'<span style="background:var(--accent4);color:#fff;font-size:10px;font-weight:700;padding:2px 8px;border-radius:20px">'+newOnes.length+' جديد</span>':'')+
    '</div>'+
    updates.map(function(u){
      var isNew = newOnes.includes(u.id);
      return '<div style="padding:12px;background:var(--surface2);border-radius:10px;margin-bottom:8px;border-right:3px solid '+(isNew?'var(--accent4)':'var(--border)')+'">'+
        '<div style="display:flex;align-items:center;gap:8px;margin-bottom:5px">'+
          '<span style="font-size:18px">'+(u.emoji||'<i class="fa-solid fa-thumbtack"></i>')+'</span>'+
          '<div style="font-size:13px;font-weight:700;flex:1">'+u.title+'</div>'+
          (isNew?'<span style="background:var(--accent4);color:#fff;font-size:9px;font-weight:700;padding:2px 7px;border-radius:8px">جديد</span>':'')+
          '<span style="font-size:10px;color:var(--text3)">'+(u.date?new Date(u.date).toLocaleDateString('ar-EG'):'')+'</span>'+
        '</div>'+
        '<div style="font-size:12px;color:var(--text2);line-height:1.7">'+u.body+'</div>'+
      '</div>';
    }).join('')+
    '<button class="btn btn-ghost btn-sm" style="margin-top:4px" onclick="_markAdminUpdatesSeen()"><i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تحديد كمقروء</button>'+
    '</div>';
}
function _markAdminUpdatesSeen(){
  var updates = (typeof S !== 'undefined' && S._platform_updates) ? S._platform_updates : [];
  if(updates.length) localStorage.setItem('_last_read_admin_update', updates[0].id);
  var adminUpdatesEl = document.getElementById('admin-updates-list');
  if(adminUpdatesEl) _renderAdminUpdates(adminUpdatesEl);
}

// Startup: check for new admin updates
(function(){
  setTimeout(function(){
    var updates = (typeof S !== 'undefined' && S._platform_updates) ? S._platform_updates : [];
    if(!updates.length) return;
    var lastRead = localStorage.getItem('_last_read_admin_update')||'';
    var latest = updates[0];
    if(latest && latest.id !== lastRead){
      // Cache them
      try{ localStorage.setItem('_platform_updates_cache', JSON.stringify(updates.slice(0,20))); }catch(e){}
      if(typeof addNotification === 'function'){
        addNotification('<i class="fa-solid fa-bullhorn"></i> '+(latest.emoji||'')+(latest.title||'تحديث جديد من الإدارة'),'info');
      }
      var badge=document.getElementById('stab-features-badge');
      if(badge)badge.style.display='inline-block';
    }
  }, 3000);
})();


function renderClients(){
  const grid=document.getElementById('clients-grid');if(!grid)return;
  const clientsPage=document.getElementById('page-clients');
  if(clientsPage) clientsPage.classList.add('clients-v2-page');

  // apply filters
  const typeF   = document.getElementById('cf-type')?.value||'';
  const chanF   = document.getElementById('cf-channel')?.value||'';
  const searchF = (document.getElementById('cf-search')?.value||'').trim().toLowerCase();

  let clients = S.clients;
  if(typeF)   clients = clients.filter(c=>c.type===typeF);
  if(chanF)   clients = clients.filter(c=>c.channel===chanF);
  if(searchF) clients = clients.filter(c=>(c.name+' '+(c.notes||'')).toLowerCase().includes(searchF));

  const cnt = document.getElementById('cf-count');
  if(cnt) cnt.textContent = clients.length < S.clients.length ? `${clients.length} من ${S.clients.length}` : '';

  if(!clients.length){
    var emptyMsg = S.clients.length
      ? '<div class="empty" style="grid-column:span 3"><div class="empty-icon"><i class="fa-solid fa-magnifying-glass"></i></div>لا نتائج تطابق الفلتر</div>'
      : '<div class="empty" style="grid-column:span 3"><div class="empty-icon"><i class="fa-solid fa-circle-dot"></i></div>لم تضف عملاء بعد</div>';
    grid.innerHTML=emptyMsg;
    var listV=document.getElementById('clients-list-view'); if(listV) listV.innerHTML=emptyMsg;
    var tbodyV=document.getElementById('clients-table-body'); if(tbodyV) tbodyV.innerHTML='<tr><td colspan="7" style="text-align:center;padding:32px;color:var(--text3)">لا نتائج</td></tr>';
    return;
  }
  const cTasks=n=>S.tasks.filter(t=>t.client===n).length;
  const cInc=n=>S.transactions.filter(t=>t.type==='income'&&t.source===n).reduce((s,t)=>s+t.amount,0);
  const cThisMonth=n=>{const now=new Date();const ms=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');return S.tasks.filter(t=>t.client===n&&((t.isoDate||'').startsWith(ms)||(t.doneAt||'').startsWith(ms))).length;};
  const idVal=v=>v==null?'':String(v);
  const invoiceTaskIdsForClient=(c,allNames,clientIds)=>{
    const ids=new Set();
    const names=(allNames&&allNames.length?allNames:[c.name]).filter(Boolean);
    const cids=(clientIds&&clientIds.length?clientIds:[String(c.id)]).map(String);
    (S.invoices||[]).filter(i=>i&&(
      names.includes(i.client||i.client_name||i.clientName||'') ||
      cids.includes(String(i.clientId||i.client_id||''))
    )).forEach(inv=>{
      (inv.items||[]).forEach(it=>{
        const taskId=it&&(idVal(it._taskId)||idVal(it.taskId)||idVal(it.linkedTaskId));
        if(taskId) ids.add(taskId);
        const projectTaskId=it&&(idVal(it._projectTaskId)||idVal(it.projectTaskId)||idVal(it.linkedProjTaskId));
        if(projectTaskId) ids.add(projectTaskId);
      });
    });
    return ids;
  };
  const cDueParts=c=>{
    const subClients=(S.clients||[]).filter(sc=>String(sc.parentClientId)===String(c.id));
    const allNames=[c.name].concat(subClients.map(sc=>sc.name)).filter(Boolean);
    const clientIds=[String(c.id)].concat(subClients.map(sc=>String(sc.id)));
    const cSummary=(window.OrdoReports&&typeof window.OrdoReports.getClientSummary==='function') ? window.OrdoReports.getClientSummary(c.id) : null;
    const matchClientEntity=e=>e&&(
      clientIds.includes(String(e.client_id||e.clientId||'')) ||
      allNames.includes(e.client||e.client_name||e.clientName||e.source||'')
    );
    const invs=(cSummary&&Array.isArray(cSummary.invoices)?cSummary.invoices:(S.invoices||[]).filter(matchClientEntity)).filter(i=>!_isProjectInvoice(i));
    const invDue=invs.filter(i=>!(i.paid||i.status==='مدفوعة'||i.status==='paid')).reduce((s,i)=>s+(+i.total||0),0);
    const invTotal=invs.reduce((s,i)=>s+(+i.total||0),0);
    const invPaid=invs.filter(i=>i.paid||i.status==='مدفوعة'||i.status==='paid').reduce((s,i)=>s+(+i.total||0),0);
    const unpaidInv=Math.max(0,invTotal-invPaid);
    const invoicedTaskIds=invoiceTaskIdsForClient(c,allNames,clientIds);
    const taskValue=t=>+(t&&(t.value??t.amount??t.price??t.total??t.clientAmount??t.clientPrice))||0;
    const taskPaidAmount=t=>+(t&&(t.deposit??t.paidAmount??t.amountPaid??t.collectedAmount))||0;
    const taskDue=getAllTasksIncludingArchived().filter(matchClientEntity).reduce((s,t)=>{
      if(invoicedTaskIds.has(idVal(t.id))) return s;
      const paid=!!(t.paymentCollected||t.paid||t.pay==='full'||t.pay==='paid'||t.paymentStatus==='collected'||t.paymentStatus==='paid');
      return s+(paid?0:Math.max(0,taskValue(t)-taskPaidAmount(t)));
    },0);
    const projectDue=_clientProjectDueRows(allNames,clientIds).reduce((s,p)=>s+p.due,0);
    const openBal=(+c.openingBalance||0);
    const openingDue=(c.openingBalanceType==='receivable'?openBal:0)-(c.openingBalanceType==='prepaid'?openBal:0);
    const profileDue=Math.max(0,unpaidInv+taskDue+openingDue);
    return {
      invoices:Math.max(0,invDue),
      tasks:Math.max(0,taskDue),
      projects:Math.max(0,projectDue),
      opening:openingDue,
      total:Math.max(0,profileDue+projectDue)
    };
  };
  const cDue=c=>cDueParts(c).total;
  const oldSummary=document.getElementById('clients-v2-summary');
  if(oldSummary) oldSummary.remove();
  
  // Grid view
  grid.innerHTML=clients.map(c=>{
    const dueParts=cDueParts(c);
    const due=dueParts.total;
    const taskCount=cTasks(c.name);
    const nameLength=String(c.name||'').trim().length;
    const nameClass=nameLength>34?' is-very-long':(nameLength>22?' is-long':'');
    const contact=[c.phone?`<span><i class="fa-solid fa-phone"></i> ${escapeHtml(c.phone)}</span>`:'',c.email?`<span><i class="fa-solid fa-envelope"></i> ${escapeHtml(c.email)}</span>`:''].filter(Boolean).join('');
    return `
    <article class="client-card client-card-v2 client-card-simple" onclick="openClientProfile(${c.id})" style="--client-color:${c.color||'var(--accent)'}">
      <div class="client-simple-card-main">
        <div class="client-simple-card-avatar">${escapeHtml((c.name||'?')[0])}</div>
        <div class="client-simple-card-info">
          <b class="${nameClass}" title="${escapeHtml(c.name||'عميل')}">${escapeHtml(c.name||'عميل')}</b>
          <span>${escapeHtml(c.type||'عميل')} · ${escapeHtml(c.channel||'غير محدد')}${c.field?' · '+escapeHtml(c.field):''}</span>
        </div>
        <div class="client-simple-card-actions" onclick="event.stopPropagation()">
          <button title="تعديل" onclick="openClientModal(${c.id})"><i class="fa-solid fa-pen"></i></button>
          <button title="بوابة" onclick="openClientPortal(${c.id})"><i class="fa-solid fa-link"></i></button>
          <button title="حذف" onclick="delClient(${c.id})"><i class="fa-solid fa-trash"></i></button>
        </div>
      </div>
      <div class="client-simple-card-contact">${contact || '<span>لا توجد بيانات تواصل</span>'}</div>
      <div class="client-simple-card-stats">
        <span><b>${taskCount.toLocaleString('ar-EG')}</b><small>مهام</small></span>
        <span class="${due>0?'is-due':'is-clear'}"><b>${due.toLocaleString('ar-EG')}</b><small>مستحق</small></span>
      </div>
    </article>`;
  }).join('');

  // List view
  var listV=document.getElementById('clients-list-view');
  if(listV){
    listV.innerHTML='<div style="display:flex;flex-direction:column;gap:8px">'+clients.map(c=>{
      var acc2=c.color||'var(--accent)';
      var clientTasks=S.tasks.filter(t=>t.client===c.name);
      var hasTasksToShow=clientTasks.length>0;
      return '<div class="card" style="padding:0;border-right:3px solid '+acc2+';overflow:hidden">'
        +'<div style="display:flex;align-items:center;gap:12px;padding:14px 18px;cursor:pointer" onclick="openClientProfile('+c.id+')">'
          +(hasTasksToShow?'<button onclick="event.stopPropagation();_toggleClientTasks('+c.id+')" style="background:none;border:none;cursor:pointer;color:var(--accent);font-size:12px;padding:4px;flex-shrink:0;transition:transform .2s" id="_cl-arrow-'+c.id+'"><i class="fa-solid fa-chevron-down"></i></button>':'<span style="width:28px"></span>')
          +'<div style="width:40px;height:40px;border-radius:50%;background:'+acc2+'22;color:'+acc2+';font-size:16px;font-weight:900;display:flex;align-items:center;justify-content:center;flex-shrink:0">'+c.name[0]+'</div>'
          +'<div style="flex:1;min-width:0">'
            +'<div style="font-size:14px;font-weight:800">'+escapeHtml(c.name)+'</div>'
            +'<div style="font-size:11px;color:var(--text3)">'+(c.type||'')+' آ· '+(c.channel||'')+(c.phone?' آ· '+c.phone:'')+'</div>'
          +'</div>'
          +'<div style="display:flex;gap:12px;align-items:center;font-size:12px;color:var(--text3)">'
            +'<span><strong style="color:'+acc2+'">'+cTasks(c.name)+'</strong> مشروع</span>'
            +'<span><strong style="color:var(--accent2)">'+cThisMonth(c.name)+'</strong> هذا الشهر</span>'
          +'</div>'
          +'<div style="display:flex;gap:4px" onclick="event.stopPropagation()">'
            +'<button class="btn btn-ghost btn-sm" onclick="openClientModal('+c.id+')"><i class="fa-solid fa-pen"></i></button>'
            +'<button class="btn btn-ghost btn-sm" onclick="openClientPortal('+c.id+')"><i class="fa-solid fa-link"></i></button>'
          +'</div>'
        +'</div>'
        +(hasTasksToShow?'<div id="_cl-tasks-'+c.id+'" style="display:none;padding:0 18px 14px;background:var(--surface2);border-top:1px solid var(--border)">'
          +'<div style="font-size:11px;font-weight:800;color:var(--text3);padding:10px 0 8px"><i class="fa-solid fa-list-check" style="color:var(--accent);margin-left:4px"></i> مشاريع العميل ('+clientTasks.length+')</div>'
          +clientTasks.slice(0,10).map(function(t){
            var isDone=t.done||t.status==='done';
            var stColor=isDone?'var(--accent3)':t.status==='progress'?'var(--accent2)':t.status==='review'?'var(--accent)':'var(--text3)';
            var stLabel=isDone?'مكتمل':t.status==='progress'?'جاري':t.status==='review'?'مراجعة':t.status==='paused'?'موقوف':'جديد';
            return '<div style="display:flex;align-items:center;gap:8px;padding:7px 0;border-bottom:1px solid var(--border);font-size:12px;cursor:pointer" onclick="event.stopPropagation();openTaskDetail('+t.id+')">'
              +'<div style="width:8px;height:8px;border-radius:50%;background:'+stColor+';flex-shrink:0"></div>'
              +'<div style="flex:1;'+(isDone?'text-decoration:line-through;color:var(--text3)':'')+'">'+escapeHtml(t.title)+'</div>'
              +'<span style="font-size:10px;font-weight:700;color:'+stColor+';background:'+stColor+'18;padding:2px 7px;border-radius:8px">'+stLabel+'</span>'
              +(t.value?'<span style="font-size:10px;color:var(--accent3);font-weight:700">'+t.value.toLocaleString()+' ج</span>':'')
            +'</div>';
          }).join('')
          +(clientTasks.length>10?'<div style="font-size:11px;color:var(--accent);text-align:center;padding:8px;font-weight:700;cursor:pointer" onclick="event.stopPropagation();openClientProfile('+c.id+')">+ '+String(clientTasks.length-10)+' مشروع آخر â†گ</div>':'')
        +'</div>':'')
      +'</div>';
    }).join('')+'</div>';
  }

  // Table view
  var tbodyV=document.getElementById('clients-table-body');
  if(tbodyV){
    tbodyV.innerHTML=clients.map(function(c,idx){
      var bg=idx%2===0?'var(--surface)':'var(--surface2)';
      return '<tr style="background:'+bg+';cursor:pointer" onclick="openClientProfile('+c.id+')">'
        +'<td style="padding:10px 14px;border-bottom:1px solid var(--border)"><div style="display:flex;align-items:center;gap:8px"><div style="width:30px;height:30px;border-radius:50%;background:'+(c.color||'var(--accent)')+'22;color:'+(c.color||'var(--accent)')+';font-size:12px;font-weight:900;display:flex;align-items:center;justify-content:center;flex-shrink:0">'+c.name[0]+'</div><div style="font-weight:700">'+escapeHtml(c.name)+'</div></div></td>'
        +'<td style="padding:10px 8px;text-align:center;border-bottom:1px solid var(--border);font-size:11px;color:var(--text3)">'+(c.type||'?')+'</td>'
        +'<td style="padding:10px 8px;text-align:center;border-bottom:1px solid var(--border);font-size:11px;color:var(--text3)">'+(c.channel||'?')+'</td>'
        +'<td style="padding:10px 8px;text-align:center;border-bottom:1px solid var(--border);font-size:11px;color:var(--text3)">'+(c.phone||'?')+'</td>'
        +'<td style="padding:10px 8px;text-align:center;border-bottom:1px solid var(--border);font-weight:700;color:'+(c.color||'var(--accent)')+'">'+cTasks(c.name)+'</td>'
        +'<td style="padding:10px 8px;text-align:center;border-bottom:1px solid var(--border);font-weight:700;color:var(--accent2)">'+cThisMonth(c.name)+'</td>'
        +'<td style="padding:10px 8px;text-align:center;border-bottom:1px solid var(--border)" onclick="event.stopPropagation()"><div style="display:flex;gap:4px;justify-content:center"><button class="btn btn-ghost btn-sm" style="padding:3px 7px" onclick="openClientModal('+c.id+')"><i class="fa-solid fa-pen"></i></button><button class="btn btn-ghost btn-sm" style="padding:3px 7px" onclick="openClientPortal('+c.id+')"><i class="fa-solid fa-link"></i></button><button class="btn btn-danger btn-sm" style="padding:3px 7px" onclick="delClient('+c.id+')"><i class="fa-solid fa-trash"></i></button></div></td>'
      +'</tr>';
    }).join('');
  }
}

// Client view switching
var _clientViewMode = localStorage.getItem('studioClientView') || 'grid';

// Toggle client tasks expandable section in list view
function _toggleClientTasks(clientId){
  var row = document.getElementById('_cl-tasks-'+clientId);
  var arrow = document.getElementById('_cl-arrow-'+clientId);
  if(!row) return;
  var isOpen = row.style.display !== 'none';
  row.style.display = isOpen ? 'none' : 'block';
  if(arrow) arrow.style.transform = isOpen ? '' : 'rotate(180deg)';
}
function _switchClientView(mode){
  _clientViewMode = mode;
  localStorage.setItem('studioClientView', mode);
  var gridEl = document.getElementById('clients-grid');
  var listEl = document.getElementById('clients-list-view');
  var tableEl = document.getElementById('clients-table-view');
  var gb=document.getElementById('cv-grid-btn'), lb=document.getElementById('cv-list-btn'), tb=document.getElementById('cv-table-btn');
  [gb,lb,tb].forEach(function(b){if(b){b.style.background='transparent';b.style.color='var(--text3)';}});
  if(gridEl) gridEl.style.display=mode==='grid'?'':'none';
  if(listEl) listEl.style.display=mode==='list'?'':'none';
  if(tableEl) tableEl.style.display=mode==='table'?'':'none';
  var activeBtn=mode==='grid'?gb:mode==='list'?lb:tb;
  if(activeBtn){activeBtn.style.background='var(--accent)';activeBtn.style.color='#fff';}
  renderClients();
}
// Apply saved view on first render
document.addEventListener('DOMContentLoaded',function(){
  setTimeout(function(){ if(_clientViewMode!=='grid') _switchClientView(_clientViewMode); },500);
});

// ============================================================
// FINANCE
// ============================================================
function onIncomeTaskLink(){
  const taskSel = document.getElementById('in-linked-task');
  const srcEl   = document.getElementById('in-source');
  if(!taskSel||!srcEl) return;
  const taskId = +taskSel.value;
  if(taskId){
    const t = S.tasks.find(x=>x.id===taskId);
    if(t && !srcEl.value) srcEl.value = t.client||'';
    const amtEl = document.getElementById('in-amount');
    if(t && amtEl && !amtEl.value) amtEl.value = t.value||'';
  }
}

function onIncomeProjectLink(){
  const projSel = document.getElementById('in-linked-project');
  if(!projSel || !projSel.value) return;
  const proj = (S.projects||[]).find(p => String(p.id) === String(projSel.value));
  if(!proj) return;
  // Auto-fill desc if empty
  const descEl = document.getElementById('in-desc');
  if(descEl && !descEl.value) descEl.value = 'دفعة مشروع: ' + proj.name;
}

function _fillOpenIncomeProject(projId) {
  // Call this when opening income modal from project page
  const projSel = document.getElementById('in-linked-project');
  if(!projSel) return;
  // Make sure all projects are loaded
  projSel.innerHTML = '<option value="">? لا يوجد مشروع ?</option>';
  (S.projects||[]).forEach(p => {
    const opt = document.createElement('option');
    opt.value = p.id;
    opt.textContent = p.name;
    projSel.appendChild(opt);
  });
  if(projId) projSel.value = String(projId);
}
function openIncomeModal(id, prefillTaskId){
  document.getElementById('income-ttl').innerHTML=id?'<i class="fa-solid fa-coins"></i> تعديل دخل':'<i class="fa-solid fa-coins"></i> تسجيل دخل';
  document.getElementById('income-eid').value=id||'';
  // Populate clients dropdown (replaces datalist)
  fillIncomeClientDropdown();
  // Populate payment methods from custom accounts
  fillPayMethodDropdowns();
  if(id){const t=S.transactions.find(t=>t.id===id);if(t){
    document.getElementById('in-amount').value=t.amount;
    // Set client in dropdown
    const srcSel = document.getElementById('in-source');
    if(srcSel) {
      if([...srcSel.options].some(o=>o.value===t.source)) srcSel.value=t.source||'';
      else srcSel.value='';
    }
    document.getElementById('in-desc').value=t.desc||'';
    document.getElementById('in-date').value=t.isoDate||'';
    // After setting client, filter projects
    if(t.source) onIncomeClientChange(t.source);
    const taskSel = document.getElementById('in-linked-task');
    if(taskSel) setTimeout(()=>{ taskSel.value=t.linkedTaskId||''; }, 50);
    setTimeout(()=>{ _fillOpenIncomeProject(t.project_id||''); }, 60);
    const ptEl=document.getElementById('in-payment-type'); if(ptEl) ptEl.value=t.paymentType||'full';
    const pmEl=document.getElementById('in-pay-method');  if(pmEl) pmEl.value=t.payMethod||'cash';
  }}
  else{
    ['in-amount','in-desc'].forEach(f=>{const e=document.getElementById(f);if(e)e.value='';});
    const srcSel=document.getElementById('in-source'); if(srcSel) srcSel.value='';
    document.getElementById('in-date').value=new Date().toISOString().split('T')[0];
    // If prefillTaskId, find client and preselect
    if(prefillTaskId){
      const task=S.tasks.find(t=>t.id==prefillTaskId);
      if(task&&task.client){
        setTimeout(()=>{
          const srcSel=document.getElementById('in-source');
          if(srcSel) srcSel.value=task.client;
          onIncomeClientChange(task.client);
          setTimeout(()=>{
            const taskSel=document.getElementById('in-linked-task');
            if(taskSel) taskSel.value=prefillTaskId;
          },60);
        },30);
      }
    }
    const ptEl=document.getElementById('in-payment-type'); if(ptEl) ptEl.value='full';
    const pmEl=document.getElementById('in-pay-method');  if(pmEl) pmEl.value='cash';
    // Fill projects dropdown for new transaction
    setTimeout(()=>{ _fillOpenIncomeProject(''); }, 20);
  }
  openM('modal-income');
}
function openExpenseModal(id){
  document.getElementById('expense-ttl').innerHTML=id?'<i class="fa-solid fa-money-bill-wave"></i> تعديل مصروف':'<i class="fa-solid fa-money-bill-wave"></i> تسجيل مصروف';
  document.getElementById('expense-eid').value=id||'';
  fillPayMethodDropdowns();
  if(id){const t=S.transactions.find(t=>t.id===id);if(t){
    document.getElementById('ex-amount').value=t.amount;
    document.getElementById('ex-desc').value=t.desc||'';
    document.getElementById('ex-date').value=t.isoDate||'';
    const catEl=document.getElementById('ex-cat'); if(catEl) catEl.value=t.expCat||t.source||'أخرى';
    _onExpenseCatChange(t.expCat||t.source||'أخرى');
    const pmEl=document.getElementById('ex-pay-method'); if(pmEl) pmEl.value=t.payMethod||'cash';
    const impact=t.expImpact||(_isPersonalExpense(t)?'personal':'work');
    const impactEl=document.querySelector('input[name="ex-profit-impact"][value="'+impact+'"]');
    if(impactEl) impactEl.checked=true;
  }}
  else{
    ['ex-amount','ex-desc'].forEach(f=>{const e=document.getElementById(f);if(e)e.value='';});
    document.getElementById('ex-date').value=new Date().toISOString().split('T')[0];
    const pmEl=document.getElementById('ex-pay-method'); if(pmEl) pmEl.value='cash';
    const impactEl=document.querySelector('input[name="ex-profit-impact"][value="work"]');
    if(impactEl) impactEl.checked=true;
  }
  openM('modal-expense');
}
function _onExpenseCatChange(value){
  const loanFields=document.getElementById('ex-loan-fields');
  if(loanFields) loanFields.style.display=value==='سلفة للغير'?'block':'none';
  const personal=document.querySelector('input[name="ex-profit-impact"][value="personal"]');
  const work=document.querySelector('input[name="ex-profit-impact"][value="work"]');
  if(value==='سحب شخصي'){
    if(personal) personal.checked=true;
  } else if(value && value!=='سلفة للغير'){
    if(work) work.checked=true;
  }
}
function saveTrans(type){
  const isInc=type==='income';
  const amount=+(isInc?v('in-amount'):v('ex-amount'));
  if(!amount)return alert('أدخل المبلغ');
  const eid=v(isInc?'income-eid':'expense-eid');
  const rawDate = isInc ? v('in-date') : v('ex-date');
  const isoDate = rawDate || new Date().toISOString().split('T')[0];
  const source = isInc ? v('in-source') : (v('ex-cat')||'أخرى');
  const linkedTaskId  = isInc ? (+(document.getElementById('in-linked-task')?.value)||null) : null;
  const linkedProjId  = isInc ? (document.getElementById('in-linked-project')?.value||null) : null;
  const linkedProjObj = linkedProjId ? (S.projects||[]).find(p=>String(p.id)===String(linkedProjId)) : null;
  const paymentType  = isInc ? (document.getElementById('in-payment-type')?.value||'full') : null;
  const payMethod    = isInc ? (document.getElementById('in-pay-method')?.value||'cash') : (document.getElementById('ex-pay-method')?.value||'cash');
  const expCat       = !isInc ? (v('ex-cat')||'أخرى') : null;
  const expImpact    = !isInc ? (document.querySelector('input[name="ex-profit-impact"]:checked')?.value||'work') : null;
  // Auto-fill source from linked task
  let finalSource = source;
  if(isInc && linkedTaskId && !source){
    const lt = S.tasks.find(t=>t.id===linkedTaskId);
    if(lt) finalSource = lt.client||lt.title;
  }
  const incRcpt = isInc ? (window._incReceiptData||null) : null;
  const isLoanTrans = isInc && paymentType==='loan_received';
  const stmtCollectionId = isInc && window._pendingStmtCollection ? window._pendingStmtCollection.id : null;
  const d={type,amount,source:finalSource,desc:v(isInc?'in-desc':'ex-desc'),
    date:new Date(isoDate+'T00:00:00').toLocaleDateString('ar-EG'), isoDate,
    payMethod,
    ...(linkedTaskId  ? {linkedTaskId}  : {}),
    ...(linkedProjId  ? {project_id: String(linkedProjId), project_name: linkedProjObj?.name||''} : {}),
    ...(paymentType   ? {paymentType}   : {}),
    ...(expCat       ? {expCat}       : {}),
    ...(expImpact    ? {expImpact}    : {}),
    ...(incRcpt      ? {receiptImage:incRcpt} : {}),
    ...(stmtCollectionId ? {statementId:stmtCollectionId, source_type:'statement_collection'} : {}),
    ...(isLoanTrans  ? {isLoan:true}  : {})};
  if(eid){const i=S.transactions.findIndex(t=>t.id==eid);if(i>-1){d.id=+eid;if(!incRcpt&&S.transactions[i].receiptImage)d.receiptImage=S.transactions[i].receiptImage;S.transactions[i]=d;}}
  else{d.id=Date.now();S.transactions.push(d);}
  if(isInc) window._incReceiptData=null;
  // تسجيل تلقائي في القروض
  if(isInc && paymentType==='loan_received'){
    const lPerson=(document.getElementById('in-loan-person')?.value||'').trim();
    if(lPerson){
      if(!S.loans) S.loans=[];
      S.loans.push({id:'ln_'+Date.now(),direction:'borrowed',amount,
        person:lPerson,phone:document.getElementById('in-loan-phone')?.value||'',
        date:isoDate,due:document.getElementById('in-loan-due')?.value||'',
        notes:'',status:'pending',settledAmount:0,
        createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});
      toast('ًں¤‌ تم تسجيل القرض في صفحة القروض');
    }
  }
  if(!isInc && expCat==='سلفة للغير'){
    const lPerson=(document.getElementById('ex-loan-person')?.value||'').trim();
    if(lPerson){
      if(!S.loans) S.loans=[];
      S.loans.push({id:'ln_'+Date.now(),direction:'lent',amount,
        person:lPerson,phone:document.getElementById('ex-loan-phone')?.value||'',
        date:isoDate,due:document.getElementById('ex-loan-due')?.value||'',
        notes:'',status:'pending',settledAmount:0,
        createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});
      toast('ًں¤‌ تم تسجيل السلفة في صفحة القروض');
    }
  }
  lsSave();closeM(isInc?'modal-income':'modal-expense');renderAll();
  // Auto-print receipt for income transactions
  if(isInc){
    const savedId = eid ? +eid : S.transactions[S.transactions.length-1]?.id;
    const savedTx = (S.transactions||[]).find(t=>String(t.id)===String(savedId));
    if(savedId && savedTx && savedTx.source_type==='statement_collection') _completePendingStmtCollection(savedId, savedTx.statementId);
    if(savedId) setTimeout(()=>exportReceipt(savedId), 400);
  }
}
function delTrans(id){
  confirmDel('هل تريد حذف هذه المعاملة؟',()=>{
    // لو المعاملة مرتبطة بـ project_task، ضع flag عشان الـ sync مش يرجعها
    var tx=S.transactions.find(t=>String(t.id)===String(id));
    if(tx && tx.linkedProjTaskId){
      var pt=(S.project_tasks||[]).find(t=>String(t.id)===String(tx.linkedProjTaskId));
      if(pt) pt._txDeleted=true;
    }
    S.transactions=S.transactions.filter(t=>String(t.id)!==String(id));
    lsSave();cloudSave(S);renderAll();
  });
}
// Finance filter state
let finFilterState = {month:'', year:'', type:'', method:'', cat:'', project:''};

function populateFinYears(){
  const sel = document.getElementById('fin-filter-year'); if(!sel) return;
  const cur = sel.value;
  sel.innerHTML = '<option value="">كل السنوات</option>';
  const years = [...new Set(S.transactions.map(t=>t.isoDate?t.isoDate.slice(0,4):null).filter(Boolean))].sort();
  const thisYear = new Date().getFullYear().toString();
  if(!years.includes(thisYear)) years.push(thisYear);
  years.sort().forEach(y=>{const o=document.createElement('option');o.value=y;o.textContent=y;sel.appendChild(o);});
  sel.value = cur;
}

function _toggleFinFilterPanel(){
  var panel=document.getElementById('_fin-filter-panel');
  var btn=document.getElementById('_fin-filter-toggle');
  if(!panel) return;
  var isOpen=panel.style.display!=='none';
  panel.style.display=isOpen?'none':'';
  if(btn){
    btn.style.borderColor=isOpen?'var(--border)':'var(--accent)';
    btn.style.color=isOpen?'var(--text2)':'var(--accent)';
    btn.style.background=isOpen?'var(--surface2)':'rgba(124,111,247,.08)';
  }
}
function _updateFinFilterDot(){
  var dot=document.getElementById('_fin-filter-dot');
  if(!dot) return;
  var f=finFilterState;
  var hasFilter=f.month||f.year||f.type||f.method||f.cat||f.project;
  dot.style.display=hasFilter?'block':'none';
}

function applyFinanceFilter(){
  finFilterState.month   = document.getElementById('fin-filter-month')?.value||'';
  finFilterState.year    = document.getElementById('fin-filter-year')?.value||'';
  finFilterState.type    = document.getElementById('fin-filter-type')?.value||'';
  finFilterState.method  = document.getElementById('fin-filter-method')?.value||'';
  finFilterState.cat     = document.getElementById('fin-filter-cat')?.value||'';
  finFilterState.project = document.getElementById('fin-filter-project')?.value||'';
  _updateFinFilterDot();
  renderFinance();
}

function resetFinanceFilter(){
  finFilterState = {month:'',year:'',type:'',method:'',cat:'',project:''};
  ['fin-filter-month','fin-filter-year','fin-filter-type','fin-filter-method','fin-filter-cat','fin-filter-project'].forEach(id=>{
    const el=document.getElementById(id);if(el)el.value='';
  });
  _updateFinFilterDot();
  renderFinance();
}

function filterTransactions(transactions){
  const f = finFilterState;
  return transactions.filter(t=>{
    const d = t.isoDate || '';
    if(f.month   && d.slice(5,7) !== f.month.padStart(2,'0')) return false;
    if(f.year    && d.slice(0,4) !== f.year) return false;
    if(f.type    && t.type !== f.type) return false;
    if(f.method  && (t.payMethod||'cash') !== f.method) return false;
    if(f.cat     && (t.expCat||t.source||'') !== f.cat) return false;
    if(f.project && String(t.project_id||'') !== String(f.project)) return false;
    return true;
  });
}

function _isPersonalExpense(t){
  if(!t || t.type!=='expense') return false;
  if(t.expImpact==='personal') return true;
  const hay = [t.expCat, t.source, t.desc].filter(Boolean).join(' ');
  return /سحب\s*شخصي|مصاريف\s*تعليمية\s*شخصية|شخصي/.test(hay);
}
function _isProfitExpense(t){
  return t && t.type==='expense' && t.expCat!=='سلفة للغير' && !_isPersonalExpense(t);
}
function _profitExpenseSum(transactions){
  return transactions.filter(_isProfitExpense).reduce((s,t)=>s+(+t.amount||0),0);
}
function _profitMargin(income, profitExpense){
  return income ? Math.round(((income - profitExpense) / income) * 100) : 0;
}


// â”€â”€ Sync project task income to S.transactions (auto-record) â”€â”€
// ملحوظة: لو المستخدم حذف المعاملة يدوياً، مش بنرجعها تاني
function _syncProjTaskTransactions(){
  return;
  if(!S.project_tasks) return;
  if(!S.transactions) S.transactions=[];
  S.project_tasks.forEach(function(t){
    if(!t.paymentCollected || !t.value || t.value<=0) return;
    // لو المستخدم حذف المعاملة يدوياً (manuallyDeleted flag) متتسجلش تاني
    if(t._txDeleted) return;
    // Check if already recorded
    var exists=S.transactions.some(function(tx){return String(tx.linkedProjTaskId)===String(t.id);});
    if(!exists){
      var proj=_getProjById?_getProjById(t.project_id):null;
      S.transactions.push({
        id:Date.now()+Math.random(),
        type:'income',
        amount:t.value,
        currency:t.currency||'ج.م',
        desc:'مهمة مشروع: '+(t.title||'')+(proj?' ? '+proj.name:''),
        date:t.createdAt?t.createdAt.slice(0,10):new Date().toISOString().slice(0,10),
        isoDate:t.createdAt?t.createdAt.slice(0,10):new Date().toISOString().slice(0,10),
        linkedProjTaskId:t.id,
        source:'project_task',
        createdAt:new Date().toISOString()
      });
    }
  });
}
function renderFinance(){
  // Sync project task completions into transactions (avoid duplicates)
  _syncProjTaskTransactions();
  populateFinYears();
  // Populate project filter
  (function(){
    var sel = document.getElementById('fin-filter-project');
    if(!sel) return;
    var cur = sel.value;
    sel.innerHTML = '<option value="">كل المشاريع</option>';
    (S.projects||[]).forEach(function(p){
      var opt = document.createElement('option');
      opt.value = p.id;
      opt.textContent = p.name;
      sel.appendChild(opt);
    });
    if(cur) sel.value = cur;
  })();
  renderMonthlyTimeline();
  renderFinLoansSummary();
  const filtered = filterTransactions(S.transactions);
  const f = finFilterState;
  
  // Label for current filter
  const lbl = document.getElementById('fin-filter-label');
  if(lbl){
    const months = ['','يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
    let parts = [];
    if(f.month) parts.push(months[+f.month]||'');
    if(f.year)  parts.push(f.year);
    lbl.innerHTML = parts.length ? '<i class="fa-solid fa-calendar-days"></i> '+parts.join(' ') : '';
  }

  const inc = filtered.filter(t=>t.type==='income'&&!t.isLoan).reduce((s,t)=>s+t.amount,0);
  const exp = filtered.filter(t=>t.type==='expense'&&t.expCat!=='سلفة للغير').reduce((s,t)=>s+t.amount,0);
  const profitExp = _profitExpenseSum(filtered);
  const net = inc-profitExp, margin = _profitMargin(inc, profitExp);
  
  // Category breakdown
  const catSum = cat => filtered.filter(t=>t.type==='expense'&&t.source===cat).reduce((s,t)=>s+t.amount,0);
  const personalSum = filtered.filter(t=>t.type==='expense'&&(t.source==='سحب شخصي'||t.source==='مصاريف تعليمية شخصية')).reduce((s,t)=>s+t.amount,0);
  
  // Pending tasks (global, not filtered)
  const pendingTasks=S.tasks.filter(t=>!t.done&&t.status!=='done'&&t.pay!=='full');
  const pendingRev=pendingTasks.reduce((s,t)=>s+(t.value||0),0);
  const depositsPending=pendingTasks.filter(t=>t.pay==='deposit').reduce((s,t)=>s+(t.deposit||0),0);
  
  const set=(id,val)=>{const e=document.getElementById(id);if(e)e.textContent=val;};
  set('fin-in',inc.toLocaleString()+' '+_getCurrency());
  set('fin-in-sub', f.month||f.year ? `(${(f.month?'الشهر':'')+(f.year?' '+f.year:'')})` : '');
  set('fin-out',exp.toLocaleString()+' '+_getCurrency());
  set('fin-net',inc?margin+'%':'—');
  set('fin-margin',net.toLocaleString()+' '+_getCurrency());
  set('fin-pending',pendingRev.toLocaleString()+' '+_getCurrency());
  set('fin-deposits',depositsPending.toLocaleString()+' '+_getCurrency());
  
  // Category cards
  
  // Unpaid task reminders
  renderUnpaidReminders();
  
  const tbody=document.getElementById('fin-tbody');if(!tbody)return;
  const rows = [...filtered].sort((a,b)=>(b.isoDate||'').localeCompare(a.isoDate||'')).map(t=>{
    const projBadge = t.project_id ? (()=>{const pj=(S.projects||[]).find(p=>String(p.id)===String(t.project_id));return pj?` <span style="font-size:10px;background:rgba(79,209,165,.12);color:#4fd1a5;padding:1px 7px;border-radius:8px;cursor:pointer" onclick="showPage('projects');setTimeout(()=>openProjectDetail('${pj.id}'),200)"><i class="fa-solid fa-diagram-project"></i> ${pj.name.slice(0,18)}</span>`:''})() : '';
    return `<tr>
    <td>${t.desc||'?'}${projBadge}${t.linkedTaskId?(()=>{const lt=S.tasks.find(x=>x.id===t.linkedTaskId);return lt?` <span style="font-size:10px;background:rgba(124,111,247,.15);color:var(--accent);padding:1px 6px;border-radius:8px;cursor:pointer" onclick="openTaskDetail(${t.linkedTaskId})"><i class="fa-solid fa-link"></i> ${lt.title.slice(0,20)}</span>`:''})():''}</td><td class="hide-mobile">${t.source||'?'}${t.paymentType&&t.paymentType!=='full'?` <span style="font-size:10px;color:var(--accent2)">(${t.paymentType==='deposit'?'عربون':'جزئي'})</span>`:''}</td>
    <td><span class="badge ${t.type==='income'?'badge-green':'badge-red'}">${t.type==='income'?'<i class="fa-solid fa-coins"></i> دخل':'<i class="fa-solid fa-money-bill-wave"></i> مصروف'}</span></td>
    <td style="font-weight:700;color:${t.type==='income'?'var(--accent3)':'var(--accent4)'}">${t.amount.toLocaleString()} ج</td>
    <td class="hide-mobile" style="font-family:var(--mono);font-size:11px">${t.isoDate||t.date||'?'}</td>
    <td><div style="display:flex;gap:4px">
      <button class="btn btn-ghost btn-sm" onclick="${t.type==='income'?'openIncomeModal':'openExpenseModal'}(${t.id})"><i class="fa-solid fa-pen"></i></button>
      ${t.type==='income'?`<button class="btn btn-ghost btn-sm" onclick="exportReceipt(${t.id})" title="إيصال PDF" style="color:var(--accent3)"><i class="fa-solid fa-receipt"></i></button>`:''}
      <button class="btn btn-danger btn-sm" onclick="delTrans(${t.id})"><i class="fa-solid fa-trash"></i></button>
    </div></td>
  </tr>`;}).join('');
  tbody.innerHTML = rows || '<tr><td colspan="6" style="text-align:center;color:var(--text3);padding:24px">لا معاملات تطابق الفلتر</td></tr>';
}

function renderUnpaidReminders(){
  const wrap = document.getElementById('fin-unpaid-reminders'); if(!wrap) return;
  // Find completed tasks whose payment was not collected
  const _projUncollected=(S.project_tasks||[]).filter(t=>t.status==='done'&&!t.paymentCollected&&t.value>0).map(t=>{
    var proj=_getProjById&&_getProjById(t.project_id);
    return Object.assign({},t,{title:(proj?proj.name+' ? ':'')+t.title,_isProjTask:true});
  });
  const uncollected = [...S.tasks.filter(t=>t.done && !t.paymentCollected && t.value>0), ..._projUncollected];

  // تذكيرات القروض المتأخرة
  const today = new Date(); today.setHours(0,0,0,0);
  const loans = S.loans || [];
  const overdueLoans = loans.filter(function(l){ return l.due && l.status!=='settled' && new Date(l.due)<today; });
  const dueSoonLoans = loans.filter(function(l){
    if(!l.due || l.status==='settled') return false;
    const d = new Date(l.due); d.setHours(0,0,0,0);
    const diff = Math.round((d-today)/(1000*60*60*24));
    return diff>=0 && diff<=7;
  });

  // مستحقات العملاء (رصيد افتتاحي)
  const clientsOwing = (S.clients||[]).filter(function(c){ return c.openingBalance>0 && c.openingBalanceType==='receivable'; });

  const hasItems = uncollected.length || overdueLoans.length || dueSoonLoans.length || clientsOwing.length;
  if(!hasItems){ wrap.style.display='none'; return; }
  wrap.style.display='block';
  const cur = _getCurrency();

  let html = '';

  if(uncollected.length){
    html += `<div class="card" style="border-color:rgba(247,201,72,.4);margin-bottom:10px">
      <div style="font-size:13px;font-weight:700;color:var(--accent2);margin-bottom:10px"><i class="fa-solid fa-triangle-exclamation"></i> مبالغ لم يتم تحصيلها</div>
      ${uncollected.map(t=>`
        <div style="display:flex;align-items:center;gap:12px;padding:9px 0;border-bottom:1px solid rgba(42,42,58,.4)">
          <div style="flex:1">
            <div style="font-size:13px;font-weight:600">${t.title}</div>
            <div style="font-size:11px;color:var(--text3)">${t.client||'?'}</div>
          </div>
          <div style="font-weight:700;color:var(--accent2)">${t.value.toLocaleString()} ${cur}</div>
          <button class="btn btn-success btn-sm" onclick="markTaskPaymentCollected(${t.id})"><i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم التحصيل</button>
        </div>`).join('')}
    </div>`;
  }

  if(overdueLoans.length){
    html += `<div class="card" style="border-color:rgba(255,107,107,.5);margin-bottom:10px">
      <div style="font-size:13px;font-weight:700;color:var(--accent4);margin-bottom:10px"><i class="fa-solid fa-bell"></i> قروض متأخرة السداد (${overdueLoans.length})</div>
      ${overdueLoans.map(l=>`
        <div style="display:flex;align-items:center;gap:12px;padding:9px 0;border-bottom:1px solid rgba(42,42,58,.4)">
          <div style="flex:1">
            <div style="font-size:13px;font-weight:600">${l.direction==='lent'?'ًں’° سلّفت لـ ':'â†© استلفت من '}${escapeHtml(l.person)}</div>
            <div style="font-size:11px;color:var(--accent4)">âڑ ï¸ڈ استحق: ${l.due}</div>
          </div>
          <div style="font-weight:700;color:var(--accent4)">${(l.amount-(l.settledAmount||0)).toLocaleString()} ${cur}</div>
          <button class="btn btn-ghost btn-sm" onclick="switchFinTab('loans');showPage('finance')"><i class="fa-solid fa-handshake"></i> عرض</button>
        </div>`).join('')}
    </div>`;
  }

  if(dueSoonLoans.length){
    html += `<div class="card" style="border-color:rgba(247,201,72,.4);margin-bottom:10px">
      <div style="font-size:13px;font-weight:700;color:var(--accent2);margin-bottom:10px"><i class="fa-solid fa-calendar-days"></i> قروض موعدها خلال 7 أيام</div>
      ${dueSoonLoans.map(l=>{
        const daysLeft = Math.round((new Date(l.due)-today)/(1000*60*60*24));
        return `<div style="display:flex;align-items:center;gap:12px;padding:9px 0;border-bottom:1px solid rgba(42,42,58,.4)">
          <div style="flex:1">
            <div style="font-size:13px;font-weight:600">${l.direction==='lent'?'ًں’° سلّفت لـ ':'â†© استلفت من '}${escapeHtml(l.person)}</div>
            <div style="font-size:11px;color:var(--accent2)">ًں“… الموعد: ${l.due} (${daysLeft===0?'اليوم!':daysLeft+' أيام'})</div>
          </div>
          <div style="font-weight:700;color:var(--accent2)">${(l.amount-(l.settledAmount||0)).toLocaleString()} ${cur}</div>
        </div>`;
      }).join('')}
    </div>`;
  }

  if(clientsOwing.length){
    const totalOwing = clientsOwing.reduce(function(s,c){ return s+(+c.openingBalance||0); },0);
    html += `<div class="card" style="border-color:rgba(168,156,255,.4);margin-bottom:10px">
      <div style="font-size:13px;font-weight:700;color:var(--accent2);margin-bottom:10px"><i class="fa-solid fa-users"></i> عملاء عندهم رصيد مستحق ? إجمالي: ${totalOwing.toLocaleString()} ${cur}</div>
      ${clientsOwing.map(c=>`
        <div style="display:flex;align-items:center;gap:12px;padding:7px 0;border-bottom:1px solid rgba(42,42,58,.4)">
          <div style="flex:1;font-size:12px;font-weight:700">${escapeHtml(c.name)}</div>
          <div style="font-size:12px;font-weight:700;color:var(--accent2)">${(+c.openingBalance).toLocaleString()} ${cur}</div>
          <button class="btn btn-ghost btn-sm" onclick="openClientProfile(${c.id})"><i class="fa-solid fa-user"></i> عرض</button>
        </div>`).join('')}
    </div>`;
  }

  wrap.innerHTML = html;
}

function markTaskPaymentCollected(taskId){
  // Check project task first
  var ptask=(S.project_tasks||[]).find(function(t){return String(t.id)===String(taskId);});
  if(ptask){
    _markTaskPaymentCollectedMeta(ptask);
    if(ptask.value>0){
      if(!S.transactions) S.transactions=[];
      var proj=typeof _getProjById==='function'?_getProjById(ptask.project_id):null;
      S.transactions.push({id:Date.now()+Math.random(),type:'income',amount:ptask.value,
        currency:ptask.currency||'ج.م',
        desc:'تحصيل: '+(ptask.title||'')+(proj?' ? '+proj.name:''),
        date:new Date().toISOString().slice(0,10),
        linkedProjTaskId:ptask.id,source:'project_task',createdAt:new Date().toISOString()});
    }
    lsSave(); cloudSave(S);
    if(typeof renderFinance==='function') renderFinance();
    if(typeof renderProjectDetail==='function') renderProjectDetail();
    toast('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم تسجيل التحصيل');
    return;
  }
  const task = S.tasks.find(x=>x.id===taskId); if(!task) return;
  _markTaskPaymentCollectedMeta(task);
  lsSave();
  // Open income modal pre-filled with task info so user can review before saving
  openIncomeModal(null, taskId);
  const amtEl=document.getElementById('in-amount');
  if(amtEl) amtEl.value = task.value||0;
  const srcEl=document.getElementById('in-source');
  if(srcEl) srcEl.value = task.client||'';
  const descEl=document.getElementById('in-desc');
  if(descEl) descEl.value = 'تحصيل مبلغ مشروع: '+task.title;
  const ptEl=document.getElementById('in-payment-type');
  if(ptEl) ptEl.value = 'full';
  renderAll();
}

// ============================================================
// INVOICES
// ============================================================
/* â”€â”€ عرض مهام العميل في مودال الفاتورة â”€â”€ */
function _isInvoiceTaskCollected(t){
  return !!(t && (t.paymentCollected || t.paid || t.pay === 'full' || t.pay === 'paid' || t.paymentStatus === 'collected' || t.paymentStatus === 'paid'));
}
function _invoiceTaskMatchesClient(t, clientName){
  return String(t && t.client || '').trim() === String(clientName || '').trim();
}
function _invoiceExistingTaskIds(exceptInvoiceId){
  const ids = new Set();
  (S.invoices||[]).forEach(inv=>{
    if(exceptInvoiceId && String(inv.id) === String(exceptInvoiceId)) return;
    (inv.items||[]).forEach(it=>{
      const taskId = it && (it._taskId || it.taskId || it.linkedTaskId);
      if(taskId != null && taskId !== '') ids.add(String(taskId));
    });
  });
  return ids;
}
function _invoiceUncollectedTasksForClient(clientName){
  const name = String(clientName || '').trim();
  if(!name) return [];
  const invoicedTaskIds = _invoiceExistingTaskIds(document.getElementById('inv-eid')?.value || '');
  return getAllTasksIncludingArchived().filter(t => _invoiceTaskMatchesClient(t, name) && !_isInvoiceTaskCollected(t) && !invoicedTaskIds.has(String(t.id)));
}
function _addTaskToInvoiceItems(t){
  if(!t) return false;
  if(invItems.some(it => String(it._taskId || '') === String(t.id || ''))) return false;

  invItems.push({
    _taskId: t.id,
    desc:  String(t.title || '').trim() + (t.notes ? ' - ' + String(t.notes).slice(0, 60) : ''),
    qty:   1,
    price: +(t.value || 0)
  });
  return true;
}
function _invoiceClientContext(clientName){
  const raw=String(clientName||'');
  const c=(S.clients||[]).find(x=>String(x.id)===raw || x.name===raw);
  const sub=c ? (S.clients||[]).filter(sc=>String(sc.parentClientId)===String(c.id)) : [];
  const names=(c?[c.name]:[raw]).concat(sub.map(sc=>sc.name)).filter(Boolean);
  const ids=(c?[String(c.id)]:[]).concat(sub.map(sc=>String(sc.id))).filter(Boolean);
  return {client:c,names,ids};
}
function _invoiceProjectRowsForClient(clientName){
  const ctx=_invoiceClientContext(clientName);
  return _clientProjectDueRows(ctx.names,ctx.ids);
}
function _invoiceClientDetails(inv){
  const raw=String((inv&&inv.client)||'').trim();
  const c=(S.clients||[]).find(x=>String(x.id)===raw || String(x.name||'').trim()===raw) || {};
  return {
    name:c.name || raw || 'العميل',
    phone:c.phone || c.mobile || c.whatsapp || c.client_phone || inv?.clientPhone || inv?.phone || '',
    email:c.email || c.client_email || inv?.clientEmail || inv?.email || '',
    address:c.address || c.client_address || inv?.clientAddress || inv?.address || ''
  };
}
function _invoiceContactRowsHTML(rows){
  return rows.filter(r=>String(r.value||'').trim()).map(r=>`
    <div class="inv-contact-line">
      <span class="inv-contact-label">${r.label}</span>
      <b class="inv-contact-value" dir="auto">${escapeHtml(String(r.value||''))}</b>
    </div>`).join('');
}
function _projectInvoiceTaskItems(p){
  const info=_projectDueInfo(p);
  const pid=_projectId(p);
  const expected=info.due || info.budget;
  const tasks=(S.project_tasks||[]).filter(t=>String(t.project_id||t.projectId||'')===String(pid));
  const items=tasks.map(t=>{
    return {
      _projectTaskId:t.id,
      project_id:pid,
      section:'projects',
      projectName:info.name,
      projectBudget:info.budget,
      _projectDetail:true,
      desc:(info.name ? info.name+' - ' : '')+(t.title||'مهمة مشروع'),
      qty:1,
      price:0
    };
  }).filter(it=>String(it.desc||'').trim());
  const mainItem={
      _projectMain:true,
      project_id:pid,
      section:'projects',
      projectName:info.name,
      projectBudget:info.budget,
      projectAmount:expected,
      desc:'مشروع '+info.name,
      qty:1,
      price:expected
  };
  return [mainItem].concat(items);
}
function toggleProjectAsInvoiceItem(projectId){
  const p=(S.projects||[]).find(x=>String(_projectId(x))===String(projectId));
  if(!p){
    if(typeof showMiniNotif==='function') showMiniNotif('لم يتم العثور على المشروع');
    return;
  }
  const existing=invItems.filter(it=>String(it.project_id||it.projectId||'')===String(projectId));
  if(existing.length){
    invItems=invItems.filter(it=>String(it.project_id||it.projectId||'')!==String(projectId));
  } else {
    invItems=invItems.concat(_projectInvoiceTaskItems(p));
  }
  renderInvForm();
  calcTotal();
  onInvClientChange(document.getElementById('inv-client')?.value || '');
  if(typeof showMiniNotif==='function') showMiniNotif(existing.length?'تم إزالة بنود المشروع من الفاتورة':'تم إضافة بنود المشروع في الفاتورة');
}
if(typeof window!=='undefined') window.toggleProjectAsInvoiceItem=toggleProjectAsInvoiceItem;
function onInvClientChange(clientName){
  const name = clientName || document.getElementById('inv-client')?.value || '';
  const panel = document.getElementById('inv-tasks-panel');
  const list  = document.getElementById('inv-tasks-list');
  const projectPanel = document.getElementById('inv-projects-panel');
  const projectList  = document.getElementById('inv-projects-list');
  if(!panel||!list) return;
  if(!name){
    panel.style.display='none';
    if(projectPanel) projectPanel.style.display='none';
    return;
  }
  const clientCtx=_invoiceClientContext(name);

  // كل تاسكات العميل ? مش بس الجاري، كمان المكتملة والمدفوعة
  const tasks = getAllTasksIncludingArchived().filter(t => clientCtx.names.includes(t.client));

  // معرفة أي مهام عندها فواتير بالفعل
  const invoicedTaskIds = _invoiceExistingTaskIds(document.getElementById('inv-eid')?.value || '');

  const statusLabel = {new:'جديد', progress:'جاري', review:'مراجعة', done:'مكتمل'};
  const statusColor = {new:'var(--text3)', progress:'var(--accent2)', review:'var(--accent)', done:'var(--accent3)'};

  const isPaidTask = _isInvoiceTaskCollected;
  const unpaidTasks = tasks.filter(t => !isPaidTask(t));
  const paidTasks = tasks.filter(t => isPaidTask(t));

  const renderTaskChip = (t, paidGroup) => {
    const taskIdSafe   = JSON.stringify(t.id);
    const already      = invItems.some(it => String(it._taskId || '') === String(t.id || ''));
    const hasInvoice   = invoicedTaskIds.has(String(t.id));
    const isPaidFull   = isPaidTask(t);
    const isPaidDeposit= t.pay === 'deposit';
    const isUnpaid     = !isPaidFull && !isPaidDeposit;

    // بطاقة الدفع
    let payBadge = '';
    if(isPaidFull)
      payBadge = `<span style="background:rgba(79,209,165,.15);color:var(--accent3);padding:1px 7px;border-radius:20px;font-size:10px;font-weight:700"><i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> مدفوع</span>`;
    else if(isPaidDeposit)
      payBadge = `<span style="background:rgba(247,201,72,.15);color:var(--accent2);padding:1px 7px;border-radius:20px;font-size:10px;font-weight:700"><i class="fa-solid fa-heart"></i> عربون ${t.deposit?t.deposit.toLocaleString()+' ج':''}</span>`;
    else
      payBadge = `<span style="background:rgba(255,99,99,.12);color:#ff6b6b;padding:1px 7px;border-radius:20px;font-size:10px;font-weight:700"><i class="fa-solid fa-circle-xmark"></i> غير مدفوع</span>`;

    // بطاقة الفاتورة
    const invBadge = hasInvoice
      ? `<span style="background:rgba(124,111,247,.15);color:var(--accent);padding:1px 7px;border-radius:20px;font-size:10px;font-weight:700"><i class="fa-solid fa-square"></i> عليها فاتورة</span>`
      : '';

    // لون الكارد
    const cardBg     = already ? 'rgba(124,111,247,.16)' : isPaidFull ? 'rgba(79,209,165,.06)' : 'var(--surface2)';
    const cardBorder = already ? 'var(--accent)' : isPaidFull ? 'rgba(79,209,165,.3)' : 'var(--border)';
    const icon       = already ? '<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i>' : hasInvoice ? '<i class="fa-solid fa-repeat"></i>' : '<i class="fa-solid fa-plus"></i>';

    return `<div id="task-chip-${String(t.id).replace(/[^a-zA-Z0-9_-]/g,'_')}" onclick="toggleTaskAsItem(${taskIdSafe})"
      style="display:flex;align-items:center;gap:10px;padding:9px 12px;border-radius:8px;cursor:pointer;
             background:${cardBg};border:1.5px solid ${cardBorder};transition:all .18s">
      <div style="flex:1;min-width:0">
        <div style="font-size:13px;font-weight:700;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${t.title}</div>
        <div style="font-size:11px;margin-top:4px;display:flex;gap:6px;flex-wrap:wrap;align-items:center">
          <span style="color:${statusColor[t.status]||'var(--text3)'}">â—ڈ ${statusLabel[t.status]||t.status}</span>
          ${t._archived ? `<span style="background:rgba(124,111,247,.12);color:var(--accent);padding:1px 7px;border-radius:20px;font-size:10px;font-weight:700"><i class="fa-solid fa-box-archive"></i> مؤرشفة</span>` : ''}
          ${t.deadline ? `<span style="color:var(--text3)"><i class="fa-solid fa-calendar-days"></i> ${t.deadline}</span>` : ''}
          ${t.value    ? `<span style="color:var(--accent3);font-weight:700">${t.value.toLocaleString()} ج</span>` : ''}
          ${payBadge}
          ${invBadge}
        </div>
        ${isPaidFull && t.value ? `<div style="font-size:10px;color:var(--accent3);margin-top:4px">â†ھ سيُضاف ${t.value.toLocaleString()} ج كمدفوع مسبقاً في الفاتورة</div>` : ''}
        ${isPaidDeposit && t.deposit ? `<div style="font-size:10px;color:var(--accent2);margin-top:4px">â†ھ سيُضاف العربون ${t.deposit.toLocaleString()} ج كمدفوع مسبقاً في الفاتورة</div>` : ''}
      </div>
      <button type="button" class="btn btn-ghost btn-sm" onclick="event.stopPropagation();openTaskModal(${taskIdSafe})" title="تعديل المهمة وحالة الدفع" style="flex-shrink:0;padding:7px 9px"><i class="fa-solid fa-pen"></i></button>
      <div style="font-size:18px;flex-shrink:0;width:28px;text-align:center">${icon}</div>
    </div>`;
  };

  const unpaidHtml = unpaidTasks.length
    ? `<div style="display:flex;flex-direction:column;gap:6px">${unpaidTasks.map(t => renderTaskChip(t,false)).join('')}</div>`
    : `<div style="padding:14px;text-align:center;color:var(--text3);font-size:12px;background:var(--surface2);border:1px dashed var(--border);border-radius:8px">لا توجد مهام غير مدفوعة لهذا العميل</div>`;

  const paidHtml = paidTasks.length
    ? `<div style="margin-top:8px">
        <button type="button" onclick="toggleInvoicePaidTasks()" style="width:100%;border:1px solid rgba(79,209,165,.35);background:rgba(79,209,165,.12);color:var(--accent3);border-radius:8px;padding:9px 12px;font-family:var(--font);font-size:12px;font-weight:900;display:flex;align-items:center;justify-content:space-between;cursor:pointer">
          <span><i class="fa-solid fa-circle-check"></i> مهام مدفوعة (${paidTasks.length})</span>
          <i class="fa-solid fa-chevron-down" id="inv-paid-tasks-arrow"></i>
        </button>
        <div id="inv-paid-tasks-body" style="display:none;margin-top:6px;flex-direction:column;gap:6px">
          ${paidTasks.map(t => renderTaskChip(t,true)).join('')}
        </div>
      </div>`
    : '';

  if(tasks.length){
    list.innerHTML =
      `<div style="font-size:11px;color:var(--text3);font-weight:800;margin-bottom:5px">مهام غير مدفوعة</div>`+
      unpaidHtml+
      paidHtml;
    panel.style.display = 'block';
  } else {
    panel.style.display = 'none';
  }

  if(projectPanel && projectList){
    const projects=_invoiceProjectRowsForClient(name);
    if(projects.length){
      projectList.innerHTML=projects.map(p=>{
        const already=invItems.some(it=>String(it.project_id||it.projectId||'')===String(p.id));
        const pid=JSON.stringify(String(p.id));
        return `<div data-invoice-project-id="${escapeHtml(String(p.id))}" style="display:flex;align-items:center;gap:10px;padding:9px 12px;border-radius:8px;cursor:pointer;background:${already?'rgba(79,209,165,.14)':'var(--surface2)'};border:1.5px solid ${already?'var(--accent3)':'var(--border)'};transition:all .18s">
          <div style="flex:1;min-width:0">
            <div style="font-size:13px;font-weight:800;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">مشروع ${escapeHtml(p.name)}</div>
            <div style="font-size:11px;margin-top:4px;display:flex;gap:6px;flex-wrap:wrap;align-items:center">
              <span style="color:var(--accent3);font-weight:800">المستحق ${p.due.toLocaleString('ar-EG')} ج</span>
              <span style="color:var(--text3)">الميزانية ${p.budget.toLocaleString('ar-EG')} ج</span>
              ${p.paid?`<span style="color:var(--text3)">محصل ${p.paid.toLocaleString('ar-EG')} ج</span>`:''}
            </div>
          </div>
          <button type="button" data-invoice-project-id="${escapeHtml(String(p.id))}" onclick="event.stopPropagation();toggleProjectAsInvoiceItem(${pid})" style="font-size:18px;flex-shrink:0;width:34px;height:34px;border:0;background:transparent;color:var(--text);cursor:pointer">${already?'<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i>':'<i class="fa-solid fa-plus"></i>'}</button>
        </div>`;
      }).join('');
      projectList.onclick=function(ev){
        const row=ev.target.closest('[data-invoice-project-id]');
        if(!row || ev.target.closest('button')) return;
        toggleProjectAsInvoiceItem(row.getAttribute('data-invoice-project-id'));
      };
      projectPanel.style.display='block';
    } else {
      projectPanel.style.display='none';
    }
  }
}

function addAllUnpaidInvItems(){
  const client = document.getElementById('inv-client')?.value || '';
  if(!client) return alert('اختر العميل أولاً');
  const tasks = _invoiceUncollectedTasksForClient(client);
  if(!tasks.length) return typeof showMiniNotif === 'function' ? showMiniNotif('<i class="fa-solid fa-circle-info"></i> لا توجد بنود غير محصلة لهذا العميل') : alert('لا توجد بنود غير محصلة لهذا العميل');

  let added = 0;
  tasks.forEach(t => { if(_addTaskToInvoiceItems(t)) added++; });
  _recalcDepositFromItems();
  renderInvForm();
  calcTotal();
  onInvClientChange(client);
  if(typeof showMiniNotif === 'function') showMiniNotif('<i class="fa-solid fa-list-check" style="color:var(--accent3)"></i> تم إضافة '+added+' بند غير محصل');
}

function toggleInvoicePaidTasks(){
  const body = document.getElementById('inv-paid-tasks-body');
  const arrow = document.getElementById('inv-paid-tasks-arrow');
  if(!body) return;
  const open = body.style.display !== 'none';
  body.style.display = open ? 'none' : 'flex';
  if(arrow) arrow.style.transform = open ? '' : 'rotate(180deg)';
}

/* إضافة / إزالة مهمة كبند ? مع منطق الدفع المسبق */
function toggleTaskAsItem(taskId){
  const t = findTaskAny(taskId);
  if(!t) return;

  const idx = invItems.findIndex(it => it._taskId === taskId);

  if(idx > -1){
    // إزالة البند
    invItems.splice(idx, 1);
    // إعادة حساب العربون ? اطرح ما أضفناه
    _recalcDepositFromItems();
  } else {
    if(_invoiceExistingTaskIds(document.getElementById('inv-eid')?.value || '').has(String(taskId))){
      if(typeof showMiniNotif === 'function') showMiniNotif('<i class="fa-solid fa-file-invoice"></i> هذا البند عليه فاتورة بالفعل');
      return;
    }
    // إضافة البند
    const isPaidFull    = !!(t.paymentCollected || t.paid || t.pay === 'full' || t.pay === 'paid' || t.paymentStatus === 'collected' || t.paymentStatus === 'paid');
    const isPaidDeposit = t.pay === 'deposit';

    _addTaskToInvoiceItems(t);

    // تحديث خانة "مدفوع مسبقاً"
    const depEl = document.getElementById('inv-deposit');
    if(depEl){
      const currentDep = +(depEl.value) || 0;
      if(isPaidFull && t.value){
        depEl.value = currentDep + t.value;
      } else if(isPaidDeposit && t.deposit){
        depEl.value = currentDep + t.deposit;
      }
    }
  }

  renderInvForm();
  calcTotal();
  const client = document.getElementById('inv-client')?.value || '';
  onInvClientChange(client);
}

/* إعادة حساب خانة العربون بناءً على البنود المتبقية */
function _recalcDepositFromItems(){
  let dep = 0;
  invItems.forEach(it => {
    if(!it._taskId) return;
    const t = S.tasks.find(x => x.id === it._taskId);
    if(!t) return;
    if((t.pay==='full'||t.done) && t.value)   dep += t.value;
    else if(t.pay==='deposit' && t.deposit)    dep += t.deposit;
  });
  const depEl = document.getElementById('inv-deposit');
  if(depEl) depEl.value = dep || 0;
  calcTotal();
}

function _invoiceSubtotal(){
  return _invoiceItemsSubtotal(invItems);
}
function _invoiceLineTotal(i){
  return (+i?.qty||0)*(+i?.price||0);
}
function _isInvoiceSettlementItem(i){
  return /^تسوية ميزانية مشروع/.test(String(i&&i.desc||'').trim());
}
function _invoiceItemsSubtotal(items){
  const arr=Array.isArray(items)?items:[];
  const regular=arr.filter(it=>!_invoiceItemIsProject(it) && !_isInvoiceSettlementItem(it)).reduce((s,it)=>s+_invoiceLineTotal(it),0);
  const projects=new Map();
  arr.filter(_invoiceItemIsProject).forEach(it=>{
    const key=String(it.project_id||it.projectId||it.projectName||_invoiceProjectName(it)||'project');
    if(!projects.has(key)) projects.set(key,{visible:0, hidden:0});
    const g=projects.get(key);
    const fallback=+(it.projectAmount||it.projectTotal||it.projectBudget||0);
    if(fallback>0) g.fallback=Math.max(g.fallback||0,fallback);
    if(_isInvoiceSettlementItem(it)) g.hidden+=_invoiceLineTotal(it);
    else g.visible+=_invoiceLineTotal(it);
  });
  const projectTotal=Array.from(projects.values()).reduce((s,g)=>{
    const lineTotal=g.visible+g.hidden;
    return s+(lineTotal>0?lineTotal:(g.fallback||0));
  },0);
  return regular+projectTotal;
}
function _invoiceProjectsSubtotal(items){
  const projects=new Map();
  (Array.isArray(items)?items:[]).filter(_invoiceItemIsProject).forEach(it=>{
    const key=String(it.project_id||it.projectId||it.projectName||_invoiceProjectName(it)||'project');
    if(!projects.has(key)) projects.set(key,{total:0,fallback:0});
    const g=projects.get(key);
    g.total+=_invoiceLineTotal(it);
    const fallback=+(it.projectAmount||it.projectTotal||it.projectBudget||0);
    if(fallback>0) g.fallback=Math.max(g.fallback,fallback);
  });
  return Array.from(projects.values()).reduce((s,g)=>s+(g.total>0?g.total:g.fallback),0);
}
function _invoiceDiscountAmount(subtotal){
  subtotal = +subtotal || 0;
  const type = (document.getElementById('inv-discount-type')?.value || 'amount');
  const raw = Math.max(0, +(document.getElementById('inv-discount')?.value || 0));
  const amount = type === 'percent' ? subtotal * Math.min(raw,100) / 100 : raw;
  return Math.min(subtotal, Math.round(amount * 100) / 100);
}
function _invoiceStoredDiscount(inv){
  if(!inv) return {subtotal:0, discountAmount:0, net:0, remaining:0};
  const computedSubtotal=_invoiceItemsSubtotal(inv.items||[]);
  const storedSubtotal=+(inv.subtotal||0);
  const subtotal = computedSubtotal || storedSubtotal || +(inv.total||0);
  const discountAmount = Math.min(subtotal, +(inv.discountAmount || 0));
  const net = computedSubtotal ? Math.max(0, subtotal - discountAmount) : +(inv.total != null ? inv.total : Math.max(0, subtotal - discountAmount));
  const remaining = Math.max(0, net - (+(inv.deposit||0)));
  return {subtotal, discountAmount, net, remaining};
}
function _invoiceDiscountDisplay(inv, totals){
  totals = totals || _invoiceStoredDiscount(inv);
  if(inv && inv.discountType === 'percent'){
    const raw=Math.min(100, Math.max(0, +(inv.discount||0)));
    return {label:'نسبة الخصم', value:(raw % 1 ? raw.toFixed(1) : raw.toFixed(0)) + '%'};
  }
  return {label:'القيمة المخصومة', value:(+(totals.discountAmount||0)).toLocaleString() + ' ج'};
}
function _invoiceBreakdown(inv, totals){
  const items=(inv&&inv.items)||[];
  const projectsTotal=_invoiceProjectsSubtotal(items);
  const invoiceParts=_invoiceSplitItems(inv);
  const individualTotal=(invoiceParts.regular||[]).reduce((sum,it)=>sum+_invoiceLineTotal(it),0);
  totals = totals || _invoiceStoredDiscount(inv);
  const discount=_invoiceDiscountDisplay(inv, totals);
  return {
    projectsTotal,
    individualTotal,
    discountLabel:discount.label,
    discountValue:discount.value,
    totalDue:totals.net,
    remainingAfterPrepaid:totals.remaining,
    prepaid:+(inv&&inv.deposit||0),
    grossTotal:projectsTotal + individualTotal
  };
}
function _invoiceRefreshStoredTotals(inv){
  if(!inv) return {subtotal:0, discountAmount:0, net:0, remaining:0};
  const totals=_invoiceStoredDiscount(inv);
  if(totals.subtotal>0){
    inv.subtotal=totals.subtotal;
    inv.total=totals.net;
    inv.discountAmount=totals.discountAmount;
  }
  return totals;
}
function _invoiceDisplayTotal(inv){
  return _invoiceRefreshStoredTotals(inv).net || +(inv&&inv.total||0);
}

function openInvoiceModal(id){
  fillDD('inv-client');
  document.getElementById('inv-modal-ttl').innerHTML=id?'<i class="fa-solid fa-square"></i> تعديل الفاتورة':'<i class="fa-solid fa-square"></i> إنشاء فاتورة جديدة';
  document.getElementById('inv-eid').value=id||'';
  // إخفاء لوحة المهام أول ما نفتح
  const panel=document.getElementById('inv-tasks-panel');
  if(panel)panel.style.display='none';
  if(id){
    const inv=S.invoices.find(i=>i.id===id);if(!inv)return;
    document.getElementById('inv-client').value=inv.client;
    document.getElementById('inv-num').value=inv.num;
    document.getElementById('inv-date').value=inv.date;
    document.getElementById('inv-due').value=inv.due;
    document.getElementById('inv-notes').value=inv.notes||'';
    document.getElementById('inv-deposit').value=inv.deposit||0;
    const invDiscType=document.getElementById('inv-discount-type'); if(invDiscType) invDiscType.value=inv.discountType||'amount';
    const invDisc=document.getElementById('inv-discount'); if(invDisc) invDisc.value=inv.discount||0;
    invItems=(inv.items||[]).map(i=>({...i}));
    invPolicies=(inv.policies||[]).map(p=>({...p}));
    const puEl=document.getElementById('inv-project-url');
    if(puEl)puEl.value=inv.projectUrl||'';
    const plEl=document.getElementById('inv-payment-link');
    if(plEl)plEl.value=inv.paymentLink||'';
    // عرض مهام العميل
    setTimeout(()=>onInvClientChange(inv.client),120);
  } else {
    window._pendingInvoiceProjectId=null;
    window._pendingInvoiceProjectName=null;
    document.getElementById('inv-client').value='';
    document.getElementById('inv-num').value='INV-'+(S.invoices.length+1).toString().padStart(3,'0');
    document.getElementById('inv-date').value=today();
    const d=new Date();d.setDate(d.getDate()+7);
    document.getElementById('inv-due').value=d.toISOString().split('T')[0];
    document.getElementById('inv-notes').value=S.settings?.terms||'';
    const invDiscType=document.getElementById('inv-discount-type'); if(invDiscType) invDiscType.value='amount';
    const invDisc=document.getElementById('inv-discount'); if(invDisc) invDisc.value='';
    invItems=[];
    invPolicies=(S.settings?.policies||[]).map(p=>({...p}));
    const plElN=document.getElementById('inv-payment-link'); if(plElN) plElN.value='';
  }
  setTimeout(()=>{
    const dep=document.getElementById('inv-deposit');if(dep){dep.oninput=calcTotal;}
    renderPoliciesList('inv-policies-list',invPolicies,'removeInvPolicy');
    const projEl=document.getElementById('inv-project-url');
    if(projEl)liveQR('inv-project-url','inv-project-qr-prev',90);
  },100);
  renderInvForm();openM('modal-invoice');
}
function openInvoiceForClient(clientName){
  openInvoiceModal();
  setTimeout(function(){
    const clientEl = document.getElementById('inv-client');
    if(clientEl){
      fillDD('inv-client');
      clientEl.value = clientName || '';
    }
    if(typeof onInvClientChange === 'function') onInvClientChange(clientName || '');
  }, 120);
}
window.openInvoiceFromReceivables = function(clientName, items, notes){
  if(typeof showPage === 'function') showPage('invoices');
  setTimeout(function(){
    if(typeof switchInvTab === 'function') switchInvTab('invoices');
    openInvoiceModal();
    setTimeout(function(){
      var clientEl = document.getElementById('inv-client');
      if(clientEl){
        fillDD('inv-client');
        var opt = Array.from(clientEl.options || []).find(function(o){
          var txt = String(o.textContent || '').trim();
          return String(o.value) === String(clientName) || txt === String(clientName) || txt.indexOf(String(clientName)) === 0;
        });
        if(opt) clientEl.value = opt.value;
        else clientEl.value = clientName || '';
        if(typeof onInvClientChange === 'function') onInvClientChange(clientEl.value || clientName);
      }
	      invItems = (items && items.length ? items : [{desc:'', qty:1, price:0}]).map(function(item){
	        return {
	          _taskId: item._taskId,
	          _projectTaskId: item._projectTaskId,
	          project_id: item.project_id,
	          section: item.section,
	          projectName: item.projectName,
	          projectBudget: item.projectBudget,
	          desc: item.desc || '',
	          qty: +(item.qty || 1),
	          price: +(item.price || 0)
	        };
	      });
      renderInvForm();
      calcTotal();
      var notesEl = document.getElementById('inv-notes');
      if(notesEl && notes) notesEl.value = notes;
    }, 120);
  }, 180);
};
function addInvItem(){invItems.push({desc:'',qty:1,price:0});renderInvForm();}
function renderInvForm(){
  const el=document.getElementById('inv-items-container');if(!el)return;
  if(!invItems.length){
    el.innerHTML='<div style="padding:14px;text-align:center;color:var(--text3);font-size:12px;background:var(--surface2);border:1px dashed var(--border);border-radius:8px;margin-bottom:8px">لا توجد بنود بعد — اختر من مهام العميل أو أضف بند يدوي</div>';
    calcTotal();
    return;
  }
  const projectGroups=_invoiceProjectGroups(invItems);
  const projectIndexes=new Set(projectGroups.flatMap(g=>g.items.map(it=>it._index)));
  const rowHtml=(item,i)=>`
    <div style="display:grid;grid-template-columns:1fr 70px 100px 34px;gap:7px;margin-bottom:8px;align-items:center">
      <input class="form-input" placeholder="وصف البند" value="${item.desc.replace(/"/g,'&quot;')}" oninput="invItems[${i}].desc=this.value">
      <input class="form-input" type="number" placeholder="كمية" value="${item.qty}" oninput="invItems[${i}].qty=+this.value;calcTotal()">
      <input class="form-input" type="number" placeholder="سعر ج" value="${item.price||''}" oninput="invItems[${i}].price=+this.value;calcTotal()">
      <button class="btn btn-danger" style="padding:8px;justify-content:center" onclick="invItems.splice(${i},1);renderInvForm()"><i class="fa-solid fa-xmark"></i></button>
    </div>`;
  const projectHtml=projectGroups.map(g=>`
    <div style="border:1px solid rgba(79,209,165,.28);background:rgba(79,209,165,.05);border-radius:10px;padding:10px;margin-bottom:10px">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:8px;flex-wrap:wrap">
        <div style="font-size:12px;font-weight:900;color:var(--accent3)"><i class="fa-solid fa-folder-open"></i> مشروع ${escapeHtml(g.name||'مشروع')}</div>
        <div style="font-size:11px;color:var(--text3)">المجموع: <b style="color:var(--accent3)">${g.total.toLocaleString('ar-EG')} ج</b>${g.budget?' · الميزانية: '+g.budget.toLocaleString('ar-EG')+' ج':''}</div>
      </div>
      ${g.items.map(item=>rowHtml(item,item._index)).join('')}
    </div>`).join('');
  const regularHtml=invItems.map((item,i)=>projectIndexes.has(i)||_isInvoiceSettlementItem(item)?'':rowHtml(item,i)).join('');
  el.innerHTML=projectHtml+(regularHtml?`<div style="font-size:11px;color:var(--text3);font-weight:800;margin:8px 0 6px">بنود فردية</div>${regularHtml}`:'');
  calcTotal();
}
function calcTotal(){
  const subtotal=_invoiceSubtotal();
  const discount=_invoiceDiscountAmount(subtotal);
  const t=Math.max(0, subtotal-discount);
  const dep=+(document.getElementById('inv-deposit')?.value||0);
  const due=Math.max(0,t-dep);
  const discountType=(document.getElementById('inv-discount-type')?.value||'amount');
  const discountRaw=Math.max(0, +(document.getElementById('inv-discount')?.value||0));
  const subEl=document.getElementById('inv-subtotal-live');if(subEl)subEl.textContent=subtotal.toLocaleString();
  const discEl=document.getElementById('inv-discount-live');if(discEl)discEl.textContent=discount.toLocaleString();
  const discLabel=document.getElementById('inv-discount-label-live');if(discLabel)discLabel.textContent=discountType==='percent'?'النسبة المخصومة ('+Math.min(discountRaw,100)+'%)':'المبلغ المخصوم';
  const e=document.getElementById('inv-total-live');if(e)e.textContent=t.toLocaleString();
  const dueEl=document.getElementById('inv-due-live');if(dueEl)dueEl.textContent=due.toLocaleString();
  const rem=document.getElementById('inv-remaining-preview');
  if(rem)rem.textContent=due.toLocaleString()+' ج';
}
function _invoiceProjectForItem(it){
  if(!it) return null;
  if(it._projectTaskId){
    const pt=(S.project_tasks||[]).find(t=>String(t.id)===String(it._projectTaskId));
    if(pt){
      const p=(S.projects||[]).find(x=>String(x.id)===String(pt.project_id||it.project_id||it.projectId));
      return {task:pt, project:p};
    }
  }
  const p=(S.projects||[]).find(x=>String(x.id)===String(it.project_id||it.projectId||''));
  return p ? {task:null, project:p} : null;
}
function _invoiceItemIsProject(it){
  return !!(it && (it.section==='projects' || it._projectTaskId || it.project_id || it.projectId || _isInvoiceSettlementItem(it)));
}
function _invoiceProjectName(it){
  const rel=_invoiceProjectForItem(it);
  const settlementName=String(it?.desc||'').replace(/^تسوية ميزانية مشروع\s*/,'').trim();
  return it?.projectName || (rel && rel.project && rel.project.name) || settlementName || 'مشروع';
}
function _invoiceProjectBudget(it){
  const rel=_invoiceProjectForItem(it);
  return +(it?.projectBudget || (rel && rel.project && (rel.project.budget||rel.project.totalBudget||rel.project.amount)) || 0);
}
function _invoiceSectionBudget(items){
  const sectionTotal=(items||[]).reduce((s,it)=>s+(+it.qty||0)*(+it.price||0),0);
  return sectionTotal || (items||[]).reduce((s,it)=>s+_invoiceProjectBudget(it),0);
}
function _invoiceSplitItems(inv){
  const items=(inv && Array.isArray(inv.items) ? inv.items : []);
  return {projects:items.filter(_invoiceItemIsProject), regular:items.filter(it=>!_invoiceItemIsProject(it))};
}
function _invoiceProjectGroups(items){
  const map=new Map();
  (items||[]).forEach((it,index)=>{
    if(!_invoiceItemIsProject(it)) return;
    const key=String(it.project_id||it.projectId||it.projectName||_invoiceProjectName(it)||'project');
    if(!map.has(key)){
      map.set(key,{key,name:_invoiceProjectName(it),budget:_invoiceProjectBudget(it),items:[],total:0});
    }
    const group=map.get(key);
    const row=Object.assign({_index:index},it);
    group.items.push(row);
    group.total+=(+it.qty||0)*(+it.price||0);
    if(!group.budget) group.budget=_invoiceProjectBudget(it);
    const fallback=+(it.projectAmount||it.projectTotal||it.projectBudget||0);
    if(fallback>0) group.fallback=Math.max(group.fallback||0,fallback);
  });
  return Array.from(map.values()).map(g=>Object.assign(g,{total:g.total>0?g.total:(g.fallback||0)}));
}
function saveInvoice(){
  const client=v('inv-client');if(!client)return alert('اختر العميل');
  const cleanItems = invItems.filter(i=>String(i.desc||'').trim()).map(i=>Object.assign({}, i, {desc:String(i.desc||'').trim()}));
  if(!cleanItems.length)return alert('أضف بنداً واحداً على الأقل');
  invItems = cleanItems;
  const subtotal=_invoiceSubtotal();
  const discountType=(document.getElementById('inv-discount-type')?.value||'amount');
  const discount=Math.max(0, +(document.getElementById('inv-discount')?.value||0));
  const discountAmount=_invoiceDiscountAmount(subtotal);
  const total=Math.max(0, subtotal-discountAmount);
  const eid=v('inv-eid');

  // Find parent client - if this client is a sub, link to parent
  const clientObj = S.clients.find(c=>c.name===client);
  let parentClientName = null;
  if(clientObj && clientObj.workType==='sub' && clientObj.parentClientId){
    const parentObj = S.clients.find(c=>String(c.id)===String(clientObj.parentClientId));
    if(parentObj) parentClientName = parentObj.name;
  }

  const d={
    client,
    parentClient: parentClientName, // الشركة الأم إن وُجدت
    num:v('inv-num'),date:v('inv-date'),due:v('inv-due'),notes:v('inv-notes'),
    items:cleanItems.map(i=>({...i})),subtotal,total,deposit:+(v('inv-deposit')||0),
    discountType,discount,discountAmount,
    from:S.settings?.name||'العمل',status:'pending',
    policies:invPolicies.map(p=>({...p})),
    projectUrl:(document.getElementById('inv-project-url')?.value||'').trim(),
    paymentLink:(document.getElementById('inv-payment-link')?.value||'').trim(),
    receiptImage: window._invReceiptData||null,
    project_id: window._pendingInvoiceProjectId || (cleanItems.find(i=>i.project_id)?.project_id || ''),
    projectName: window._pendingInvoiceProjectName || (cleanItems.find(i=>i.projectName)?.projectName || '')
  };
  if(eid){const i=S.invoices.findIndex(x=>x.id==eid);if(i>-1){_clearInvoicePendingFlags(eid);d.id=+eid;d.status=S.invoices[i].status;if(!d.receiptImage&&S.invoices[i].receiptImage)d.receiptImage=S.invoices[i].receiptImage;S.invoices[i]=d;}}
  else{ if(!checkLimit('max_invoices', S.invoices.length)) return; d.id=Date.now();S.invoices.push(d);}
  _markInvoiceLinkedTasksInvoiced(d);
  window._invReceiptData=null;
  window._pendingInvoiceProjectId=null;
  window._pendingInvoiceProjectName=null;
  lsSave();closeM('modal-invoice');renderInvoices();updateDash();previewInv(d.id);
}
function delInvoice(id){
  confirmDel('هل تريد حذف هذه الفاتورة؟',()=>{
    S.invoices=S.invoices.filter(i=>i.id!==id);lsSave();renderAll();
    document.getElementById('inv-preview-card').innerHTML='<div class="section-title">معاينة الفاتورة</div><div class="empty"><div class="empty-icon"><i class="fa-solid fa-square"></i></div>اختر فاتورة أو أنشئ جديدة</div>';
  });
}
function _clearInvoicePendingFlags(invoiceId){
  if(!invoiceId) return;
  (S.tasks||[]).concat(S.project_tasks||[]).forEach(t=>{
    if(String(t.invoiceId||'')!==String(invoiceId)) return;
    if(t.paymentCollected||t.paid||t.paymentStatus==='collected'||t.paymentStatus==='paid') return;
    t.invoicePending=false;
    t.invoiced=false;
    t.invoiceId=null;
    t.invoiceNum=null;
    if(t.paymentStatus==='invoiced') t.paymentStatus=(+t.deposit||0)>0?'deposit':'pending';
  });
}
function _markInvoiceLinkedTasksInvoiced(inv){
  if(!inv) return;
  const touched=new Set();
  const markOne=t=>{
    if(!t || touched.has(String(t.id))) return;
    touched.add(String(t.id));
    if(t.paymentCollected||t.paid||t.paymentStatus==='collected'||t.paymentStatus==='paid') return;
    t.invoicePending=true;
    t.invoiced=true;
    t.invoiceId=inv.id;
    t.invoiceNum=inv.num||'';
    t.paymentStatus='invoiced';
  };
  (inv.items||[]).forEach(it=>{
    const taskId=it._taskId||it.taskId||it.linkedTaskId;
    const projectTaskId=it._projectTaskId||it.projectTaskId||it.linkedProjTaskId;
    const task=taskId?(S.tasks||[]).find(t=>String(t.id)===String(taskId)):null;
    const ptask=projectTaskId?(S.project_tasks||[]).find(t=>String(t.id)===String(projectTaskId)):null;
    [task,ptask].filter(Boolean).forEach(markOne);
    const projectId=it.project_id||it.projectId||it._projectId||(ptask&&(ptask.project_id||ptask.projectId));
    if(projectId){
      (S.project_tasks||[]).filter(t=>String(t.project_id||t.projectId||'')===String(projectId)).forEach(markOne);
    }
  });
}
function _markInvoiceLinkedTasksCollected(inv){
  if(!inv) return;
  const todayIso=new Date().toISOString().split('T')[0];
  const touched = new Set();
  const projectAmounts = new Map();
  const markOne = t=>{
    if(!t || touched.has(String(t.id))) return;
    touched.add(String(t.id));
    _markTaskPaymentCollectedMeta(t, todayIso);
  };
  const addProjectAmount = (projectId, amount)=>{
    if(!projectId) return;
    const key=String(projectId);
    projectAmounts.set(key,(projectAmounts.get(key)||0)+(+amount||0));
  };
  (inv.items||[]).forEach(it=>{
    const taskId=it._taskId||it.taskId||it.linkedTaskId;
    const projectTaskId=it._projectTaskId||it.projectTaskId||it.linkedProjTaskId;
    const itemAmount=(+it.qty||0)*(+it.price||0);
    const task=taskId?(S.tasks||[]).find(t=>String(t.id)===String(taskId)):null;
    const ptask=projectTaskId?(S.project_tasks||[]).find(t=>String(t.id)===String(projectTaskId)):null;
    [task,ptask].filter(Boolean).forEach(markOne);
    const projectId=it.project_id||it.projectId||it._projectId||(ptask&&(ptask.project_id||ptask.projectId))||(task&&(task.project_id||task.projectId));
    if(projectId){
      addProjectAmount(projectId,itemAmount);
      (S.project_tasks||[]).filter(t=>String(t.project_id||t.projectId||'')===String(projectId)).forEach(markOne);
    }
  });
  const invProjectId=inv.project_id||inv.projectId;
  if(invProjectId && !projectAmounts.has(String(invProjectId))) addProjectAmount(invProjectId, _invoiceDisplayTotal(inv));
  projectAmounts.forEach((amount,projectId)=>{
    if(amount<=0){
      const projectItems=(inv.items||[]).filter(it=>String(it.project_id||it.projectId||'')===String(projectId));
      amount=_invoiceProjectsSubtotal(projectItems);
    }
    const p=(S.projects||[]).find(x=>String(x.id)===String(projectId));
    if(!p || amount<=0) return;
    if(!Array.isArray(p.projectLedger)) p.projectLedger=[];
    const exists=p.projectLedger.some(r=>String(r.invoiceId||r.invoice_id||'')===String(inv.id) && r.kind==='client_payment');
    if(!exists){
      p.projectLedger.push({
        id:'pl_inv_'+Date.now()+'_'+Math.random().toString(36).slice(2,7),
        kind:'client_payment',
        amount:amount,
        currency:inv.currency||p.budgetCurrency||_getCurrency(),
        date:todayIso,
        desc:'تحصيل فاتورة '+(inv.num||inv.id||''),
        invoiceId:inv.id,
        invoiceNum:inv.num||'',
        posted:false,
        createdAt:new Date().toISOString()
      });
    }
  });
}
function markPaid(id){const inv=S.invoices.find(i=>i.id===id);if(inv){inv.status='paid';inv.paid=true;inv.collectedAt=new Date().toISOString().split('T')[0];_markInvoiceLinkedTasksCollected(inv);if(inv.statementId&&typeof _finalizeStmtCollection==='function'){inv._ordoPaidTransactionCreated=true;_finalizeStmtCollection(inv.statementId,null);}lsSave();renderAll();previewInv(id);showMiniNotif('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم تسجيل التحصيل');}}
function markUncollected(id){const inv=S.invoices.find(i=>i.id===id);if(inv){inv.status='pending';inv.collectedAt=null;lsSave();renderAll();previewInv(id);}}

// ============================================================
// RECEIPT PDF ? إيصال استلام مبلغ
// ============================================================
function exportReceipt(transId){
  const t = S.transactions.find(x=>x.id===transId);
  if(!t) return;
  const s = S.settings||{};
  const receiptLogo = _logoForContext('dark-bg');
  const logo = receiptLogo ? `<img src="${receiptLogo}" style="max-height:56px;max-width:130px;object-fit:contain" onerror="this.style.display=\'none\'">` : `<div style="font-size:20px;font-weight:900;color:#7c6ff7">${s.name||'Ordo'}</div>`;
  const linkedTask = t.linkedTaskId ? S.tasks.find(x=>x.id===t.linkedTaskId) : null;
  const payTypeAr = {full:'دفعة كاملة',deposit:'عربون',partial:'دفعة جزئية'}[t.paymentType||'full'] || 'دفعة';
  const receiptNum = 'RCP-' + String(transId).slice(-5);
  const dateStr = t.isoDate ? new Date(t.isoDate+'T00:00:00').toLocaleDateString('ar-EG',{year:'numeric',month:'long',day:'numeric'}) : t.date||'';
  const receiptHTML = `<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;900&display=swap" rel="stylesheet">
<style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:'Cairo',sans-serif;background:#fff;color:#1a1a2e;direction:rtl;}@page{size:A4;margin:0;}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact;}}</style>
</head><body><div style="width:210mm;min-height:297mm;background:#fff">
<div style="background:#14141e;padding:22px 28px;display:flex;justify-content:space-between;align-items:center">
  <div>${logo}</div>
  <div style="text-align:left"><div style="font-size:24px;font-weight:900;color:#4fd1a5">إيصال استلام</div><div style="font-size:11px;color:#b0a8ff;margin-top:3px">${receiptNum}</div></div>
</div>
<div style="height:3px;background:linear-gradient(to left,#4fd1a5,#7c6ff7)"></div>
<div style="display:flex;justify-content:space-between;padding:22px 28px;background:#f7fffe">
  <div><div style="font-size:10px;color:#888;margin-bottom:4px">صادر من</div><div style="font-size:14px;font-weight:700">${s.name||'العمل'}</div>${s.phone?`<div style="font-size:11px;color:#555;margin-top:2px"><i class="fa-solid fa-phone"></i> ${s.phone}</div>`:''}</div>
  <div style="text-align:left"><div style="font-size:10px;color:#888;margin-bottom:4px">بيانات الإيصال</div><div style="font-size:13px;font-weight:700">رقم: ${receiptNum}</div><div style="font-size:11px;color:#555;margin-top:3px">التاريخ: ${dateStr}</div></div>
</div>
<div style="margin:0 28px 24px;background:linear-gradient(135deg,#14141e,#1e1e30);border-radius:12px;padding:24px 28px;display:flex;justify-content:space-between;align-items:center">
  <div><div style="font-size:11px;color:#b0a8ff;margin-bottom:6px">تم استلام مبلغ</div>
    <div style="font-size:36px;font-weight:900;color:#4fd1a5">${t.amount.toLocaleString()} <span style="font-size:18px">ج.م</span></div>
    <div style="margin-top:8px;display:inline-block;background:rgba(79,209,165,.2);color:#4fd1a5;padding:3px 12px;border-radius:20px;font-size:11px;font-weight:700">${payTypeAr}</div>
  </div>
  <div style="text-align:left"><div style="font-size:11px;color:#b0a8ff;margin-bottom:3px">من</div><div style="font-size:15px;font-weight:700;color:#fff">${t.source||'?'}</div></div>
</div>
<div style="margin:0 28px 24px;border:1px solid #e8e8f0;border-radius:10px;overflow:hidden">
  <div style="padding:10px 16px;background:#f8f8fc;font-size:10px;font-weight:700;color:#666;text-transform:uppercase;letter-spacing:.5px">تفاصيل الإيصال</div>
  <table style="width:100%;border-collapse:collapse">
    <tr><td style="padding:11px 16px;font-size:12px;color:#888;border-bottom:1px solid #f0f0f5;width:38%">الوصف</td><td style="padding:11px 16px;font-size:13px;font-weight:600;border-bottom:1px solid #f0f0f5">${t.desc||'?'}</td></tr>
    ${linkedTask ? `<tr><td style="padding:11px 16px;font-size:12px;color:#888;border-bottom:1px solid #f0f0f5">المشروع</td><td style="padding:11px 16px;font-size:13px;font-weight:600;border-bottom:1px solid #f0f0f5"><i class="fa-solid fa-clipboard-list"></i> ${linkedTask.title}</td></tr><tr><td style="padding:11px 16px;font-size:12px;color:#888;border-bottom:1px solid #f0f0f5">العميل</td><td style="padding:11px 16px;font-size:13px;font-weight:600;border-bottom:1px solid #f0f0f5">${linkedTask.client||'?'}</td></tr>` : ''}
    <tr><td style="padding:11px 16px;font-size:12px;color:#888;border-bottom:1px solid #f0f0f5">نوع الدفعة</td><td style="padding:11px 16px;font-size:13px;font-weight:600;border-bottom:1px solid #f0f0f5">${payTypeAr}</td></tr>
    <tr><td style="padding:11px 16px;font-size:12px;color:#888">تاريخ الاستلام</td><td style="padding:11px 16px;font-size:13px;font-weight:600">${dateStr}</td></tr>
  </table>
</div>
<div style="margin:0 28px;padding:16px;border-top:2px solid #f0f0f5;display:flex;justify-content:space-between;align-items:center">
  <div style="font-size:11px;color:#aaa">هذا الإيصال يُثبت استلام المبلغ المذكور أعلاه</div>
  <div style="font-size:11px;color:#aaa">توقيع: _______________</div>
</div>
${s.terms?`<div style="margin:12px 28px;padding:12px;background:#fafafe;border-radius:8px;font-size:10px;color:#888;line-height:1.6">${s.terms}</div>`:''}
</div></body></html>`;
  // Use hidden iframe to avoid popup blockers
  let iframe = document.getElementById('_receipt_frame');
  if(!iframe){
    iframe = document.createElement('iframe');
    iframe.id = '_receipt_frame';
    iframe.style.cssText = 'position:fixed;top:-9999px;left:-9999px;width:1px;height:1px;border:none;';
    document.body.appendChild(iframe);
  }
  iframe.srcdoc = receiptHTML;
  iframe.onload = () => {
    try { iframe.contentWindow.focus(); iframe.contentWindow.print(); }
    catch(e){ 
      // fallback: open in new tab
      const w = window.open('','_blank'); w.document.write(receiptHTML); w.document.close(); setTimeout(()=>w.print(),600);
    }
  };
}

function _invLinkToProject(invId) {
  var projects = S.projects || [];
  if (!projects.length) { toast('âڑ ï¸ڈ لا توجد مشاريع ? أنشئ مشروعاً أولاً'); return; }
  var inv = S.invoices.find(function(i){ return i.id===invId; });
  if (!inv) return;

  var clientId = inv.clientId || inv.client_id || '';
  var sorted = projects.slice().sort(function(a,b) {
    var aM = clientId && String(a.client_id||'')===clientId ? 0 : 1;
    var bM = clientId && String(b.client_id||'')===clientId ? 0 : 1;
    return aM - bM;
  });

  var opts = sorted.map(function(p) {
    var sel = (inv.project_id||inv.projectId) && String(p.id)===String(inv.project_id||inv.projectId) ? ' selected' : '';
    var mark = (clientId && String(p.client_id||'')===clientId) ? ' âک…' : '';
    return '<option value="'+p.id+'"'+sel+'>'+escapeHtml(p.name)+mark+'</option>';
  }).join('');

  var ov = document.createElement('div');
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);display:flex;align-items:center;justify-content:center;z-index:99999;padding:16px';
  ov.innerHTML = '<div style="background:var(--surface);border-radius:16px;padding:24px;width:min(380px,95vw);box-shadow:0 24px 60px rgba(0,0,0,.5)">'
    + '<div style="font-size:15px;font-weight:900;margin-bottom:4px"><i class="fa-solid fa-diagram-project" style="color:var(--accent3)"></i> ربط الفاتورة بمشروع</div>'
    + '<div style="font-size:12px;color:var(--text3);margin-bottom:16px">'+escapeHtml(inv.num||'فاتورة')+' ? '+escapeHtml(inv.client||'')+'</div>'
    + '<select id="_inv-proj-sel" class="form-select" style="width:100%;margin-bottom:16px">'
    + '<option value="">? اختر مشروعاً ?</option>' + opts
    + '</select>'
    + '<div style="display:flex;gap:8px">'
    + '<button id="_inv-link-ok" class="btn btn-primary" style="flex:1"><i class="fa-solid fa-check"></i> ربط</button>'
    + '<button class="btn btn-ghost" style="flex:1" onclick="this.closest(\'[style*=fixed]\').remove()">إلغاء</button>'
    + '</div></div>';
  document.body.appendChild(ov);
  ov.addEventListener('click', function(e){ if(e.target===ov) ov.remove(); });

  document.getElementById('_inv-link-ok').onclick = function() {
    var projId = document.getElementById('_inv-proj-sel').value;
    if (!projId) { toast('âڑ ï¸ڈ اختر مشروعاً'); return; }
    if (typeof attachInvoiceToProject === 'function') {
      attachInvoiceToProject(invId, projId);
    }
    ov.remove();
    renderInvoices();
  };
}

function renderInvoices(){
  const tbody=document.getElementById('inv-tbody');if(!tbody)return;
  (S.invoices||[]).forEach(_invoiceRefreshStoredTotals);
  const sm={
    pending:'<span class="inv-status-badge inv-uncollected">âڈ³ لم يتم التحصيل</span>',
    paid:'<span class="inv-status-badge inv-collected"><i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم التحصيل</span>',
    cancelled:'<span class="inv-status-badge inv-cancelled">ًںڑ« ملغية</span>'
  };
  tbody.innerHTML=S.invoices.map(inv=>`<tr>
    <td style="font-family:var(--mono);color:var(--accent);font-size:12px">${inv.num}</td>
    <td>${inv.client}${inv.parentClient?`<div style="font-size:10px;color:var(--text3);margin-top:1px"><i class="fa-solid fa-building"></i> ${inv.parentClient}</div>`:''}</td>
    <td style="font-weight:700;color:var(--accent3)">${_invoiceDisplayTotal(inv).toLocaleString()} ج</td>
    <td>${sm[inv.status]}</td>
    <td><div class="inv-actions">
      <button class="btn btn-ghost btn-sm" onclick="previewInv(${inv.id})" title="معاينة"><i class="fa-solid fa-eye"></i></button>
      <button class="btn btn-ghost btn-sm" onclick="openInvoiceModal(${inv.id})" title="تعديل"><i class="fa-solid fa-pen"></i></button>
      <button class="btn btn-warn btn-sm" onclick="exportPDF(${inv.id})" title="PDF">PDF</button>
      <button class="btn btn-sm" style="background:#25D366;color:#fff;border:none;padding:4px 9px" onclick="openWaModal('invoice',${inv.id})" title="إرسال واتساب">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="white" style="vertical-align:middle"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413Z"/></svg>
      </button>
      ${inv.status==='pending'?`<button class="btn btn-success btn-sm" onclick="markPaid(${inv.id})" title="تم التحصيل" style="font-size:10px"><i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تحصيل</button>`:''}
      ${inv.status==='paid'?`<button class="btn btn-ghost btn-sm" onclick="markUncollected(${inv.id})" title="إلغاء التحصيل" style="font-size:10px">â†©</button>`:''}
      <button class="btn btn-ghost btn-sm" style="color:var(--accent3)" onclick="_invLinkToProject(${inv.id})" title="ربط بمشروع"><i class="fa-solid fa-diagram-project"></i>${inv.project_id||inv.projectId ? '<span style="font-size:9px;margin-right:2px">â—ڈ</span>' : ''}</button>
      <button class="btn btn-danger btn-sm" onclick="delInvoice(${inv.id})" title="حذف"><i class="fa-solid fa-trash"></i></button>
    </div></td>
  </tr>`).join('')||'<tr><td colspan="5" style="text-align:center;color:var(--text3);padding:24px">لا فواتير</td></tr>';
}
function previewInv(id){
  const inv=S.invoices.find(i=>i.id===id);if(!inv)return;
  const profileModal=document.getElementById('modal-client-profile');
  if(profileModal && getComputedStyle(profileModal).display !== 'none'){
    if(typeof closeM==='function') closeM('modal-client-profile');
    if(typeof showPage==='function') showPage('invoices');
    setTimeout(function(){
      if(typeof switchInvTab==='function') switchInvTab('invoices');
      previewInv(id);
      const target=document.getElementById('inv-preview-card');
      if(target&&target.scrollIntoView) target.scrollIntoView({behavior:'smooth',block:'start'});
    },160);
    return;
  }
  const card=document.getElementById('inv-preview-card');
  if(!card){
    if(typeof closeM==='function') closeM('modal-client-profile');
    if(typeof showPage==='function') showPage('invoices');
    setTimeout(function(){
      if(typeof switchInvTab==='function') switchInvTab('invoices');
      previewInv(id);
      const target=document.getElementById('inv-preview-card');
      if(target&&target.scrollIntoView) target.scrollIntoView({behavior:'smooth',block:'start'});
    },160);
    return;
  }
  const s=S.settings||{};
  const totals=_invoiceStoredDiscount(inv);
  const discountLabel=inv.discountType==='percent' ? `خصم (${+(inv.discount||0)}%)` : 'خصم';
  const previewLogo=_logoForContext('light-bg');
  const logo=previewLogo?`<img src="${previewLogo}" style="max-height:56px;max-width:120px;object-fit:contain;margin-bottom:6px;display:block" onerror="this.style.display=\'none\'">`:'';
  const clientDetails=_invoiceClientDetails(inv);
  const studioRows=_invoiceContactRowsHTML([
    {label:'الاسم',value:inv.from||s.name||'العمل'},
    {label:'الهاتف',value:s.phone},
    {label:'البريد',value:s.email},
    {label:'العنوان',value:s.address}
  ]);
  const clientRows=_invoiceContactRowsHTML([
    {label:'اسم العميل',value:clientDetails.name},
    {label:'هاتف العميل',value:clientDetails.phone},
    {label:'بريد العميل',value:clientDetails.email},
    {label:'عنوان العميل',value:clientDetails.address}
  ]);
  const previewContactBlock=`
    <div style="text-align:center;margin:0 0 18px;padding:11px 16px;border:1px solid #f1dfbd;border-radius:12px;background:#fffaf2;color:#1f2030">
      <div style="font-size:15px;font-weight:900;line-height:1.4">${escapeHtml(inv.from||s.name||'العمل')}</div>
      <div style="font-size:11.5px;line-height:1.9;color:#252638">
        ${s.email?`${escapeHtml(s.email)}`:''}${s.email&&s.phone?' <span style="color:#f39a08">•</span> ':''}${s.phone?`${escapeHtml(s.phone)}`:''}
      </div>
      ${s.address?`<div style="font-size:11.5px;line-height:1.9;color:#252638">${escapeHtml(s.address)}</div>`:''}
    </div>`;
  const invoiceParts=_invoiceSplitItems(inv);
  const projectGroups=_invoiceProjectGroups(inv.items||[]);
  const breakdown=_invoiceBreakdown(inv, totals);
  const individualTotal=breakdown.individualTotal;
  const projectsTotal=breakdown.projectsTotal;
  const rowsForItems=items=>(items||[]).map(it=>{
    const qty=+(it.qty||0), price=+(it.price||0);
    const lineTotal=qty*price;
    const isProject=!!(it.section==='projects'||it.project_id||it.projectId||it._projectTaskId);
    const rowStyle=it._projectMain||(_invoiceItemIsProject(it)&&lineTotal>0)
      ? 'background:#fff4dc;font-weight:900;color:#1f2030'
      : (isProject?'background:#fffaf2;color:#444':'');
    return `<tr style="${rowStyle}"><td>${escapeHtml(it.desc||'بند')}</td><td style="text-align:center">${qty}</td><td style="text-align:left">${price.toLocaleString()} ج</td><td style="text-align:left;font-weight:700">${lineTotal.toLocaleString()} ج</td></tr>`;
  }).join('');
  const projectBudget=_invoiceSectionBudget(invoiceParts.projects);
  const sectionTable=(title,items,extra)=>items.length?`
    <div style="margin:14px 0 7px;font-size:13px;font-weight:900;color:var(--accent);display:flex;justify-content:space-between;gap:10px">
      <span>${title} <small style="font-size:10px;color:#777;font-weight:900">(${items.length} بنود)</small></span>${extra?`<span style="font-size:11px;color:#555">${extra}</span>`:''}
    </div>
    <table class="inv-tbl"><thead><tr><th>البند</th><th style="text-align:center">الكمية</th><th style="text-align:left">السعر</th><th style="text-align:left">الإجمالي</th></tr></thead><tbody>${rowsForItems(items)}</tbody></table>`:'';
  const projectSections=projectGroups.map(g=>sectionTable('مشروع '+(g.name||'مشروع'),g.items,`${g.total.toLocaleString()} ج`)).join('');
  const finalSummary=`
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:16px 0 10px">
      <div style="background:#fff8e8;border:1px solid #ffe2ad;border-radius:12px;padding:12px;text-align:center">
        <div style="font-size:10px;color:#9a7a35;font-weight:900">إجمالي الفاتورة</div>
        <div style="font-size:20px;font-weight:900;color:#f39a08;margin-top:4px">${totals.subtotal.toLocaleString()} ج</div>
      </div>
      <div style="background:#fffaf2;border:1px solid #ffe2ad;border-radius:12px;padding:12px;text-align:center">
        <div style="font-size:10px;color:#9a7a35;font-weight:900">${breakdown.discountLabel}</div>
        <div style="font-size:20px;font-weight:900;color:#c28a00;margin-top:4px">${breakdown.discountValue}</div>
      </div>
      <div style="background:#f5f2ff;border:1px solid #ded6ff;border-radius:12px;padding:12px;text-align:center">
        <div style="font-size:10px;color:#6a5bb5;font-weight:900">إجمالي المستحق</div>
        <div style="font-size:20px;font-weight:900;color:var(--accent);margin-top:4px">${breakdown.totalDue.toLocaleString()} ج</div>
      </div>
    </div>
    <div style="font-size:11px;font-weight:900;color:#8a7b9a;margin:4px 0 8px">تقرير سريع</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(135px,1fr));gap:10px;margin:0 0 10px">
      <div style="background:#fff8e8;border:1px solid #ffe2ad;border-radius:12px;padding:12px;text-align:center">
        <div style="font-size:10px;color:#9a7a35;font-weight:900">إجمالي التاسكات الفردية</div>
        <div style="font-size:20px;font-weight:900;color:#f39a08;margin-top:4px">${individualTotal.toLocaleString()} ج</div>
      </div>
      <div style="background:#f0fff8;border:1px solid #c8f1df;border-radius:12px;padding:12px;text-align:center">
        <div style="font-size:10px;color:#438268;font-weight:900">إجمالي المشاريع</div>
        <div style="font-size:20px;font-weight:900;color:#4fd1a5;margin-top:4px">${projectsTotal.toLocaleString()} ج</div>
      </div>
      <div style="background:#f0fff8;border:1px solid #c8f1df;border-radius:12px;padding:12px;text-align:center">
        <div style="font-size:10px;color:#438268;font-weight:900">مدفوع مسبقاً</div>
        <div style="font-size:20px;font-weight:900;color:#4fd1a5;margin-top:4px">${breakdown.prepaid.toLocaleString()} ج</div>
      </div>
      <div style="background:#f5f2ff;border:1px solid #ded6ff;border-radius:12px;padding:12px;text-align:center">
        <div style="font-size:10px;color:#6a5bb5;font-weight:900">المتبقي بعد المدفوع</div>
        <div style="font-size:20px;font-weight:900;color:var(--accent);margin-top:4px">${breakdown.remainingAfterPrepaid.toLocaleString()} ج</div>
      </div>
    </div>`;
  card.innerHTML=`
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">
      <div class="section-title" style="margin:0">معاينة: ${inv.num}</div>
      <div style="display:flex;gap:6px">
        <button class="btn btn-ghost btn-sm" style="background:#25D366;color:#fff;border:none" onclick="openWaModal('invoice',${inv.id})">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="white" style="vertical-align:middle"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413Z"/></svg>
          واتساب
        </button>
        <button class="btn btn-warn btn-sm" onclick="exportPDF(${inv.id})">â¬‡ PDF</button>
      </div>
    </div>
    <div class="invoice-print" style="font-family:'Cairo',var(--font),Arial,sans-serif">
      <div style="display:flex;justify-content:space-between;margin-bottom:24px;align-items:flex-start">
        <div>${logo}<div style="font-size:26px;font-weight:900;color:var(--accent)">فاتورة</div><div style="font-size:11px;color:var(--text3);margin-top:4px">${inv.num} آ· ${inv.date||''}</div>
          <div style="margin-top:10px;font-size:12px"><strong style="display:block;font-size:14px">${inv.from||s.name||'العمل'}</strong>${s.phone?`<i class="fa-solid fa-phone"></i> ${s.phone} `:''}${s.email?`<i class="fa-solid fa-envelope"></i> ${s.email}`:''}${s.address?`<br>${s.address}`:''}</div>
        </div>
        <div style="text-align:left">
          <div style="font-size:11px;color:#888">صادرة إلى</div>
          <div style="font-size:16px;font-weight:700;margin-top:4px">${inv.client}</div>
          <div style="font-size:11px;color:#888;margin-top:8px">تاريخ الاستحقاق</div>
          <div style="font-size:13px;font-weight:600">${inv.due||''}</div>
          <div style="margin-top:10px;display:inline-block;padding:3px 12px;border-radius:20px;font-size:11px;font-weight:700;background:${inv.status==='paid'?'#d4edda':'#fff3cd'};color:${inv.status==='paid'?'#155724':'#856404'}">${inv.status==='paid'?'<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> مدفوعة':'⏳ معلقة'}</div>
        </div>
      </div>
      ${previewContactBlock}
	      ${sectionTable('التاسكات الفردية والبنود',invoiceParts.regular,individualTotal?'المبلغ: '+individualTotal.toLocaleString()+' ج':'')}
	      ${projectSections}
        ${finalSummary}
	      <table class="inv-tbl" style="margin-top:12px">
	        <tfoot>
	          <tr><td colspan="3" style="padding:8px 12px;text-align:right;background:#f8f8fc;color:#555;font-size:12px">الإجمالي قبل الخصم</td><td style="padding:8px 12px;text-align:left;background:#f8f8fc;font-weight:700;font-size:12px">${totals.subtotal.toLocaleString()} ج</td></tr>
	          ${totals.discountAmount>0?`<tr><td colspan="3" style="padding:8px 12px;text-align:right;background:#fff8e6;color:#856404;font-size:12px">${discountLabel}</td><td style="padding:8px 12px;text-align:left;background:#fff8e6;color:#856404;font-weight:700;font-size:12px">- ${totals.discountAmount.toLocaleString()} ج</td></tr>`:''}
	          <tr class="inv-total-row"><td colspan="3" style="padding:9px 12px;text-align:right">توتال الفاتورة</td><td style="padding:9px 12px;text-align:left;color:var(--accent)">${totals.net.toLocaleString()} ج</td></tr>
          ${inv.deposit&&inv.deposit>0?`
          <tr><td colspan="3" style="padding:7px 12px;text-align:right;background:#fffbea;color:#856404;font-size:12px"><i class="fa-solid fa-heart"></i> عربون مدفوع مسبقاً</td><td style="padding:7px 12px;text-align:left;background:#fffbea;color:#856404;font-weight:700;font-size:12px">- ${inv.deposit.toLocaleString()} ج</td></tr>`:''}
          <tr><td colspan="3" style="padding:9px 12px;text-align:right;background:#f0fff8;color:#155724;font-weight:700">إجمالي المستحق</td><td style="padding:9px 12px;text-align:left;background:#f0fff8;color:#155724;font-weight:700">${totals.remaining.toLocaleString()} ج</td></tr>
        </tfoot>
      </table>
      ${inv.notes?`<div style="margin-top:14px;padding:10px 14px;background:#f9f9ff;border-radius:8px;font-size:11px;color:#666;line-height:1.8">${inv.notes}</div>`:''}
      ${inv.policies&&inv.policies.length?buildPoliciesHTML(inv.policies):''}
      ${inv.paymentLink?`<div style="margin-top:16px;text-align:center"><a href="${inv.paymentLink}" target="_blank" style="display:inline-flex;align-items:center;gap:8px;background:linear-gradient(135deg,#4fd1a5,#38b28a);color:#fff;text-decoration:none;padding:12px 28px;border-radius:12px;font-size:14px;font-weight:900;box-shadow:0 4px 16px rgba(79,209,165,.35)"><i class="fa-solid fa-credit-card"></i> ادفع الفاتورة الآن</a></div>`:''}
      ${buildQRSectionHTML(inv, false)}
    </div>`;
  if(card.scrollIntoView) card.scrollIntoView({behavior:'smooth',block:'start'});
}

// ============================================================
// PDF EXPORT ? print-based (full Arabic support)
// ============================================================
function exportPDF(id){
  const inv=S.invoices.find(i=>i.id===id);if(!inv)return;
  const s=S.settings||{};
  const theme=_printTheme();
  const totals=_invoiceStoredDiscount(inv);
  const discountLabel=inv.discountType==='percent' ? `خصم (${+(inv.discount||0)}%)` : 'خصم';
  const printLogo=_logoForContext('dark-bg');
  const logo=printLogo?`<img src="${printLogo}" style="max-height:64px;max-width:150px;object-fit:contain" onerror="this.style.display=\'none\'">` : `<div style="font-size:22px;font-weight:900;color:#fff">${s.name||'Ordo'}</div>`;
  const clientDetails=_invoiceClientDetails(inv);
  const studioRows=_invoiceContactRowsHTML([
    {label:'الاسم',value:inv.from||s.name||'العمل'},
    {label:'الهاتف',value:s.phone},
    {label:'البريد',value:s.email},
    {label:'العنوان',value:s.address}
  ]);
  const clientRows=_invoiceContactRowsHTML([
    {label:'اسم العميل',value:clientDetails.name},
    {label:'هاتف العميل',value:clientDetails.phone},
    {label:'بريد العميل',value:clientDetails.email},
    {label:'عنوان العميل',value:clientDetails.address}
  ]);
  const printContactBlock=`
      <div class="inv-studio-compact">
        <div class="inv-studio-line">
          ${[s.email,s.phone,s.address].filter(Boolean).map(v=>escapeHtml(v)).join(' <span>•</span> ')}
        </div>
      </div>`;
  const itemModels=(inv.items||[]).map(it=>{
    const task=it._taskId ? findTaskAny(it._taskId) : null;
    const projectRel=_invoiceProjectForItem(it);
    const ptask=projectRel && projectRel.task;
    const sourceTask=task || ptask;
    const isProject=_invoiceItemIsProject(it);
    const st=sourceTask ? (sourceTask.done||sourceTask.status==='done' ? 'done' : 'progress') : 'item';
    const amount=(+it.qty||0)*(+it.price||0);
    return {
      desc:it.desc||sourceTask?.title||'بند فاتورة',
      projectName:isProject ? _invoiceProjectName(it) : '',
      projectKey:isProject ? String(it.project_id||it.projectId||_invoiceProjectName(it)||'project') : '',
      projectBudget:isProject ? _invoiceProjectBudget(it) : 0,
      date:(sourceTask&&(sourceTask.doneAt||sourceTask.deadline||sourceTask.isoDate||sourceTask.createdAt)||inv.date||'').slice(0,10),
      amount,
      status:st,
      label:isProject?'مشروع':(st==='done'?'مكتمل':st==='progress'?'جاري':'بند'),
      section:isProject?'projects':'regular',
      main:!!it._projectMain,
      detail:!!it._projectDetail
    };
  });
  const projectItems=itemModels.filter(x=>x.section==='projects');
  const completedItems=itemModels.filter(x=>x.section!=='projects'&&x.status==='done');
  const currentItems=itemModels.filter(x=>x.section!=='projects'&&x.status==='progress');
  const manualItems=itemModels.filter(x=>x.section!=='projects'&&x.status==='item');
  const breakdown=_invoiceBreakdown(inv, totals);
  const individualTotal=breakdown.individualTotal;
  const projectsTotal=breakdown.projectsTotal;
  const projectBudget=_invoiceSectionBudget(_invoiceSplitItems(inv).projects);
  const projectModelGroups=Array.from(projectItems.reduce((map,it)=>{
    const key=it.projectKey||it.projectName||'project';
    if(!map.has(key)) map.set(key,{name:it.projectName||'مشروع',budget:it.projectBudget||0,total:0,fallback:0,items:[]});
    const g=map.get(key); g.items.push(it); g.total+=it.amount; if(!g.budget&&it.projectBudget) g.budget=it.projectBudget; if(it.projectBudget>0) g.fallback=Math.max(g.fallback,it.projectBudget);
    return map;
  },new Map()).values()).map(g=>{
    const total=g.total>0?g.total:g.fallback;
    if(total>0 && !g.items.some(it=>it.amount>0)){
      g.items.unshift({desc:'مشروع '+(g.name||'مشروع'),date:inv.date||'',amount:total,label:'مشروع',section:'projects',main:true});
    }
    return Object.assign(g,{total});
  });
  const rowsFor=arr=>arr.map(it=>{
    const rowClass=(it.main || (it.section==='projects'&&it.amount>0)) ? ' class="inv-project-main"' : (it.detail || it.section==='projects' ? ' class="inv-project-detail"' : '');
    return `
    <tr${rowClass}>
      <td>${it.projectName?it.projectName+' - ':''}${it.desc}</td>
      <td style="text-align:center">${it.date||inv.date||''}</td>
      <td style="text-align:left;font-weight:800">${it.amount>0?it.amount.toLocaleString()+' ج':(it.projectName?'':'0 ج')}</td>
      <td style="text-align:center">${it.label}</td>
    </tr>`;
  }).join('');
  const sectionFor=(title,arr,total)=>arr.length?`
    <section class="inv-section">
      <div class="inv-section-title"><span>${title} <small>${arr.length} بنود</small></span>${total!=null?`<em>${(+total||0).toLocaleString()} ج</em>`:''}</div>
      <table>
        <thead><tr><th>الطلب</th><th style="text-align:center">التاريخ</th><th style="text-align:left">القيمة</th><th style="text-align:center">الحالة</th></tr></thead>
        <tbody>${rowsFor(arr)}</tbody>
      </table>
    </section>`:'';
  const projectSectionsFor=groups=>groups.map(g=>sectionFor('مشروع '+(g.name||'مشروع'),g.items,g.total)).join('');
  const depositRow = inv.deposit && inv.deposit>0 ? `
    <tr>
      <td colspan="3" style="padding:8px 14px;background:#fffbea;color:#856404;font-size:12px;border-bottom:1px solid #eee"><i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> عربون مدفوع مسبقاً</td>
      <td style="padding:8px 14px;background:#fffbea;color:#856404;font-weight:700;font-size:12px;border-bottom:1px solid #eee">- ${inv.deposit.toLocaleString()} ج</td>
    </tr>` : '';
  const dueRow = `<tr>
      <td colspan="3" class="sum-main">إجمالي المستحق</td>
      <td class="sum-main sum-value">${totals.remaining.toLocaleString()} ج</td>
    </tr>`;
  const printHeader = `
      <div class="inv-head">
        <div>${logo}</div>
        <div style="text-align:left">
          <div style="font-size:29px;font-weight:900;color:#fff;line-height:1">فاتورة</div>
          <div style="font-size:12px;color:rgba(255,255,255,.72);margin-top:8px;font-weight:800">${inv.num}</div>
        </div>
      </div>
      <div class="inv-band"></div>`;
  const printFooter = `
      <div class="inv-footer">
        <div style="font-size:11px;color:#9090b0">شكراً لتعاملكم معنا <i class="fa-solid fa-hands"></i></div>
        <div style="font-size:11px;color:#9090b0">${s.name||'العمل'}${s.phone?' آ· '+s.phone:''}</div>
      </div>`;
  const firstPageIntro = `
      <div class="inv-meta-strip">
        <div><b>العميل:</b> ${inv.client}</div>
        <div><b>تاريخ الفاتورة:</b> ${inv.date||''}</div>
        <div><b>تاريخ الاستحقاق:</b> ${inv.due||''}</div>
      </div>
      ${printContactBlock}
      <div class="inv-summary">
        <div class="inv-card"><div class="v">${totals.subtotal.toLocaleString()} ج</div><div class="l">إجمالي الفاتورة</div></div>
        <div class="inv-card"><div class="v" style="color:${theme.warn}">${breakdown.discountValue}</div><div class="l">${breakdown.discountLabel}</div></div>
        <div class="inv-card"><div class="v" style="color:${theme.accent}">${breakdown.totalDue.toLocaleString()} ج</div><div class="l">إجمالي المستحق</div></div>
      </div>`;
  const sectionBlockFor=(title,arr,total)=>`
    <section class="inv-section">
      <div class="inv-section-title"><span>${title} <small>${arr.length} بنود</small></span>${total!=null?`<em>${(+total||0).toLocaleString()} ج</em>`:''}</div>
      <table>
        <thead><tr><th>الطلب</th><th style="text-align:center">التاريخ</th><th style="text-align:left">القيمة</th><th style="text-align:center">الحالة</th></tr></thead>
        <tbody>${rowsFor(arr)}</tbody>
      </table>
    </section>`;
  const sectionContinuationBlockFor=arr=>`
    <section class="inv-section inv-section-cont">
      <table>
        <tbody>${rowsFor(arr)}</tbody>
      </table>
    </section>`;
  const rowUnits=it=>{
    const text=(it.projectName?it.projectName+' - ':'')+(it.desc||'');
    return Math.max(1, Math.ceil(String(text).length/56));
  };
  const SECTION_CHUNK_UNITS=8;
  const pushSplitSection=(blocks,title,arr,total)=>{
    if(!arr.length) return;
    let chunk=[], units=2, chunkTotal=0, firstChunk=true;
    const sectionTotal = total != null ? total : null;
    arr.forEach(it=>{
      const u=rowUnits(it);
      if(chunk.length && units+u>SECTION_CHUNK_UNITS){
        blocks.push({
          html:firstChunk ? sectionBlockFor(title,chunk,sectionTotal != null ? sectionTotal : chunkTotal) : sectionContinuationBlockFor(chunk),
          units:units+(firstChunk?1:0)
        });
        firstChunk=false;
        chunk=[]; units=2; chunkTotal=0;
      }
      chunk.push(it); units+=u; chunkTotal+=it.amount||0;
    });
    if(chunk.length) blocks.push({
      html:firstChunk ? sectionBlockFor(title,chunk,sectionTotal != null ? sectionTotal : null) : sectionContinuationBlockFor(chunk),
      units:units+(firstChunk?1:0)
    });
  };
  const blocks=[{html:firstPageIntro,units:8}];
  pushSplitSection(blocks,'المهام المكتملة',completedItems,completedItems.reduce((s,it)=>s+it.amount,0));
  pushSplitSection(blocks,'المهام الجارية',currentItems,currentItems.reduce((s,it)=>s+it.amount,0));
  pushSplitSection(blocks,'بنود الفاتورة',manualItems,manualItems.reduce((s,it)=>s+it.amount,0));
  projectModelGroups.forEach(g=>pushSplitSection(blocks,'مشروع '+(g.name||'مشروع'),g.items,g.total));
  blocks.push({html:`
      <div class="inv-cost-summary">
        <div class="inv-card"><div class="v" style="color:${theme.accent}">${individualTotal.toLocaleString()} ج</div><div class="l">إجمالي التاسكات الفردية</div></div>
        <div class="inv-card"><div class="v" style="color:${theme.ok}">${projectsTotal.toLocaleString()} ج</div><div class="l">إجمالي المشاريع</div></div>
        <div class="inv-card"><div class="v" style="color:${theme.ok}">${breakdown.prepaid.toLocaleString()} ج</div><div class="l">مدفوع مسبقاً</div></div>
        <div class="inv-card"><div class="v" style="color:${theme.warn}">${breakdown.remainingAfterPrepaid.toLocaleString()} ج</div><div class="l">المتبقي بعد المدفوع</div></div>
      </div>`,units:5});
  blocks.push({html:`
      <div class="inv-table-wrap" style="padding-top:0">
        <table>
          <tfoot>
            <tr>
              <td colspan="3" class="sum-lite">الإجمالي قبل الخصم</td>
              <td class="sum-lite" style="text-align:left">${totals.subtotal.toLocaleString()} ج</td>
            </tr>
            ${totals.discountAmount>0?`<tr>
              <td colspan="3" style="padding:9px 14px;background:#fff8e6;font-weight:800;font-size:12px;color:#856404">${discountLabel}</td>
              <td style="padding:9px 14px;background:#fff8e6;font-weight:800;font-size:12px;color:#856404;text-align:left">- ${totals.discountAmount.toLocaleString()} ج</td>
            </tr>`:''}
            <tr>
              <td colspan="3" class="sum-main">توتال الفاتورة</td>
              <td class="sum-main sum-value">${totals.net.toLocaleString()} ج</td>
            </tr>
            ${depositRow}
            ${dueRow}
          </tfoot>
        </table>
      </div>`,units:6});
  if(inv.notes) blocks.push({html:`<div class="inv-note">
        <div style="font-size:11px;font-weight:900;color:${theme.accent};margin-bottom:5px">ملاحظات وشروط الدفع</div>
        <div style="font-size:12px;color:#555;line-height:1.8">${inv.notes}</div>
      </div>`,units:4});
  if(inv.policies&&inv.policies.length) blocks.push({html:`<div class="inv-policies">
        <div style="font-size:11px;font-weight:900;color:${theme.accent};margin-bottom:10px;text-transform:uppercase;letter-spacing:.5px"><i class="fa-solid fa-clipboard-list"></i> السياسات والشروط</div>
        ${inv.policies.map(p=>`<div style="display:flex;align-items:flex-start;gap:8px;margin-bottom:7px;font-size:12px;color:#555;line-height:1.6">
          <span style="font-size:14px;flex-shrink:0">${p.icon}</span><span>${p.text}</span>
        </div>`).join('')}
      </div>`,units:Math.min(10,3+inv.policies.length)});
  const qrHtml=buildQRSectionHTML(inv, true);
  if(qrHtml) blocks.push({html:qrHtml,units:7});
  const pages=[];
  let page=[], used=0;
  const PAGE_UNITS=31;
  blocks.forEach(block=>{
    if(page.length && used+block.units>PAGE_UNITS){
      pages.push(page);
      page=[]; used=0;
    }
    page.push(block.html);
    used+=block.units;
  });
  if(page.length) pages.push(page);
  const pageHtml=pages.map((items,index)=>`
    <div class="inv-page${index===pages.length-1?' last':''}">
      ${printHeader}
      <main class="inv-content">${items.join('')}</main>
      ${printFooter}
    </div>`).join('');
  const html=`
    <!DOCTYPE html><html lang="ar" dir="rtl">
    <head>
    <meta charset="UTF-8">
    <link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;900&display=swap" rel="stylesheet">
    <style>
      *{margin:0;padding:0;box-sizing:border-box;}
      body{font-family:'Cairo',sans-serif;background:#fff;color:#1a1a2e;direction:rtl;}
      @page{size:A4;margin:0;}
      .inv-page{width:210mm;height:297mm;padding:0;background:#fff;position:relative;overflow:hidden;display:flex;flex-direction:column;break-after:page;page-break-after:always}
      .inv-page.last{break-after:auto;page-break-after:auto}
      .inv-head{background:linear-gradient(135deg,${theme.ink},${theme.accentDark});padding:24px 30px 22px;display:flex;justify-content:space-between;align-items:center}
      .inv-band{height:4px;background:${theme.accent}}
      .inv-content{flex:1;padding:8mm 30px 7mm;overflow:hidden}
      .inv-info{display:grid;grid-template-columns:1fr 1fr;gap:20px;padding:24px 30px;background:${theme.softer};border-bottom:1px solid ${theme.line}}
      .inv-k{font-size:10px;color:${theme.muted};font-weight:900;letter-spacing:.5px;margin-bottom:5px}
      .inv-name{font-size:15px;font-weight:900;color:${theme.ink};line-height:1.45}
      .inv-muted{font-size:11px;color:#555;line-height:1.8}
      .inv-table-wrap{padding:22px 30px 16px}
      .inv-meta-strip{margin:0 0 18px;padding:14px 18px;background:${theme.softer};border:1px solid ${theme.line};border-radius:12px;display:flex;justify-content:space-between;gap:14px;align-items:center;font-size:12.5px}
      .inv-meta-strip b{color:${theme.accent};font-weight:900}
      .inv-contact-panel{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0;margin:0 0 18px;border-top:1px solid ${theme.line};border-bottom:1px solid ${theme.line};background:linear-gradient(90deg,${theme.softer},#fff)}
      .inv-contact-col{padding:13px 18px}
      .inv-contact-col+.inv-contact-col{border-right:1px solid ${theme.line}}
      .inv-contact-title{font-size:11px;font-weight:900;color:${theme.accent};margin-bottom:8px}
      .inv-contact-line{display:grid;grid-template-columns:88px minmax(0,1fr);gap:10px;padding:6px 0;border-bottom:1px solid rgba(0,0,0,.055);font-size:11.5px;line-height:1.6}
      .inv-contact-line:last-child{border-bottom:0}
      .inv-contact-label{color:${theme.muted};font-weight:900;white-space:nowrap}
      .inv-contact-value{color:${theme.ink};font-weight:900;overflow-wrap:anywhere;word-break:normal}
      .inv-studio-compact{margin:0 0 18px;padding:11px 16px;text-align:center;border:1px solid ${theme.line};border-radius:12px;background:${theme.softer};color:${theme.ink}}
      .inv-studio-name{font-size:15px;font-weight:900;line-height:1.4}
      .inv-studio-line{font-size:11.5px;line-height:1.9;color:${theme.ink};font-weight:500;white-space:normal;overflow-wrap:anywhere}
      .inv-studio-line span{color:${theme.accent};font-weight:900}
      .inv-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:0 0 20px}
      .inv-cost-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:0 0 20px}
      .inv-card{background:${theme.softer};border:1px solid ${theme.line};border-radius:12px;padding:14px;text-align:center}
      .inv-card .v{font-size:21px;font-weight:900;color:${theme.accent};line-height:1.1}
      .inv-card .l{font-size:10.5px;color:${theme.muted};font-weight:800;margin-top:6px}
      .inv-section{margin:0 0 18px;break-inside:avoid;page-break-inside:avoid}
      .inv-section-cont{margin-top:0}
      .inv-section-title{font-size:15px;font-weight:900;color:${theme.accent};border-bottom:3px solid ${theme.line};padding-bottom:8px;margin-bottom:12px;text-align:right;display:flex;justify-content:space-between;gap:12px;align-items:center}
      .inv-section-title small{font-size:10px;color:${theme.muted};font-weight:900;margin-right:6px}
      .inv-section-title em{font-style:normal;font-size:12px;color:${theme.warn};white-space:nowrap}
      .inv-project-main td{background:#fff4dc!important;color:${theme.ink}!important;font-weight:900}
      .inv-project-detail td{background:#fffaf2!important;color:#444}
      table{width:100%;border-collapse:collapse;table-layout:fixed}
      thead{display:table-header-group}
      tfoot{display:table-footer-group}
      tr{break-inside:avoid;page-break-inside:avoid}
      th{background:${theme.soft};padding:10px 14px;text-align:right;font-size:11.5px;color:${theme.ink};font-weight:900;border-bottom:2px solid ${theme.line}}
      th,td{overflow-wrap:anywhere;word-break:normal;line-height:1.65;vertical-align:top}
      td{padding:10px 14px;border-bottom:1px solid #eee;font-size:12.5px;color:#333}
      tfoot td{border-bottom:0}
      .sum-lite{background:${theme.softer}!important;color:#555!important;font-weight:800}
      .sum-main{background:${theme.soft}!important;color:${theme.ink}!important;font-weight:900;font-size:14px}
      .sum-value{color:${theme.accent}!important;text-align:left}
      .inv-note{margin:0 0 16px;padding:13px 15px;background:${theme.softer};border-right:3px solid ${theme.accent};border-radius:8px;font-size:12px;color:#555;line-height:1.8}
      .inv-policies{margin:0 0 18px;padding:16px 18px;background:${theme.softer};border-radius:8px;border:1px solid ${theme.line};break-inside:avoid;page-break-inside:avoid}
      .inv-footer{background:${theme.softer};border-top:1px solid ${theme.line};padding:13px 30px;display:flex;justify-content:space-between;align-items:center;width:100%;font-size:10.5px;color:${theme.muted};margin-top:18px}
      @media print{
        html,body{width:210mm;margin:0;background:#fff;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
        .inv-page{width:210mm;height:297mm;overflow:hidden}
        .inv-head,.inv-band,.inv-footer{position:static}
        .inv-head{break-after:avoid;page-break-after:avoid}
        .inv-meta-strip,.inv-summary,.inv-cost-summary,.inv-table-wrap,.inv-note,.inv-policies{break-inside:avoid;page-break-inside:avoid}
        .inv-section{break-inside:avoid;page-break-inside:avoid;margin-bottom:14px}
        .inv-section-title{break-after:avoid;page-break-after:avoid}
        .inv-card{break-inside:avoid;page-break-inside:avoid}
        th,td{font-size:11.5px;padding:8px 10px}
      }
    </style>
    </head><body>${pageHtml}</body></html>`;
  const pa=document.getElementById('print-area');
  if(pa){
    const bodyMatch=html.match(/<body[^>]*>([\s\S]*)<\/body>/i);
    pa.innerHTML=bodyMatch ? bodyMatch[1] : html;
    pa.style.display='block';
  }
  const frame=document.createElement('iframe');
  frame.style.position='fixed';
  frame.style.left='-10000px';
  frame.style.top='0';
  frame.style.width='210mm';
  frame.style.height='297mm';
  frame.style.border='0';
  document.body.appendChild(frame);
  const doc=frame.contentDocument||frame.contentWindow.document;
  doc.open();
  doc.write(html);
  doc.close();
  const doPrint=()=>{
    try{
      frame.contentWindow.focus();
      frame.contentWindow.print();
      setTimeout(()=>{
        frame.remove();
        if(pa){pa.style.display='none';pa.innerHTML='';}
      },1200);
    }catch(e){
      frame.remove();
      if(pa){pa.style.display='none';pa.innerHTML='';}
      const w=window.open('','_blank');
      if(!w) return alert('المتصفح منع نافذة الطباعة. اسمح بالنوافذ المنبثقة وجرب مرة أخرى.');
      w.document.open();
      w.document.write(html);
      w.document.close();
      setTimeout(()=>{w.focus();w.print();},500);
    }
  };
  if(frame.contentWindow.document.readyState==='complete') setTimeout(doPrint,250);
  else frame.onload=()=>setTimeout(doPrint,250);
}

