// â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
// الميزانيات تظهر في صفحة الأهداف
// â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
function _renderBudgetsAsGoals(){
  var container = document.getElementById('goals-budgets-section');
  if(!container){
    var grid = document.getElementById('goals-grid');
    if(!grid) return;
    // أنشئ section للميزانيات بعد الـ grid
    container = document.createElement('div');
    container.id = 'goals-budgets-section';
    container.style.marginTop = '24px';
    grid.parentNode.insertBefore(container, grid.nextSibling);
  }
  var budgets = S.budgets || [];
  if(!budgets.length){ container.innerHTML=''; return; }
  var active = budgets.filter(function(b){ return (b.saved||0)<b.target; });
  var done = budgets.filter(function(b){ return (b.saved||0)>=b.target; });
  var cur = _getCurrency();
  var html = '<div class="section-title" style="margin-bottom:12px"><i class="fa-solid fa-piggy-bank" style="color:var(--accent2)"></i> أهداف الميزانية والادخار</div>';
  if(active.length){
    html += '<div class="grid grid-2" style="margin-bottom:16px">';
    html += active.map(function(b){
      var pct = b.target>0 ? Math.min(100,Math.round((b.saved||0)/b.target*100)) : 0;
      var rem = Math.max(0, b.target-(b.saved||0));
      var barColor = pct>=75?'var(--accent3)':pct>=40?'var(--accent2)':'var(--accent)';
      return '<div class="card" style="border-right:3px solid '+barColor+'">'
        +'<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:10px">'
          +'<div><div style="font-size:14px;font-weight:800">'+escapeHtml(b.name)+'</div>'
          +'<div style="font-size:11px;color:var(--text3)">ًں’° هدف ادخار'+(b.deadline?' آ· âڈ° '+b.deadline:'')+'</div></div>'
          +'<button class="btn btn-ghost btn-sm" onclick="switchFinTab(&apos;budgets&apos;);showPage(&apos;finance&apos;)" title="اذهب للميزانية"><i class="fa-solid fa-arrow-left"></i></button>'
        +'</div>'
        +'<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px">'
          +'<span style="color:var(--text3)">المدّخر</span>'
          +'<span style="font-weight:800;color:'+barColor+'">'+(b.saved||0).toLocaleString()+' / '+b.target.toLocaleString()+' '+cur+'</span>'
        +'</div>'
        +'<div style="height:8px;background:var(--surface3);border-radius:4px;margin-bottom:8px;overflow:hidden">'
          +'<div style="height:100%;width:'+pct+'%;background:'+barColor+';border-radius:4px;transition:.4s"></div>'
        +'</div>'
        +'<div style="display:flex;justify-content:space-between;align-items:center">'
          +'<span style="font-size:12px;font-weight:900;color:'+barColor+'">'+pct+'%</span>'
          +'<button class="btn btn-ghost btn-sm" style="font-size:11px" onclick="addToBudget(&apos;'+b.id+'&apos;)"><i class="fa-solid fa-plus"></i> أضف مبلغ</button>'
        +'</div>'
        +'</div>';
    }).join('');
    html += '</div>';
  }
  if(done.length){
    html += '<div style="display:flex;flex-wrap:wrap;gap:8px">'
      +done.map(function(b){
        return '<div style="display:inline-flex;align-items:center;gap:8px;padding:6px 14px;background:rgba(79,209,165,.1);border:1px solid var(--accent3);border-radius:20px;font-size:12px;font-weight:700;color:var(--accent3)">'
          +'<i class="fa-solid fa-square-check"></i> '+escapeHtml(b.name)+' ('+b.target.toLocaleString()+' '+cur+')'
          +'</div>';
      }).join('')
    +'</div>';
  }
  container.innerHTML = html;
}


window._scheduleSelectedDate = window._scheduleSelectedDate || new Date().toISOString().split('T')[0];
window._scheduleViewDate = window._scheduleViewDate || window._scheduleSelectedDate.slice(0,7);

function openSchedModal(id, prefillDate){
  // ملأ قائمة المهام
  const sel=document.getElementById('s-linked-task');
  if(sel){
    sel.innerHTML='<option value="">? بدون ربط ?</option>';
    S.tasks.filter(t=>!t.done).forEach(t=>{
      sel.innerHTML+=`<option value="${t.id}">${t.title}${t.client?' ('+t.client+')':''}</option>`;
    });
  }
  document.getElementById('sched-modal-ttl').innerHTML=id?'<i class="fa-solid fa-clock"></i> تعديل الوقت':'<i class="fa-solid fa-clock"></i> إضافة وقت في الجدول';
  document.getElementById('sched-eid').value=id||'';
  if(id){
    const s=S.schedule.find(s=>s.id===id);
    if(s){
      const sd=document.getElementById('s-date'); if(sd) sd.value=s.date||s.isoDate||window._scheduleSelectedDate||today();
      document.getElementById('s-time').value=s.time||'';
      document.getElementById('s-type').value=s.type||'work';
      document.getElementById('s-title').value=s.title||'';
      _setScheduleColor(_scheduleColor(s));
      if(sel) sel.value=s.linkedTaskId||'';
    }
  } else {
    const sd=document.getElementById('s-date'); if(sd) sd.value=prefillDate||window._scheduleSelectedDate||today();
    document.getElementById('s-time').value='';
    document.getElementById('s-title').value='';
    _setScheduleColor(_scheduleTypeColor(document.getElementById('s-type')?.value||'work'));
    if(sel) sel.value='';
  }
  openM('modal-schedule');
}
function saveSched(){
  const title=v('s-title').trim();if(!title)return alert('أدخل العنوان');
  const eid=v('sched-eid');
  const linkedTaskId=document.getElementById('s-linked-task')?.value ? +document.getElementById('s-linked-task').value : null;
  const date=v('s-date')||window._scheduleSelectedDate||today();
  const color=document.getElementById('s-color')?.value||_scheduleTypeColor(v('s-type'));
  const d={date,isoDate:date,time:v('s-time'),type:v('s-type'),title,linkedTaskId,color,done:false};
  if(eid){const i=S.schedule.findIndex(s=>s.id==eid);if(i>-1){d.id=+eid;d.done=S.schedule[i].done||false;S.schedule[i]=d;}}
  else{d.id=Date.now();S.schedule.push(d);}
  S.schedule.sort((a,b)=>String((a.date||'')+' '+(a.time||'')).localeCompare(String((b.date||'')+' '+(b.time||''))));
  window._scheduleSelectedDate=date;
  window._scheduleViewDate=date.slice(0,7);
  lsSave();closeM('modal-schedule');renderAll();
}
function delSched(id){confirmDel('هل تريد حذف هذا الوقت؟',()=>{S.schedule=S.schedule.filter(s=>s.id!==id);lsSave();renderAll();});}
function toggleSchedDone(id){
  const s=S.schedule.find(x=>x.id===id);if(!s)return;
  s.done=!s.done;
  // إذا اكتمل الوقت وفيه مهمة مربوطة ? اكمل المهمة
  if(s.done && s.linkedTaskId){
    const t=S.tasks.find(x=>x.id===s.linkedTaskId);
    if(t&&!t.done){
      t.done=true;t.status='done';
      showToast('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم اكتمال المهمة المرتبطة: '+t.title);
    }
  }
  lsSave();renderAll();
}
function renderSchedule(){
  const el=document.getElementById('sched-list');if(!el)return;
  const todayStr = today();
  if(!window._scheduleSelectedDate) window._scheduleSelectedDate = todayStr;
  if(!window._scheduleViewDate) window._scheduleViewDate = window._scheduleSelectedDate.slice(0,7);
  const selected = window._scheduleSelectedDate;
  const items = _scheduleItemsForDay(selected);
  renderScheduleCalendar();
  el.innerHTML=items.length?items.map(item=>{
    if(item.kind==='task'){
      const t=item.raw;
      const done=t.done||t.status==='done';
      return `<div class="ordo-agenda-item task-clickable" onclick="openTaskDetail(${t.id})" style="${done?'opacity:.62':''}">
        <div class="ordo-agenda-time">${item.time||'مهمة'}</div>
        <div class="ordo-agenda-dot" style="background:var(--accent)"></div>
        <div style="flex:1;min-width:0">
          <div style="font-size:13.5px;font-weight:800;${done?'text-decoration:line-through;color:var(--text3)':''}">${escapeHtml(item.title)}</div>
          <div style="font-size:11px;color:var(--text3);margin-top:2px"><i class="fa-solid fa-list-check"></i> ${item.meta}</div>
        </div>
        <button class="btn btn-ghost btn-sm" onclick="event.stopPropagation();openTaskModal(${t.id})"><i class="fa-solid fa-pen"></i></button>
      </div>`;
    }
    if(item.kind==='project_task'){
      const t=item.raw;
      const done=t.done||t.status==='done';
      return `<div class="ordo-agenda-item task-clickable" onclick="openProjectDetail('${String(t.project_id).replace(/'/g,"\\'")}')" style="${done?'opacity:.62':''}">
        <div class="ordo-agenda-time">${item.time||'مشروع'}</div>
        <div class="ordo-agenda-dot" style="background:${escapeHtml(item.color||'var(--accent)')}"></div>
        <div style="flex:1;min-width:0">
          <div style="font-size:13.5px;font-weight:800;${done?'text-decoration:line-through;color:var(--text3)':''}">${escapeHtml(item.title)}</div>
          <div style="font-size:11px;color:var(--text3);margin-top:2px"><i class="fa-solid fa-diagram-project"></i> ${escapeHtml(item.meta)}</div>
        </div>
        <button class="btn btn-ghost btn-sm" onclick="event.stopPropagation();openProjTaskModal('${String(t.project_id).replace(/'/g,"\\'")}','${String(t.id).replace(/'/g,"\\'")}')"><i class="fa-solid fa-pen"></i></button>
      </div>`;
    }
    if(item.kind==='meeting'){
      const m=item.raw;
      return `<div class="ordo-agenda-item task-clickable" onclick="openMeetingDetail(${m.id})" style="${m.done?'opacity:.62':''}">
        <div class="ordo-agenda-time">${m.time||'--:--'}</div>
        <div class="ordo-agenda-dot" style="background:var(--accent4)"></div>
        <div style="flex:1;min-width:0">
          <div style="font-size:13.5px;font-weight:800;${m.done?'text-decoration:line-through;color:var(--text3)':''}">${escapeHtml(item.title)}</div>
          <div style="font-size:11px;color:var(--text3);margin-top:2px"><i class="fa-solid fa-handshake"></i> ${escapeHtml(item.meta)}</div>
        </div>
        <button class="btn btn-ghost btn-sm" onclick="event.stopPropagation();openMeetingModal(${m.id})"><i class="fa-solid fa-pen"></i></button>
      </div>`;
    }
    const s=item.raw;
    const linkedTask=s.linkedTaskId?S.tasks.find(t=>t.id===s.linkedTaskId):null;
    const taskDone=linkedTask?.done||false;
    const isDone=s.done||taskDone;
    return `<div class="ordo-agenda-item" style="${isDone?'opacity:.6':''}">
      <div class="ordo-agenda-time" style="${isDone?'text-decoration:line-through':''}">${s.time||'?'}</div>
      <div class="ordo-agenda-dot" style="background:${isDone?'var(--accent3)':_scheduleColor(s)}"></div>
      <div style="flex:1">
        <div style="font-size:13.5px;font-weight:600;${isDone?'text-decoration:line-through;color:var(--text3)':''}">${s.title}</div>
        <div style="font-size:11px;color:var(--text2)">${tname[s.type]||''}</div>
        ${linkedTask?`<div class="sched-linked ${isDone?'done':''}"><i class="fa-solid fa-link"></i> ${linkedTask.title}${isDone?' <i class="fa-solid fa-check"></i>':''}</div>`:''}
      </div>
      <div style="display:flex;gap:4px;align-items:center">
        <button class="btn btn-sm" style="background:${isDone?'rgba(79,209,165,.15)':'rgba(124,111,247,.15)'};color:${isDone?'var(--accent3)':'var(--accent)'};border:none;border-radius:6px;padding:4px 8px;font-size:11px;cursor:pointer" onclick="toggleSchedDone(${s.id})" title="${isDone?'إلغاء الاكتمال':'تأشير كمكتمل'}">${isDone?'â†© رجوع':'<i class="fa-solid fa-check"></i> تم'}</button>
        <button class="btn btn-ghost btn-sm" onclick="openSchedModal(${s.id})"><i class="fa-solid fa-pen"></i></button>
        <button class="btn btn-danger btn-sm" onclick="delSched(${s.id})"><i class="fa-solid fa-trash"></i></button>
      </div>
    </div>`;
  }).join(''):'<div class="empty"><div class="empty-icon"><i class="fa-solid fa-calendar-day"></i></div>لا يوجد شيء في هذا اليوم</div>';
}

function _scheduleDateLabel(dateStr){
  if(!dateStr) return '';
  try{
    return new Date(dateStr+'T12:00:00').toLocaleDateString('ar-EG',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
  }catch(e){ return dateStr; }
}
function _scheduleISO(d){
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
function _scheduleAddDays(dateStr, n){
  const d=new Date(dateStr+'T12:00:00');
  d.setDate(d.getDate()+n);
  return _scheduleISO(d);
}
function _scheduleDiffDays(a,b){
  return Math.round((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000);
}
function _taskColor(t){
  return (t && (t.color || t.calendarColor || t.taskColor)) || '#7c6ff7';
}
function _scheduleTypeColor(type){
  return ({work:'#7c6ff7',meeting:'#f76f7c',learning:'#4fd1a5',break:'#f7c948',admin:'#8f93b5'})[type||'work'] || '#4fd1a5';
}
function _scheduleColor(s){
  return (s && (s.color || s.calendarColor || s.scheduleColor)) || _scheduleTypeColor(s && s.type);
}
function _setScheduleColor(color){
  const el=document.getElementById('s-color');
  if(el) el.value=color||'#4fd1a5';
}
function _setTaskColor(color){
  const el=document.getElementById('t-color');
  if(el) el.value=color;
  _previewTaskCalendarColor(color);
}
function _previewTaskCalendarColor(color){
  const eid=document.getElementById('task-eid')?.value||'';
  if(!eid) return;
  const t=(S.tasks||[]).find(function(x){ return String(x.id)===String(eid); });
  if(!t) return;
  t.color=color||'#7c6ff7';
  lsSave();
  if(typeof renderSchedule==='function') renderSchedule();
}
function _calDateInRange(date,start,end){
  return date>=start && date<=end;
}
function _scheduleItemsForDay(day){
  const items = [];
  (S.schedule||[]).forEach(function(s){
    const d=s.date||s.isoDate||today();
    if(d!==day) return;
    items.push({kind:'schedule',date:d,time:s.time||'',title:s.title||'وقت مجدول',meta:tname[s.type]||'',raw:s});
  });
  (S.tasks||[]).forEach(function(t){
    const a=t.orderDate||t.deadline;
    const b=t.deadline||t.orderDate;
    if(!a&&!b) return;
    let start=a||b, end=b||a;
    if(start>end){ const tmp=start; start=end; end=tmp; }
    if(day<start || day>end) return;
    const span=_scheduleDiffDays(start,end)+1;
    let meta=day===start?'تاريخ البدء':day===end?'موعد التسليم':'ضمن مدة التنفيذ';
    if(span>1) meta += ' · '+span+' أيام';
    items.push({kind:'task',date:day,time:'',title:t.title||'مهمة',meta:meta+(t.client?' · '+t.client:''),raw:t});
  });
  (S.project_tasks||[]).forEach(function(t){
    const a=t.orderDate||t.deadline;
    const b=t.deadline||t.orderDate;
    if(!a&&!b) return;
    let start=a||b, end=b||a;
    if(start>end){ const tmp=start; start=end; end=tmp; }
    if(day<start || day>end) return;
    const proj=(S.projects||[]).find(function(p){return String(p.id)===String(t.project_id);})||{};
    const span=_scheduleDiffDays(start,end)+1;
    let meta='مهمة مرتبطة بمشروع: '+(proj.name||'مشروع');
    if(span>1) meta += ' · '+span+' أيام';
    items.push({kind:'project_task',date:day,time:'',title:t.title||'مهمة مشروع',meta:meta,raw:t,color:proj.color||t.color||'#7c6ff7'});
  });
  (S.meetings||[]).forEach(function(m){
    if(m.date===day) items.push({kind:'meeting',date:m.date,time:m.time||'',title:m.title||'ميتنج',meta:m.client||'ميتنج',raw:m});
  });
  return items.sort(function(a,b){
    return String(a.time||'99:99').localeCompare(String(b.time||'99:99')) || a.kind.localeCompare(b.kind);
  });
}
function renderScheduleCalendar(){
  const grid=document.getElementById('schedule-calendar-grid');
  if(!grid) return;
  const selected=window._scheduleSelectedDate||today();
  const view=(window._scheduleViewDate||selected.slice(0,7));
  const y=+view.slice(0,4), m=+view.slice(5,7)-1;
  const first=new Date(y,m,1);
  const startOffset=(first.getDay()+1)%7;
  const start=new Date(y,m,1-startOffset);
  const monthTitle=document.getElementById('schedule-month-title');
  if(monthTitle) monthTitle.textContent=first.toLocaleDateString('ar-EG',{month:'long',year:'numeric'});
  const selectedLabel=document.getElementById('schedule-selected-label');
  if(selectedLabel) selectedLabel.textContent=_scheduleDateLabel(selected);
  const dayTitle=document.getElementById('schedule-day-title');
  if(dayTitle) dayTitle.textContent=_scheduleDateLabel(selected);
  const weeks=[];
  const daysInMonth = new Date(y, m+1, 0).getDate();
  const weeksCount = Math.ceil((startOffset + daysInMonth) / 7);
  for(let w=0;w<weeksCount;w++){
    const weekStart=_scheduleISO(new Date(start.getFullYear(),start.getMonth(),start.getDate()+(w*7)));
    const weekEnd=_scheduleAddDays(weekStart,6);
    const cells=[];
    for(let i=0;i<7;i++){
      const d=new Date(start.getFullYear(),start.getMonth(),start.getDate()+(w*7)+i);
      const iso=_scheduleISO(d);
      const items=_scheduleItemsForDay(iso);
      const inMonth=d.getMonth()===m;
      cells.push('<button class="ordo-cal-day '+(inMonth?'':'out')+' '+(iso===today()?'today':'')+' '+(iso===selected?'selected':'')+'" data-date="'+iso+'" onclick="selectScheduleDay(\''+iso+'\')" ondblclick="event.stopPropagation();openCalendarDayDetails(\''+iso+'\')" type="button" style="grid-column:'+(7-i)+';grid-row:1">'+
        '<div class="ordo-cal-num"><b>'+d.getDate()+'</b>'+(items.length?'<span>'+items.length+'</span>':'')+'</div>'+
      '</button>');
    }
    weeks.push('<div class="ordo-cal-week">'+cells.join('')+_calendarWeekEvents(weekStart,weekEnd)+'</div>');
  }
  grid.innerHTML=weeks.join('');
  const stats=document.getElementById('schedule-day-stats');
  if(stats){
    const c=_scheduleItemsForDay(selected).length;
    stats.textContent=c+' عناصر';
  }
}
function _calendarWeekEvents(weekStart, weekEnd){
  const events=[];
  (S.tasks||[]).forEach(function(t){
    const a=t.orderDate||t.deadline;
    const b=t.deadline||t.orderDate;
    if(!a&&!b) return;
    let start=a||b, end=b||a;
    if(start>end){ const tmp=start; start=end; end=tmp; }
    if(end<weekStart || start>weekEnd) return;
    events.push({
      kind:'task', id:t.id, title:t.title||'مهمة',
      segStart:start>weekStart?start:weekStart,
      segEnd:end<weekEnd?end:weekEnd,
      color:_taskColor(t), done:t.done||t.status==='done'
    });
  });
  (S.project_tasks||[]).forEach(function(t){
    const a=t.orderDate||t.deadline;
    const b=t.deadline||t.orderDate;
    if(!a&&!b) return;
    let start=a||b, end=b||a;
    if(start>end){ const tmp=start; start=end; end=tmp; }
    if(end<weekStart || start>weekEnd) return;
    const proj=(S.projects||[]).find(function(p){return String(p.id)===String(t.project_id);})||{};
    events.push({
      kind:'project_task', id:t.id, projectId:t.project_id, title:(t.title||'مهمة مشروع')+' · '+(proj.name||'مشروع'),
      segStart:start>weekStart?start:weekStart,
      segEnd:end<weekEnd?end:weekEnd,
      color:proj.color||t.color||'#7c6ff7', done:t.done||t.status==='done'
    });
  });
  (S.meetings||[]).forEach(function(m){
    if(!m.date || !_calDateInRange(m.date,weekStart,weekEnd)) return;
    events.push({kind:'meeting',id:m.id,title:(m.time?m.time+' ':'')+(m.title||'ميتنج'),segStart:m.date,segEnd:m.date,done:m.done});
  });
  (S.schedule||[]).forEach(function(s){
    const d=s.date||s.isoDate||today();
    if(!_calDateInRange(d,weekStart,weekEnd)) return;
    events.push({kind:'schedule',id:s.id,title:(s.time?s.time+' ':'')+(s.title||'وقت'),segStart:d,segEnd:d,done:s.done,color:_scheduleColor(s)});
  });
  events.sort(function(a,b){
    const spanA=_scheduleDiffDays(a.segStart,a.segEnd);
    const spanB=_scheduleDiffDays(b.segStart,b.segEnd);
    return a.segStart.localeCompare(b.segStart) || spanB-spanA || a.kind.localeCompare(b.kind);
  });
  const lanes=[];
  return events.map(function(ev){
    let lane=0;
    while(lanes[lane] && lanes[lane]>=ev.segStart) lane++;
    lanes[lane]=ev.segEnd;
    const startDiff=_scheduleDiffDays(weekStart,ev.segStart);
    const endDiff=_scheduleDiffDays(weekStart,ev.segEnd);
    const colStart=7-endDiff;
    const colEnd=8-startDiff;
    const top=34+(lane*27);
    const cls='ordo-cal-event '+ev.kind+(ev.done?' done':'')+(ev.segStart===ev.segEnd?' single':'');
    const style='grid-column:'+colStart+' / '+colEnd+';margin-top:'+top+'px;--event-color:'+escapeHtml(ev.color||'#7c6ff7');
    if(ev.kind==='task'){
      return '<div class="'+cls+'" style="'+style+'" onpointerdown="_calTaskDragStart(event,'+ev.id+')" ondblclick="event.stopPropagation();openTaskDetail('+ev.id+')" onclick="event.stopPropagation()" title="'+escapeHtml(ev.title)+'">'+
        '<span class="cal-resize-handle" title="تغيير البداية" onpointerdown="_calResizeStart(event,\'task\','+ev.id+',\'start\')"></span>'+
        '<span class="cal-event-title">'+escapeHtml(ev.title)+'</span>'+
        '<span class="cal-resize-handle" title="تغيير النهاية" onpointerdown="_calResizeStart(event,\'task\','+ev.id+',\'end\')"></span>'+
      '</div>';
    }
    if(ev.kind==='schedule'){
      return '<div class="'+cls+'" style="'+style+'" onpointerdown="_calScheduleDragStart(event,'+ev.id+')" ondblclick="event.stopPropagation();openScheduleDetail('+ev.id+')" onclick="event.stopPropagation()" title="'+escapeHtml(ev.title)+'">'+
        '<span class="cal-event-title">'+escapeHtml(ev.title)+'</span>'+
      '</div>';
    }
    if(ev.kind==='project_task'){
      return '<div class="'+cls+'" style="'+style+'" onpointerdown="_calTaskDragStart(event,'+ev.id+')" ondblclick="event.stopPropagation();openProjectDetail(\''+String(ev.projectId).replace(/'/g,"\\'")+'\')" onclick="event.stopPropagation()" title="'+escapeHtml(ev.title)+'">'+
        '<span class="cal-event-title"><i class="fa-solid fa-diagram-project"></i> '+escapeHtml(ev.title)+'</span>'+
      '</div>';
    }
    return '<div class="'+cls+'" style="'+style+'" onclick="event.stopPropagation()" ondblclick="event.stopPropagation();openMeetingDetail('+ev.id+')" title="'+escapeHtml(ev.title)+'"><span class="cal-event-title">'+escapeHtml(ev.title)+'</span></div>';
  }).join('');
}

function openScheduleDetail(id){
  const s=(S.schedule||[]).find(function(x){ return String(x.id)===String(id); });
  if(!s) return;
  var typeMap={work:'عمل',personal:'شخصي',meeting:'ميتنج',break:'راحة',learn:'تعلم'};
  var linkedTask = s.linkedTaskId ? (S.tasks||[]).find(function(t){ return String(t.id)===String(s.linkedTaskId); }) : null;
  var ov=document.getElementById('calendar-detail-modal');
  if(!ov){
    ov=document.createElement('div');
    ov.id='calendar-detail-modal';
    ov.className='modal-overlay open';
    document.body.appendChild(ov);
  }
  ov.style.display='flex';
  ov.innerHTML =
    '<div class="modal calendar-detail-modal">'+
      '<div class="modal-header"><h3 style="margin:0"><i class="fa-solid fa-calendar-check"></i> تفاصيل الموعد</h3><button class="close-btn" onclick="document.getElementById(&quot;calendar-detail-modal&quot;)?.remove()"><i class="fa-solid fa-xmark"></i></button></div>'+
      '<div class="calendar-detail-body">'+
        '<div class="calendar-detail-title" style="--event-color:'+escapeHtml(_scheduleColor(s))+'"><span></span><div><b>'+escapeHtml(s.title||'وقت مجدول')+'</b><small>'+escapeHtml(typeMap[s.type]||s.type||'موعد')+'</small></div></div>'+
        '<div class="calendar-detail-grid">'+
          '<div><small>التاريخ</small><b>'+escapeHtml(s.date||s.isoDate||'غير محدد')+'</b></div>'+
          '<div><small>الوقت</small><b>'+escapeHtml(s.time||'غير محدد')+'</b></div>'+
          '<div><small>الحالة</small><b>'+(s.done?'مكتمل':'نشط')+'</b></div>'+
          '<div><small>مهمة مرتبطة</small><b>'+escapeHtml(linkedTask ? linkedTask.title : 'لا يوجد')+'</b></div>'+
        '</div>'+
        (s.notes?'<div class="calendar-detail-note">'+escapeHtml(s.notes).replace(/\\n/g,'<br>')+'</div>':'')+
      '</div>'+
      '<div class="calendar-detail-actions">'+
        (linkedTask?'<button class="btn btn-ghost" onclick="document.getElementById(&quot;calendar-detail-modal&quot;)?.remove();openTaskDetail('+linkedTask.id+')"><i class="fa-regular fa-eye"></i> فتح المهمة</button>':'')+
        '<button class="btn btn-ghost" onclick="document.getElementById(&quot;calendar-detail-modal&quot;)?.remove();openSchedModal('+s.id+')"><i class="fa-solid fa-pen"></i> تعديل</button>'+
      '</div>'+
    '</div>';
}

function openCalendarDayDetails(day){
  var items=_scheduleItemsForDay(day);
  var ov=document.getElementById('calendar-detail-modal');
  if(!ov){
    ov=document.createElement('div');
    ov.id='calendar-detail-modal';
    ov.className='modal-overlay open';
    document.body.appendChild(ov);
  }
  ov.style.display='flex';
  ov.innerHTML =
    '<div class="modal calendar-detail-modal">'+
      '<div class="modal-header"><h3 style="margin:0"><i class="fa-solid fa-calendar-day"></i> تفاصيل اليوم</h3><button class="close-btn" onclick="document.getElementById(&quot;calendar-detail-modal&quot;)?.remove()"><i class="fa-solid fa-xmark"></i></button></div>'+
      '<div class="calendar-detail-body">'+
        '<div style="font-size:13px;color:var(--text3);margin-bottom:10px">'+escapeHtml(_scheduleDateLabel(day))+' · '+items.length+' عناصر</div>'+
        (items.length?items.map(function(it){
          var color = it.kind==='task' ? _taskColor(it.raw) : _scheduleColor(it.raw);
          var action = it.kind==='task' ? 'openTaskDetail('+it.raw.id+')' : 'openScheduleDetail('+it.raw.id+')';
          return '<button class="calendar-detail-row" style="--event-color:'+escapeHtml(color)+'" onclick="document.getElementById(&quot;calendar-detail-modal&quot;)?.remove();'+action+'"><span></span><div><b>'+escapeHtml(it.title)+'</b><small>'+escapeHtml([it.time,it.meta].filter(Boolean).join(' · '))+'</small></div><i class="fa-solid fa-chevron-left"></i></button>';
        }).join(''):'<div class="empty" style="padding:22px">لا يوجد شيء في هذا اليوم</div>')+
      '</div>'+
      '<div class="calendar-detail-actions"><button class="btn btn-primary" onclick="document.getElementById(&quot;calendar-detail-modal&quot;)?.remove();openCalendarTask(\''+day+'\')"><i class="fa-solid fa-plus"></i> إضافة لهذا اليوم</button></div>'+
    '</div>';
}
function selectScheduleDay(day){
  window._scheduleSelectedDate=day;
  window._scheduleViewDate=day.slice(0,7);
  renderSchedule();
}
function moveScheduleMonth(delta){
  const view=window._scheduleViewDate||today().slice(0,7);
  const d=new Date(+view.slice(0,4),+view.slice(5,7)-1+delta,1);
  window._scheduleViewDate=_scheduleISO(d).slice(0,7);
  renderScheduleCalendar();
}
function goScheduleToday(){
  const d=today();
  window._scheduleSelectedDate=d;
  window._scheduleViewDate=d.slice(0,7);
  renderSchedule();
}
function openCalendarTask(day){
  day=day||window._scheduleSelectedDate||today();
  openTaskModal();
  setTimeout(function(){
    const order=document.getElementById('t-order');
    const deadline=document.getElementById('t-deadline');
    if(order) order.value=today();
    if(deadline) deadline.value=day;
  },80);
}

window._calDragJustMoved = false;
function _calTaskClick(ev, id){
  ev.stopPropagation();
  return false;
}
function _calScheduleDragStart(ev, id){
  ev.preventDefault();
  ev.stopPropagation();
  const el=ev.currentTarget;
  const sched=(S.schedule||[]).find(function(s){ return String(s.id)===String(id); });
  if(!sched) return;
  const originX=ev.clientX, originY=ev.clientY;
  const rect=el.getBoundingClientRect();
  const ghost=el.cloneNode(true);
  ghost.className='ordo-cal-drag-ghost';
  ghost.style.left=rect.left+'px';
  ghost.style.top=rect.top+'px';
  ghost.style.width=rect.width+'px';
  ghost.style.background=getComputedStyle(el).backgroundColor;
  ghost.style.transform='translate3d(0,0,0)';
  document.body.appendChild(ghost);
  let moved=false, lastX=0, lastY=0, raf=0;
  el.classList.add('dragging');
  el.style.opacity='.35';
  function paint(){
    raf=0;
    ghost.style.transform='translate3d('+lastX+'px,'+lastY+'px,0)';
  }
  function move(e){
    lastX=e.clientX-originX;
    lastY=e.clientY-originY;
    if(Math.abs(lastX)+Math.abs(lastY)>4) moved=true;
    if(!raf) raf=requestAnimationFrame(paint);
  }
  function finish(e){
    document.removeEventListener('pointermove', move);
    document.removeEventListener('pointerup', finish);
    if(raf) cancelAnimationFrame(raf);
    el.classList.remove('dragging');
    el.style.opacity='';
    if(ghost.parentNode) ghost.remove();
    if(!moved) return;
    window._calDragJustMoved=true;
    setTimeout(function(){ window._calDragJustMoved=false; },250);
    const date=_calDateFromPoint(e.clientX,e.clientY);
    if(!date) return;
    sched.date=date;
    sched.isoDate=date;
    window._scheduleSelectedDate=date;
    window._scheduleViewDate=date.slice(0,7);
    lsSave();
    if(typeof cloudSave==='function') cloudSave(S);
    renderSchedule();
    showMiniNotif('<i class="fa-solid fa-clock"></i> تم نقل الوقت');
  }
  document.addEventListener('pointermove', move);
  document.addEventListener('pointerup', finish);
}
function _calTaskDragStart(ev, id){
  if(ev.target && ev.target.classList && ev.target.classList.contains('cal-resize-handle')) return;
  ev.preventDefault();
  ev.stopPropagation();
  const el=ev.currentTarget;
  const task=(S.tasks||[]).find(function(t){ return String(t.id)===String(id); });
  if(!task) return;
  let start=task.orderDate||task.deadline||today();
  let end=task.deadline||task.orderDate||start;
  if(start>end){ const tmp=start; start=end; end=tmp; }
  const duration=Math.max(0,_scheduleDiffDays(start,end));
  const originX=ev.clientX, originY=ev.clientY;
  const rect=el.getBoundingClientRect();
  const ghost=el.cloneNode(true);
  ghost.className='ordo-cal-drag-ghost';
  ghost.style.left=rect.left+'px';
  ghost.style.top=rect.top+'px';
  ghost.style.width=rect.width+'px';
  ghost.style.background=getComputedStyle(el).backgroundColor;
  ghost.style.transform='translate3d(0,0,0)';
  ghost.querySelectorAll('.cal-resize-handle').forEach(function(h){ h.remove(); });
  document.body.appendChild(ghost);
  let moved=false, lastX=0, lastY=0, raf=0;
  el.classList.add('dragging');
  el.style.opacity='.35';
  function paint(){
    raf=0;
    ghost.style.transform='translate3d('+lastX+'px,'+lastY+'px,0)';
  }
  function move(e){
    lastX=e.clientX-originX;
    lastY=e.clientY-originY;
    if(Math.abs(lastX)+Math.abs(lastY)>4) moved=true;
    if(!raf) raf=requestAnimationFrame(paint);
  }
  function finish(e){
    document.removeEventListener('pointermove', move);
    document.removeEventListener('pointerup', finish);
    if(raf) cancelAnimationFrame(raf);
    el.classList.remove('dragging');
    el.style.opacity='';
    if(ghost.parentNode) ghost.remove();
    if(!moved) return;
    window._calDragJustMoved=true;
    setTimeout(function(){ window._calDragJustMoved=false; },250);
    const date=_calDateFromPoint(e.clientX,e.clientY);
    if(!date) return;
    task.orderDate=date;
    task.deadline=_scheduleAddDays(date,duration);
    window._scheduleSelectedDate=date;
    window._scheduleViewDate=date.slice(0,7);
    lsSave();
    if(typeof cloudSave==='function') cloudSave(S);
    renderSchedule();
    showMiniNotif('<i class="fa-solid fa-arrows-up-down-left-right"></i> تم نقل المهمة');
  }
  document.addEventListener('pointermove', move);
  document.addEventListener('pointerup', finish);
}
function _calDateFromPoint(x,y){
  const target=(document.elementsFromPoint(x,y)||[]).find(function(el){ return el.classList && el.classList.contains('ordo-cal-day'); });
  return target && target.dataset ? target.dataset.date : '';
}
function _calResizeStart(ev, kind, id, side){
  ev.preventDefault();
  ev.stopPropagation();
  if(kind!=='task') return;
  const el=ev.currentTarget.closest('.ordo-cal-event');
  const state={id:String(id),side,originX:ev.clientX,originY:ev.clientY};
  if(el) el.classList.add('resizing');
  function move(e){
    if(!el) return;
    el.style.transform='translate('+(e.clientX-state.originX)+'px,'+(e.clientY-state.originY)+'px)';
  }
  function finish(e){
    document.removeEventListener('pointermove', move);
    document.removeEventListener('pointerup', finish);
    if(el){ el.classList.remove('resizing'); el.style.transform=''; }
    const date=_calDateFromPoint(e.clientX,e.clientY);
    if(!date) return;
    const t=(S.tasks||[]).find(function(x){ return String(x.id)===state.id; });
    if(!t) return;
    const curStart=t.orderDate||t.deadline||date;
    const curEnd=t.deadline||t.orderDate||date;
    if(state.side==='start'){
      t.orderDate = date<=curEnd ? date : curEnd;
      t.deadline = date<=curEnd ? curEnd : date;
    } else {
      t.orderDate = curStart<=date ? curStart : date;
      t.deadline = curStart<=date ? date : curStart;
    }
    window._scheduleSelectedDate=date;
    window._scheduleViewDate=date.slice(0,7);
    lsSave();
    if(typeof cloudSave==='function') cloudSave(S);
    renderSchedule();
    showMiniNotif('<i class="fa-solid fa-calendar-check"></i> تم تعديل مدة المهمة');
  }
  document.addEventListener('pointermove', move);
  document.addEventListener('pointerup', finish);
}
window._setTaskColor = _setTaskColor;
window._setScheduleColor = _setScheduleColor;
window._scheduleTypeColor = _scheduleTypeColor;
window._previewTaskCalendarColor = _previewTaskCalendarColor;
window._calTaskClick = _calTaskClick;
window._calScheduleDragStart = _calScheduleDragStart;
window._calTaskDragStart = _calTaskDragStart;
window._calResizeStart = _calResizeStart;

