// TASK STEPS
// ============================================================
let _editingSteps=[];
function renderTaskStepsForm(steps){
  _editingSteps=JSON.parse(JSON.stringify(steps||[]));
  _renderStepsFormUI();
}
function _renderStepsFormUI(){
  const el=document.getElementById('t-steps-list');if(!el)return;
  if(!_editingSteps.length){el.innerHTML='<div style="font-size:12px;color:var(--text3);text-align:center;padding:8px 0">لا خطوات ? اضغط + خطوة لإضافة</div>';return;}
  el.innerHTML=_editingSteps.map((s,i)=>`
    <div style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid var(--border);flex-wrap:wrap">
      <div class="step-num ${s.done?'done':''}" onclick="toggleEditStep(${i})">${s.done?'<i class="fa-solid fa-check"></i>':i+1}</div>
      <input class="form-input" style="flex:1;min-width:140px;height:32px;font-size:12px" value="${s.text||''}" placeholder="وصف الخطوة..." oninput="_editingSteps[${i}].text=this.value">
      <input type="date" class="form-input" style="width:130px;height:32px;font-size:11px" value="${s.deadline||''}" oninput="_editingSteps[${i}].deadline=this.value" title="موعد تسليم الخطوة">
      <button onclick="removeEditStep(${i})" style="background:none;border:none;color:var(--text3);cursor:pointer;font-size:14px"><i class="fa-solid fa-xmark"></i></button>
    </div>`).join('');
}
function addTaskStep(){
  _editingSteps.push({text:'',done:false,deadline:''});
  _renderStepsFormUI();
  // focus last input
  const inputs=document.querySelectorAll('#t-steps-list input');
  if(inputs.length) inputs[inputs.length-1].focus();
}
function toggleEditStep(i){_editingSteps[i].done=!_editingSteps[i].done;_renderStepsFormUI();}
function removeEditStep(i){_editingSteps.splice(i,1);_renderStepsFormUI();}
function collectTaskSteps(){return _editingSteps.filter(s=>s.text.trim());}
function mergeSteps(oldSteps,newSteps){
  // Preserve done status from old steps for matching text
  return newSteps.map(ns=>{
    const old=oldSteps.find(o=>o.text===ns.text);
    return old?{...ns,done:old.done}:ns;
  });
}
function toggleTaskStep(taskId,stepIdx){
  const t=S.tasks.find(x=>x.id===taskId);if(!t||!t.steps)return;
  t.steps[stepIdx].done=!t.steps[stepIdx].done;
  // لو كل الخطوات اتنفذت ? إكمال المهمة تلقائياً
  if(t.steps.every(s=>s.done)&&!t.done){
    showToast('<i class="fa-solid fa-champagne-glasses"></i> تم إنجاز كل الخطوات! المهمة جاهزة للإكمال.');
  }
  lsSave();renderAll();
  // إعادة فتح الديتيل
  if(document.getElementById('modal-task-detail')?.classList.contains('open')){
    openTaskDetail(taskId);
  }
}
function renderStepsInDetail(task, isMemberTask, ownerId, authorName){
  if(!task.steps||!task.steps.length) return '';
  var total=task.steps.length, done=task.steps.filter(function(s){return s.done;}).length;
  var pct=Math.round(done/total*100);
  var currentStep=task.steps.find(function(s){return !s.done;});
  var tid = String(task.id);
  var html = '<div style="margin:14px 0;padding:14px;background:var(--surface2);border-radius:var(--r2);border:1px solid var(--border)">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">'
      +'<div style="font-size:13px;font-weight:700"><i class="fa-solid fa-clipboard-list"></i> خطوات التنفيذ</div>'
      +'<div style="font-size:12px;font-weight:700;color:var(--accent)">'+done+'/'+total+' ? '+pct+'%</div>'
    +'</div>'
    +'<div class="steps-progress"><div class="steps-progress-fill" style="width:'+pct+'%"></div></div>'
    +(currentStep
      ? '<div style="font-size:11px;color:var(--accent3);margin:6px 0 10px"><i class="fa-solid fa-play"></i> الخطوة الحالية: '+currentStep.text+'</div>'
      : '<div style="font-size:11px;color:var(--accent3);margin:6px 0 10px"><i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> كل الخطوات مكتملة!</div>')
    +'<div class="steps-container">';

  task.steps.forEach(function(s,i){
    var stepComments = (task.comments||[]).filter(function(c){return String(c.stepIdx)===String(i);});
    var toggleFn = isMemberTask
      ? 'window._memberToggleStep(\''+tid+'\','+i+',!'+s.done+')'
      : 'toggleTaskStep('+task.id+','+i+')';
    var inputId = 'step-note-'+tid+'-'+i;
    var submitFn = isMemberTask
      ? 'window._submitMemberComment(\''+ownerId+'\',\''+tid+'\',document.getElementById(\''+inputId+'\'),'+i+',\''+escapeHtml(authorName||'')+'\')' 
      : 'window._submitLocalComment(\''+tid+'\',document.getElementById(\''+inputId+'\'),'+i+')';

    html += '<div style="border-bottom:1px solid var(--border);padding-bottom:8px;margin-bottom:8px">'
      +'<div class="step-row" style="cursor:pointer;margin-bottom:0" onclick="'+toggleFn+'">'
        +'<div class="step-num '+(s.done?'done':task.steps.slice(0,i).every(function(x){return x.done;})?'active-step':'')+'">'+(s.done?'<i class="fa-solid fa-check"></i>':String(i+1))+'</div>'
        +'<div class="step-text '+(s.done?'done':'')+'">'+escapeHtml(s.text||s.title||s.name||'خطوة')+'</div>'
        +'<div style="font-size:10px;color:var(--text3)">'+(s.done?'<i class="fa-solid fa-check"></i> مكتمل':'معلق')+'</div>'
      +'</div>'
      +'<div style="margin-top:6px;padding-right:32px">'
        +(stepComments.length ? stepComments.map(function(c){
          return '<div style="background:rgba(124,111,247,.08);border-radius:8px;padding:6px 10px;margin-bottom:4px;font-size:11px">'
            +'<span style="color:var(--accent);font-weight:700">'+escapeHtml(c.author||'')+'</span>'
            +'<span style="color:var(--text3);font-size:10px;margin-right:6px">'+new Date(c.at).toLocaleDateString('ar-EG')+'</span>'
            +'<div style="color:var(--text2);margin-top:2px">'+escapeHtml(c.text)+'</div>'
          +'</div>';
        }).join('') : '')
        +'<div style="display:flex;gap:5px;margin-top:4px">'
          +'<input type="text" id="'+inputId+'" style="flex:1;padding:5px 8px;background:var(--surface);border:1px solid var(--border);border-radius:7px;font-size:11px;color:var(--text);font-family:var(--font)" placeholder="ملاحظة على الخطوة...">'
          +'<button style="padding:5px 10px;background:var(--accent);color:#fff;border:none;border-radius:7px;cursor:pointer;font-size:11px" onclick="'+submitFn+'"><i class="fa-solid fa-paper-plane"></i></button>'
        +'</div>'
      +'</div>'
    +'</div>';
  });

  html += '</div></div>';
  return html;
}

// ============================================================
// CLIENT FOLLOW-UP REMINDERS
// ============================================================
function renderFollowupReminders(){
  const el=document.getElementById('dash-followup-reminders');if(!el)return;
  const now=new Date();
  const alerts=[];
  S.clients.forEach(c=>{
    if(c.followupEnabled!=='on')return;
    const months=c.followupMonths||3;
    // آخر طلب = آخر مهمة
    const cTasks=S.tasks.filter(t=>t.client===c.name&&t.orderDate).sort((a,b)=>b.orderDate.localeCompare(a.orderDate));
    const lastOrderDate=cTasks[0]?.orderDate||null;
    if(!lastOrderDate)return; // مفيش طلبات أصلاً ? مش هنبعت تنبيه
    const last=new Date(lastOrderDate);
    const diffMonths=(now-last)/(1000*60*60*24*30.44);
    if(diffMonths>=months){
      alerts.push({client:c,lastOrderDate,diffMonths:Math.round(diffMonths)});
    }
  });
  if(!alerts.length){el.style.display='none';return;}
  el.style.display='block';
  el.innerHTML=`
    <div class="card" style="border-color:rgba(247,201,72,.3)">
      <div class="section-title" style="color:var(--accent2)"><i class="fa-solid fa-bell"></i> تذكيرات متابعة العملاء</div>
      ${alerts.map(({client:c,lastOrderDate,diffMonths})=>`
        <div class="followup-alert ${diffMonths>=(c.followupMonths||3)*2?'overdue':''}">
          <div class="followup-dot"></div>
          <div style="flex:1">
            <div style="font-size:13px;font-weight:700">${c.name}</div>
            <div style="font-size:11px;color:var(--text3)">آخر طلب: ${lastOrderDate} ? منذ ${diffMonths} شهر تقريباً</div>
          </div>
          ${c.phone?`<button class="btn btn-sm" style="background:#25D366;color:#fff;border:none;border-radius:8px;padding:6px 12px;font-size:11px;cursor:pointer;font-weight:700" onclick="sendFollowupWA(${c.id})"><i class="fa-solid fa-mobile-screen"></i> واتساب</button>`:''}
        </div>`).join('')}
    </div>`;
}
function sendFollowupWA(clientId){
  const c=S.clients.find(x=>x.id===clientId);if(!c)return;
  const msg=c.followupMsg||`أهلاً ${c.name}، اتمنى تكون بخير <i class="fa-solid fa-hands"></i> عايز أطمن عليك وأعرف لو محتاج حاجة من ناحيتنا âœ¨`;
  const phone=c.phone?.replace(/\D/g,'');
  if(!phone){alert('مفيش رقم واتساب محفوظ للعميل ده');return;}
  window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`,'_blank');
}

// helper: show toast notification
function toast(msg,dur=3000,opts){
  if(dur && typeof dur==='object'){ opts=dur; dur=3000; }
  showToast(msg,dur,opts);
}
function _budgetNotifText(msg){
  const div=document.createElement('div');
  div.innerHTML=String(msg||'');
  return (div.textContent||div.innerText||'').replace(/\s+/g,' ').trim();
}
function _projectBudgetAlertInfo(projectId){
  const p=(S.projects||[]).find(x=>String(x.id)===String(projectId));
  if(!p) return null;
  const cur=p.budgetCurrency||p.currency||'ج.م';
  const tasks=(S.project_tasks||[]).filter(t=>String(t.project_id||t.projectId||'')===String(p.id));
  const rows=Array.isArray(p.projectLedger)?p.projectLedger:[];
  const num=v=>+(v||0);
  const budget=num(p.budget||p.totalBudget||p.amount||p.value);
  const taskCost=tasks.reduce((s,t)=>s+num(t.memberCost||t.workerAmount||t.workerCost||t.cost||t.value||t.amount),0);
  const teamPaid=rows.filter(r=>r&&r.kind==='team_payout').reduce((s,r)=>s+num(r.amount),0);
  const expenses=rows.filter(r=>r&&r.kind==='project_expense').reduce((s,r)=>s+num(r.amount),0);
  const spent=taskCost+teamPaid+expenses;
  const over=Math.max(0,spent-budget);
  return {project:p,cur,tasks,rows,budget,taskCost,teamPaid,expenses,spent,over};
}
function _findBudgetAlertProjectFromText(text){
  const clean=String(text||'').trim();
  if(!clean || clean.indexOf('تجاوزت الميزانية')<0) return null;
  const matches=(S.projects||[]).filter(p=>p&&p.name&&clean.indexOf(String(p.name).trim())>=0);
  if(matches.length) return matches.sort((a,b)=>String(b.name).length-String(a.name).length)[0];
  return (S.projects||[]).find(p=>p&&p.name&&clean.indexOf(String(p.name).split(' ')[0])>=0) || null;
}
function openBudgetAlertDetails(projectId){
  const info=_projectBudgetAlertInfo(projectId);
  if(!info) return;
  const h=(typeof escapeHtml==='function')?escapeHtml:(v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])));
  const fmt=(v)=> (typeof money==='function'?money(v,info.cur):(Number(v||0).toLocaleString('ar-EG')+' '+info.cur));
  const topTasks=info.tasks.slice().sort((a,b)=>+(b.value||b.amount||b.workerAmount||0)-+(a.value||a.amount||a.workerAmount||0)).slice(0,6);
  const taskRows=topTasks.map(t=>`<div style="display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;padding:8px 0;border-bottom:1px solid var(--border)"><span style="font-weight:800;color:var(--text);overflow-wrap:anywhere">${h(t.title||'مهمة')}</span><b style="color:var(--accent2);white-space:nowrap">${fmt(t.memberCost||t.workerAmount||t.workerCost||t.cost||t.value||t.amount||0)}</b></div>`).join('');
  const ov=document.createElement('div');
  ov.className='modal-overlay';
  ov.style.display='flex';
  ov.innerHTML=`<div class="modal" style="max-width:560px">
    <div class="modal-header">
      <div class="modal-title"><i class="fa-solid fa-triangle-exclamation" style="color:#f76f7c"></i> تفاصيل تجاوز الميزانية</div>
      <button class="close-btn" onclick="this.closest('.modal-overlay').remove()"><i class="fa-solid fa-xmark"></i></button>
    </div>
    <div style="border:1px solid rgba(247,111,124,.25);background:rgba(247,111,124,.08);border-radius:12px;padding:14px;margin-bottom:12px">
      <div style="font-size:18px;font-weight:900;color:var(--text);margin-bottom:4px">${h(info.project.name||'مشروع')}</div>
      <div style="font-size:12px;color:var(--text3)">المشروع تخطى ميزانيته بمبلغ <b style="color:#f76f7c">${fmt(info.over)}</b></div>
    </div>
    <div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-bottom:12px">
      <span style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:10px"><small style="color:var(--text3)">الميزانية</small><b style="display:block;color:var(--accent);font-size:16px">${fmt(info.budget)}</b></span>
      <span style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:10px"><small style="color:var(--text3)">إجمالي التكلفة</small><b style="display:block;color:#f76f7c;font-size:16px">${fmt(info.spent)}</b></span>
      <span style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:10px"><small style="color:var(--text3)">تكلفة المهام</small><b style="display:block;color:var(--text);font-size:15px">${fmt(info.taskCost)}</b></span>
      <span style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:10px"><small style="color:var(--text3)">مدفوعات/مصروفات</small><b style="display:block;color:var(--text);font-size:15px">${fmt(info.teamPaid+info.expenses)}</b></span>
    </div>
    <div style="font-size:12px;font-weight:900;color:var(--text3);margin-bottom:6px">أكبر البنود المؤثرة</div>
    <div style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:0 10px;margin-bottom:14px">${taskRows||'<div style="padding:12px;color:var(--text3);text-align:center">لا توجد مهام مسجلة</div>'}</div>
    <div style="display:flex;gap:8px">
      <button class="btn btn-primary" style="flex:1;justify-content:center" onclick="this.closest('.modal-overlay').remove();showPage('projects');setTimeout(function(){openProjectDetail('${String(info.project.id).replace(/'/g,"\\'")}')},120)"><i class="fa-solid fa-diagram-project"></i> فتح المشروع</button>
      <button class="btn btn-ghost" onclick="this.closest('.modal-overlay').remove()">إغلاق</button>
    </div>
  </div>`;
  document.body.appendChild(ov);
}
function _budgetNotifHandler(msg,opts){
  if(opts&&opts.projectId) return ()=>openBudgetAlertDetails(opts.projectId);
  const p=_findBudgetAlertProjectFromText(_budgetNotifText(msg));
  return p ? ()=>openBudgetAlertDetails(p.id) : null;
}
function _wireBudgetAlertElement(el){
  if(!el || el.nodeType!==1 || el.dataset.budgetAlertWired==='1') return false;
  const text=(el.textContent||'').replace(/\s+/g,' ').trim();
  const p=_findBudgetAlertProjectFromText(text);
  if(!p) return false;
  el.dataset.budgetAlertWired='1';
  el.dataset.projectId=String(p.id);
  el.style.cursor='pointer';
  el.title='اضغط لعرض تفاصيل التنبيه';
  el.addEventListener('click',function(e){
    if(e.target && e.target.closest && e.target.closest('button,[data-close],.close-btn,.close-x')) return;
    e.preventDefault();
    e.stopPropagation();
    openBudgetAlertDetails(p.id);
  },true);
  return true;
}
function _wireBudgetAlertsIn(root){
  root=root||document;
  if(!root.querySelectorAll) return;
  Array.from(root.querySelectorAll('div,article,section,button,[role="alert"],[class*="toast"],[class*="notif"],[class*="alert"]')).forEach(_wireBudgetAlertElement);
}
if(typeof MutationObserver!=='undefined'){
  try{
    new MutationObserver(function(list){
      list.forEach(function(m){
        Array.from(m.addedNodes||[]).forEach(function(n){
          _wireBudgetAlertElement(n);
          _wireBudgetAlertsIn(n);
        });
      });
    }).observe(document.documentElement,{childList:true,subtree:true});
    setTimeout(function(){_wireBudgetAlertsIn(document);},500);
  }catch(e){}
}
function _showProjectBudgetExceededNotif(projectId){
  const info=_projectBudgetAlertInfo(projectId);
  if(!info || info.budget<=0 || info.over<=0) return false;
  const amount=Number(info.over||0).toLocaleString('ar-EG');
  const msg=`<i class="fa-solid fa-triangle-exclamation" style="color:#f76f7c"></i> <b>${(typeof escapeHtml==='function'?escapeHtml(info.project.name):String(info.project.name||'مشروع'))}</b><br><span style="color:#f76f7c">تجاوزت الميزانية بـ ${amount} ${info.cur}</span>`;
  if(typeof showMiniNotif==='function') showMiniNotif(msg,{projectId:info.project.id});
  return true;
}
function showToast(msg,dur=3000,opts){
  if(dur && typeof dur==='object'){ opts=dur; dur=3000; }
  let t=document.getElementById('_toast');
  if(!t){t=document.createElement('div');t.id='_toast';t.style.cssText='position:fixed;bottom:24px;left:50%;transform:translateX(-50%) translateY(60px);background:var(--surface,#1a1a2e);color:var(--text,#fff);padding:10px 20px;border-radius:12px;font-size:13px;font-weight:600;z-index:9999;transition:.3s;border:1px solid rgba(124,111,247,.4);opacity:0;box-shadow:0 8px 32px rgba(0,0,0,.2)';document.body.appendChild(t);}
  t.innerHTML=msg;
  const handler=_budgetNotifHandler(msg,opts);
  t.onclick=handler||null;
  t.style.cursor=handler?'pointer':'default';
  t.title=handler?'اضغط لعرض تفاصيل التنبيه':'';
  t.style.transform='translateX(-50%) translateY(0)';t.style.opacity='1';
  clearTimeout(t._to);t._to=setTimeout(()=>{t.style.transform='translateX(-50%) translateY(60px)';t.style.opacity='0';},dur);
}

