function openSubscriptionModal(){
  renderSubsList();
  openM('modal-subscription');
}

function renderSubsList(){
  renderSubsWithReminder();
}

function addSubscription(){
  const name = document.getElementById('sub-name')?.value.trim();
  const amount = +(document.getElementById('sub-amount')?.value)||0;
  const day = +(document.getElementById('sub-day')?.value)||1;
  const cat = document.getElementById('sub-cat')?.value||'برامج واشتراكات';
  if(!name||!amount) return alert('أدخل اسم الاشتراك والمبلغ');
  if(!S.subscriptions) S.subscriptions=[];
  S.subscriptions.push({name,amount,day,cat});
  lsSave();
  renderSubsList();
  ['sub-name','sub-amount','sub-day'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  showMiniNotif('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم إضافة الاشتراك: '+name);
}

function renewSubscription(i){
  const s = S.subscriptions[i]; if(!s) return;
  S.transactions.push({
    id:Date.now(), type:'expense', amount:s.amount,
    source:s.cat||'برامج واشتراكات', desc:'تجديد اشتراك: '+s.name,
    isoDate:new Date().toISOString().split('T')[0],
    date:new Date().toLocaleDateString('ar-EG')
  });
  lsSave(); renderAll();
  showMiniNotif('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم تسجيل تجديد اشتراك '+s.name+': '+s.amount.toLocaleString()+' ج');
}

function delSubscription(i){
  S.subscriptions.splice(i,1);
  lsSave(); renderSubsList();
}


// ============================================================
// TASK VIEW SWITCH
// ============================================================
function switchTaskView(mode){
  // My Tasks views (inside tasks-active-view)
  var kanban = document.getElementById('kanban-view');
  var list   = document.getElementById('list-view');
  var table  = document.getElementById('table-view');
  // Project Tasks views
  var pKanban = document.getElementById('project-tasks-kanban');
  var pList   = document.getElementById('project-tasks-list');
  var pTable  = document.getElementById('project-tasks-table-wrap');
  // All Tasks views
  var aKanban = document.getElementById('all-tasks-kanban');
  var aList   = document.getElementById('all-tasks-list');
  var aTable  = document.getElementById('all-tasks-table-wrap');
  // Buttons
  var kb = document.getElementById('view-kanban-btn');
  var lb = document.getElementById('view-list-btn');
  var tb = document.getElementById('view-table-btn');
  var acc = 'var(--accent)';
  // Reset buttons
  [kb,lb,tb].forEach(function(btn){ if(btn){ btn.style.background='transparent'; btn.style.color='var(--text3)'; } });
  // Reset My Tasks inner views
  [kanban,list,table].forEach(function(el){ if(el) el.style.display='none'; });
  // Reset Project Tasks inner views
  [pKanban,pList,pTable].forEach(function(el){ if(el) el.style.display='none'; });
  // Reset All Tasks inner views
  [aKanban,aList,aTable].forEach(function(el){ if(el) el.style.display='none'; });

  if(mode==='kanban'){
    if(kanban) kanban.style.display='block';
    if(pKanban) pKanban.style.display='grid';
    if(aKanban) aKanban.style.display='grid';
    if(kb){ kb.style.background=acc; kb.style.color='#fff'; }
  } else if(mode==='list'){
    if(list) list.style.display='block';
    if(pList) pList.style.display='block';
    if(aList) aList.style.display='block';
    if(lb){ lb.style.background=acc; lb.style.color='#fff'; }
  } else if(mode==='table'){
    if(table) table.style.display='block';
    if(pTable) pTable.style.display='block';
    if(aTable) aTable.style.display='block';
    if(tb){ tb.style.background=acc; tb.style.color='#fff'; }
    _renderTasksTable();
  }
  localStorage.setItem('studioTaskView', mode);
  // Re-render the active scope
  if(_taskScope === 'project') _renderProjectTasksList();
  else if(_taskScope === 'all') _renderAllTasksList();
  else renderTasks();
}

// â”€â”€ جدول المهام الكامل مع تغيير الحالة inline â”€â”€
function _renderTasksTable(){
  var tbody = document.getElementById('tasks-table-body');
  var countEl = document.getElementById('tasks-table-count');
  var thead = document.getElementById('tasks-table-thead');
  if(!tbody) return;
  var filtered = filterTasks(S.tasks);
  if(countEl) countEl.textContent = filtered.length + ' مهمة';

  var allCustomStatuses = S.customStatuses||[];
  var baseStatuses = [
    {id:'new',      label:'جديد',         color:'var(--text3)'},
    {id:'progress', label:'قيد التنفيذ',  color:'var(--accent2)'},
    {id:'review',   label:'مراجعة',       color:'var(--accent)'},
    {id:'paused',   label:'موقوف',        color:'#64b5f6'},
    {id:'done',     label:'مكتمل',        color:'var(--accent3)'}
  ];
  allCustomStatuses.forEach(function(cs){
    if(cs.id && cs.label && !baseStatuses.find(function(b){return b.id===cs.id;})){
      baseStatuses.push({id:cs.id, label:cs.label, color:cs.color||'var(--accent)'});
    }
  });

  function stSelect(t){
    var cur = baseStatuses.find(function(s){return s.id===(t.status||'new');})||{label:t.status||'جديد',color:'#888'};
    var opts = baseStatuses.map(function(s){
      return '<option value="'+s.id+'"'+(t.status===s.id?' selected':'')+'>'+s.label+'</option>';
    }).join('');
    return '<div style="position:relative;display:inline-block">'
      +'<select data-tid="'+t.id+'" onchange="_changeRegTaskStatusFromTable(this.dataset.tid,this.value)" '
        +'style="appearance:none;-webkit-appearance:none;font-size:10px;font-weight:800;padding:3px 24px 3px 10px;border-radius:20px;background:'+cur.color+'22;color:'+cur.color+';border:1.5px solid '+cur.color+'55;cursor:pointer;outline:none;font-family:var(--font)">'
        +opts
      +'</select>'
      +'<span style="position:absolute;left:7px;top:50%;transform:translateY(-50%);pointer-events:none;font-size:8px;color:'+cur.color+'">?</span>'
    +'</div>';
  }

  var payBadgeTbl = {
    none:    '<span style="font-size:10px;color:#f76f7c;font-weight:700">غير مدفوع</span>',
    deposit: '<span style="font-size:10px;color:#a78bfa;font-weight:700">عربون</span>',
    full:    '<span style="font-size:10px;color:#4fd1a5;font-weight:700">âœ“ مدفوع</span>'
  };

  // Column visibility
  var cols = _getTableCols();
  var colVisible = {};
  cols.forEach(function(c){ colVisible[c.id] = c.visible; });

  // Build table header dynamically
  if(thead){
    var thStyle = 'padding:10px 8px;text-align:center;font-weight:800;color:var(--text3);border-bottom:1px solid var(--border)';
    var hdrCells = '<th style="padding:10px 4px;width:22px;border-bottom:1px solid var(--border)"></th>'
      +'<th style="padding:10px 6px;width:28px;border-bottom:1px solid var(--border)"></th>'
      +'<th style="padding:10px 14px;text-align:right;font-weight:800;color:var(--text3);border-bottom:1px solid var(--border)">المهمة</th>';
    if(colVisible.client!==false) hdrCells += '<th style="'+thStyle+'">العميل</th>';
    if(colVisible.deadline!==false) hdrCells += '<th style="'+thStyle+'">تاريخ التسليم</th>';
    if(colVisible.priority!==false) hdrCells += '<th style="'+thStyle+'" class="hide-mobile">الأولوية</th>';
    if(colVisible.orderDate) hdrCells += '<th style="'+thStyle+'" class="hide-mobile">تاريخ الطلب</th>';
    if(colVisible.pay!==false) hdrCells += '<th style="'+thStyle+'">حالة الدفع</th>';
    if(colVisible.status!==false) hdrCells += '<th style="'+thStyle+'">الحالة</th>';
    if(colVisible.value) hdrCells += '<th style="'+thStyle+'">القيمة</th>';
    if(colVisible.actions!==false) hdrCells += '<th style="'+thStyle+'">إجراءات</th>';
    thead.innerHTML = '<tr style="background:var(--surface2)">'+hdrCells+'</tr>';
  }

  var totalCols = 3; // drag + cb + title always shown
  cols.forEach(function(c){ if(c.visible) totalCols++; });

  if(!filtered.length){
    tbody.innerHTML='<tr><td colspan="'+totalCols+'" style="text-align:center;color:var(--text3);padding:32px;font-size:13px">لا توجد مهام تطابق الفلتر</td></tr>';
    return;
  }

  // â”€â”€ فصل نشطة / مكتملة â”€â”€
  var activeTbl = filtered.filter(function(t){ return !(t.done||t.status==='done'); });
  var doneTbl   = filtered.filter(function(t){ return  t.done||t.status==='done'; });

  function makeTableRow(t, idx){
    var rowBg = idx%2===0?'var(--surface)':'var(--surface2)';
    var isDone = t.done||t.status==='done';
    var isLate = t.deadline && new Date(t.deadline)<new Date() && !isDone;
    var projLink = t.projectLink||t.driveLink||'';
    var hasSteps = t.steps && t.steps.length > 0;
    var stepsHtml = '';
    if(hasSteps){
      stepsHtml = '<tr id="steps-row-'+t.id+'" style="display:none"><td colspan="'+totalCols+'" style="padding:0 14px 12px 40px;background:var(--surface2);border-bottom:2px solid var(--border)">'
        +'<div style="padding:10px 0;font-size:11px;font-weight:800;color:var(--text2);margin-bottom:4px"><i class="fa-solid fa-list-check" style="color:var(--accent);margin-left:4px"></i> خطوات المهمة ('+t.steps.filter(function(s){return s.done;}).length+'/'+t.steps.length+')</div>'
        +t.steps.map(function(s,si){
          var stepDone = s.done;
          var stepLate = s.deadline && new Date(s.deadline)<new Date() && !stepDone;
          return '<div style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid var(--border);font-size:12px" onclick="event.stopPropagation()">'
            +'<div onclick="toggleTaskStep('+t.id+','+si+');_renderTasksTable()" style="width:20px;height:20px;border-radius:50%;border:2px solid '+(stepDone?'var(--accent3)':'var(--border)')+';display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;font-size:10px;background:'+(stepDone?'var(--accent3)':'transparent')+';color:'+(stepDone?'#fff':'transparent')+';transition:.15s"><i class="fa-solid fa-check"></i></div>'
            +'<div style="flex:1;'+(stepDone?'text-decoration:line-through;color:var(--text3)':'color:var(--text)')+'">'+escapeHtml(s.text||s.title||'خطوة')+'</div>'
            +(s.deadline?'<div style="font-size:10px;font-family:var(--mono);color:'+(stepLate?'#f76f7c':'var(--text3)')+';white-space:nowrap">'+(stepLate?'<i class="fa-solid fa-triangle-exclamation" style="font-size:9px"></i> ':'')+_friendlyDate(s.deadline)+'</div>':'')
          +'</div>';
        }).join('')
      +'</td></tr>';
    }
    var row = '<tr class="tt-row" draggable="true" data-tid="'+t.id+'" '
      +'ondragstart="_ttDragStart(event,\''+t.id+'\')" '
      +'ondragover="_ttDragOver(event)" '
      +'ondrop="_ttDrop(event,\''+t.id+'\')" '
      +'ondragend="_ttDragEnd(event)" '
      +'style="background:'+rowBg+';transition:background .12s,box-shadow .12s;cursor:pointer" '
      +'onmouseover="this.style.background=\'var(--surface3)\'" '
      +'onmouseout="this.style.background=\''+rowBg+'\'" '
      +'onclick="openTaskDetail('+t.id+')">'
      // drag handle
      +'<td style="padding:10px 4px;border-bottom:1px solid var(--border);width:22px;text-align:center;color:var(--text3);cursor:grab" onclick="event.stopPropagation()" title="اسحب لإعادة الترتيب">'
        +'<i class="fa-solid fa-grip-vertical" style="font-size:10px"></i>'
      +'</td>'
      // checkbox
      +'<td style="padding:10px 6px;border-bottom:1px solid var(--border);width:28px" onclick="event.stopPropagation()">'
        +'<input type="checkbox" class="bulk-task-cb" data-tid="'+t.id+'" onchange="_bulkTasksUpdateCount()" style="width:15px;height:15px;cursor:pointer;accent-color:var(--accent)">'
      +'</td>'
      // title (always visible)
      +'<td style="padding:10px 14px;font-weight:700;border-bottom:1px solid var(--border);max-width:220px">'
        +'<div style="display:flex;align-items:center;gap:6px">'
          +(hasSteps?'<button onclick="event.stopPropagation();_toggleStepsRow('+t.id+')" style="background:none;border:none;cursor:pointer;color:var(--accent);font-size:12px;padding:2px 4px;flex-shrink:0;transition:transform .2s" id="steps-arrow-'+t.id+'"><i class="fa-solid fa-chevron-down"></i></button>':'<span style="width:22px"></span>')
          +'<div style="'+(isDone?'text-decoration:line-through;color:var(--text3)':'')+';white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+escapeHtml(t.title||'')+'</div>'
        +'</div>'
        +(hasSteps?'<div style="font-size:10px;color:var(--text3);margin-top:2px;margin-right:28px"><i class="fa-solid fa-list-check"></i> '+t.steps.filter(function(s){return s.done;}).length+'/'+t.steps.length+' خطوة</div>':'')
        +(projLink&&isDone?'<div style="font-size:9px;color:var(--accent3);margin-top:2px;margin-right:28px"><i class="fa-solid fa-link"></i> رابط التسليم</div>':'')
      +'</td>';
    // client
    if(colVisible.client!==false) row += '<td style="padding:10px 8px;text-align:center;border-bottom:1px solid var(--border);color:var(--text3);font-size:11px">'+(escapeHtml(t.client||'?'))+'</td>';
    // deadline
    if(colVisible.deadline!==false) row += '<td style="padding:10px 8px;text-align:center;border-bottom:1px solid var(--border);font-size:11px;font-family:var(--mono);color:'+(isLate?'#f76f7c':'var(--text3)')+'"><span title="'+(isLate?'متأخرة':'')+'">'+_friendlyDate(t.deadline||'?')+'</span></td>';
    // priority
    if(colVisible.priority!==false){
      var prioBadgeT = {high:'<span class="badge badge-red">عالية</span>',med:'<span class="badge badge-yellow">متوسطة</span>',low:'<span class="badge badge-green">منخفضة</span>'};
      row += '<td style="padding:10px 8px;text-align:center;border-bottom:1px solid var(--border)" class="hide-mobile">'+(prioBadgeT[t.priority]||'?')+'</td>';
    }
    // orderDate
    if(colVisible.orderDate) row += '<td style="padding:10px 8px;text-align:center;border-bottom:1px solid var(--border);color:var(--text3);font-size:11px;font-family:var(--mono)" class="hide-mobile">'+_friendlyDate(t.orderDate||'?')+'</td>';
    // pay
    if(colVisible.pay!==false) row += '<td style="padding:10px 8px;text-align:center;border-bottom:1px solid var(--border)">'
      +(t.value>0?'<div>'+(payBadgeTbl[t.pay||'none']||'')+'</div>':'<span style="color:var(--text3)">?</span>')
      +(t.pay==='deposit'&&t.deposit?'<div style="font-size:10px;color:#a78bfa">'+t.deposit.toLocaleString()+' ج</div>':'')
      +'</td>';
    // status
    if(colVisible.status!==false) row += '<td style="padding:10px 8px;text-align:center;border-bottom:1px solid var(--border)" onclick="event.stopPropagation()">'+stSelect(t)+'</td>';
    // value
    if(colVisible.value) row += '<td style="padding:10px 8px;text-align:center;border-bottom:1px solid var(--border)">'
      +(t.value>0?'<div style="font-weight:900;color:#f7c948;font-size:12px">'+t.value.toLocaleString()+' ج</div>':'<span style="color:var(--text3)">?</span>')
      +'</td>';
    // actions
    if(colVisible.actions!==false) row += '<td style="padding:10px 8px;text-align:center;border-bottom:1px solid var(--border)" onclick="event.stopPropagation()">'
      +'<div style="display:flex;gap:4px;justify-content:center">'
        +'<button data-tid="'+t.id+'" onclick="openTaskModal(this.dataset.tid)" class="btn btn-ghost btn-sm" style="padding:3px 7px;font-size:11px"><i class="fa-solid fa-pen"></i></button>'
        +'<button data-tid="'+t.id+'" onclick="delTask(this.dataset.tid)" class="btn btn-danger btn-sm" style="padding:3px 7px;font-size:11px"><i class="fa-solid fa-trash"></i></button>'
      +'</div></td>';
    row += '</tr>' + stepsHtml;
    return row;
  }

  var activeHTML = activeTbl.map(function(t,i){ return makeTableRow(t,i); }).join('');
  if(!activeHTML) activeHTML = '<tr><td colspan="'+totalCols+'" style="text-align:center;color:var(--text3);padding:24px;font-size:12px">لا توجد مهام نشطة</td></tr>';

  var doneSectionHTML = '';
  if(doneTbl.length){
    var collapsed = localStorage.getItem('_tt_done_collapsed')==='1';
    doneSectionHTML = '<tr class="tt-done-header" onclick="_ttToggleDone()" style="cursor:pointer">'
      +'<td colspan="'+totalCols+'" style="padding:9px 14px;background:rgba(79,209,165,.05);border-top:2px solid rgba(79,209,165,.2);border-bottom:1px solid var(--border)">'
        +'<div style="display:flex;align-items:center;gap:8px;font-size:12px;font-weight:800;color:var(--accent3)">'
          +'<i class="fa-solid fa-square-check"></i> مكتملة '
          +'<span style="background:rgba(79,209,165,.18);color:var(--accent3);padding:1px 9px;border-radius:20px;font-size:10px">'+doneTbl.length+'</span>'
          +'<i class="fa-solid fa-chevron-down" id="tt-done-arrow" style="margin-right:auto;font-size:10px;transition:transform .2s;'+(collapsed?'transform:rotate(-90deg)':'')+'"></i>'
        +'</div>'
      +'</td>'
    +'</tr>';
    if(!collapsed){
      doneSectionHTML += doneTbl.map(function(t,i){ return makeTableRow(t,i); }).join('');
    }
  }

  tbody.innerHTML = activeHTML + doneSectionHTML;
}

// Toggle مكتملة section في table view
function _ttToggleDone(){
  var cur = localStorage.getItem('_tt_done_collapsed')==='1';
  localStorage.setItem('_tt_done_collapsed', cur?'0':'1');
  _renderTasksTable();
}

// Drag-to-reorder في table view
var _ttDragId = null;
function _ttDragStart(e, tid){
  _ttDragId = tid;
  e.currentTarget.classList.add('tt-dragging');
  e.dataTransfer.effectAllowed = 'move';
}
function _ttDragEnd(e){
  e.currentTarget.classList.remove('tt-dragging');
  document.querySelectorAll('.tt-row').forEach(function(r){ r.style.boxShadow=''; });
}
function _ttDragOver(e){
  e.preventDefault();
  e.currentTarget.style.boxShadow = 'inset 0 -2px 0 var(--accent)';
}
function _ttDrop(e, targetId){
  e.preventDefault();
  document.querySelectorAll('.tt-row').forEach(function(r){ r.style.boxShadow=''; });
  if(!_ttDragId || String(_ttDragId)===String(targetId)) return;
  var fi = S.tasks.findIndex(function(t){ return String(t.id)===String(_ttDragId); });
  var ti = S.tasks.findIndex(function(t){ return String(t.id)===String(targetId); });
  if(fi<0||ti<0) return;
  var moved = S.tasks.splice(fi,1)[0];
  S.tasks.splice(ti,0,moved);
  lsSave(); cloudSave(S);
  _renderTasksTable();
  _ttDragId = null;
}

// Toggle steps sub-rows in table view
function _toggleStepsRow(taskId){
  var row = document.getElementById('steps-row-'+taskId);
  var arrow = document.getElementById('steps-arrow-'+taskId);
  if(!row) return;
  var isOpen = row.style.display !== 'none';
  row.style.display = isOpen ? 'none' : 'table-row';
  if(arrow) arrow.style.transform = isOpen ? '' : 'rotate(180deg)';
}

function _changeRegTaskStatusFromTable(taskId, newStatus){
  var t = S.tasks.find(function(x){ return String(x.id)===String(taskId); });
  if(!t) return;
  var prevDone = t.done||t.status==='done';
  if(newStatus==='done' && !prevDone){
    // Use completeTask flow which has income registration prompt
    completeTask(+taskId);
    return;
  }
  t.status = newStatus;
  if(newStatus==='done'){
    t.done = true;
    t.doneAt = t.doneAt||new Date().toISOString().split('T')[0];
  } else {
    t.done = false;
  }
  lsSave(); cloudSave(S);
  _renderTasksTable();
  showMiniNotif('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم تغيير الحالة');
}

// ============================================================
// BULK SELECTION ? Tasks
// ============================================================
function _bulkTasksUpdateCount(){
  var cbs = document.querySelectorAll('.bulk-task-cb:checked');
  var toolbar = document.getElementById('bulk-tasks-toolbar');
  var countEl = document.getElementById('bulk-tasks-count');
  if(countEl) countEl.textContent = cbs.length;
  if(toolbar) toolbar.style.display = cbs.length > 0 ? 'flex' : 'none';
  var selectAll = document.getElementById('bulk-tasks-selectall');
  var allCbs = document.querySelectorAll('.bulk-task-cb');
  if(selectAll && allCbs.length) selectAll.checked = cbs.length === allCbs.length;
}

function _bulkTasksToggleAll(checked){
  document.querySelectorAll('.bulk-task-cb').forEach(function(cb){ cb.checked = checked; });
  _bulkTasksUpdateCount();
}

function _bulkTasksClear(){
  document.querySelectorAll('.bulk-task-cb').forEach(function(cb){ cb.checked = false; });
  _bulkTasksUpdateCount();
  var selectAll = document.getElementById('bulk-tasks-selectall');
  if(selectAll) selectAll.checked = false;
}

function _getSelectedTaskIds(){
  var ids = [];
  document.querySelectorAll('.bulk-task-cb:checked').forEach(function(cb){ ids.push(String(cb.dataset.tid)); });
  return ids;
}

function _bulkTasksAction(action){
  var ids = _getSelectedTaskIds();
  if(!ids.length){ toast('<i class="fa-solid fa-triangle-exclamation"></i> حدد مهام أولاً'); return; }

  if(action === 'status'){
    var newStatus = document.getElementById('bulk-tasks-status').value;
    if(!newStatus){ toast('<i class="fa-solid fa-triangle-exclamation"></i> اختر حالة أولاً'); return; }
    ids.forEach(function(tid){
      var t = S.tasks.find(function(x){ return String(x.id)===tid; });
      if(t){
        t.status = newStatus;
        if(newStatus==='done'){ t.done=true; t.doneAt=t.doneAt||new Date().toISOString().split('T')[0]; }
        else { t.done=false; }
      }
    });
    lsSave(); _bulkTasksClear(); _renderTasksTable(); renderTasks();
    showMiniNotif('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم تغيير حالة '+ids.length+' مهمة');
  }
  else if(action === 'archive'){
    confirmDel('أرشفة '+ids.length+' مهمة؟', function(){
      ids.forEach(function(tid){
        var t = S.tasks.find(function(x){ return String(x.id)===tid; });
        if(t){ t.archived = true; t.status = 'done'; t.done = true; }
      });
      lsSave(); _bulkTasksClear(); _renderTasksTable(); renderTasks();
      showMiniNotif('<i class="fa-solid fa-box-archive"></i> تم أرشفة '+ids.length+' مهمة');
    });
  }
  else if(action === 'delete'){
    confirmDel('حذف '+ids.length+' مهمة نهائياً؟', function(){
      S.tasks = S.tasks.filter(function(t){ return !ids.includes(String(t.id)); });
      lsSave(); _bulkTasksClear(); _renderTasksTable(); renderTasks();
      showMiniNotif('<i class="fa-solid fa-trash"></i> تم حذف '+ids.length+' مهمة');
    });
  }
}

// ============================================================
// BULK SELECTION ? Reviews
// ============================================================
function _bulkReviewsUpdateCount(){
  var cbs = document.querySelectorAll('.bulk-review-cb:checked');
  var toolbar = document.getElementById('bulk-reviews-toolbar');
  var countEl = document.getElementById('bulk-reviews-count');
  if(countEl) countEl.textContent = cbs.length;
  if(toolbar) toolbar.style.display = cbs.length > 0 ? 'flex' : 'none';
}

function _bulkReviewsToggleAll(checked){
  document.querySelectorAll('.bulk-review-cb').forEach(function(cb){ cb.checked = checked; });
  _bulkReviewsUpdateCount();
}

function _bulkReviewsClear(){
  document.querySelectorAll('.bulk-review-cb').forEach(function(cb){ cb.checked = false; });
  _bulkReviewsUpdateCount();
}

function _bulkReviewsAction(action){
  var ids = [];
  document.querySelectorAll('.bulk-review-cb:checked').forEach(function(cb){ ids.push(String(cb.dataset.rid)); });
  if(!ids.length){ toast('<i class="fa-solid fa-triangle-exclamation"></i> حدد تقييمات أولاً'); return; }

  if(action === 'delete'){
    confirmDel('حذف '+ids.length+' تقييم نهائياً؟', function(){
      S.reviews = (S.reviews||[]).filter(function(r){ return !ids.includes(String(r.id)); });
      lsSave(); cloudSave(S); renderReviewsPage();
      showMiniNotif('<i class="fa-solid fa-trash"></i> تم حذف '+ids.length+' تقييم');
    });
  }
  else if(action === 'markread'){
    var total = (S.reviews||[]).length;
    localStorage.setItem('_reviewsReadCount', String(total));
    _bulkReviewsClear(); renderReviewsPage();
    showMiniNotif('<i class="fa-solid fa-envelope-open"></i> تم تعليم الكل كمقروء');
  }
}

// ============================================================
// WORKER PAY MODE (% or fixed amount)
// ============================================================
let workerPayMode = 'pct'; // 'pct' or 'fixed'
function setWorkerPayMode(mode){
  workerPayMode = mode;
  const pctBtn   = document.getElementById('worker-pay-pct-btn');
  const fixedBtn = document.getElementById('worker-pay-fixed-btn');
  const pctInput = document.getElementById('t-worker-pct');
  const fixInput = document.getElementById('t-worker-amount');
  const pctSym   = document.getElementById('t-worker-pct-sym');
  if(mode==='pct'){
    if(pctBtn)  { pctBtn.style.background='var(--accent)';   pctBtn.style.color='#fff'; }
    if(fixedBtn){ fixedBtn.style.background='transparent';   fixedBtn.style.color='var(--text3)'; }
    if(pctInput) pctInput.style.display='block';
    if(fixInput) fixInput.style.display='none';
    if(pctSym)   pctSym.style.display='inline';
  } else {
    if(pctBtn)  { pctBtn.style.background='transparent';    pctBtn.style.color='var(--text3)'; }
    if(fixedBtn){ fixedBtn.style.background='var(--accent)';fixedBtn.style.color='#fff'; }
    if(pctInput) pctInput.style.display='none';
    if(fixInput) fixInput.style.display='block';
    if(pctSym)   pctSym.style.display='none';
  }
  calcTaskProfit();
}

// ============================================================
// MONTHLY FINANCE TIMELINE
// ============================================================
function renderMonthlyTimeline(){
  const el = document.getElementById('monthly-timeline'); if(!el) return;
  const yearSel = document.getElementById('fin-year-timeline');
  // Populate years
  const years = [...new Set(S.transactions.map(t=>t.isoDate?t.isoDate.slice(0,4):null).filter(Boolean))];
  const thisYear = new Date().getFullYear().toString();
  if(!years.includes(thisYear)) years.push(thisYear);
  years.sort((a,b)=>b-a);
  if(yearSel){
    const cur = yearSel.value;
    yearSel.innerHTML = years.map(y=>`<option value="${y}">${y}</option>`).join('');
    yearSel.value = cur && years.includes(cur) ? cur : thisYear;
  }
  const selYear = yearSel ? yearSel.value : thisYear;
  const mNames = ['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
  const now = new Date();
  const rows = mNames.map((mName,i)=>{
    const mNum = String(i+1).padStart(2,'0');
    const prefix = `${selYear}-${mNum}`;
    const mTrans = S.transactions.filter(t=>(t.isoDate||'').startsWith(prefix));
    const inc = mTrans.filter(t=>t.type==='income').reduce((s,t)=>s+t.amount,0);
    const exp = mTrans.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0);
    const net = inc-exp;
    const isCurrent = +selYear===now.getFullYear() && i===now.getMonth();
    const isFuture = +selYear>now.getFullYear() || (+selYear===now.getFullYear() && i>now.getMonth());
    if(isFuture && !mTrans.length) return '';
    return `<div onclick="jumpToMonth('${String(i+1)}','${selYear}')" style="display:flex;align-items:center;gap:10px;padding:8px 12px;border-radius:8px;cursor:pointer;transition:.15s;${isCurrent?'background:rgba(124,111,247,.1);border:1px solid rgba(124,111,247,.3)':'border:1px solid transparent'};margin-bottom:4px" class="task-clickable">
      <div style="font-size:12px;font-weight:700;color:${isCurrent?'var(--accent)':'var(--text2)'};width:60px">${mName}${isCurrent?' â—€':''}</div>
      <div style="flex:1;height:6px;background:var(--surface3);border-radius:4px;overflow:hidden;position:relative">
        ${inc?`<div style="position:absolute;right:0;top:0;height:100%;width:${Math.min(100,Math.round(inc/(Math.max(inc,exp)||1)*100))}%;background:var(--accent3);border-radius:4px;opacity:.7"></div>`:''}
        ${exp?`<div style="position:absolute;right:0;top:0;height:100%;width:${Math.min(100,Math.round(exp/(Math.max(inc,exp)||1)*100))}%;background:var(--accent4);border-radius:4px;opacity:.5"></div>`:''}
      </div>
      <div style="font-size:11px;color:var(--accent3);width:70px;text-align:left;font-weight:700">+${inc.toLocaleString()}</div>
      <div style="font-size:11px;color:var(--accent4);width:70px;text-align:left">-${exp.toLocaleString()}</div>
      <div style="font-size:11px;font-weight:800;width:70px;text-align:left;color:${net>=0?'var(--accent3)':'var(--accent4)'}">${net>=0?'+':''}${net.toLocaleString()} ج</div>
    </div>`;
  }).filter(Boolean).join('');
  el.innerHTML = rows || `<div style="font-size:12px;color:var(--text3);padding:8px">لا معاملات في ${selYear}</div>`;
}

function jumpToMonth(month, year){
  const ms = document.getElementById('fin-filter-month');
  const ys = document.getElementById('fin-filter-year');
  if(ms) ms.value = month;
  if(ys) ys.value = year;
  finFilterState.month = month;
  finFilterState.year  = year;
  renderFinance();
}

// ============================================================
// MEMBER PROFILE VIEW
// ============================================================
function openMemberProfile(memberName){
  document.getElementById('teams-grid-view').style.display='none';
  document.getElementById('member-profile-view').style.display='block';
  document.getElementById('member-profile-title').innerHTML='<i class="fa-solid fa-user"></i> '+memberName;

  // Tasks assigned to this member
  const allTasks = S.tasks.filter(t=>t.workerMember===memberName);
  const activeTasks = allTasks.filter(t=>!t.done);
  const doneTasks   = allTasks.filter(t=>t.done);

  // Financial summary
  const totalOwed  = allTasks.reduce((s,t)=>s+(t.workerAmount||0),0);
  const totalDeposits = allTasks.filter(t=>t.workerDepositPaid).reduce((s,t)=>s+(t.workerDepositAmount||0),0);
  const pendingPay = totalOwed - totalDeposits;

  const set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v;};
  set('mp-tasks-count', activeTasks.length);
  set('mp-done-count',  doneTasks.length);
  set('mp-total-paid', totalDeposits.toLocaleString()+' '+_getCurrency());
  set('mp-pending-pay', pendingPay.toLocaleString()+' '+_getCurrency());
  // Store data for manual statement generation
  window._mpCurrentMember = memberName;
  window._mpAllTasks = allTasks;
  window._mpTotalOwed = totalOwed;
  window._mpTotalDeposits = totalDeposits;
  window._mpPendingPay = pendingPay;
  const stmtTable = document.getElementById('mp-statement-table');
  if(stmtTable){
    if(!allTasks.length){
      stmtTable.innerHTML='<div style="text-align:center;color:var(--text3);padding:16px">لا توجد مهام مسجلة لهذا العضو</div>';
    } else {
      stmtTable.innerHTML='<table style="width:100%;border-collapse:collapse">'+
        '<thead><tr style="background:var(--surface2)">'+
        '<th style="padding:8px 10px;text-align:right;font-size:11px;font-weight:700;color:var(--text3)">المهمة</th>'+
        '<th style="padding:8px 10px;text-align:right;font-size:11px;font-weight:700;color:var(--text3)">الحالة</th>'+
        '<th style="padding:8px 10px;text-align:right;font-size:11px;font-weight:700;color:var(--text3)">المستحق</th>'+
        '<th style="padding:8px 10px;text-align:right;font-size:11px;font-weight:700;color:var(--text3)">المدفوع</th>'+
        '<th style="padding:8px 10px;text-align:right;font-size:11px;font-weight:700;color:var(--text3)">المتبقي</th>'+
        '</tr></thead><tbody>'+
        allTasks.map(function(t){
          var stM={new:'جديد',progress:'قيد التنفيذ',review:'مراجعة',done:'<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> مكتمل'};
          var st=t.done?'<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> مكتمل':(stM[t.status]||t.status);
          var owed=t.workerAmount||0;
          var paid=t.workerDepositPaid?(t.workerDepositAmount||0):0;
          var bal=owed-paid;
          return '<tr style="border-bottom:1px solid var(--border)">'+
            '<td style="padding:8px 10px;font-size:12px;font-weight:600">'+t.title+'</td>'+
            '<td style="padding:8px 10px;font-size:11px">'+st+'</td>'+
            '<td style="padding:8px 10px;font-size:12px;color:var(--accent2);font-weight:700">'+owed.toLocaleString()+' ج</td>'+
            '<td style="padding:8px 10px;font-size:12px;color:var(--accent3);font-weight:700">'+paid.toLocaleString()+' ج</td>'+
            '<td style="padding:8px 10px;font-size:12px;font-weight:700;color:'+(bal>0?'var(--accent4)':'var(--accent3)')+'">'+bal.toLocaleString()+' ج</td>'+
            '</tr>';
        }).join('')+
        '</tbody>'+
        '<tfoot><tr style="background:var(--surface2)">'+
        '<td colspan="2" style="padding:8px 10px;font-size:12px;font-weight:800">الإجمالي</td>'+
        '<td style="padding:8px 10px;font-size:12px;color:var(--accent2);font-weight:800">'+totalOwed.toLocaleString()+' ج</td>'+
        '<td style="padding:8px 10px;font-size:12px;color:var(--accent3);font-weight:800">'+totalDeposits.toLocaleString()+' ج</td>'+
        '<td style="padding:8px 10px;font-size:12px;font-weight:800;color:'+(pendingPay>0?'var(--accent4)':'var(--accent3)')+'">'+pendingPay.toLocaleString()+' ج</td>'+
        '</tr></tfoot></table>';
    }
  }

  // Active tasks list
  const el1 = document.getElementById('mp-tasks-list');
  if(el1) el1.innerHTML = activeTasks.length ? activeTasks.map(t=>{
    const stMap={new:'<i class="fa-solid fa-clipboard-list"></i> جديد',progress:'<i class="fa-solid fa-bolt"></i> جاري',review:'<i class="fa-solid fa-magnifying-glass"></i> مراجعة',paused:'âڈ¸ موقوف',done:'<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> مكتمل'};
    const stepsTotal=t.steps?t.steps.length:0;
    const stepsDone=t.steps?t.steps.filter(s=>s.done).length:0;
    const pct=stepsTotal?Math.round(stepsDone/stepsTotal*100):0;
    return `<div onclick="openTaskDetail(${t.id})" class="task-clickable" style="padding:10px;background:var(--surface2);border:1px solid var(--border);border-radius:8px;margin-bottom:8px;cursor:pointer">
      <div style="font-size:13px;font-weight:700;margin-bottom:4px">${t.title}</div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;font-size:11px;color:var(--text3)">
        <span>${t.client||'?'}</span>
        <span style="color:var(--accent2)">${stMap[t.status||'new']}</span>
        ${t.workerAmount?`<span style="color:var(--accent4);font-weight:700">مستحق: ${t.workerAmount.toLocaleString()} ج</span>`:''}
      </div>
      ${stepsTotal?`<div style="margin-top:6px;display:flex;align-items:center;gap:6px">
        <div style="flex:1;height:4px;background:var(--surface3);border-radius:2px"><div style="height:100%;width:${pct}%;background:var(--accent);border-radius:2px"></div></div>
        <span style="font-size:10px;color:var(--text3)">${pct}%</span></div>`:''}
    </div>`;
  }).join('') : '<div class="empty" style="padding:16px 0;font-size:12px">لا مهام نشطة</div>';

  // Payments list
  const el2 = document.getElementById('mp-payments-list');
  if(el2) el2.innerHTML = allTasks.filter(t=>t.workerAmount>0).length ? allTasks.filter(t=>t.workerAmount>0).map(t=>`
    <div style="display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid var(--border)">
      <div>
        <div style="font-size:12px;font-weight:700">${t.title}</div>
        <div style="font-size:11px;color:var(--text3)">${t.done?'مكتمل':'جاري'}</div>
      </div>
      <div style="text-align:left">
        <div style="font-size:13px;font-weight:800;color:var(--accent4)">${(t.workerAmount||0).toLocaleString()} ج</div>
        ${t.workerDepositPaid?`<div style="font-size:10px;color:var(--accent3)">عربون: ${(t.workerDepositAmount||0).toLocaleString()} ج <i class="fa-solid fa-check"></i></div>`:'<div style="font-size:10px;color:var(--accent2)">لم يُدفع عربون</div>'}
      </div>
    </div>`).join('') : '<div class="empty" style="padding:16px 0;font-size:12px">لا مدفوعات مسجلة</div>';

  // Done tasks
  const el3 = document.getElementById('mp-done-list');
  if(el3) el3.innerHTML = doneTasks.length ? doneTasks.map(t=>`
    <div onclick="openTaskDetail(${t.id})" class="task-clickable" style="padding:9px;background:var(--surface2);border:1px solid rgba(79,209,165,.2);border-radius:8px;margin-bottom:7px;cursor:pointer;display:flex;justify-content:space-between;align-items:center">
      <div>
        <div style="font-size:12px;font-weight:700;color:var(--text2);text-decoration:line-through">${t.title}</div>
        <div style="font-size:11px;color:var(--text3)">${t.client||'?'}</div>
      </div>
      ${t.workerAmount?`<span style="font-size:12px;font-weight:700;color:var(--accent3)">${t.workerAmount.toLocaleString()} ج</span>`:''}
    </div>`).join('') : '<div class="empty" style="padding:16px 0;font-size:12px">لا مهام مكتملة</div>';
}

