// â”€â”€ Convert Order to Task â”€â”€
function openOrderToTask(orderId){
  const order=(S.svc_orders||[]).find(o=>String(o.id)===String(orderId)); if(!order) return;
  document.getElementById('ott-order-id').value=orderId;
  document.getElementById('ott-title').value=order.service_name+(order.pkg_name?' ? '+order.pkg_name:'');
  document.getElementById('ott-client').value=order.client_name||'';
  document.getElementById('ott-amount').value=order.price||'';
  document.getElementById('ott-notes').value=order.desc||'';
  document.getElementById('ott-deadline').value='';
  document.getElementById('ott-status').value='جديد';
  const sum=document.getElementById('ott-order-summary');
  if(sum) sum.innerHTML=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">
    <div><div style="font-size:10px;color:var(--text3)">العميل</div><div style="font-weight:800">${escapeHtml(order.client_name)}</div></div>
    <div><div style="font-size:10px;color:var(--text3)">الخدمة</div><div style="font-weight:700">${escapeHtml(order.service_name)}</div></div>
    ${order.price?`<div><div style="font-size:10px;color:var(--text3)">القيمة</div><div style="font-weight:800;color:var(--accent)">${Number(order.price).toLocaleString()} ج</div></div>`:''}
  </div>`;
  openM('modal-order-to-task');
}
function confirmOrderToTask(){
  const orderId=document.getElementById('ott-order-id')?.value;
  const title=document.getElementById('ott-title')?.value?.trim(); if(!title){ alert('أدخل عنوان المهمة'); return; }
  const client=document.getElementById('ott-client')?.value||'';
  const amount=document.getElementById('ott-amount')?.value||'';
  const deadline=document.getElementById('ott-deadline')?.value||'';
  const notes=document.getElementById('ott-notes')?.value||'';
  const status=document.getElementById('ott-status')?.value||'جديد';
  const order=(S.svc_orders||[]).find(o=>String(o.id)===String(orderId));
  const newTask={
    id:Date.now(), title, client, status,
    amount:+amount||0, deadline, notes,
    type:'مشروع', created_at:new Date().toISOString(),
    steps:[], done:false,
    source_order_id:orderId
  };
  if(!S.tasks) S.tasks=[];
  S.tasks.unshift(newTask);
  // mark order as accepted + linked
  if(order){ order.status='accepted'; order.linked_task_id=newTask.id; }
  lsSave();
  closeM('modal-order-to-task');
  closeM('modal-oa');
  showMiniNotif('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم إنشاء المهمة: '+title);
  setTimeout(()=>{ showPage('tasks'); },400);
}

function renderMeetings(){
  const list=document.getElementById('meetings-list'); if(!list) return;
  // Fill client filter
  const cf=document.getElementById('mtg-filter-client');
  if(cf){ const cur=cf.value; cf.innerHTML='<option value="">كل العملاء</option>'; S.clients.forEach(c=>{const o=document.createElement('option');o.value=c.name;o.textContent=c.name;cf.appendChild(o);}); cf.value=cur; }
  const sf=document.getElementById('mtg-filter-status')?.value||'';
  const cff=document.getElementById('mtg-filter-client')?.value||'';
  let mtgs=[...S.meetings].sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));
  if(cff) mtgs=mtgs.filter(m=>m.client===cff);
  if(sf==='upcoming') mtgs=mtgs.filter(m=>!m.done);
  if(sf==='done') mtgs=mtgs.filter(m=>m.done);
  const typeIcon={online:'<i class="fa-solid fa-video"></i>',offline:'<i class="fa-solid fa-location-dot"></i>',phone:'<i class="fa-solid fa-phone"></i>',whatsapp:'<i class="fa-brands fa-whatsapp"></i>'};
  const typeLabel={online:'أونلاين',offline:'حضوري',phone:'مكالمة',whatsapp:'واتساب'};
  const typeBg={online:'rgba(124,111,247,.12)',offline:'rgba(79,209,165,.12)',phone:'rgba(247,201,72,.12)',whatsapp:'rgba(37,211,102,.12)'};
  const typeColor={online:'var(--accent)',offline:'var(--accent3)',phone:'var(--accent2)',whatsapp:'#25D366'};

  // Stats
  const totalMtgs = S.meetings.length;
  const upcomingCount = S.meetings.filter(m=>!m.done).length;
  const doneCount = S.meetings.filter(m=>m.done).length;
  const thisWeek = S.meetings.filter(m=>{
    if(!m.date) return false;
    const d=new Date(m.date);const now=new Date();
    const diff=(d-now)/(1000*60*60*24);
    return diff>=-1&&diff<=7&&!m.done;
  }).length;

  if(!mtgs.length){
    list.innerHTML=`
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin-bottom:20px">
      <div class="card" style="padding:16px;text-align:center"><div style="font-size:28px;font-weight:900;color:var(--accent)">${totalMtgs}</div><div style="font-size:11px;color:var(--text3)">إجمالي</div></div>
      <div class="card" style="padding:16px;text-align:center"><div style="font-size:28px;font-weight:900;color:var(--accent2)">${upcomingCount}</div><div style="font-size:11px;color:var(--text3)">قادمة</div></div>
      <div class="card" style="padding:16px;text-align:center"><div style="font-size:28px;font-weight:900;color:var(--accent3)">${doneCount}</div><div style="font-size:11px;color:var(--text3)">مكتملة</div></div>
    </div>
    <div class="card" style="text-align:center;padding:60px 20px">
      <div style="font-size:48px;opacity:.2;margin-bottom:12px"><i class="fa-solid fa-calendar-days"></i></div>
      <div style="font-size:16px;font-weight:800;color:var(--text2);margin-bottom:6px">لا اجتماعات مطابقة</div>
      <div style="font-size:12px;color:var(--text3)">اضغط "ميتنج جديد" لإضافة اجتماع</div>
    </div>`;
    return;
  }

  // Group by upcoming vs done
  const upcoming = mtgs.filter(m=>!m.done);
  const done = mtgs.filter(m=>m.done);

  function meetingCard(m){
    const tp = m.type||'online';
    const monthNames = ['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
    const day = m.date?m.date.slice(8):'?';
    const mon = m.date?monthNames[+m.date.slice(5,7)-1]||'':'';
    const isToday = m.date === new Date().toISOString().split('T')[0];
    const isPast = m.date && new Date(m.date)<new Date() && !m.done;

    return `<div class="card" style="padding:0;overflow:hidden;border-right:3px solid ${m.done?'var(--accent3)':isToday?'var(--accent2)':isPast?'var(--accent4)':'var(--accent)'};transition:transform .15s,box-shadow .15s;cursor:pointer" onclick="openMeetingDetail(${m.id})" onmouseover="this.style.transform='translateY(-2px)';this.style.boxShadow='0 6px 24px rgba(0,0,0,.08)'" onmouseout="this.style.transform='';this.style.boxShadow=''">
      <div style="display:flex;gap:0">
        <!-- Date column -->
        <div style="width:72px;flex-shrink:0;padding:16px 8px;display:flex;flex-direction:column;align-items:center;justify-content:center;background:${m.done?'var(--surface2)':isToday?'rgba(247,201,72,.1)':'var(--surface2)'}">
          <div style="font-size:24px;font-weight:900;color:${m.done?'var(--text3)':isToday?'var(--accent2)':'var(--accent)'};line-height:1">${day}</div>
          <div style="font-size:10px;color:var(--text3);margin-top:2px">${mon}</div>
          ${isToday?'<div style="font-size:8px;font-weight:800;color:var(--accent2);background:rgba(247,201,72,.2);padding:1px 6px;border-radius:8px;margin-top:4px">اليوم</div>':''}
          ${isPast&&!m.done?'<div style="font-size:8px;font-weight:800;color:var(--accent4);background:rgba(247,111,124,.15);padding:1px 6px;border-radius:8px;margin-top:4px">فات</div>':''}
        </div>
        <!-- Content -->
        <div style="flex:1;padding:14px 16px;min-width:0">
          <div style="display:flex;align-items:start;justify-content:space-between;gap:8px;margin-bottom:8px">
            <div style="flex:1;min-width:0">
              <div style="font-size:14px;font-weight:800;${m.done?'text-decoration:line-through;color:var(--text3)':''};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escapeHtml(m.title)}</div>
              <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:5px;align-items:center">
                <span style="font-size:10px;padding:3px 8px;border-radius:8px;background:${typeBg[tp]||typeBg.online};color:${typeColor[tp]||typeColor.online};font-weight:700;display:inline-flex;align-items:center;gap:4px">${typeIcon[tp]||typeIcon.online} ${typeLabel[tp]||tp}</span>
                ${m.time?`<span style="font-size:11px;color:var(--text3);display:flex;align-items:center;gap:3px"><i class="fa-solid fa-clock" style="font-size:9px"></i> ${m.time}</span>`:''}
                ${m.duration?`<span style="font-size:11px;color:var(--text3)">(${m.duration} د)</span>`:''}
              </div>
            </div>
            <div style="display:flex;gap:4px;flex-shrink:0" onclick="event.stopPropagation()">
              <button onclick="toggleMeetingDone(${m.id})" class="btn btn-ghost btn-sm" style="padding:5px 8px" title="${m.done?'إعادة':'مكتمل'}">${m.done?'<i class="fa-solid fa-rotate-left"></i>':'<i class="fa-solid fa-check"></i>'}</button>
              <button onclick="openMeetingModal(${m.id})" class="btn btn-ghost btn-sm" style="padding:5px 8px"><i class="fa-solid fa-pen"></i></button>
              <button onclick="delMeeting(${m.id})" class="btn btn-danger btn-sm" style="padding:5px 8px"><i class="fa-solid fa-trash"></i></button>
            </div>
          </div>
          ${m.client?`<div style="font-size:11px;color:var(--accent);display:flex;align-items:center;gap:4px;margin-bottom:4px"><i class="fa-solid fa-user" style="font-size:9px"></i> ${escapeHtml(m.client)}</div>`:''}
          ${m.brief?`<div style="font-size:11px;color:var(--text2);line-height:1.6;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical">${m.brief.replace(/<[^>]*>/g,'')}</div>`:''}
          ${m.link?`<a href="${escapeHtml(m.link)}" target="_blank" onclick="event.stopPropagation()" style="display:inline-flex;align-items:center;gap:5px;margin-top:8px;font-size:11px;color:var(--accent);background:rgba(124,111,247,.08);padding:5px 12px;border-radius:8px;text-decoration:none;font-weight:700;border:1px solid rgba(124,111,247,.2);transition:.15s" onmouseover="this.style.background='rgba(124,111,247,.15)'" onmouseout="this.style.background='rgba(124,111,247,.08)'"><i class="fa-solid fa-link"></i> انضم للاجتماع</a>`:''}
        </div>
      </div>
    </div>`;
  }

  list.innerHTML = `
  <!-- Stats -->
  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin-bottom:20px">
    <div class="card" style="padding:16px;text-align:center"><div style="font-size:28px;font-weight:900;color:var(--accent)">${totalMtgs}</div><div style="font-size:11px;color:var(--text3)">إجمالي</div></div>
    <div class="card" style="padding:16px;text-align:center"><div style="font-size:28px;font-weight:900;color:var(--accent2)">${upcomingCount}</div><div style="font-size:11px;color:var(--text3)">قادمة</div></div>
    <div class="card" style="padding:16px;text-align:center"><div style="font-size:28px;font-weight:900;color:var(--accent4)">${thisWeek}</div><div style="font-size:11px;color:var(--text3)">هذا الأسبوع</div></div>
    <div class="card" style="padding:16px;text-align:center"><div style="font-size:28px;font-weight:900;color:var(--accent3)">${doneCount}</div><div style="font-size:11px;color:var(--text3)">مكتملة</div></div>
  </div>
  <!-- Upcoming -->
  ${upcoming.length?`
  <div style="display:flex;align-items:center;gap:10px;margin-bottom:12px">
    <div style="font-size:14px;font-weight:900;color:var(--accent)"><i class="fa-solid fa-calendar-day"></i> القادمة</div>
    <div style="flex:1;height:1px;background:var(--border)"></div>
    <span style="font-size:11px;background:rgba(124,111,247,.12);color:var(--accent);padding:3px 10px;border-radius:20px;font-weight:700">${upcoming.length}</span>
  </div>
  <div style="display:flex;flex-direction:column;gap:10px;margin-bottom:24px">
    ${upcoming.map(meetingCard).join('')}
  </div>`:''}
  <!-- Done -->
  ${done.length?`
  <div style="display:flex;align-items:center;gap:10px;margin-bottom:12px">
    <div style="font-size:14px;font-weight:900;color:var(--text3)"><i class="fa-solid fa-check-double"></i> المكتملة</div>
    <div style="flex:1;height:1px;background:var(--border)"></div>
    <span style="font-size:11px;background:var(--surface2);color:var(--text3);padding:3px 10px;border-radius:20px;font-weight:700">${done.length}</span>
  </div>
  <div style="display:flex;flex-direction:column;gap:10px">
    ${done.map(meetingCard).join('')}
  </div>`:''}`;

  // Update badge
  const badge=document.getElementById('meetings-badge');
  if(badge){ badge.textContent=upcomingCount; badge.style.display=upcomingCount?'inline-flex':'none'; }
}
function openMeetingDetail(id){
  const m=S.meetings.find(x=>x.id===id); if(!m) return;
  const card=document.getElementById('meeting-detail-card');
  const body=document.getElementById('meeting-detail-body');
  if(!card||!body) return;
  card.style.display='block';
  const typeLabel={online:'<i class="fa-solid fa-desktop"></i> أونلاين',offline:'<i class="fa-solid fa-location-dot"></i> حضوري',phone:'<i class="fa-solid fa-phone"></i> مكالمة',whatsapp:'<i class="fa-solid fa-comments"></i> واتساب'};
  body.innerHTML=`
    <div style="display:flex;justify-content:space-between;align-items:start;margin-bottom:14px">
      <div><div style="font-size:15px;font-weight:800">${m.title}</div>
        <div style="font-size:12px;color:var(--text3);margin-top:3px">${typeLabel[m.type]||''} آ· ${m.date||''} ${m.time?'<i class="fa-solid fa-alarm-clock"></i> '+m.time:''}</div>
        ${m.client?`<div style="font-size:12px;color:var(--accent);margin-top:2px"><i class="fa-solid fa-user"></i> ${m.client}</div>`:''}
      </div>
      <button onclick="openMeetingModal(${m.id})" class="btn btn-ghost btn-sm"><i class="fa-solid fa-pen"></i> تعديل</button>
    </div>
    ${m.link?`<a href="${m.link}" target="_blank" class="btn btn-primary btn-sm" style="display:inline-flex;align-items:center;gap:6px;text-decoration:none;margin-bottom:12px"><i class="fa-solid fa-link"></i> انضم للاجتماع</a>`:''}
    ${m.brief?`<div style="margin-bottom:14px"><div style="font-size:11px;font-weight:700;color:var(--text3);margin-bottom:6px;text-transform:uppercase">الأجندة</div><div style="background:var(--surface3);border-radius:8px;padding:10px 12px;font-size:13px;line-height:1.7">${m.brief}</div></div>`:''}
    ${m.notes?`<div><div style="font-size:11px;font-weight:700;color:var(--text3);margin-bottom:6px;text-transform:uppercase">الملاحظات</div><div style="background:rgba(247,201,72,.06);border:1px solid rgba(247,201,72,.2);border-radius:8px;padding:10px 12px;font-size:13px;line-height:1.7">${m.notes}</div></div>`:''}`;
}

