// â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
// RECEIPT IMAGE HELPERS
// â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
window._invReceiptData = null;
window._incReceiptData = null;

function invReceiptPreview(inp){
  var file=inp.files[0]; if(!file) return;
  toast('<i class="fa-solid fa-spinner fa-spin"></i> جاري رفع الإيصال...');
  uploadToStorage(file,'receipts',function(url){
    window._invReceiptData=url;
    var img=document.getElementById('inv-receipt-img');
    var prev=document.getElementById('inv-receipt-prev');
    var ph=document.getElementById('inv-receipt-ph');
    if(img) img.src=url;
    if(prev) prev.style.display='block';
    if(ph) ph.style.display='none';
    toast('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم رفع الإيصال');
  },function(){
    // fallback base64 للإيصالات (صغيرة عادة)
    var r=new FileReader(); r.onload=function(e){ window._invReceiptData=e.target.result; var img=document.getElementById('inv-receipt-img'); var prev=document.getElementById('inv-receipt-prev'); var ph=document.getElementById('inv-receipt-ph'); if(img) img.src=e.target.result; if(prev) prev.style.display='block'; if(ph) ph.style.display='none'; }; r.readAsDataURL(file);
  });
}
function invReceiptClear(){
  window._invReceiptData=null;
  var img=document.getElementById('inv-receipt-img');
  var prev=document.getElementById('inv-receipt-prev');
  var ph=document.getElementById('inv-receipt-ph');
  var fi=document.getElementById('inv-receipt-file');
  if(img) img.src=''; if(prev) prev.style.display='none';
  if(ph) ph.style.display=''; if(fi) fi.value='';
}
function invReceiptDrop(e){
  e.preventDefault();
  var file=e.dataTransfer&&e.dataTransfer.files&&e.dataTransfer.files[0];
  if(!file||!file.type.startsWith('image/')) return;
  var inp=document.getElementById('inv-receipt-file');
  if(inp){ var dt=new DataTransfer(); dt.items.add(file); inp.files=dt.files; invReceiptPreview(inp); }
}
function incReceiptPreview(inp){
  var file=inp.files[0]; if(!file) return;
  toast('<i class="fa-solid fa-spinner fa-spin"></i> جاري رفع الإيصال...');
  uploadToStorage(file,'receipts',function(url){
    window._incReceiptData=url;
    var img=document.getElementById('in-receipt-img');
    var prev=document.getElementById('in-receipt-prev');
    var ph=document.getElementById('in-receipt-ph');
    if(img) img.src=url;
    if(prev) prev.style.display='block';
    if(ph) ph.style.display='none';
    toast('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم رفع الإيصال');
  },function(){
    var r=new FileReader(); r.onload=function(e){ window._incReceiptData=e.target.result; var img=document.getElementById('in-receipt-img'); var prev=document.getElementById('in-receipt-prev'); var ph=document.getElementById('in-receipt-ph'); if(img) img.src=e.target.result; if(prev) prev.style.display='block'; if(ph) ph.style.display='none'; }; r.readAsDataURL(file);
  });
}

// â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
// TEAM INVITE INBOX + MEMBER PROFILE ENHANCED
// â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ

// â”€â”€â”€ Inbox: show pending invites in a modal â”€â”€â”€
window.openTeamInviteInbox = function(){
  // Trigger immediate poll to get latest invites before opening
  if(typeof window._teamPollNow === 'function') window._teamPollNow();
  
  var invites = window._pendingTeamInvites || [];
  var memberships = window._myTeamMemberships || [];
  
  var ex = document.getElementById('_team-inbox-overlay');
  if(ex) ex.remove();
  
  var overlay = document.createElement('div');
  overlay.id = '_team-inbox-overlay';
  overlay.className = 'modal-overlay';
  overlay.style.display = 'flex';
  
  var pendingHtml = invites.length ? invites.map(function(inv,i){
    var roleMatch = inv.body && inv.body.match(/كـ (.+?) في فريق/);
    var roleText = roleMatch ? roleMatch[1] : (inv.memberRole||'عضو');
    var specsText = inv.extraSpecs && inv.extraSpecs.length ? ' آ· ' + inv.extraSpecs.join('، ') : '';
    return '<div style="background:var(--surface2);border:1.5px solid rgba(124,111,247,.25);border-radius:14px;padding:16px;margin-bottom:10px">'
      +'<div style="display:flex;align-items:center;gap:12px;margin-bottom:12px">'
        +'<div style="width:42px;height:42px;border-radius:12px;background:linear-gradient(135deg,var(--accent),var(--accent3));display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0"><i class="fa-solid fa-building"></i></div>'
        +'<div style="flex:1">'
          +'<div style="font-size:14px;font-weight:800">'+escapeHtml(inv.ownerName||'مشرف')+'</div>'
          +'<div style="font-size:12px;color:var(--text3)">دعوة للانضمام لـ <strong style="color:var(--accent)">'+escapeHtml(inv.teamName||'فريق')+'</strong></div>'
          +'<div style="font-size:11px;color:var(--text2);margin-top:3px">دورك: <strong>'+escapeHtml(roleText)+'</strong>'+escapeHtml(specsText)+'</div>'
        +'</div>'
      +'</div>'
      +'<div style="display:flex;gap:8px">'
        +'<button class="btn btn-ghost btn-sm" style="flex:1;justify-content:center" data-inv-idx="'+i+'" onclick="window._inboxRejectInvite(+this.dataset.invIdx)"><i class="fa-solid fa-xmark"></i> رفض</button>'
        +'<button class="btn btn-primary btn-sm" style="flex:2;justify-content:center" data-inv-idx="'+i+'" onclick="window._inboxAcceptInvite(+this.dataset.invIdx)"><i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> قبول الدعوة</button>'
      +'</div>'
    +'</div>';
  }).join('') : '<div style="text-align:center;padding:24px;color:var(--text3)"><div style="font-size:36px;margin-bottom:10px"><i class="fa-solid fa-envelope-open"></i></div><div style="font-size:13px">لا توجد دعوات معلقة</div></div>';

  var membersHtml = memberships.length ? '<div style="margin-top:8px">'
    +'<div style="font-size:11px;font-weight:700;color:var(--text3);margin-bottom:10px"><i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> الفرق التي أنا عضو فيها</div>'
    +memberships.map(function(m){
      var tc = m.tasks ? m.tasks.length : 0;
      return '<div style="display:flex;align-items:center;gap:10px;padding:10px 12px;background:rgba(79,209,165,.06);border:1px solid rgba(79,209,165,.2);border-radius:10px;margin-bottom:6px">'
        +'<span style="font-size:18px"><i class="fa-solid fa-building"></i></span>'
        +'<div style="flex:1"><div style="font-size:13px;font-weight:700;color:var(--accent3)">'+escapeHtml(m.ownerName)+'</div><div style="font-size:11px;color:var(--text3)">'+escapeHtml(m.teamName)+' آ· '+escapeHtml(m.role||'عضو')+'</div></div>'
        +(tc ? '<span style="font-size:10px;background:rgba(247,201,72,.2);color:var(--accent2);padding:2px 8px;border-radius:8px;font-weight:700">'+tc+' مهام</span>' : '<span style="font-size:10px;color:var(--accent3)"><i class="fa-solid fa-check"></i> محدث</span>')
      +'</div>';
    }).join('')
  +'</div>' : '';

  overlay.innerHTML = '<div class="modal" style="max-width:480px;max-height:88vh;overflow-y:auto">'
    +'<div class="modal-header" style="position:sticky;top:0;background:var(--surface);z-index:2">'
      +'<div class="modal-title"><i class="fa-solid fa-envelope-open-text"></i> صندوق الدعوات</div>'
      +'<button class="close-btn" id="_inbox-close-btn"><i class="fa-solid fa-xmark"></i></button>'
    +'</div>'
    +(invites.length ? '<div style="background:rgba(124,111,247,.07);border-radius:10px;padding:10px 14px;margin-bottom:14px;font-size:12px;color:var(--accent)"><i class="fa-solid fa-bell"></i> لديك <strong>'+invites.length+'</strong> دعوة جديدة تنتظر ردك</div>' : '')
    +pendingHtml
    +membersHtml
  +'</div>';
  
  document.body.appendChild(overlay);
  overlay.querySelector('#_inbox-close-btn').onclick = function(){ overlay.remove(); };
  overlay.onclick = function(e){ if(e.target===overlay) overlay.remove(); };
};

window._inboxAcceptInvite = function(idx){
  var invites = window._pendingTeamInvites || [];
  var inv = invites[idx]; if(!inv) return;
  invites.splice(idx, 1);
  window._pendingTeamInvites = invites;
  _updateInboxBadge();
  // PHASE 3 FIX: Save acceptance locally
  if(inv) {
    var localKey = '_accepted_team_invites_' + (_supaUserId||'');
    var localList = JSON.parse(localStorage.getItem(localKey) || '[]');
    var alreadySaved = localList.some(function(li){ return li.teamId===String(inv.teamId) && li.ownerId===inv.ownerId; });
    if(!alreadySaved) {
      localList.push({ teamId: String(inv.teamId||inv.id), ownerId: inv.ownerId||'', teamName: inv.teamName });
      localStorage.setItem(localKey, JSON.stringify(localList));
    }
    // Update team_invites table
    if(typeof supa !== 'undefined' && inv.id) {
      (async()=>{try{await supa.from('team_invites').update({status:'accepted'}).eq('id',String(inv.id).replace('pn_',''));}catch(e){}})();
    }
  }
  // Re-check membership
  var em = null;
  try{ var _s=JSON.parse(localStorage.getItem('studioOS_auth_v1')||'{}'); em=_s&&_s.email?_s.email:null; }catch(e){}
  if(em) window._checkTeamMembership(em);
  showMiniNotif('<i class="fa-solid fa-champagne-glasses"></i> انضممت لفريق "'+inv.teamName+'"!');
  var inbox = document.getElementById('_team-inbox-overlay');
  if(inbox) inbox.remove();
  setTimeout(function(){ renderTeams(); renderMyMemberTeams(); openTeamInviteInbox(); }, 600);
};

window._inboxRejectInvite = function(idx){
  var invites = window._pendingTeamInvites || [];
  var inv = invites[idx]; if(!inv) return;
  invites.splice(idx, 1);
  window._pendingTeamInvites = invites;
  _updateInboxBadge();
  showMiniNotif('تم رفض دعوة "'+inv.teamName+'"');
  var inbox = document.getElementById('_team-inbox-overlay');
  if(inbox) inbox.remove();
  setTimeout(openTeamInviteInbox, 200);
};

function _updateInboxBadge(){
  var invites = window._pendingTeamInvites || [];
  var badge = document.getElementById('team-invite-inbox-badge');
  if(!badge) return;
  if(invites.length){
    badge.textContent = invites.length;
    badge.style.display = 'flex';
  } else {
    badge.style.display = 'none';
  }
}

// â”€â”€â”€ Render member teams in team page â”€â”€â”€
function renderMyMemberTeams(){
  var section = document.getElementById('my-member-teams-section');
  var grid    = document.getElementById('my-member-teams-grid');
  var countEl = document.getElementById('my-member-teams-count');
  var memberships = window._myTeamMemberships || [];
  
  if(!section || !grid) return;
  
  if(!memberships.length){
    section.style.display = 'none';
    return;
  }
  
  section.style.display = '';
  if(countEl) countEl.textContent = memberships.length;
  
  grid.innerHTML = memberships.map(function(m){
    var tasks = m.tasks || [];
    var doneTasks = m.doneTasks || [];
    var lateTasks = tasks.filter(function(t){ return t.deadline && new Date(t.deadline) < new Date(); });
    var isCompany = m.isCompany || m.type==='company';

    // â”€â”€ بطاقة الشركة â”€â”€
    if(isCompany){
      var teamUrl = m.teamUrl || (function(){
        var base = window.location.href.replace(/[^/]*(\?.*)?$/,'');
        return base+'team.html?openTeam='+(m.teamId||'');
      })();
      return '<div class="card" style="cursor:pointer;border-color:rgba(247,201,72,.2);transition:border-color .15s,transform .15s;position:relative;overflow:hidden" onclick="window.open(\''+teamUrl+'\',\'_blank\')" onmouseenter="this.style.borderColor=\'var(--accent2)\';this.style.transform=\'translateY(-2px)\'" onmouseleave="this.style.borderColor=\'rgba(247,201,72,.2)\';this.style.transform=\'\'">'
        +'<div style="position:absolute;top:0;right:0;width:3px;height:100%;background:var(--accent2)"></div>'
        +'<div style="display:flex;align-items:center;gap:12px;margin-bottom:14px">'
          +'<div style="width:44px;height:44px;border-radius:12px;background:'+(m.teamColor||'var(--accent2)')+';display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0">'+(m.teamEmoji||'ًںڈ¢')+'</div>'
          +'<div style="flex:1;min-width:0">'
            +'<div style="font-size:15px;font-weight:800">'+escapeHtml(m.teamName)+'</div>'
            +'<span style="font-size:10px;background:rgba(247,201,72,.12);color:var(--accent2);padding:2px 8px;border-radius:10px;font-weight:800">ًںڈ¢ شركة آ· '+escapeHtml(m.role||'عضو')+'</span>'
          +'</div>'
        +'</div>'
        +'<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:12px">'
          +'<div style="background:var(--surface2);border-radius:10px;padding:10px;text-align:center">'
            +'<div style="font-size:20px;font-weight:900;color:var(--accent4)">'+tasks.length+'</div>'
            +'<div style="font-size:10px;color:var(--text3)">نشطة</div>'
          +'</div>'
          +'<div style="background:var(--surface2);border-radius:10px;padding:10px;text-align:center">'
            +'<div style="font-size:20px;font-weight:900;color:var(--accent3)">'+doneTasks.length+'</div>'
            +'<div style="font-size:10px;color:var(--text3)">مكتملة</div>'
          +'</div>'
          +'<div style="background:var(--surface2);border-radius:10px;padding:10px;text-align:center">'
            +'<div style="font-size:20px;font-weight:900;color:'+(lateTasks.length?'var(--accent4)':'var(--accent3)')+'">'+lateTasks.length+'</div>'
            +'<div style="font-size:10px;color:var(--text3)">متأخرة</div>'
          +'</div>'
        +'</div>'
        +'<div style="font-size:11px;color:var(--accent2);border-top:1px solid var(--border);padding-top:10px;display:flex;align-items:center;gap:6px">'
          +'<i class="fa-solid fa-table-columns"></i> اضغط لفتح بورد الشركة'
        +'</div>'
      +'</div>';
    }

    // â”€â”€ بطاقة الفريق العادي â”€â”€
    return '<div class="card" style="cursor:pointer;transition:border-color .15s,transform .15s" data-oid="'+m.ownerId+'" onclick="openMyMemberTeamProfile(this.dataset.oid)" onmouseenter="this.style.borderColor=\'var(--accent3)\';this.style.transform=\'translateY(-2px)\'" onmouseleave="this.style.borderColor=\'\';this.style.transform=\'\'">'
      +'<div style="display:flex;align-items:center;gap:12px;margin-bottom:14px">'
        +(m.ownerLogo ? '<img src="'+escapeHtml(m.ownerLogo)+'" style="width:44px;height:44px;border-radius:12px;object-fit:cover;flex-shrink:0" onerror=\'this.style.display="none"\'">'
          : '<div style="width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,var(--accent),var(--accent3));display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0"><i class="fa-solid fa-building"></i></div>')
        +'<div style="flex:1;min-width:0">'
          +'<div style="font-size:15px;font-weight:800;color:var(--accent3)">'+escapeHtml(m.ownerName)+'</div>'
          +'<div style="font-size:11px;color:var(--text3)">'+escapeHtml(m.teamName)+'</div>'
        +'</div>'
        +'<span style="font-size:10px;background:rgba(79,209,165,.12);color:var(--accent3);padding:3px 10px;border-radius:8px;font-weight:700">'+escapeHtml(m.role||'عضو')+'</span>'
      +'</div>'
      +'<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:12px">'
        +'<div style="background:var(--surface2);border-radius:10px;padding:10px;text-align:center">'
          +'<div style="font-size:20px;font-weight:900;color:var(--accent4)">'+tasks.length+'</div>'
          +'<div style="font-size:10px;color:var(--text3)">نشطة</div>'
        +'</div>'
        +'<div style="background:var(--surface2);border-radius:10px;padding:10px;text-align:center">'
          +'<div style="font-size:20px;font-weight:900;color:var(--accent3)">'+doneTasks.length+'</div>'
          +'<div style="font-size:10px;color:var(--text3)">مكتملة</div>'
        +'</div>'
        +'<div style="background:var(--surface2);border-radius:10px;padding:10px;text-align:center">'
          +'<div style="font-size:20px;font-weight:900;color:'+(lateTasks.length?'var(--accent4)':'var(--accent3)')+'">'+lateTasks.length+'</div>'
          +'<div style="font-size:10px;color:var(--text3)">متأخرة</div>'
        +'</div>'
      +'</div>'
      +(tasks.length ? '<div style="font-size:11px;color:var(--text3);border-top:1px solid var(--border);padding-top:10px">ًں‘† اضغط لعرض مهامك التفصيلية</div>' : '<div style="font-size:11px;color:var(--accent3);border-top:1px solid var(--border);padding-top:10px"><i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> لا مهام نشطة حاليًا</div>')
    +'</div>';
  }).join('');
}

// â”€â”€â”€ Full profile modal for "teams I'm a member of" â”€â”€â”€
window.openMyMemberTeamProfile = function(ownerId){
  var membership = (window._myTeamMemberships||[]).find(function(m){ return m.ownerId===ownerId; });
  if(!membership) return;

  var ex = document.getElementById('_member-team-modal');
  if(ex) ex.remove();

  var overlay = document.createElement('div');
  overlay.id = '_member-team-modal';
  overlay.className = 'modal-overlay';
  overlay.style.display = 'flex';

  function _buildModal(){
    var tasks = membership.tasks || [];
    var doneTasks = membership.doneTasks || [];

    // â”€â”€ Update task status in owner's studio_data â”€â”€
    window._memberUpdateTaskStatus = async function(taskId, newStatus){
      var isDone = (newStatus === 'done');
      // Update locally first
      var tIdx = membership.tasks.findIndex(function(t){ return String(t.id)===String(taskId); });
      var dIdx = membership.doneTasks.findIndex(function(t){ return String(t.id)===String(taskId); });
      var taskObj = tIdx > -1 ? membership.tasks[tIdx] : (dIdx > -1 ? membership.doneTasks[dIdx] : null);
      if(!taskObj) return;
      taskObj.status = newStatus;
      taskObj.done = isDone;
      if(isDone && tIdx > -1){ membership.tasks.splice(tIdx,1); membership.doneTasks.unshift(taskObj); }
      else if(!isDone && dIdx > -1){ membership.doneTasks.splice(dIdx,1); membership.tasks.push(taskObj); }
      overlay.querySelector('.modal').innerHTML = _renderModalBody();
      _bindModalEvents();
      // Update in owner's studio_data
      try {
        var { data: ownerRow } = await supa.from('studio_data').select('data').eq('user_id', ownerId).maybeSingle();
        if(!ownerRow) return;
        var od = typeof ownerRow.data==='string' ? JSON.parse(ownerRow.data) : ownerRow.data;
        if(od.data && !od.tasks) od = typeof od.data==='string' ? JSON.parse(od.data) : od.data;
        // Update in regular tasks
        var ot = (od.tasks||[]).find(function(t){ return String(t.id)===String(taskId); });
        if(ot){ ot.status=newStatus; ot.done=isDone; }
        // Also update in project_tasks (مهام المشاريع)
        var opt = (od.project_tasks||[]).find(function(t){ return String(t.id)===String(taskId); });
        if(opt){ opt.status=newStatus; if(isDone){ opt.done=true; } else { opt.done=false; } }
        await supa.from('studio_data').update({data:JSON.stringify(od),updated_at:new Date().toISOString()}).eq('user_id',ownerId);
        if(typeof showMiniNotif==='function') showMiniNotif('? تم تحديث حالة المهمة');
      } catch(e){ console.warn('task update err:', e); }
    };

    // â”€â”€ Update step done status â”€â”€
    window._memberToggleStep = async function(taskId, stepIdx, isDone){
      var task = (membership.tasks||[]).concat(membership.doneTasks||[]).find(function(t){ return String(t.id)===String(taskId); });
      if(!task || !task.steps || !task.steps[stepIdx]) return;
      task.steps[stepIdx].done = isDone;
      overlay.querySelector('.modal').innerHTML = _renderModalBody();
      _bindModalEvents();
      try {
        var { data: ownerRow } = await supa.from('studio_data').select('data').eq('user_id', ownerId).maybeSingle();
        if(!ownerRow) return;
        var od = typeof ownerRow.data==='string' ? JSON.parse(ownerRow.data) : ownerRow.data;
        if(od.data && !od.tasks) od = typeof od.data==='string' ? JSON.parse(od.data) : od.data;
        // Update steps in regular tasks
        var ot = (od.tasks||[]).find(function(t){ return String(t.id)===String(taskId); });
        if(ot && ot.steps && ot.steps[stepIdx]) ot.steps[stepIdx].done = isDone;
        // Also update steps in project_tasks
        var opt = (od.project_tasks||[]).find(function(t){ return String(t.id)===String(taskId); });
        if(opt && opt.steps && opt.steps[stepIdx]) opt.steps[stepIdx].done = isDone;
        await supa.from('studio_data').update({data:JSON.stringify(od),updated_at:new Date().toISOString()}).eq('user_id',ownerId);
      } catch(e){ console.warn('step update err:', e); }
    };

    // â”€â”€ Open full task detail overlay for member â”€â”€
    window._openMemberTaskDetail = function(taskId){
      var allTasks = (membership.tasks||[]).concat(membership.doneTasks||[]);
      var t = allTasks.find(function(x){ return String(x.id)===String(taskId); });
      if(!t) return;
      var ex = document.getElementById('_mtd-overlay');
      if(ex) ex.remove();
      var ov = document.createElement('div');
      ov.id = '_mtd-overlay';
      ov.className = 'modal-overlay';
      ov.style.display = 'flex';
      ov.style.zIndex = '10001';
      var authorName = membership.memberName || (S.settings&&S.settings.name) || 'عضو';
      var stColors = {new:'var(--text3)',progress:'var(--accent2)',review:'#f7c948',paused:'#64b5f6',done:'var(--accent3)'};
      var stLabels = {new:'ًں†• جديد',progress:'âڑ، جاري',review:'ًں”چ مراجعة',paused:'âڈ¸ موقوف',done:'? مكتمل'};
      var curSt = t.status||'new';
      var isLate = t.deadline && new Date(t.deadline)<new Date() && !t.done;
      var daysLeft = t.deadline ? Math.ceil((new Date(t.deadline)-new Date())/864e5) : null;
      var tid = String(t.id);
      var oid = ownerId;

      function _buildDetailHTML(){
        var stepsTotal = (t.steps||[]).length;
        var stepsDone  = (t.steps||[]).filter(function(s){return s.done;}).length;
        var pct = stepsTotal ? Math.round(stepsDone/stepsTotal*100) : (t.done?100:0);

        // Steps with per-step comments + toggle
        var stepsHTML = '';
        if(stepsTotal){
          stepsHTML = '<div style="margin:14px 0;padding:14px;background:var(--surface2);border-radius:12px;border:1px solid var(--border)">'
            +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">'
              +'<div style="font-size:13px;font-weight:700"><i class="fa-solid fa-clipboard-list"></i> خطوات التنفيذ</div>'
              +'<div style="font-size:12px;font-weight:700;color:var(--accent)">'+stepsDone+'/'+stepsTotal+' ? '+pct+'%</div>'
            +'</div>'
            +'<div style="height:6px;background:var(--surface3);border-radius:3px;overflow:hidden;margin-bottom:12px">'
              +'<div style="height:100%;width:'+pct+'%;background:linear-gradient(90deg,var(--accent),var(--accent3));border-radius:3px;transition:.4s"></div>'
            +'</div>';
          (t.steps||[]).forEach(function(s,si){
            var stepComments = (t.comments||[]).filter(function(c){return String(c.stepIdx)===String(si);});
            var inputId = '_mts-'+tid+'-'+si;
            stepsHTML += '<div style="border-bottom:1px solid rgba(255,255,255,.06);padding-bottom:10px;margin-bottom:10px">'
              +'<div style="display:flex;align-items:center;gap:10px;cursor:pointer;padding:6px 0" data-step-toggle="'+tid+'-'+si+'">'
                +'<div style="width:24px;height:24px;border-radius:6px;border:2px solid '+(s.done?'var(--accent3)':'var(--border)')+';background:'+(s.done?'var(--accent3)':'transparent')+';display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:11px;color:#fff;transition:.2s">'+(s.done?'<i class="fa-solid fa-check"></i>':String(si+1))+'</div>'
                +'<div style="flex:1;font-size:13px;font-weight:600;'+(s.done?'text-decoration:line-through;opacity:.5':'')+'" data-step-text="'+si+'">'+escapeHtml(s.title||s.text||s.name||'خطوة')+'</div>'
                +'<div style="font-size:10px;font-weight:700;color:'+(s.done?'var(--accent3)':'var(--text3)'+';opacity:.7')+'">'+( s.done?'? مكتمل':'◯ معلق')+'</div>'
              +'</div>'
              // Step comments
              +(stepComments.length ? '<div style="padding-right:34px;margin-bottom:6px">'+stepComments.map(function(c){
                var d=new Date(c.at);
                return '<div style="background:rgba(124,111,247,.1);border-radius:8px;padding:6px 10px;margin-bottom:4px">'
                  +'<span style="font-size:10px;font-weight:700;color:var(--accent)">'+escapeHtml(c.author||'')+'</span>'
                  +'<span style="font-size:10px;color:var(--text3);margin-right:6px">'+d.getDate()+'/'+(d.getMonth()+1)+'</span>'
                  +'<div style="font-size:11px;color:var(--text2);margin-top:2px">'+escapeHtml(c.text)+'</div>'
                +'</div>';
              }).join('')+'</div>' : '')
              // Step comment input
              +'<div style="padding-right:34px;display:flex;gap:6px">'
                +'<input type="text" id="'+inputId+'" style="flex:1;padding:5px 10px;background:var(--surface);border:1px solid var(--border);border-radius:8px;font-size:11px;color:var(--text);font-family:var(--font)" placeholder="ملاحظة على هذه الخطوة...">'
                +'<button data-step-comment="'+tid+'" data-step-idx="'+si+'" data-input-id="'+inputId+'" style="padding:5px 10px;background:var(--accent);color:#fff;border:none;border-radius:8px;cursor:pointer;font-size:11px"><i class="fa-solid fa-paper-plane"></i></button>'
              +'</div>'
            +'</div>';
          });
          stepsHTML += '</div>';
        }

        // Task comments
        var taskComments = (t.comments||[]).filter(function(c){return c.stepIdx===null||c.stepIdx===undefined;});
        var commentsHTML = '<div style="margin:14px 0;padding:14px;background:var(--surface2);border-radius:12px;border:1px solid var(--border)">'
          +'<div style="font-size:13px;font-weight:700;margin-bottom:10px"><i class="fa-solid fa-comments" style="color:var(--accent)"></i> ملاحظات وتعليقات <span style="font-size:10px;background:rgba(124,111,247,.15);color:var(--accent);padding:2px 8px;border-radius:8px">'+taskComments.length+'</span></div>'
          +(taskComments.length ? taskComments.map(function(c){
            var d=new Date(c.at);
            var ts=d.getDate()+'/'+(d.getMonth()+1)+'/'+d.getFullYear()+' '+d.getHours().toString().padStart(2,'0')+':'+d.getMinutes().toString().padStart(2,'0');
            return '<div style="background:var(--surface);border:1px solid rgba(124,111,247,.2);border-radius:10px;padding:10px 14px;margin-bottom:6px">'
              +'<div style="display:flex;justify-content:space-between;margin-bottom:4px">'
                +'<span style="font-size:11px;font-weight:700;color:var(--accent)">'+escapeHtml(c.author||'')+'</span>'
                +'<span style="font-size:10px;color:var(--text3)">'+ts+'</span>'
              +'</div>'
              +'<div style="font-size:13px;color:var(--text2);line-height:1.6">'+escapeHtml(c.text)+'</div>'
            +'</div>';
          }).join('') : '<div style="text-align:center;font-size:12px;color:var(--text3);padding:8px">لا ملاحظات بعد</div>')
          +'<div style="display:flex;gap:8px;margin-top:10px">'
            +'<textarea id="_mtc-main-'+tid+'" rows="2" style="flex:1;padding:8px 12px;background:var(--surface);border:1px solid var(--border);border-radius:10px;font-size:13px;color:var(--text);resize:none;font-family:var(--font)" placeholder="أضف ملاحظة..."></textarea>'
            +'<button id="_mtc-submit-'+tid+'" style="padding:10px 16px;background:var(--accent);color:#fff;border:none;border-radius:10px;cursor:pointer;font-size:13px;align-self:flex-end"><i class="fa-solid fa-paper-plane"></i></button>'
          +'</div>'
        +'</div>';

        // Status buttons
        var statusBtns = !t.done
          ? '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:16px;padding-top:14px;border-top:1px solid var(--border)">'
              +'<span style="font-size:12px;color:var(--text3);align-self:center">تغيير الحالة:</span>'
              +(curSt!=='done'?'<button data-st-action="done" style="padding:7px 14px;background:var(--accent3);color:#fff;border:none;border-radius:8px;cursor:pointer;font-size:12px;font-weight:700"><i class="fa-solid fa-check"></i> مكتمل</button>':'')
              +(curSt!=='progress'?'<button data-st-action="progress" style="padding:7px 14px;background:var(--accent2)22;color:var(--accent2);border:1px solid var(--accent2)44;border-radius:8px;cursor:pointer;font-size:12px">âڑ، جاري</button>':'')
              +(curSt!=='paused'?'<button data-st-action="paused" style="padding:7px 14px;background:rgba(100,100,100,.2);color:var(--text2);border:1px solid var(--border);border-radius:8px;cursor:pointer;font-size:12px">âڈ¸ موقوف</button>':'')
              +(curSt!=='review'?'<button data-st-action="review" style="padding:7px 14px;background:rgba(247,201,72,.15);color:#f7c948;border:1px solid rgba(247,201,72,.3);border-radius:8px;cursor:pointer;font-size:12px">ًں”چ مراجعة</button>':'')
            +'</div>'
          : '<div style="margin-top:14px"><button data-st-action="progress" style="padding:7px 14px;background:var(--surface2);color:var(--text2);border:1px solid var(--border);border-radius:8px;cursor:pointer;font-size:12px">â†© إعادة فتح</button></div>';

        return '<div class="modal" style="max-width:580px;max-height:92vh;overflow-y:auto;padding:0">'
          // Header
          +'<div style="background:linear-gradient(135deg,rgba(124,111,247,.15),rgba(79,209,165,.08));padding:18px 20px;border-radius:12px 12px 0 0;position:sticky;top:0;backdrop-filter:blur(8px);z-index:2">'
            +'<div style="display:flex;align-items:flex-start;gap:12px">'
              +'<div style="flex:1">'
                +'<div style="font-size:10px;font-weight:700;color:var(--accent3);margin-bottom:4px"><i class="fa-solid fa-users"></i> '+escapeHtml(membership.ownerName)+' ? '+escapeHtml(membership.teamName)+'</div>'
                +'<div style="font-size:18px;font-weight:900;line-height:1.3">'+escapeHtml(t.title)+'</div>'
                +'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:6px;font-size:11px">'
                  +'<span style="color:'+stColors[curSt]+'">'+stLabels[curSt]+'</span>'
                  +(t.client?'<span style="color:var(--text3)"><i class="fa-solid fa-user"></i> '+escapeHtml(t.client)+'</span>':'')
                  +(t.deadline?'<span style="color:'+(isLate?'var(--accent4)':(daysLeft<=2?'var(--accent2)':'var(--text3)'))+'">'+(isLate?'âڑ ï¸ڈ متأخرة':(t.done?'? منجزة':daysLeft+' يوم'))+'</span>':'')
                  +(t.workerAmount?'<span style="color:var(--accent2);font-weight:700">ًں’° '+Number(t.workerAmount).toLocaleString()+' ج</span>':'')
                +'</div>'
              +'</div>'
              +'<button id="_mtd-close" style="width:32px;height:32px;border-radius:8px;background:rgba(0,0,0,.2);border:none;color:var(--text);cursor:pointer;font-size:14px;display:flex;align-items:center;justify-content:center;flex-shrink:0"><i class="fa-solid fa-xmark"></i></button>'
            +'</div>'
          +'</div>'
          // Body
          +'<div style="padding:16px 20px">'
            +stepsHTML
            +commentsHTML
            +statusBtns
          +'</div>'
        +'</div>';
      }

      function _bindDetailEvents(){
        // Close
        var closeBtn = ov.querySelector('#_mtd-close');
        if(closeBtn) closeBtn.onclick = function(){ ov.remove(); };
        ov.onclick = function(e){ if(e.target===ov) ov.remove(); };

        // Status change
        ov.querySelectorAll('[data-st-action]').forEach(function(btn){
          btn.onclick = async function(){
            var st = this.dataset.stAction;
            curSt = st; t.status=st; t.done=(st==='done');
            if(t.done){ var mem=membership; var i=mem.tasks.findIndex(function(x){return String(x.id)===tid;}); if(i>-1){mem.doneTasks.unshift(mem.tasks[i]);mem.tasks.splice(i,1);} }
            else { var doneI=membership.doneTasks.findIndex(function(x){return String(x.id)===tid;}); if(doneI>-1){membership.tasks.push(membership.doneTasks[doneI]);membership.doneTasks.splice(doneI,1);} }
            ov.querySelector('.modal').innerHTML = _buildDetailHTML().match(/<div class="modal"[^>]*>([\s\S]*)<\/div>$/)[0]; ov.querySelector('.modal').outerHTML; 
            ov.innerHTML = _buildDetailHTML();
            _bindDetailEvents();
            // Sync to owner DB
            try {
              var { data: ownerRow } = await supa.from('studio_data').select('data').eq('user_id', oid).maybeSingle();
              if(!ownerRow) return;
              var od = typeof ownerRow.data==='string' ? JSON.parse(ownerRow.data) : ownerRow.data;
              if(od.data&&!od.tasks) od = typeof od.data==='string'?JSON.parse(od.data):od.data;
              var ot = (od.tasks||[]).find(function(x){return String(x.id)===tid;});
              if(ot){ot.status=st;ot.done=(st==='done');}
              // Add notification for owner about status change
              if(!od._pending_notifications) od._pending_notifications = [];
              var stN={done:'? مكتمل',progress:'âڑ، جاري',review:'ًں”چ مراجعة',paused:'âڈ¸ موقوف',new:'ًں†• جديد'};
              od._pending_notifications.push({
                id:Date.now(), type:'task_status',
                title:'<i class="fa-solid fa-bolt" style="color:var(--accent2)"></i> تحديث حالة مهمة',
                body: '"'+t.title+'" ? '+authorName+' غيّر الحالة إلى: '+(stN[st]||st),
                read:false, created_at:new Date().toISOString()
              });
              await supa.from('studio_data').update({data:JSON.stringify(od),updated_at:new Date().toISOString()}).eq('user_id',oid);
              if(typeof showMiniNotif==='function') showMiniNotif('? تم تحديث حالة المهمة');
              // Also refresh team modal behind
              if(typeof _renderMemberTasksSection==='function') _renderMemberTasksSection();
            } catch(e){ console.warn('status sync:', e); }
          };
        });

        // Step toggle
        ov.querySelectorAll('[data-step-toggle]').forEach(function(row){
          row.onclick = async function(){
            var parts = this.dataset.stepToggle.split('-');
            var si = parseInt(parts[parts.length-1]);
            t.steps[si].done = !t.steps[si].done;
            ov.innerHTML = _buildDetailHTML();
            _bindDetailEvents();
            // Sync
            try {
              var { data: ownerRow } = await supa.from('studio_data').select('data').eq('user_id', oid).maybeSingle();
              if(!ownerRow) return;
              var od = typeof ownerRow.data==='string' ? JSON.parse(ownerRow.data) : ownerRow.data;
              if(od.data&&!od.tasks) od = typeof od.data==='string'?JSON.parse(od.data):od.data;
              var ot = (od.tasks||[]).find(function(x){return String(x.id)===tid;});
              if(ot&&ot.steps&&ot.steps[si]) ot.steps[si].done = t.steps[si].done;
              await supa.from('studio_data').update({data:JSON.stringify(od),updated_at:new Date().toISOString()}).eq('user_id',oid);
            } catch(e){}
          };
        });

        // Step comment buttons
        ov.querySelectorAll('[data-step-comment]').forEach(function(btn){
          btn.onclick = async function(){
            var si = parseInt(this.dataset.stepIdx);
            var inputEl = document.getElementById(this.dataset.inputId);
            var text = inputEl ? inputEl.value.trim() : '';
            if(!text) return;
            this.disabled = true;
            var comment = { id:Date.now(), text:text, author:authorName, stepIdx:si, at:new Date().toISOString() };
            if(!t.comments) t.comments=[];
            t.comments.push(comment);
            inputEl.value = '';
            ov.innerHTML = _buildDetailHTML();
            _bindDetailEvents();
            // Sync to owner
            try {
              var { data: ownerRow } = await supa.from('studio_data').select('data').eq('user_id', oid).maybeSingle();
              if(!ownerRow) return;
              var od = typeof ownerRow.data==='string' ? JSON.parse(ownerRow.data) : ownerRow.data;
              if(od.data&&!od.tasks) od = typeof od.data==='string'?JSON.parse(od.data):od.data;
              var ot = (od.tasks||[]).find(function(x){return String(x.id)===tid;});
              if(ot){ if(!ot.comments) ot.comments=[]; ot.comments.push(comment); }
              await supa.from('studio_data').update({data:JSON.stringify(od),updated_at:new Date().toISOString()}).eq('user_id',oid);
              if(typeof showMiniNotif==='function') showMiniNotif('? تمت إضافة الملاحظة');
            } catch(e){ console.warn('step comment sync:',e); }
          };
        });

        // Main task comment
        var submitBtn = ov.querySelector('#_mtc-submit-'+tid);
        if(submitBtn) submitBtn.onclick = async function(){
          var ta = document.getElementById('_mtc-main-'+tid);
          var text = ta ? ta.value.trim() : '';
          if(!text) return;
          this.disabled = true;
          var comment = { id:Date.now(), text:text, author:authorName, stepIdx:null, at:new Date().toISOString() };
          if(!t.comments) t.comments=[];
          t.comments.push(comment);
          if(ta) ta.value='';
          ov.innerHTML = _buildDetailHTML();
          _bindDetailEvents();
          try {
            var { data: ownerRow } = await supa.from('studio_data').select('data').eq('user_id', oid).maybeSingle();
            if(!ownerRow) return;
            var od = typeof ownerRow.data==='string' ? JSON.parse(ownerRow.data) : ownerRow.data;
            if(od.data&&!od.tasks) od = typeof od.data==='string'?JSON.parse(od.data):od.data;
            var ot = (od.tasks||[]).find(function(x){return String(x.id)===tid;});
            if(ot){ if(!ot.comments) ot.comments=[]; ot.comments.push(comment); }
            await supa.from('studio_data').update({data:JSON.stringify(od),updated_at:new Date().toISOString()}).eq('user_id',oid);
            if(typeof showMiniNotif==='function') showMiniNotif('? تمت إضافة الملاحظة');
          } catch(e){ console.warn('main comment sync:',e); }
        };
      }

      ov.innerHTML = _buildDetailHTML();
      document.body.appendChild(ov);
      _bindDetailEvents();
    };

    // â”€â”€ Simple task card (click ? open full detail) â”€â”€
    function _renderTaskCard(t, isActive){
      var isLate = t.deadline && new Date(t.deadline) < new Date() && !t.done;
      var daysLeft = t.deadline ? Math.ceil((new Date(t.deadline) - new Date()) / 864e5) : null;
      var stepsTotal = (t.steps||[]).length;
      var stepsDone  = (t.steps||[]).filter(function(s){ return s.done; }).length;
      var pct = stepsTotal ? Math.round(stepsDone/stepsTotal*100) : (t.done?100:0);
      var stColors = {new:'var(--accent2)',progress:'var(--accent)',review:'#f7c948',paused:'var(--text3)',done:'var(--accent3)'};
      var stLabels = {new:'ًں†• جديد',progress:'âڑ، جاري',review:'ًں”چ مراجعة',paused:'âڈ¸ موقوف',done:'? مكتمل'};
      var curSt = t.status||'new';
      var commentsCount = (t.comments||[]).length;

      return '<div style="background:var(--surface2);border:1px solid var(--border);border-right:3px solid '+(isLate?'var(--accent4)':(t.done?'var(--accent3)':'var(--accent)'))+';border-radius:12px;padding:12px 14px;margin-bottom:8px;cursor:pointer;transition:opacity .15s" onclick="window._openMemberTaskDetail(\''+t.id+'\')" onmouseenter="this.style.opacity=\'.85\'" onmouseleave="this.style.opacity=\'1\'">'
        +'<div style="display:flex;justify-content:space-between;align-items:flex-start">'
          +'<div style="flex:1;min-width:0">'
            +'<div style="font-size:14px;font-weight:700;margin-bottom:4px;'+(t.done?'text-decoration:line-through;opacity:.7':'')+'">'+escapeHtml(t.title)+'</div>'
            +'<div style="display:flex;gap:8px;flex-wrap:wrap;font-size:11px;color:var(--text3)">'
              +(t.client?'<span><i class="fa-solid fa-user"></i> '+escapeHtml(t.client)+'</span>':'')
              +'<span style="color:'+stColors[curSt]+'">'+stLabels[curSt]+'</span>'
              +(t.workerAmount?'<span style="color:var(--accent2);font-weight:700">ًں’° '+Number(t.workerAmount).toLocaleString()+' ج</span>':'')
              +(commentsCount?'<span style="color:var(--accent)"><i class="fa-solid fa-comment"></i> '+commentsCount+'</span>':'')
            +'</div>'
          +'</div>'
          +(t.deadline?'<div style="font-size:10px;font-weight:700;color:'+(isLate?'var(--accent4)':(daysLeft<=2?'var(--accent2)':'var(--accent3)'))+';flex-shrink:0;text-align:left;padding-right:6px">'+(isLate?'âڑ ï¸ڈ متأخرة':(t.done?'? منجزة':daysLeft+' يوم'))+'</div>':'')
        +'</div>'
        +(stepsTotal?'<div style="margin-top:8px"><div style="height:3px;background:var(--surface3);border-radius:2px;overflow:hidden"><div style="height:100%;width:'+pct+'%;background:linear-gradient(90deg,var(--accent),var(--accent3))"></div></div><div style="font-size:10px;color:var(--text3);margin-top:2px">'+stepsDone+'/'+stepsTotal+' خطوات</div></div>':'')
        +'<div style="font-size:10px;color:var(--accent);margin-top:8px"><i class="fa-solid fa-arrow-left"></i> اضغط لفتح التفاصيل وتعديل الحالة</div>'
      +'</div>';
    }

    function _renderModalBody(){
      var tasks2 = membership.tasks || [];
      var doneTasks2 = membership.doneTasks || [];
      return '<div style="background:linear-gradient(135deg,rgba(124,111,247,.12),rgba(79,209,165,.08));padding:20px 24px;border-radius:var(--radius) var(--radius) 0 0;position:sticky;top:0;backdrop-filter:blur(8px);z-index:2">'
          +'<div style="display:flex;align-items:center;gap:14px">'
            +(membership.ownerLogo&&typeof _validImgSrc==="function"&&_validImgSrc(membership.ownerLogo)?'<img src="'+escapeHtml(membership.ownerLogo)+'" style="width:52px;height:52px;border-radius:14px;object-fit:cover">':'<div style="width:52px;height:52px;border-radius:14px;background:linear-gradient(135deg,var(--accent),var(--accent3));display:flex;align-items:center;justify-content:center;font-size:24px"><i class="fa-solid fa-building"></i></div>')
            +'<div style="flex:1">'
              +'<div style="font-size:17px;font-weight:900">'+escapeHtml(membership.ownerName)+'</div>'
              +'<div style="font-size:12px;color:var(--text3)">'+escapeHtml(membership.teamName)+' آ· دورك: <strong style="color:var(--accent)">'+escapeHtml(membership.role||'عضو')+'</strong></div>'
            +'</div>'
            +'<button class="close-btn" id="_mmt-close"><i class="fa-solid fa-xmark"></i></button>'
          +'</div>'
          +'<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:16px">'
            +'<div style="background:rgba(0,0,0,.2);border-radius:10px;padding:10px;text-align:center"><div style="font-size:22px;font-weight:900;color:var(--accent2)">'+tasks2.length+'</div><div style="font-size:10px;color:var(--text3)">مهام نشطة</div></div>'
            +'<div style="background:rgba(0,0,0,.2);border-radius:10px;padding:10px;text-align:center"><div style="font-size:22px;font-weight:900;color:var(--accent3)">'+doneTasks2.length+'</div><div style="font-size:10px;color:var(--text3)">مكتملة</div></div>'
            +'<div style="background:rgba(0,0,0,.2);border-radius:10px;padding:10px;text-align:center"><div style="font-size:22px;font-weight:900;color:var(--accent4)">'+tasks2.filter(function(t){return t.deadline&&new Date(t.deadline)<new Date();}).length+'</div><div style="font-size:10px;color:var(--text3)">متأخرة</div></div>'
          +'</div>'
        +'</div>'
        +'<div style="padding:20px">'
          +'<div style="font-size:13px;font-weight:800;margin-bottom:12px"><i class="fa-solid fa-clipboard-list"></i> مهامي النشطة <span style="background:rgba(247,201,72,.2);color:var(--accent2);padding:2px 8px;border-radius:8px;font-size:10px">'+tasks2.length+'</span></div>'
          +(tasks2.length ? tasks2.map(function(t){ return _renderTaskCard(t, true); }).join('') : '<div style="text-align:center;padding:20px;color:var(--text3)"><i class="fa-solid fa-square-check" style="font-size:28px;color:var(--accent3);display:block;margin-bottom:8px"></i>لا مهام نشطة الآن</div>')
          +(doneTasks2.length ? '<div style="font-size:13px;font-weight:800;margin-top:16px;margin-bottom:10px;color:var(--accent3)"><i class="fa-solid fa-square-check"></i> مكتملة ('+doneTasks2.length+')</div>'
            +doneTasks2.slice(0,10).map(function(t){ return _renderTaskCard(t, false); }).join('') : '')
        +'</div>';
    }

    function _bindModalEvents(){
      var modal = overlay.querySelector('.modal');
      var closeBtn = modal.querySelector('#_mmt-close');
      if(closeBtn) closeBtn.onclick = function(){ overlay.remove(); };
    }

    overlay.innerHTML = '<div class="modal" style="max-width:560px;max-height:92vh;overflow-y:auto;padding:0">'+_renderModalBody()+'</div>';
    _bindModalEvents();
  }

  _buildModal();
  document.body.appendChild(overlay);
  overlay.onclick = function(e){ if(e.target===overlay) overlay.remove(); };
};


// â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
// TEAM MEMBERSHIP SYSTEM
// â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
(function(){

  window._myTeamMemberships = [];

  window._checkTeamMembership = async function(myEmail){
    if(!myEmail || typeof supa==='undefined') return;
    myEmail = myEmail.toLowerCase().trim();
    try {
      if(!_supaUserId) return;
      var memberships = [];

      // â”€â”€ Source 1: team_invites accepted â”€â”€
      try {
        var invRes = await supa.from('team_invites').select('id,team_id,team_name,owner_user_id,owner_name,to_email,to_user_id,member_name,member_role,role,status,payload,data,created_at')
          .eq('to_email', myEmail).eq('status','accepted');
        var acceptedInvs = invRes.data || [];
        acceptedInvs.forEach(function(inv){
          var pl={};
          try{ pl=typeof inv.payload==='string'?JSON.parse(inv.payload):(inv.payload||{}); }catch(e){}
          var already=memberships.find(function(x){return String(x.teamId||x.teamName)===String(inv.team_id||inv.team_name);});
          if(!already) memberships.push({
            ownerId:pl.ownerUserId||'', ownerName:inv.owner_name||pl.ownerName||'مشرف', ownerLogo:'',
            teamId:inv.team_id||'', teamName:inv.team_name||'الفريق', memberName:inv.member_name||'',
            role:inv.member_role||'عضو', isCompany:pl.isCompanyTeam||false,
            type:pl.isCompanyTeam?'company':'team', tasks:[], doneTasks:[], _fromInvite:true
          });
        });
      }catch(e){ console.warn('team_invites check:', e.message||e); }

      // â”€â”€ Source 2: user_notifications type=team_added â”€â”€
      try {
        var notifRes = await supa.from('user_notifications').select('id,user_id,title,body,type,read,data,created_at')
          .eq('user_id',_supaUserId).eq('type','team_added');
        var notifRows = notifRes.data || [];
        notifRows.forEach(function(n){
          try{
            var d2=typeof n.data==='string'?JSON.parse(n.data||'{}'):(n.data||{});
            var already=memberships.find(function(x){return (x.teamId&&x.teamId===d2.teamId)||(x.teamName===d2.teamName&&x.ownerName===(d2.ownerName||'مشرف'));});
            if(!already) memberships.push({
              ownerId:d2.ownerUserId||'', ownerName:d2.ownerName||'مشرف', ownerLogo:'',
              teamId:d2.teamId||'', teamName:d2.teamName||'الفريق', memberName:'',
              role:d2.memberRole||'عضو', isCompany:d2.isCompanyTeam||false,
              type:d2.isCompanyTeam?'company':'team', teamColor:'', teamEmoji:'',
              tasks:[], doneTasks:[]
            });
          }catch(e){}
        });
      }catch(e){}

      // Source 3: normalized team_members table. Avoid scanning studio_data.
      try {
        var tmRes = await supa.from('team_members')
          .select('team_id,team_name,owner_user_id,owner_name,member_name,role,is_company')
          .eq('member_email', myEmail)
          .eq('status','active')
          .limit(100);
        (tmRes.data||[]).forEach(function(m){
          var already=memberships.find(function(x){return String(x.teamId)===String(m.team_id)&&String(x.ownerId)===String(m.owner_user_id);});
          if(!already) memberships.push({
            ownerId:m.owner_user_id||'', ownerName:m.owner_name||'مشرف', ownerLogo:'',
            teamId:m.team_id||'', teamName:m.team_name||'الفريق', memberName:m.member_name||'',
            role:m.role||'عضو', isCompany:!!m.is_company,
            type:m.is_company?'company':'team', tasks:[], doneTasks:[]
          });
        });
      }catch(e){}

      window._myTeamMemberships = memberships;
      if(typeof renderMyMemberTeams === 'function') renderMyMemberTeams();
      if(typeof _renderMemberTasksSection === 'function') _renderMemberTasksSection();
      _updateInboxBadge();
      if(memberships.length){
        _showTeamMembershipBanner(memberships);
        var knownKey  = 'known_teams_'+(_supaUserId||'g');
        var knownList = JSON.parse(localStorage.getItem(knownKey)||'[]');
        var newTeams  = memberships.filter(function(m){ return !knownList.includes(m.ownerName+'_'+m.teamName); });
        if(newTeams.length){
          newTeams.forEach(function(m){ showMiniNotif('<i class="fa-solid fa-users" style="color:var(--accent3)"></i> انضممت لفريق "'+m.teamName+'" ? '+m.ownerName); });
          localStorage.setItem(knownKey, JSON.stringify(memberships.map(function(m){ return m.ownerName+'_'+m.teamName; })));
        }
      }
    } catch(e){ console.warn('_checkTeamMembership:', e); }
  };

  // On login: check team_invites table for invites sent to this user's email
  async function _checkPendingTeamInvitesImpl(){
    try{
      if(!_supaUserId) return;
      var myEmail = '';
      try{ var _as=JSON.parse(localStorage.getItem('studioOS_auth_v1')||'{}'); myEmail=(_as.email||'').toLowerCase().trim(); }catch(e){}
      if(!myEmail && S.settings && S.settings.email) myEmail = (S.settings.email||'').toLowerCase().trim();
      if(!myEmail) return;
      var pendingInvs = null;
      try{
        var _r = await supa.from('team_invites').select('id,team_id,team_name,owner_user_id,owner_name,to_email,to_user_id,member_name,member_role,role,status,payload,data,created_at').eq('to_email', myEmail).in('status',['pending','delivered']);
        pendingInvs = _r.data;
      }catch(e){ return; }
      if(!pendingInvs || !pendingInvs.length) return;
      // فلترة ما سبق قبوله أو رفضه محلياً
      var localAccepted = JSON.parse(localStorage.getItem('_accepted_team_invites_'+(_supaUserId||''))||'[]');
      var localDeclined = JSON.parse(localStorage.getItem('_declined_team_invites_'+(_supaUserId||''))||'[]');
      pendingInvs = pendingInvs.filter(function(p){
        var wasAccepted = localAccepted.some(function(a){ return String(a.teamId)===String(p.team_id); });
        var wasDeclined = localDeclined.includes(String(p.id));
        return !wasAccepted && !wasDeclined;
      });
      if(!pendingInvs.length) return;
      // Deliver each pending invite as a notification
      for(var pinv of pendingInvs){
        var notif;
        try{ notif = typeof pinv.payload==='string' ? JSON.parse(pinv.payload) : pinv.payload; }catch(e){ notif={}; }
        notif = notif || {};
        notif.id        = notif.id || pinv.id;
        notif.type      = 'team_invite';
        notif.teamName  = pinv.team_name;
        notif.teamId    = pinv.team_id;
        notif.ownerName = pinv.owner_name;
        notif.memberName= pinv.member_name;
        notif.memberRole= pinv.member_role;
        notif.status    = 'pending';
        notif.read      = false;
        // Add to notifications if not already there
        var exists = _notifications.find(function(x){ return x.id==='pn_'+notif.id; });
        if(!exists){
          _notifications.unshift({ id:'pn_'+notif.id, msg:'دعوة فريق! ' + notif.body, type:'team_invite', time:notif.created_at, read:false });
          if(typeof _saveNotifications==='function') _saveNotifications();
          if(typeof _updateNotifBell==='function') _updateNotifBell();
        }
        if(typeof window._showTeamInviteDialog==='function'){
          setTimeout(function(){ window._showTeamInviteDialog([notif]); }, 2000);
        }
        // Mark as delivered in team_invites table
        try{ await supa.from('team_invites').update({status:'delivered'}).eq('id',pinv.id); }catch(e){}
      }
    }catch(e){ console.warn('_checkPendingTeamInvites:', e); }
  }
  // Expose globally so it can be called on demand
  window._checkPendingTeamInvitesNow = _checkPendingTeamInvitesImpl;
  // Run immediately on login
  _checkPendingTeamInvitesImpl();
  // Reduced polling to limit Supabase egress.
  setInterval(_checkPendingTeamInvitesImpl, 5*60*1000);

  // â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
  //  BRIDGE: نظام الشركات â†” index.html
  //  ١. يعرض فرق الشركات في صفحة الفريق بالـ index
  //  ٢. يجيب إشعارات نظام الشركات على الهوم
  //  ٣. لو في membership في فرق شركات تظهر في my-member-teams
  // â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
  (function _initCompanyBridge(){

    // â”€â”€ أ. مراقبة إشعارات الشركات من localStorage + Supabase â”€â”€
    async function _syncCompanyNotifications(){
      try {
        var myEmail = '';
        try{ var _as=JSON.parse(localStorage.getItem('studioOS_auth_v1')||'{}'); myEmail=(_as.email||'').toLowerCase().trim(); }catch(e){}
        if(!myEmail && S.settings && S.settings.email) myEmail=(S.settings.email||'').toLowerCase().trim();
        if(!myEmail) return;

        var allTeamsToCheck = [];

        // â”€â”€ ١. من localStorage (نفس الجهاز / المالك) â”€â”€
        var raw = localStorage.getItem('ordo_teams_v2');
        if(raw){
          try {
            var tsData = JSON.parse(raw);
            (tsData.teams||[]).forEach(function(t){ if(t.type==='company') allTeamsToCheck.push({team:t, source:'local'}); });
          }catch(e){}
        }

        // â”€â”€ ٢. من Supabase (أجهزة مختلفة / مستخدمون آخرون) â”€â”€
        if(_supaUserId && typeof supa!=='undefined'){
          try {
            var tmCompany = await supa.from('team_members')
              .select('team_id,team_name,owner_user_id,owner_name,role,member_name,is_company')
              .eq('member_email', myEmail)
              .eq('status','active')
              .eq('is_company', true)
              .limit(100);
            (tmCompany.data||[]).forEach(function(m){
              allTeamsToCheck.push({
                team:{id:m.team_id,name:m.team_name,type:'company',members:[{id:m.member_name||myEmail,email:myEmail,role:m.role||'عضو'}],tasks:[]},
                source:'supabase',
                ownerUserId:m.owner_user_id
              });
            });
          }catch(e){ console.warn('Supabase team_members lookup:', e); }
        }

        // â”€â”€ فحص العضوية في كل الفرق â”€â”€
        var companyMemberships = [];
        allTeamsToCheck.forEach(function(item){
          var team = item.team;
          (team.members||[]).forEach(function(m){
            var mEmail = (m.email||'').toLowerCase().trim();
            if(mEmail === myEmail && m.id !== 'me'){
              // تجنب التكرار
              var already = companyMemberships.find(function(x){ return x.teamId===team.id; });
              if(!already){
                companyMemberships.push({
                  teamId:    team.id,
                  teamName:  team.name,
                  teamColor: team.color,
                  teamEmoji: team.emoji,
                  role:      m.role||'عضو',
                  memberId:  m.id,
                  source:    item.source,
                  ownerUserId: item.ownerUserId||null,
                  tasks:     (team.tasks||[]).filter(function(t){ return t.assigneeId===m.id && t.status!=='done' && !t.done; }),
                  doneTasks: (team.tasks||[]).filter(function(t){ return t.assigneeId===m.id && (t.status==='done'||t.done); }),
                });
              }
            }
          });
        });

        // أيضاً تحقق من user_notifications في Supabase
        if(_supaUserId && typeof supa!=='undefined'){
          try {
            var {data:notifRows} = await supa.from('user_notifications')
              .select('id,user_id,title,body,type,read,data,created_at').eq('user_id',_supaUserId).eq('type','team_added');
            if(notifRows){
              notifRows.forEach(function(n){
                try {
                  var nd = typeof n.data==='string'?JSON.parse(n.data||'{}'):(n.data||{});
                  if(nd.isCompanyTeam && nd.teamId){
                    var already = companyMemberships.find(function(x){ return x.teamId===nd.teamId; });
                    if(!already){
                      companyMemberships.push({
                        teamId:    nd.teamId,
                        teamName:  nd.teamName||n.body||'شركة',
                        teamColor: 'var(--accent2)',
                        teamEmoji: 'ًںڈ¢',
                        role:      nd.memberRole||'عضو',
                        source:    'notification',
                        ownerUserId: nd.ownerUserId||null,
                        tasks:     [], doneTasks:[],
                        teamUrl:   nd.teamUrl||null
                      });
                    }
                  }
                }catch(e){}
              });
            }
          }catch(e){}
        }

        // â”€â”€ إظهار فرق الشركات في قسم "الفرق التي أنا عضو فيها" â”€â”€
        if(companyMemberships.length){
          var knownKey  = '_known_company_memberships_'+(_supaUserId||'g');
          var knownList = JSON.parse(localStorage.getItem(knownKey)||'[]');
          companyMemberships.forEach(function(cm){
            var isNew = !knownList.includes(cm.teamId);
            if(isNew){
              if(typeof addNotification==='function'){
                addNotification('<i class="fa-solid fa-building" style="color:var(--accent2)"></i> تمت إضافتك لشركة <strong>'+escapeHtml(cm.teamName)+'</strong> كـ '+escapeHtml(cm.role), 'info');
              }
              if(typeof showMiniNotif==='function'){
                showMiniNotif('<i class="fa-solid fa-building" style="color:var(--accent2)"></i> انضممت لشركة "'+escapeHtml(cm.teamName)+'"');
              }
            }
          });
          localStorage.setItem(knownKey, JSON.stringify(companyMemberships.map(function(cm){ return cm.teamId; })));

          var existing = window._myTeamMemberships || [];
          companyMemberships.forEach(function(cm){
            var alreadyIdx = existing.findIndex(function(x){ return (x.teamId||x.ownerId)===cm.teamId && x.type==='company'; });
            var entry = {
              type:'company', teamId:cm.teamId,
              ownerId:'local_company_'+cm.teamId,
              ownerName:cm.teamName, ownerLogo:'',
              teamName:cm.teamName, teamColor:cm.teamColor, teamEmoji:cm.teamEmoji,
              memberName:'', role:cm.role,
              tasks:cm.tasks, doneTasks:cm.doneTasks,
              isCompany:true,
              teamUrl: cm.teamUrl||null
            };
            if(alreadyIdx===-1) existing.push(entry);
            else existing[alreadyIdx]=entry;
          });
          window._myTeamMemberships = existing;
          if(typeof renderMyMemberTeams==='function') renderMyMemberTeams();
        }

        // â”€â”€ إشعارات موجهة من نظام الشركات (localStorage) â”€â”€
        if(raw){
          try {
            var tsData2 = JSON.parse(raw);
            var _companyNotifs = tsData2._companyNotifications || {};
            var myNotifs = _companyNotifs[myEmail] || [];
            myNotifs.forEach(function(n){
              var nid = 'cn_'+n.id;
              var notifExists = typeof _notifications!=='undefined' && _notifications.find(function(x){ return x.id===nid; });
              if(!notifExists){
                if(typeof _notifications!=='undefined'){
                  _notifications.unshift({ id:nid, msg:(n.title||'إشعار')+(n.body?'\n'+n.body:''), type:n.type||'company', time:n.createdAt||new Date().toISOString(), read:false });
                  if(typeof _saveNotifications==='function') _saveNotifications();
                  if(typeof _updateNotifBell==='function') _updateNotifBell();
                }
                if(typeof showMiniNotif==='function'){
                  showMiniNotif('<i class="fa-solid fa-bell" style="color:var(--accent2)"></i> '+escapeHtml(n.title||'إشعار جديد'));
                }
              }
            });
          }catch(e){}
        }

      } catch(e){ console.warn('_syncCompanyNotifications:', e); }
    }

    // شغّل فور الفتح ثم كل 5 دقائق لتقليل egress
    setTimeout(_syncCompanyNotifications, 3000);
    setInterval(_syncCompanyNotifications, 5*60*1000);

    // استمع لتغييرات localStorage من team.html
    window.addEventListener('storage', function(e){
      if(e.key === 'ordo_teams_v2'){
        setTimeout(_syncCompanyNotifications, 500);
        if(typeof renderTeams==='function') setTimeout(renderTeams, 600);
      }
    });

  })();

  (function _startPolling(){
    if(!_supaUserId){ setTimeout(_startPolling, 5000); return; }
    async function _poll(){
      try {
        var res = await supa.from('studio_data').select('data').eq('user_id',_supaUserId).single();
        if(!res.data) return;
        var ud = typeof res.data.data==='string' ? JSON.parse(res.data.data) : res.data.data;
        if(!ud) return;
        if(ud._pending_notifications && ud._pending_notifications.length){
          var newCount = 0;
          var teamInvites = [];
          ud._pending_notifications.forEach(function(n){
            var exists = _notifications.find(function(x){ return x.id==='pn_'+n.id; });
            if(!exists){
              _notifications.unshift({ id:'pn_'+n.id, msg:(n.title?'**'+n.title+'**\n':'')+n.body, type:n.type||'message', orderId:n.orderId||'', time:n.created_at, read:false });
              if(!n.read) newCount++;
              if((n.type==='team' || n.type==='team_invite' || n.type==='team_added') && n.teamName && n.ownerName) teamInvites.push(n);
              // Handle svc_order: pull into S.svc_orders if not already there
              if(n.type==='svc_order' && ud.svc_orders){
                S.svc_orders = S.svc_orders||[];
                ud.svc_orders.forEach(function(o){
                  if(!S.svc_orders.find(function(x){ return x.id===o.id; })){ S.svc_orders.push(o); }
                });
                lsSave();
                if(typeof renderServices==='function') setTimeout(renderServices,200);
                addNotification('<i class="fa-solid fa-inbox"></i> '+n.title+': '+n.body, 'info');
              }
              // Handle direct_message: show in support page and notifications
              if(n.type==='direct_message'){
                S.support_msgs = S.support_msgs||[];
                var msgEntry = {
                  id: 'dm_'+n.id,
                  type:'direct_message',
                  from: n.from||'عضو',
                  msg: n.body,
                  created_at: n.created_at,
                  read: false
                };
                if(!S.support_msgs.find(function(x){return x.id===msgEntry.id;})){
                  S.support_msgs.unshift(msgEntry);
                }
                lsSave();
                if(typeof renderSupport==='function') setTimeout(renderSupport,200);
                var suppBadge=document.getElementById('support-badge');
                if(suppBadge){ var unrD=(S.support_msgs||[]).filter(function(x){return !x.read;}).length; suppBadge.textContent=unrD; suppBadge.style.display=unrD?'':'none'; }
                addNotification('<i class="fa-solid fa-envelope" style="color:var(--accent)"></i> رسالة من '+escapeHtml(n.from||'عضو')+': '+n.body, 'info');
              }
              if((n.type==='meeting_request'||n.type==='meeting'||n.type==='support') && ud.support_msgs){
                S.support_msgs = S.support_msgs||[];
                ud.support_msgs.forEach(function(m){
                  if(!S.support_msgs.find(function(x){ return x.id===m.id; })){ S.support_msgs.push(m); }
                });
                lsSave();
                if(typeof renderSupport==='function') setTimeout(renderSupport,200);
                var suppBadge=document.getElementById('support-badge');
                if(suppBadge){ var unr=(S.support_msgs||[]).filter(function(x){return !x.read;}).length; suppBadge.textContent=unr; suppBadge.style.display=unr?'':'none'; }
              }
            }
          });
          if(newCount>0){ if(typeof _saveNotifications==='function') _saveNotifications(); if(typeof _updateNotifBell==='function') _updateNotifBell(); showMiniNotif('<i class="fa-solid fa-bell"></i> لديك '+newCount+' إشعار جديد'); }

          // â”€â”€ Sync _inbox from server (revision requests from client portal) â”€â”€
          if(ud._inbox && ud._inbox.length){
            S._inbox = S._inbox||[];
            var inboxChanged=false;
            ud._inbox.forEach(function(item){
              var exists=S._inbox.find(function(x){ return String(x.id)===String(item.id); });
              if(!exists){
                S._inbox.unshift(item);
                inboxChanged=true;
                if(item.type==='revision'&&item.status==='pending'){
                  addNotification('<i class="fa-solid fa-rotate-left" style="color:#f97316"></i> طلب تعديل من <strong>'+(item.clientName||'عميل')+'</strong> على: '+escapeHtml(item.taskTitle||'مهمة'),'warning');
                }
              }
            });
            if(inboxChanged){ lsSave(); if(typeof _updateInboxBadge==='function') _updateInboxBadge(); }
          }
          // â‌— لا نكتب ud القديمة كلها - بس نمسح الـ notifications من S الحالي
          // ده يمنع الـ poll من overwrite البيانات الجديدة في S
          if(!S._pending_notifications) S._pending_notifications = [];
          S._pending_notifications = [];
          // حفظ S الحالي (مش ud القديم) مع مسح الـ notifications
          try {
            const _safeS = JSON.parse(JSON.stringify(S));
            await supa.from('studio_data').update({data:JSON.stringify(_safeS),updated_at:new Date().toISOString()}).eq('user_id',_supaUserId);
          } catch(e) {
            // fallback: احفظ ud مع مسح الـ notifications بس
            ud._pending_notifications = [];
            await supa.from('studio_data').update({data:JSON.stringify(ud),updated_at:new Date().toISOString()}).eq('user_id',_supaUserId);
          }
          if(teamInvites.length) _showTeamInviteDialog(teamInvites);
        }
        var em = null;
        try{ var _s=JSON.parse(localStorage.getItem('studioOS_auth_v1')||'{}'); em=_s&&_s.email?_s.email:null; }catch(e){}
        if(em && typeof window._checkTeamMembership==='function') window._checkTeamMembership(em);
      } catch(e){}
    }
    _poll();
    window._teamPollNow = _poll;
    setInterval(_poll, 5*60*1000);

    // â”پâ”پ Supabase Realtime ? instant notifications â”پâ”پ
    try {
      var _rtChannel = supa.channel('studio-realtime-' + _supaUserId)
        .on('postgres_changes', {
          event: 'UPDATE',
          schema: 'public',
          table: 'studio_data',
          filter: 'user_id=eq.' + _supaUserId
        }, function(payload) {
          console.log('[Realtime] Data changed, polling now...');
          setTimeout(_poll, 500);
        })
        .subscribe(function(status) {
          console.log('[Realtime] Subscription status:', status);
        });
      window._rtChannel = _rtChannel;
    } catch(e) { console.warn('[Realtime] Setup failed:', e); }

    // Also subscribe to review_queue for instant review notifications
    try {
      supa.channel('review-realtime-' + _supaUserId)
        .on('postgres_changes', {
          event: 'INSERT',
          schema: 'public',
          table: 'review_queue',
          filter: 'target_user_id=eq.' + _supaUserId
        }, function(payload) {
          console.log('[Realtime] New review received!');
          if(typeof _syncReviewsNow === 'function') setTimeout(function(){ _syncReviewsNow(null); }, 1000);
          showMiniNotif('<i class="fa-solid fa-star" style="color:#f7c948"></i> تقييم جديد من عميل!');
        })
        .subscribe();
    } catch(e) { console.warn('[Realtime] Review subscription failed:', e); }

    // â”پâ”پ Realtime listener for team_invites ? instant invite notification â”پâ”پ
    try {
      var myEmail2 = '';
      try{ var _as2=JSON.parse(localStorage.getItem('studioOS_auth_v1')||'{}'); myEmail2=(_as2.email||'').toLowerCase().trim(); }catch(e){}
      if(!myEmail2 && S.settings) myEmail2=(S.settings.email||'').toLowerCase().trim();

      if(myEmail2){
        supa.channel('team-invites-' + _supaUserId)
          .on('postgres_changes', {
            event: 'INSERT',
            schema: 'public',
            table: 'team_invites'
          }, function(payload) {
            var rec = payload.new || {};
            if((rec.to_email||'').toLowerCase().trim() !== myEmail2) return;
            console.log('[Realtime] New team invite received!');
            // بناء الإشعار
            var pl={};
            try{ pl=typeof rec.payload==='string'?JSON.parse(rec.payload):(rec.payload||{}); }catch(e){}
            var inv = {
              id: rec.id, type:'team_invite',
              teamName: rec.team_name, teamId: rec.team_id,
              ownerName: rec.owner_name, memberName: rec.member_name,
              memberRole: rec.member_role, ownerUserId: pl.ownerUserId||'',
              isCompanyTeam: pl.isCompanyTeam||false, teamUrl: pl.teamUrl||'',
              body: 'دعوة للانضمام لـ "'+(rec.team_name||'فريق')+'" بواسطة '+(rec.owner_name||'مشرف'),
              status:'pending', read:false
            };
            // أضف للقائمة وأظهر الـ dialog
            window._pendingTeamInvites = window._pendingTeamInvites||[];
            var exists = window._pendingTeamInvites.find(function(x){return x.id===inv.id;});
            if(!exists){
              window._pendingTeamInvites.push(inv);
              if(typeof _updateInboxBadge==='function') _updateInboxBadge();
              var inboxBtn=document.getElementById('team-invite-inbox-btn');
              if(inboxBtn) inboxBtn.style.display='';
              showMiniNotif('<i class="fa-solid fa-envelope" style="color:var(--accent2)"></i> دعوة جديدة من '+escapeHtml(rec.owner_name||'مشرف')+'!');
              if(typeof window._showTeamInviteDialog==='function'){
                setTimeout(function(){ window._showTeamInviteDialog([inv]); }, 1000);
              }
              // حدّث قسم الدعوات في صفحة الفريق
              if(typeof _renderPendingInvitesSection==='function'){
                setTimeout(_renderPendingInvitesSection, 500);
              }
            }
          })
          .subscribe();
      }
    } catch(e) { console.warn('[Realtime] Team invites subscription failed:', e); }
  })();

  window._showTeamInviteDialog = function(invites){
    // Store for inbox button
    if(!window._pendingTeamInvites) window._pendingTeamInvites = [];
    invites.forEach(function(inv){
      var exists = window._pendingTeamInvites.find(function(x){ return x.id===inv.id; });
      if(!exists) window._pendingTeamInvites.push(inv);
    });
    _updateInboxBadge();
    var existing = document.getElementById('_team-invite-overlay');
    if(existing) existing.remove();
    var invite = invites[0];
    var overlay = document.createElement('div');
    overlay.id = '_team-invite-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.72);display:flex;align-items:center;justify-content:center;padding:20px';
    var roleMatch = invite.body && invite.body.match(/كـ (.+?) في فريق/);
    var roleText  = roleMatch ? roleMatch[1] : 'عضو';
    overlay.innerHTML = [
      '<div style="background:var(--surface);border:1.5px solid rgba(124,111,247,.35);border-radius:20px;max-width:420px;width:100%;padding:28px;box-shadow:0 20px 60px rgba(0,0,0,.5)">',
        '<div style="text-align:center;margin-bottom:20px">',
          '<div style="font-size:52px;margin-bottom:10px"><i class="fa-solid fa-users"></i></div>',
          '<div style="font-size:18px;font-weight:900;margin-bottom:6px">دعوة لانضمام فريق!</div>',
          '<div style="font-size:13px;color:var(--text3)">لديك دعوة للانضمام إلى فريق عمل</div>',
        '</div>',
        '<div style="background:var(--surface2);border:1px solid var(--border);border-radius:14px;padding:16px;margin-bottom:20px">',
          '<div style="display:flex;align-items:center;gap:12px;margin-bottom:12px">',
            '<div style="width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,var(--accent),var(--accent3));display:flex;align-items:center;justify-content:center;font-size:20px"><i class="fa-solid fa-building"></i></div>',
            '<div>',
              '<div style="font-size:15px;font-weight:800">'+escapeHtml(invite.ownerName)+'</div>',
              '<div style="font-size:12px;color:var(--text3)">المشرف / صاحب الفريق</div>',
            '</div>',
          '</div>',
          '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">',
            '<div style="background:var(--surface);border-radius:10px;padding:10px;text-align:center">',
              '<div style="font-size:11px;color:var(--text3);margin-bottom:3px">الفريق</div>',
              '<div style="font-size:13px;font-weight:700">'+escapeHtml(invite.teamName)+'</div>',
            '</div>',
            '<div style="background:var(--surface);border-radius:10px;padding:10px;text-align:center">',
              '<div style="font-size:11px;color:var(--text3);margin-bottom:3px">دورك</div>',
              '<div style="font-size:13px;font-weight:700">'+escapeHtml(roleText)+'</div>',
            '</div>',
          '</div>',
        '</div>',
        '<div style="display:flex;gap:10px">',
          '<button id="_inv-reject-btn" style="flex:1;padding:13px;background:var(--surface2);border:1.5px solid var(--border);border-radius:12px;color:var(--text2);font-family:var(--font);font-size:14px;font-weight:700;cursor:pointer"><i class="fa-solid fa-xmark"></i> رفض الدعوة</button>',
          '<button id="_inv-accept-btn" style="flex:2;padding:13px;background:linear-gradient(135deg,var(--accent),var(--accent3));border:none;border-radius:12px;color:#fff;font-family:var(--font);font-size:14px;font-weight:900;cursor:pointer"><i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> قبول الدعوة</button>',
        '</div>',
        (invites.length>1 ? '<div style="text-align:center;margin-top:12px;font-size:11px;color:var(--text3)">لديك '+(invites.length-1)+' دعوة أخرى</div>' : ''),
      '</div>'
    ].join('');
    overlay._inviteData = invite;
    overlay._remainingInvites = invites.slice(1);
    document.body.appendChild(overlay);
    overlay.querySelector('#_inv-accept-btn').onclick = function(){ _handleTeamInvite(true); };
    overlay.querySelector('#_inv-reject-btn').onclick = function(){ _handleTeamInvite(false); };
  };

  window._handleTeamInvite = async function(accepted){
    var overlay = document.getElementById('_team-invite-overlay');
    if(!overlay) return;
    var invite    = overlay._inviteData;
    var remaining = overlay._remainingInvites || [];
    overlay.remove();
    if(accepted){
      showMiniNotif('ًںژ‰ انضممت لفريق "'+invite.teamName+'" ? '+invite.ownerName);
      // Update team_invites table
      if(typeof supa!=='undefined' && invite.id){
        (async()=>{try{await supa.from('team_invites').update({status:'accepted'}).eq('id',invite.id.replace('pn_',''));}catch(e){}})();
      }
      var em = null;
      try{ var _s=JSON.parse(localStorage.getItem('studioOS_auth_v1')||'{}'); em=_s&&_s.email?_s.email:null; }catch(e){}
      if(em) window._checkTeamMembership(em);
    } else {
      showMiniNotif('تم رفض دعوة "'+invite.teamName+'"');
      if(typeof supa!=='undefined' && invite.id){
        (async()=>{try{await supa.from('team_invites').update({status:'declined'}).eq('id',invite.id.replace('pn_',''));}catch(e){}})();
      }
      // حفظ الرفض محلياً لتجنب إعادة العرض
      var decKey = '_declined_team_invites_'+(_supaUserId||'');
      var decList = JSON.parse(localStorage.getItem(decKey)||'[]');
      var rawId = String(invite.id).replace('pn_','');
      if(!decList.includes(rawId)) decList.push(rawId);
      localStorage.setItem(decKey, JSON.stringify(decList));
    }
    if(remaining.length) setTimeout(function(){ window._showTeamInviteDialog(remaining); }, 400);
  };

  window._showTeamMembershipBanner = function(memberships){
    var el = document.getElementById('team-membership-section');
    if(!el){
      el = document.createElement('div');
      el.id = 'team-membership-section';
      el.style.cssText = 'padding:8px 0';
      var sidebar = document.querySelector('.sidebar');
      var settingsLabel = Array.from(document.querySelectorAll('.nav-section-label')).find(function(x){ return x.textContent.includes('الإعدادات'); });
      if(sidebar && settingsLabel) sidebar.insertBefore(el, settingsLabel);
      else if(sidebar) sidebar.appendChild(el);
    }
    if(!el) return;
    var totalTasks = memberships.reduce(function(s,m){ return s+(m.tasks?m.tasks.length:0); },0);
    var base = window.location.href.replace(/[^/]*(\?.*)?$/, '');

    el.innerHTML =
      '<div class="nav-section-label" style="color:var(--accent3)"><i class="fa-solid fa-users"></i> فرقي</div>'
      +memberships.map(function(m){
        var tc = m.tasks?m.tasks.length:0;
        var isCompany = m.isCompany || m.type==='company';
        var icon = isCompany ? 'ًںڈ¢' : '<i class="fa-solid fa-users"></i>';
        var color = isCompany ? 'var(--accent2)' : 'var(--accent3)';
        var teamColor = m.teamColor || color;
        var onclick = isCompany
          ? 'window.open(\''+base+'team.html\',\'_blank\')'
          : 'openTeamMemberDashboard(\''+m.ownerId+'\')';
        return '<div class="nav-item" onclick="'+onclick+'" style="flex-direction:column;align-items:flex-start;padding:10px 16px;gap:4px;cursor:pointer">'
          +'<div style="display:flex;align-items:center;gap:8px;width:100%">'
            +'<span style="font-size:14px;flex-shrink:0">'+icon+'</span>'
            +'<span style="font-size:13px;font-weight:700;flex:1;color:'+color+'">'+escapeHtml(m.teamName)+'</span>'
            +(tc ? '<span style="background:var(--accent4);color:#fff;font-size:10px;font-weight:700;padding:2px 8px;border-radius:20px">'+tc+'</span>'
                 : '<span style="background:'+color+';color:#fff;font-size:10px;font-weight:700;padding:2px 8px;border-radius:20px"><i class="fa-solid fa-check"></i></span>')
          +'</div>'
          +'<div style="font-size:11px;color:var(--text3);padding-right:22px">'
            +escapeHtml(m.ownerName)+' آ· '+escapeHtml(m.role||'عضو')
            +(isCompany ? ' آ· <span style="color:var(--accent2)">فتح البورد â†—</span>' : '')
          +'</div>'
        +'</div>';
      }).join('')
      +(totalTasks>0 ? '<div style="margin:4px 16px 8px;padding:7px 12px;background:rgba(247,111,124,.08);border:1px solid rgba(247,111,124,.2);border-radius:8px;font-size:11px;color:var(--accent4);font-weight:700"><i class="fa-solid fa-bolt"></i> لديك '+totalTasks+' مهمة نشطة في الفريق</div>' : '');
  };

  window.openTeamMemberDashboard = function(ownerId){
    var membership = window._myTeamMemberships.find(function(m){ return m.ownerId===ownerId; });
    if(!membership) return;
    var tasks=membership.tasks||[], doneTasks=membership.doneTasks||[];
    var html = [
      '<div style="margin-bottom:20px">',
        '<div style="display:flex;align-items:center;gap:12px;margin-bottom:16px;padding:16px;background:linear-gradient(135deg,rgba(124,111,247,.1),rgba(79,209,165,.06));border-radius:14px">',
          (_validImgSrc(membership.ownerLogo) ? '<img src="'+escapeHtml(membership.ownerLogo)+'" style="width:48px;height:48px;border-radius:12px;object-fit:cover" onerror=\'this.style.display=\"none\"\'">'
            : '<div style="width:48px;height:48px;border-radius:12px;background:linear-gradient(135deg,var(--accent),var(--accent3));display:flex;align-items:center;justify-content:center;font-size:22px"><i class="fa-solid fa-building"></i></div>'),
          '<div>',
            '<div style="font-size:16px;font-weight:900">'+escapeHtml(membership.ownerName)+'</div>',
            '<div style="font-size:12px;color:var(--text3)">'+escapeHtml(membership.teamName)+' آ· '+escapeHtml(membership.role||'عضو')+'</div>',
          '</div>',
        '</div>',
        '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:16px">',
          '<div class="card" style="text-align:center;padding:14px"><div style="font-size:24px;font-weight:900;color:var(--accent4)">'+tasks.length+'</div><div style="font-size:11px;color:var(--text3)">مهام نشطة</div></div>',
          '<div class="card" style="text-align:center;padding:14px"><div style="font-size:24px;font-weight:900;color:var(--accent3)">'+doneTasks.length+'</div><div style="font-size:11px;color:var(--text3)">مكتملة</div></div>',
          '<div class="card" style="text-align:center;padding:14px"><div style="font-size:24px;font-weight:900;color:var(--accent2)">'+tasks.filter(function(t){ return t.deadline&&new Date(t.deadline)<new Date(); }).length+'</div><div style="font-size:11px;color:var(--text3)">متأخرة</div></div>',
        '</div>',
        (tasks.length
          ? '<div class="section-title" style="margin-bottom:10px"><i class="fa-solid fa-clipboard-list"></i> مهامي النشطة</div>'
            +tasks.map(function(t){
              var isLate=t.deadline&&new Date(t.deadline)<new Date();
              var daysLeft=t.deadline?Math.ceil((new Date(t.deadline)-new Date())/864e5):null;
              return '<div class="card" style="padding:12px;margin-bottom:8px;border-right:3px solid '+(isLate?'var(--accent4)':'var(--accent)')+'"><div style="display:flex;justify-content:space-between;align-items:flex-start"><div style="flex:1"><div style="font-size:14px;font-weight:700;margin-bottom:3px">'+escapeHtml(t.title)+'</div>'+(t.client?'<div style="font-size:11px;color:var(--text3)"><i class="fa-solid fa-user"></i> '+escapeHtml(t.client)+'</div>':'')+(t.notes?'<div style="font-size:11px;color:var(--text3)"><i class="fa-solid fa-pen-to-square"></i> '+escapeHtml(t.notes.slice(0,80))+'</div>':'')+'</div><div style="text-align:left;flex-shrink:0;padding-right:10px">'+(t.deadline?'<div style="font-size:11px;font-weight:700;color:'+(isLate?'var(--accent4)':(daysLeft<=2?'var(--accent2)':'var(--accent3)'))+'">'+(isLate?'<i class="fa-solid fa-triangle-exclamation"></i> متأخرة':daysLeft+' يوم')+'</div>':'')+'</div></div></div>';
            }).join('')
          : '<div class="empty" style="padding:24px"><div class="empty-icon"><i class="fa-solid fa-square-check" style="color:var(--accent3)"></i></div>لا مهام نشطة الآن</div>'),
        (doneTasks.length
          ? '<div class="section-title" style="margin-top:14px;margin-bottom:10px;color:var(--accent3)"><i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> مكتملة ('+doneTasks.length+')</div>'
            +doneTasks.slice(0,5).map(function(t){
              return '<div style="display:flex;align-items:center;gap:8px;padding:8px 12px;background:var(--surface2);border-radius:8px;margin-bottom:6px"><span style="color:var(--accent3)"><i class="fa-solid fa-check"></i></span><span style="font-size:13px;color:var(--text2);text-decoration:line-through">'+escapeHtml(t.title)+'</span></div>';
            }).join('')
          : ''),
      '</div>'
    ].join('');

    var overlay = document.getElementById('_team-member-modal');
    if(!overlay){
      overlay = document.createElement('div');
      overlay.id = '_team-member-modal';
      overlay.className = 'modal-overlay';
      var inner = document.createElement('div');
      inner.className = 'modal';
      inner.style.cssText = 'max-width:540px;max-height:88vh;overflow-y:auto';
      inner.innerHTML = [
        '<div class="modal-header" style="position:sticky;top:0;background:var(--surface);z-index:2">',
          '<div class="modal-title" id="_tmm-title"><i class="fa-solid fa-clipboard-list"></i> مهامي في الفريق</div>',
          '<button class="close-btn" id="_tmm-close"><i class="fa-solid fa-xmark"></i></button>',
        '</div>',
        '<div id="_tmm-body" style="padding:0 4px"></div>'
      ].join('');
      overlay.appendChild(inner);
      document.body.appendChild(overlay);
      document.getElementById('_tmm-close').onclick = function(){ overlay.style.display='none'; };
      overlay.onclick = function(e){ if(e.target===overlay) overlay.style.display='none'; };
    }
    document.getElementById('_tmm-title').innerHTML='<i class="fa-solid fa-clipboard-list"></i> فريق ? '+membership.ownerName;
    document.getElementById('_tmm-body').innerHTML = html;
    overlay.style.display = 'flex';
  };

})();



