function _renderDashGrid(){
  var grid = document.getElementById('_dash-grid');
  if(!grid) return;

  var layout = _getDashLayout().sort(function(a,b){ return a.row - b.row; });
  // تحدي الأسبوع دائماً مرئي ولا يمكن إخفاؤه
  layout.forEach(function(w){ if(w.id==='challenge') w.visible=true; });
  var visible = layout.filter(function(w){ return w.visible; });
  var hidden  = layout.filter(function(w){ return !w.visible; });

  var html = '';

  // Render by rows ? group consecutive non-full widgets into 2-col rows
  var i = 0;
  while(i < visible.length){
    var w = visible[i];
    var def = _getDef(w.id);
    var isFull = w.full !== undefined ? w.full : def.full;

    if(isFull){
      // Full width widget
      html += _wrapWidget(w, _widgetInnerHTML(w.id), true);
      i++;
    } else {
      // Try to pair with next non-full widget
      var w2 = visible[i+1];
      var def2 = w2 ? _getDef(w2.id) : null;
      var w2Full = w2 ? (w2.full !== undefined ? w2.full : def2.full) : true;
      if(w2 && !w2Full){
        // Responsive: 2-col on desktop, 1-col on mobile
        var isMobile = window.innerWidth <= 540;
        if(isMobile){
          html += _wrapWidget(w,  _widgetInnerHTML(w.id),  true);
          html += _wrapWidget(w2, _widgetInnerHTML(w2.id), true);
        } else {
          html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;align-items:stretch">';
          html += _wrapWidget(w,  _widgetInnerHTML(w.id),  false);
          html += _wrapWidget(w2, _widgetInnerHTML(w2.id), false);
          html += '</div>';
        }
        i += 2;
      } else {
        html += _wrapWidget(w, _widgetInnerHTML(w.id), true);
        i++;
      }
    }
  }

  // Hidden restore bar
  if(_dashEditMode && hidden.length > 0){
    var hidBtns = '';
    for(var h=0; h<hidden.length; h++){
      var hw = hidden[h];
      var hd = _getDef(hw.id);
      hidBtns += '<button onclick="_showWidget(\'' + hw.id + '\')" style="padding:5px 12px;background:var(--surface3);border:1px solid var(--border);border-radius:20px;font-size:12px;color:var(--text2);cursor:pointer;font-family:var(--font)">' + hd.label + '</button>';
    }
    html += '<div style="background:var(--surface2);border:1.5px dashed var(--border);border-radius:12px;padding:12px 14px">' +
      '<div style="font-size:11px;color:var(--text3);margin-bottom:8px;font-weight:700">ويدجت مخفية - اضغط لإظهارها</div>' +
      '<div style="display:flex;flex-wrap:wrap;gap:8px">' + hidBtns + '</div></div>';
  }

  grid.innerHTML = html;

  // Setup drag in edit mode
  if(_dashEditMode){
    var cards = grid.querySelectorAll('[data-widget-card]');
    cards.forEach(function(el){
      el.draggable = true;
      el.style.cursor = 'grab';
      el.addEventListener('dragstart', function(e){
        _dashDragSrc = el.dataset.widgetCard;
        el.style.opacity = '0.5';
        e.dataTransfer.effectAllowed = 'move';
      });
      el.addEventListener('dragend', function(){ el.style.opacity='1'; });
      el.addEventListener('dragover', function(e){ e.preventDefault(); el.style.outline='2px dashed var(--accent)'; });
      el.addEventListener('dragleave', function(){ el.style.outline='none'; });
      // Touch drag support for mobile
      el.addEventListener('touchstart', function(e){
        _dashDragSrc = el.dataset.widgetCard;
        el.style.opacity='0.6';
        el.style.outline='2px dashed var(--accent)';
      },{passive:true});
      el.addEventListener('touchend', function(e){
        el.style.opacity='1'; el.style.outline='none';
        var touch = e.changedTouches[0];
        var target = document.elementFromPoint(touch.clientX, touch.clientY);
        var targetEl = target ? target.closest('[data-widget-card]') : null;
        var targetId = targetEl ? targetEl.dataset.widgetCard : null;
        if(!_dashDragSrc || !targetId || _dashDragSrc===targetId){_dashDragSrc=null;return;}
        var lay=_getDashLayout();
        var si=lay.findIndex(function(x){return x.id===_dashDragSrc;});
        var ti=lay.findIndex(function(x){return x.id===targetId;});
        if(si>-1&&ti>-1){var tmp=lay[si].row;lay[si].row=lay[ti].row;lay[ti].row=tmp;}
        _saveDashLayout(lay); _dashDragSrc=null; _renderDashGrid();
      },{passive:true});
      el.addEventListener('drop', function(e){
        e.preventDefault(); el.style.outline='none';
        var targetId = el.dataset.widgetCard;
        if(!_dashDragSrc || _dashDragSrc === targetId) return;
        var lay = _getDashLayout();
        var si2 = lay.findIndex(function(x){ return x.id===_dashDragSrc; });
        var ti2 = lay.findIndex(function(x){ return x.id===targetId; });
        if(si2===-1||ti2===-1) return;
        var tmp = lay[si2].row; lay[si2].row = lay[ti2].row; lay[ti2].row = tmp;
        // Also swap full flags for layout
        var tmpF = lay[si2].full; lay[si2].full = lay[ti2].full; lay[ti2].full = tmpF;
        _saveDashLayout(lay);
        _renderDashGrid();
        updateDash();
      });
    });
  }

  updateDash();
}

function _wrapWidget(w, innerHtml, fullWidth){
  var def = _getDef(w.id);
  var isFull = w.full !== undefined ? w.full : def.full;
  var editStyle = _dashEditMode ? 'border:2px dashed rgba(124,111,247,.35);border-radius:14px;' : '';
  var hideBtn = '';
  if(_dashEditMode){
    hideBtn = '<button onclick="_hideWidget(\'' + w.id + '\')" style="position:absolute;top:-7px;right:-7px;z-index:10;width:22px;height:22px;border-radius:50%;background:var(--accent4);border:none;color:#fff;font-size:11px;cursor:pointer;font-weight:900;display:flex;align-items:center;justify-content:center;line-height:1">\u2715</button>';
  }
  // Toggle full/half button in edit mode
  var toggleBtn = '';
  if(_dashEditMode && !['stats','meetings'].includes(w.id)){
    var icon = isFull ? '\u25D6' : '\u25A1';
    var tip = isFull ? '\u062C\u0639\u0644\u0647 \u0646\u0635\u0641' : '\u062C\u0639\u0644\u0647 \u0643\u0627\u0645\u0644';
    toggleBtn = '<button onclick="_toggleWidgetFull(\'' + w.id + '\')" title="' + tip + '" style="position:absolute;top:-7px;left:20px;z-index:10;width:22px;height:22px;border-radius:50%;background:var(--accent);border:none;color:#fff;font-size:10px;cursor:pointer;font-weight:900;display:flex;align-items:center;justify-content:center">' + icon + '</button>';
  }
  return '<div data-widget-card="' + w.id + '" class="ordo-reveal" style="position:relative;' + editStyle + '">' +
    hideBtn + toggleBtn + innerHtml + '</div>';
}

function _toggleWidgetFull(id){
  var lay = _getDashLayout();
  var w = lay.find(function(x){ return x.id===id; });
  var def = _getDef(id);
  if(w){
    var curFull = w.full !== undefined ? w.full : def.full;
    w.full = !curFull;
    _saveDashLayout(lay);
    _renderDashGrid();
  }
}

// updateDash calls _renderDashGrid if grid is empty (see updateDash function above)
window.addEventListener('load', function(){ setTimeout(_renderDashGrid, 400); });

// â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
//  CLIENT FILTER PANEL TOGGLE
// â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
function _toggleClientFilter(){
  var panel = document.getElementById('_cf-filter-panel');
  var btn   = document.getElementById('_cf-filter-toggle');
  if(!panel) return;
  var open = panel.style.display === 'none' || panel.style.display === '';
  panel.style.display = open ? 'block' : 'none';
  if(btn){
    btn.style.background  = open ? 'rgba(124,111,247,.18)' : 'var(--surface2)';
    btn.style.borderColor = open ? 'var(--accent)'         : 'var(--border)';
    btn.style.color       = open ? 'var(--accent)'         : 'var(--text2)';
  }
  // Show active-filter dot when any filter is active
  _updateClientFilterDot();
}

function _updateClientFilterDot(){
  var dot   = document.getElementById('_cf-filter-dot');
  var typeF = document.getElementById('cf-type')?.value    || '';
  var chanF = document.getElementById('cf-channel')?.value || '';
  var srcF  = document.getElementById('cf-search')?.value  || '';
  if(dot) dot.style.display = (typeF||chanF||srcF) ? 'block' : 'none';
}

// Patch existing filter functions to also update the dot
var _origSetCFType    = typeof setCFType    === 'function' ? setCFType    : null;
var _origSetCFChannel = typeof setCFChannel === 'function' ? setCFChannel : null;
var _origResetCF      = typeof resetClientFilters === 'function' ? resetClientFilters : null;

if(_origSetCFType)    setCFType    = function(v,el){ _origSetCFType(v,el);    _updateClientFilterDot(); };
if(_origSetCFChannel) setCFChannel = function(v,el){ _origSetCFChannel(v,el); _updateClientFilterDot(); };
if(_origResetCF)      resetClientFilters = function(){
  _origResetCF();
  _updateClientFilterDot();
  // close panel on reset
  var panel = document.getElementById('_cf-filter-panel');
  if(panel) panel.style.display = 'none';
  var btn = document.getElementById('_cf-filter-toggle');
  if(btn){ btn.style.background='var(--surface2)'; btn.style.borderColor='var(--border)'; btn.style.color='var(--text2)'; }
};

// â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
//  SCROLL-REVEAL + PAGE-LOAD ANIMATIONS
// â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
(function(){
  // Page load: fade-up the sidebar, header, grid
  function _animatePageLoad(){
    var sidebar = document.getElementById('sidebar');
    var grid    = document.getElementById('_dash-grid');
    if(sidebar) sidebar.style.animation = '_ordo-fadeIn .4s ease both';
    if(grid)    grid.style.animation    = '_ordo-fadeUp .5s cubic-bezier(.22,1,.36,1) .15s both';
    var hdr = document.querySelector('#page-dashboard.active .page-header');
    if(hdr)  hdr.style.animation = '_ordo-fadeUp .45s cubic-bezier(.22,1,.36,1) .05s both';
  }
  setTimeout(_animatePageLoad, 150);

  // Scroll-reveal IntersectionObserver
  var _revObs = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if(!e.isIntersecting) return;
      e.target.classList.add('ordo-visible');
      _revObs.unobserve(e.target);
    });
  }, { threshold: 0.07, rootMargin: '0px 0px -20px 0px' });

  function _observeAll(){
    document.querySelectorAll('.ordo-reveal:not(.ordo-visible), .ordo-stagger:not(.ordo-visible)')
      .forEach(function(el){ _revObs.observe(el); });
  }

  // Observe after initial render
  setTimeout(_observeAll, 700);

  // Re-observe whenever new elements are injected
  var _mo = new MutationObserver(function(){ clearTimeout(_mo._t); _mo._t = setTimeout(_observeAll, 80); });
  _mo.observe(document.body, { childList: true, subtree: true });

  // On page switch: animate incoming page header + re-observe
  var _origShowPage = window.showPage;
  if(typeof _origShowPage === 'function'){
    window.showPage = function(page){
      _origShowPage(page);
      setTimeout(function(){
        var ap = document.querySelector('.page.active');
        if(!ap) return;
        // animate page header
        var hdr = ap.querySelector('.page-header');
        if(hdr){ hdr.style.animation='none'; void hdr.offsetHeight; hdr.style.animation='_ordo-fadeUp .4s cubic-bezier(.22,1,.36,1) both'; }
        // reset & re-observe reveals in this page
        ap.querySelectorAll('.ordo-reveal').forEach(function(el){
          el.classList.remove('ordo-visible');
          el.style.transition = 'none'; void el.offsetHeight; el.style.transition = '';
        });
        setTimeout(_observeAll, 60);
      }, 25);
    };
  }
})();

// â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
// TIME LOG EDIT/DELETE in task detail
// â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
function deleteTimeLog(taskId, dateKey){
  confirmDel('هل تريد حذف هذا السجل الزمني؟', function(){
    var t = S.tasks.find(function(x){ return x.id===taskId; });
    if(!t) return;
    t.timeLogs = (t.timeLogs||[]).filter(function(l){ return l.date!==dateKey; });
    S.timeEntries = (S.timeEntries||[]).filter(function(e){
      var d=(e.started_at||'').split('T')[0];
      return !(d===dateKey && (e.task_title||'').toLowerCase()===(t.title||'').toLowerCase());
    });
    lsSave(); cloudSave(S);
    openTaskDetail(taskId);
    if(typeof toast==='function') toast('<i class="fa-solid fa-trash"></i> تم حذف السجل');
  });
}

function editTimeLog(taskId, dateKey){
  var t = S.tasks.find(function(x){ return x.id===taskId; });
  if(!t) return;
  var log = (t.timeLogs||[]).find(function(l){ return l.date===dateKey; });
  var curSecs = log ? (log.seconds||0) : 0;
  var curH = Math.floor(curSecs/3600);
  var curM = Math.floor((curSecs%3600)/60);
  var modal = document.getElementById('_modal-edit-timelog');
  if(!modal){
    modal = document.createElement('div');
    modal.id='_modal-edit-timelog';
    modal.className='modal-overlay';
    modal.innerHTML='<div class="modal" style="max-width:340px" id="_modal-edit-timelog-inner"></div>';
    document.body.appendChild(modal);
    modal.addEventListener('click',function(e){ if(e.target===modal) closeM('_modal-edit-timelog'); });
  }
  document.getElementById('_modal-edit-timelog-inner').innerHTML=
    '<div class="modal-header">' +
    '<div class="modal-title"><i class="fa-solid fa-stopwatch"></i> تعديل سجل الوقت</div>' +
    '<button class="close-btn" onclick="closeM(\'_modal-edit-timelog\')"><i class="fa-solid fa-xmark"></i></button></div>' +
    '<div style="padding:20px">' +
    '<div style="font-size:12px;color:var(--text3);margin-bottom:12px"><i class="fa-solid fa-calendar-days"></i> التاريخ: ' + dateKey + '</div>' +
    '<div style="display:flex;gap:10px;align-items:center;margin-bottom:16px">' +
    '<div class="form-group" style="flex:1;margin:0"><label class="form-label">الساعات</label>' +
    '<input id="_etl-hours" type="number" min="0" max="23" value="' + curH + '" class="form-input" style="text-align:center;font-size:18px;font-weight:700"></div>' +
    '<div style="font-size:20px;color:var(--text3);margin-top:18px">:</div>' +
    '<div class="form-group" style="flex:1;margin:0"><label class="form-label">الدقائق</label>' +
    '<input id="_etl-mins" type="number" min="0" max="59" value="' + curM + '" class="form-input" style="text-align:center;font-size:18px;font-weight:700"></div></div>' +
    '<div style="display:flex;gap:8px">' +
    '<button onclick="deleteTimeLog(' + taskId + ',\'' + dateKey + '\')" class="btn btn-danger" style="flex:1"><i class="fa-solid fa-trash"></i> حذف</button>' +
    '<button onclick="_saveEditedTimeLog(' + taskId + ',\'' + dateKey + '\')" class="btn btn-primary" style="flex:1" data-i18n="btn_save"><i class="fa-solid fa-floppy-disk" style="margin-left:4px"></i> حفظ</button>' +
    '</div></div>';
  openM('_modal-edit-timelog');
}

function _saveEditedTimeLog(taskId, dateKey){
  var h = parseInt(document.getElementById('_etl-hours').value)||0;
  var m = parseInt(document.getElementById('_etl-mins').value)||0;
  var newSecs = h*3600 + m*60;
  if(newSecs<=0){ if(typeof toast==='function') toast('أدخل وقتاً صحيحاً'); return; }
  var t = S.tasks.find(function(x){ return x.id===taskId; });
  if(!t) return;
  if(!t.timeLogs) t.timeLogs=[];
  var existing = t.timeLogs.find(function(l){ return l.date===dateKey; });
  if(existing){ existing.seconds=newSecs; } else { t.timeLogs.push({date:dateKey,seconds:newSecs}); }
  lsSave(); cloudSave(S);
  closeM('_modal-edit-timelog');
  openTaskDetail(taskId);
  if(typeof toast==='function') toast('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تم تحديث الوقت');
}

function addManualTimeLog(taskId){
  var today = new Date().toISOString().split('T')[0];
  var modal = document.getElementById('_modal-edit-timelog');
  if(!modal){
    modal = document.createElement('div');
    modal.id='_modal-edit-timelog';
    modal.className='modal-overlay';
    modal.innerHTML='<div class="modal" style="max-width:340px" id="_modal-edit-timelog-inner"></div>';
    document.body.appendChild(modal);
    modal.addEventListener('click',function(e){ if(e.target===modal) closeM('_modal-edit-timelog'); });
  }
  document.getElementById('_modal-edit-timelog-inner').innerHTML=
    '<div class="modal-header"><div class="modal-title">+ إضافة وقت يدوي</div>' +
    '<button class="close-btn" onclick="closeM(\'_modal-edit-timelog\')"><i class="fa-solid fa-xmark"></i></button></div>' +
    '<div style="padding:20px">' +
    '<div class="form-group"><label class="form-label">التاريخ</label>' +
    '<input id="_etl-date" type="date" value="' + today + '" class="form-input"></div>' +
    '<div style="display:flex;gap:10px;align-items:center;margin-bottom:16px">' +
    '<div class="form-group" style="flex:1;margin:0"><label class="form-label">الساعات</label>' +
    '<input id="_etl-hours" type="number" min="0" max="23" value="1" class="form-input" style="text-align:center;font-size:18px;font-weight:700"></div>' +
    '<div style="font-size:20px;color:var(--text3);margin-top:18px">:</div>' +
    '<div class="form-group" style="flex:1;margin:0"><label class="form-label">الدقائق</label>' +
    '<input id="_etl-mins" type="number" min="0" max="59" value="0" class="form-input" style="text-align:center;font-size:18px;font-weight:700"></div></div>' +
    '<button onclick="_saveManualTimeLog(' + taskId + ')" class="btn btn-primary" style="width:100%"><i class="fa-solid fa-floppy-disk"></i> إضافة</button></div>';
  openM('_modal-edit-timelog');
}

function _saveManualTimeLog(taskId){
  var h = parseInt(document.getElementById('_etl-hours').value)||0;
  var m = parseInt(document.getElementById('_etl-mins').value)||0;
  var date = document.getElementById('_etl-date').value || new Date().toISOString().split('T')[0];
  var newSecs = h*3600 + m*60;
  if(newSecs<=0){ if(typeof toast==='function') toast('أدخل وقتاً صحيحاً'); return; }
  var t = S.tasks.find(function(x){ return x.id===taskId; });
  if(!t) return;
  if(!t.timeLogs) t.timeLogs=[];
  var existing = t.timeLogs.find(function(l){ return l.date===date; });
  if(existing){ existing.seconds += newSecs; } else { t.timeLogs.push({date:date,seconds:newSecs}); }
  lsSave(); cloudSave(S);
  closeM('_modal-edit-timelog');
  openTaskDetail(taskId);
  if(typeof toast==='function') toast('<i class="fa-solid fa-square-check" style="color:var(--accent3)"></i> تمت إضافة الوقت');
}

function clearAllTimeLogs(taskId){
  confirmDel('سيتم حذف كل سجلات الوقت. هل أنت متأكد؟', function(){
    var t = S.tasks.find(function(x){ return x.id===taskId; });
    if(!t) return;
    t.timeLogs = [];
    S.timeEntries = (S.timeEntries||[]).filter(function(e){
      return (e.task_title||'').toLowerCase() !== (t.title||'').toLowerCase();
    });
    lsSave(); cloudSave(S);
    openTaskDetail(taskId);
    if(typeof toast==='function') toast('<i class="fa-solid fa-trash"></i> تم مسح كل سجلات الوقت');
  });
}

