    var pct=tasks.length ? Math.round(done/tasks.length*100) : 0;
    return '<article class="project-period-v5-card" onclick="openProjectPeriod(&quot;'+esc(parent.id)+'&quot;,&quot;'+esc(sp.id||sp.projectId)+'&quot;)">'+
      '<div class="project-period-v5-card-head"><span><i class="fa-solid fa-calendar-days"></i></span><button title="تعديل" onclick="event.stopPropagation();openProjectPeriodModal(&quot;'+esc(parent.id)+'&quot;,&quot;'+esc(sp.id||sp.projectId)+'&quot;)"><i class="fa-solid fa-pen"></i></button></div>'+
      '<h3>'+esc(sp.name||'مرحلة')+'</h3>'+
      '<p>'+esc(sp.start||'بدون بداية')+' - '+esc(sp.deadline||'بدون موعد نهائي')+'</p>'+
      '<div class="project-period-v5-stats"><span><b>'+money(sp.budget,parent.budgetCurrency)+'</b><small>ميزانية</small></span><span><b>'+tasks.length+'</b><small>مهام</small></span><span><b>'+pct+'%</b><small>تقدم</small></span></div>'+
      '<div class="project-period-v5-progress"><i style="width:'+pct+'%;background:'+(child&&child.color||parent.color||'#7c6ff7')+'"></i></div>'+
    '</article>';
